window.NYT_RECIPES = [{"pair":1023396,"title":"Puttanesca Chickpea-Tomato Salad","subtitle":null,"author":"Ali Slagle","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"15 minutes","nutrition":{"calories":"851","fat":"14 g","carbohydrates":"134 g","protein":"54 g"},"description":"This recipe turns tomato salad into a meal by marrying creamy beans with some of the briny, salty ingredients found in pasta puttanesca, like tomatoes, capers, olives and garlic. While Parmesan isn’t traditional to puttanesca, coarsely chopped pebbles of it add bursts of umami to this salad. Feel free to omit the cheese for a vegan dish, or embellish the mix with fresh or dried chile, tinned fish or more vegetables. This recipe is not only adaptable but also improves as it sits: The tomato juices mingle with the oil, olives and capers — and the beans drink it all up.","from_your_kitchen":null,"ingredients":["1 ½ pounds ripe tomatoes of any size, cut into 1- or 2-bite pieces","3 cups cooked, rinsed chickpeas, white beans or a mix (homemade or from two 15-ounce cans)","½ cup coarsely chopped parsley leaves and stems","1 ½ ounces Parmesan, coarsely chopped or crumbled (about ⅓ cup)","¼ cup extra-virgin olive oil","¼ cup kalamata olives, torn in half and pitted","3 tablespoons drained capers","1 tablespoon lemon juice, plus more to taste","1 small garlic clove, finely grated","Kosher salt"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, stir together the tomatoes, chickpeas, parsley, Parmesan, olive oil, olives, capers, lemon juice and garlic. Season lightly with salt and stir once more. Let sit for 10 minutes or up to 2 hours at room temperature."},{"n":2,"title":null,"text":"Before serving, taste and add more salt and lemon juice until it tastes bright. The balance is largely dependent on your tomatoes. (This salad keeps for up to 2 days in the refrigerator. Bring to room temperature before serving.)"}],"tips":[],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["chickpeas","tomato"],"item_tags":["capers","lemon","olives","parmesan","parsley"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Chickpea","Dinner","Easy","Lunch","Main Course","Olive","Parmesan","Quick","Salad","Side Dish","Summer","Tomato","Weeknight"],"issues":null,"front":"nyt_1023396.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1023396-puttanesca-chickpea-tomato-salad","rating":{"value":5,"count":2936},"date":"2022-08-11"},{"pair":1023630,"title":"Za’atar Roasted Tofu With Chickpeas, Tomatoes and Lemony Tahini","subtitle":null,"author":"Yewande Komolafe","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"693","fat":"47 g","carbohydrates":"47 g","protein":"31 g"},"description":"Tofu and chickpeas form the hearty base for vibrant, woodsy za’atar, the popular Middle Eastern spice blend. The tomatoes, when roasted, become acidic, little bursts in the salad, a great complement to the earthiness of the other ingredients. The roasted vegetables, chickpeas and tofu and the tahini dressing will keep for days once refrigerated. Assemble your bowl to order, and enjoy it for lunch or as a light dinner.","from_your_kitchen":null,"ingredients":["1 (14-ounce) package firm tofu, drained and patted dry","1 (15 ½-ounce) can chickpeas, drained, rinsed and patted dry","1 pint cherry or grape tomatoes","Salt and pepper","3 garlic cloves","2 lemons","½ cup extra-virgin olive oil","1 ½ tablespoons za’atar dry spice mix (see Tip)","1 teaspoon dried oregano or marjoram","½ cup chopped flat-leaf parsley","2 tablespoons soy sauce","¼ cup tahini","1 tablespoon honey","1 (8-ounce) bag leafy greens, such as baby spinach, baby kale or mixed greens"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Cut the tofu into ½-inch-thick slices and place them on a kitchen or paper towel to dry out."},{"n":2,"title":null,"text":"Combine the chickpeas and tomatoes on a half-sheet pan and sprinkle with salt and black pepper to season."},{"n":3,"title":null,"text":"Using a Microplane or other fine grater, grate the garlic cloves and zest 1 lemon into a large bowl. Squeeze ¼ cup juice from the lemon (using the second lemon if needed) and reserve. Add the oil, za’atar, oregano and ¼ cup chopped parsley to the garlic mixture and stir to combine. Pour half of the marinade over the chickpeas and tomatoes, toss to combine and spread in an even layer. Roast until the tomatoes are just beginning to burst open and the chickpeas are warmed through, about 15 minutes."},{"n":4,"title":null,"text":"Meanwhile, add the soy sauce to the remaining marinade and stir. Add the tofu slices to the bowl and carefully turn each piece to coat both sides. Allow the tofu to marinate while the chickpea mixture cooks, then nestle the tofu slices, topped with any leftover marinade in the bowl, among the chickpeas and tomatoes on the sheet pan."},{"n":5,"title":null,"text":"Roast until the tofu begins to brown around the edges and top, the tomatoes have burst open releasing their juices and the chickpeas are golden brown and crunchy, about 15 minutes."},{"n":6,"title":null,"text":"While the tofu roasts, whisk together the tahini, honey, reserved lemon juice and 2 tablespoons of water. Season to taste with salt and black pepper."},{"n":7,"title":null,"text":"Divide the leafy greens among 4 bowls. Dress the tofu, chickpeas and tomatoes on the baking sheet with 4 tablespoons of the tahini mixture and sprinkle with the remaining ¼ cup parsley. Divide evenly among the bowls and spoon additional dressing all over everything."}],"tips":["Za’atar, the classic Middle Eastern seasoning, is a mix of savory dried herbs, sumac and sesame seeds. It can be purchased as a pre-made blend or made at home."],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["chickpeas","spinach","tofu","tomato"],"item_tags":["honey","lemon","soy sauce","tahini","za'atar"],"course_tags":["Dinner","Lunch"],"keywords":["Beans","Cherry Tomato","Chickpea","Dinner","Easy","Firm Tofu","Healthy","Leafy Greens","Lunch","Main Course","Roast","Sheet-Pan","Soy Sauce","Tahini","Vegetarian","Za’atar"],"issues":null,"front":"nyt_1023630.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1023630-zaatar-roasted-tofu-with-chickpeas-tomatoes-and-lemony-tahini","rating":{"value":5,"count":5240},"date":"2022-11-10"},{"pair":1026898,"title":"Easy Chickpea Salad","subtitle":null,"author":"Kristina Felix","servings":"6","yield_text":"6 servings, about 5 1/2 cups","yield_count":6,"cook_time":"20 minutes","nutrition":{"calories":"311","fat":"13 g","carbohydrates":"41 g","protein":"12 g"},"description":"A bright zesty salad with crisp cucumbers and tender chickpeas inspired by the Levant, where chickpeas have been cultivated for millennia. Ready in a flash, this salad combines lemon and fresh aromatic herbs with a crunch and flavor that improves over time in the refrigerator, making it a great salad to bring to a picnic or potluck. Serve with warm pita bread, or spoon over rice. Instead of discarding the chickpea liquid (aquafaba), try making homemade vegan mayonnaise or even meringues. Leftovers keep beautifully for up to a week, and try this: mix in a touch of that homemade mayo for a delicious chickpea salad sandwich the next day.","from_your_kitchen":null,"ingredients":["3 tablespoons lemon juice (from 1 lemon)","1 tablespoon white vinegar","1 teaspoon honey or maple syrup","1 garlic clove, grated","Kosher salt and freshly ground black pepper","2 (15-ounce) cans chickpeas, drained and rinsed","½ English cucumber, diced (about 1 cup)","½ red onion, diced (about 1 cup)","1 medium tomato, diced (about 1 cup)","¼ cup chopped parsley","¼ cup chopped dill","3 tablespoons extra-virgin olive oil","Za’atar to taste, plus warm pita or rice for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, whisk together lemon juice, vinegar, honey, garlic, 1 teaspoon salt and ½ teaspoon pepper. Add the chickpeas, cucumber, onion, tomato, parsley and dill to the bowl; toss together until evenly coated, then drizzle the oil evenly over everything and toss again."},{"n":2,"title":null,"text":"Taste and adjust salt and pepper to your liking. Serve immediately, sprinkled with za’atar to taste, alongside warm pita bread or over rice if desired. Leftovers will keep in the refrigerator, in an airtight container, for up to 5 days."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["chickpeas","cucumber","tomato"],"item_tags":["dill","lemon","parsley","za'atar"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Beans","Chickpea","Cucumber","Dairy-Free","Dinner","Easy","Fourth of July","Gluten-Free","Healthy","Lemon Juice","Lunch","Main Course","Memorial Day","No Cook","Picnic","Quick","Salad","Side Dish","Summer","Tomato","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1026898.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1026898-easy-chickpea-salad","rating":{"value":5,"count":1478},"date":"2025-05-23"},{"pair":1017463,"title":"Summer Pasta With Zucchini, Ricotta and Basil","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"450","fat":"12 g","carbohydrates":"68 g","protein":"18 g"},"description":"A summer pasta should be simple and fresh, ideally made with vegetables straight from the garden or market. Look for the best artisanal ricotta; top-quality ingredients make all the difference here.","from_your_kitchen":null,"ingredients":["Extra-virgin olive oil","1 small onion, finely diced","2 pounds zucchini, sliced into ¼-inch-thick pieces (for larger zucchini, cut in half lengthwise before slicing)","Salt and pepper","2 garlic cloves, minced, or 2 tablespoons chopped green garlic","1 ounce basil, about 2 cups loose leaves","1 pound ziti or other dry pasta","8 ounces ricotta, about 1 cup (see recipe)","Pinch of crushed red pepper","Zest of 1 lemon","2 ounces grated Parmesan, pecorino or a mixture, about 1 cup, plus more for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put a pot of water on to boil. In a large skillet over medium-high heat, cook the onions in 3 tablespoons olive oil until softened, 5 to 8 minutes. Reduce heat as necessary to keep onions from browning. Add zucchini, season generously with salt and pepper, and continue cooking, stirring occasionally until rather soft, about 10 minutes. Turn off heat."},{"n":2,"title":null,"text":"Meanwhile, use a mortar and pestle to pound garlic, basil and a little salt into a rough paste (or use a mini food processor). Stir in 3 tablespoons olive oil."},{"n":3,"title":null,"text":"Salt the pasta water well and put in the pasta, stirring. Boil per package instructions but make sure to keep pasta quite al dente. Drain pasta, reserving 1 cup of cooking water."},{"n":4,"title":null,"text":"Add cooked pasta to zucchini in skillet and turn heat to medium-high. Add ½ cup cooking water, then the ricotta, crushed red pepper and lemon zest, stirring to distribute. Check seasoning and adjust. Cook for 1 minute more. Mixture should look creamy. Add a little more pasta water if necessary. Add the basil paste and half the grated cheese and quickly stir to incorporate. Spoon pasta into warm soup plates and sprinkle with additional cheese. Serve immediately."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["pasta","ricotta","zucchini"],"item_tags":["basil","lemon","parmesan","red chile flakes"],"course_tags":["Dinner","Lunch"],"keywords":["Basil","Boil","Dinner","Lunch","Main Course","Parmesan","Pastas","Quick","Ricotta","Summer","Vegetarian","Weeknight","Ziti","Zucchini"],"issues":null,"front":"nyt_1017463.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017463-summer-pasta-with-zucchini-ricotta-and-basil","rating":{"value":5,"count":15216},"date":"2015-12-16"},{"pair":1026267,"title":"Sheet-Pan Coconut Curry With Squash and Tofu","subtitle":null,"author":"Hetty Lui McKinnon","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"55 minutes","nutrition":{"calories":"536","fat":"34 g","carbohydrates":"52 g","protein":"17 g"},"description":"In this warming sheet-pan dinner, winter squash receives the royal treatment, as it roasts in a (shallow!) coconut curry. Choosing a thin-skinned winter squash such as red kuri, kabocha, delicata or butternut means that no peeling is necessary. (In fact, the skin helps the squash keep its structure while cooking.) The whole curry is cooked on one sheet pan: The squash is roasted first, then the tofu, greens and coconut milk are added for an easy, hands-off approach. All curry pastes will vary in saltiness and heat, so add according to your taste preference. If you wanted a bigger flavor punch, you could add some grated ginger and garlic to the coconut milk. The leafy greens will crisp up around the edges, bringing a lovely textural contrast.","from_your_kitchen":null,"ingredients":["2 pounds thin-skinned winter squash, such as red kuri, kabocha, delicata or butternut, seeds removed and squash cut into 1-inch wedges","2 tablespoons vegetable oil or other neutral oil","Salt and pepper","1 (14-ounce) can coconut milk, well shaken","2 to 3 tablespoons store-bought red or green Thai curry paste","4 ounces leafy greens, such as chard or kale leaves, stemmed and roughly chopped (4 cups, from about ½ bunch)","1 (14- to 16-ounce) package extra-firm tofu, cut into 1-inch cubes","Cooked rice, for serving","Chopped cilantro, for serving","Red or green chile (optional), thinly sliced, for serving","1 lime, cut into wedges, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees."},{"n":2,"title":null,"text":"Place the squash onto a rimmed baking sheet. Drizzle over the oil and season with salt and pepper. Toss to coat and then lay the squash wedges flat on one cut side. Place into the oven and roast for 20 minutes."},{"n":3,"title":null,"text":"While the squash roasts, in a large jug or medium bowl, add the coconut milk and curry paste (use according to your spice level preference) and season generously with salt and pepper."},{"n":4,"title":null,"text":"Remove the baking sheet from the oven and tuck the leafy greens and tofu around the squash. Pour the spiced coconut milk over everything. Return to the oven and cook until the squash is completely tender and the greens are wilted, 15 to 20 minutes. Season with more salt and pepper if needed."},{"n":5,"title":null,"text":"Spoon the squash, tofu, greens and sauce over rice and top with cilantro and sliced chile (if using); serve with a lime wedge on the side."}],"tips":[],"cuisine_tags":["Thai"],"ingredient_tags":["squash","tofu"],"item_tags":["cilantro","coconut milk","curry paste","lime"],"course_tags":["Dinner"],"keywords":["Butternut Squash","Coconut Milk","Curry","Curry Paste","Dinner","Easy","Extra-Firm Tofu","Great Leftovers","Healthy","Leafy Greens","Main Course","Quick","Roast","Sheet-Pan","Squash","Vegan","Vegan Thanksgiving","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1026267.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1026267-sheet-pan-coconut-curry-with-squash-and-tofu","rating":{"value":5,"count":1778},"date":"2025-01-17"},{"pair":1019020,"title":"Fudgy Nutella Brownies","subtitle":null,"author":"Yossy Arefi","servings":null,"yield_text":"One 8x8-inch pan","yield_count":1,"cook_time":"45 minutes","nutrition":null,"description":"Generous swirls of chocolate-hazelnut spread put these super decadent brownies straight over the top. Take care to fold the flour in gently and bake them until they are just set for the richest, fudgiest texture.","from_your_kitchen":null,"ingredients":["½ cup/113 grams unsalted butter (1 stick), plus more for greasing the baking dish","4 ounces/113 grams bittersweet chocolate, chopped","1 cup/296 grams chocolate-hazelnut spread, like Nutella","⅔ cup/134 grams granulated sugar","2 large eggs","½ teaspoon espresso powder","1 teaspoon vanilla extract","¾ cup/96 grams all-purpose flour","½ teaspoon kosher salt"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 350 degrees. Butter and line an 8x8-inch baking dish with parchment paper."},{"n":2,"title":null,"text":"Combine the chopped chocolate and butter in a heat-safe bowl set over a pan of simmering water. Stir the mixture occasionally until melted. Set aside."},{"n":3,"title":null,"text":"In the bowl of a stand mixer fitted with the paddle attachment, combine ¾ cup/222 grams chocolate-hazelnut spread, sugar and eggs. Mix on medium-high for 5 minutes, scraping down the bowl a couple of times. Add espresso powder and vanilla and mix briefly to combine."},{"n":4,"title":null,"text":"Turn the mixer to low and stream in the chocolate-butter mixture. Mix until well combined, then fold in the flour and salt."},{"n":5,"title":null,"text":"Pour the mixture into the prepared pan, spread evenly with a knife or offset spatula and spoon several dollops of the remaining ¼ cup/74 grams chocolate-hazelnut spread evenly over the top. Use a toothpick or skewer to swirl the spread and brownie batter a few times, leaving big streaks of the spread on the surface."},{"n":6,"title":null,"text":"Bake the brownies for 25 to 30 minutes, or until just set in the middle. A toothpick inserted into the center should pull out some moist crumbs."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate","hazelnuts"],"item_tags":["espresso powder","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Bittersweet Chocolate","Brownie","Dessert","Nutella"],"issues":null,"front":"nyt_1019020.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019020-fudgy-nutella-brownies","rating":{"value":5,"count":1399},"date":"2017-10-26"},{"pair":1026472,"title":"One-Pot Beans, Greens and Grains","subtitle":null,"author":"Ali Slagle","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"40 minutes","nutrition":{"calories":"380","fat":"8 g","carbohydrates":"66 g","protein":"13 g"},"description":"Many filling, flavorful and flexible meals are within reach with this technique: It produces fluffy grains, just-soft-enough greens and creamy and garlicky beans all in one pot. Customize your mix based on your cravings and your pantry: Use any dark leafy greens and any cooked legumes. Use quinoa, rice or a mix of the two for a variety of textures; for other grains, refer to the cooking instructions on their package and add the greens in the last 5 to 7 minutes. You can infuse the grains with flavor by stirring ground spices or other seasonings into the pot. Add brightness with lemon and garnish wildly — or not at all. This meal can be eaten warm or cold, which means lunchtime grain bowls are now easier to pull off.","from_your_kitchen":null,"ingredients":["1¾ cups water or broth","1 cup quinoa, long-grain white rice or a mix of the two, rinsed","Salt and black pepper","1 (14-ounce) can of any beans","1 small garlic clove","2 tablespoons extra-virgin olive oil","1 bunch collard greens, kale, spinach or other hearty dark leafy green","1 lemon","Toppings (optional): toasted nuts or seeds, fresh herbs, grated or crumbled cheese, soft-boiled egg, avocado, hot sauce or other sauces and so on"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large pot or Dutch oven, bring the water, quinoa and a generous pinch each of salt and pepper to a boil over high. Cover, reduce heat to low and simmer for 13 minutes."},{"n":2,"title":null,"text":"While the quinoa cooks, drain and rinse the beans, then transfer to a small bowl. Finely grate the garlic over the beans, then add the oil and a pinch each of salt and pepper, and stir to combine. Set aside. Remove and discard any tough stems from the greens, then roughly chop the leaves."},{"n":3,"title":null,"text":"After 13 minutes, arrange the greens on top of the quinoa and season well with salt and pepper. Cover and cook until the quinoa is tender, 5 to 7 minutes. (When the quinoa is tender, it’s also translucent and has a thin white tail.) Remove the pot from heat, scrape the beans over the greens, then cover the pot and let sit for 5 minutes."},{"n":4,"title":null,"text":"Finely grate some of the lemon zest over the beans and greens, then cut the lemon into wedges. Eat the beans, greens and grains with a squeeze of lemon juice, salt and pepper to taste and any toppings you like."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["beans","kale","rice"],"item_tags":["hot sauce","lemon"],"course_tags":["Dinner","Lunch"],"keywords":["Bean","Beans","Budget","Dinner","Dutch Oven","Easy","For Two","Grain Bowl","Healthy","Lunch","Main Course","One Pot","Quick","Quinoa","Rice","Stovetop","Sturdy Greens","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1026472.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1026472-one-pot-beans-greens-and-grains","rating":{"value":5,"count":5838},"date":"2025-01-02"},{"pair":1024690,"title":"Easy Skillet Brownies","subtitle":null,"author":"Melissa Clark","servings":null,"yield_text":"8 to 12 brownies","yield_count":8,"cook_time":"40 minutes, plus cooling","nutrition":{"calories":"466","fat":"29 g","carbohydrates":"50 g","protein":"6 g"},"description":"These simple brownies are mixed and baked in the same skillet. Chewy and fudgy, they’re everything you want in a brownie but faster and with less mess to clean up. If you don’t have an ovenproof nonstick skillet (preferably ceramic, or you could try this in a very well-seasoned cast-iron pan), pour the batter into a greased 9-inch square pan for baking. You can let the brownies cool and cut them into wedges or squares. Or, serve them warm from the oven and straight from the pan, preferably with a scoop of ice cream plopped on top.","from_your_kitchen":null,"ingredients":["¾ cup/185 grams unsalted butter","6 ounces bittersweet chocolate, coarsely chopped (about 1 cup)","½ teaspoon fine sea or table salt","1 ½ cups/300 grams granulated sugar","3 large eggs","2 teaspoons vanilla extract","¾ cup/95 grams all-purpose flour","¾ cup/110 grams walnut or pecan pieces (optional)","Flaky sea salt (optional)","Ice cream, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 350 degrees. In an ovenproof 10- or 11-inch nonstick skillet (preferably ceramic nonstick) set over medium-low heat, combine the butter, chocolate and salt. Let butter and chocolate melt, stirring occasionally. Turn off the heat."},{"n":2,"title":null,"text":"Carefully whisk in sugar until smooth, then whisk in eggs and vanilla. Finally, whisk in flour until no streaks remain. Using a spatula, fold in the nuts, if using. Smooth top and sprinkle lightly with flaky sea salt if you like."},{"n":3,"title":null,"text":"Bake until the top is set, the center is soft and the edges are firm and start to pull away from the pan, 20 to 27 minutes. (A toothpick inserted into the center will come out gooey.) Transfer to a wire rack to cool. You can serve these still a little warm and straight from the pan, with ice cream on top if you like. Or, let cool completely before slicing into wedges or bars."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate","walnuts"],"item_tags":["flaky salt","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Bittersweet Chocolate","Brownie","Dessert","Easy","Father’s Day","Kid-Friendly","Mother’s Day","One Bowl","Quick","Skillet","Snack"],"issues":null,"front":"nyt_1024690.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1024690-easy-skillet-brownies","rating":{"value":4,"count":610},"date":"2023-10-10"},{"pair":1025700,"title":"Ginger-Scallion Tofu and Greens","subtitle":null,"author":"Hetty Lui McKinnon","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"384","fat":"28 g","carbohydrates":"17 g","protein":"22 g"},"description":"A classic Chinese condiment, ginger-scallion oil is most commonly served with poached chicken but is incredibly versatile — and shines here, applied to cold silken tofu and blanched greens. Most Chinese families will have their own version of the aromatic oil, each with their own ideal ratio of ginger to scallions. There are no hard rules here, so feel free to adjust the amount of ginger and scallions to your preferences. Thinly slicing both will give you a robust sauce, but you may chop them until minced for a smoother sauce. This oil is a great one to make in bulk, as it keeps, refrigerated, up to one month, so you can add it to rice, roasted veggies, pan-fried tofu, cold noodles or eggs, invigorating your everyday cooking.","from_your_kitchen":null,"ingredients":["Salt","4 baby bok choy (about 12 ounces), each trimmed and quartered lengthwise","4 scallions, trimmed, white and green parts thinly sliced and separated","2 tablespoons soy sauce or tamari","1 tablespoon sesame oil","2 teaspoons rice vinegar","1 (2-inch piece) fresh ginger, peeled and finely chopped (about ¼ cup)","¼ cup neutral oil","2 (14- to 16-ounce) blocks silken tofu, cold","Toasted white or black sesame seeds, for serving","White rice (optional), to serve"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a pot of salted water to a boil. Add the baby bok choy and cook until the stems are just tender and the leaves are bright green, 1½ to 2 minutes. Rinse under cold water until thoroughly cooled, then drain well."},{"n":2,"title":null,"text":"Place the green parts of the scallions into a heatproof bowl and add the soy sauce, sesame oil and rice vinegar."},{"n":3,"title":null,"text":"Place the ginger, white parts of the scallions and the neutral oil into a small pot and place on medium-high heat. Stir until the ginger and scallions start to sizzle and become aromatic (watch closely so that they don’t burn), 2 to 3 minutes. Remove from the heat and immediately — and carefully — pour this over the green scallion mixture. Stir to combine. Taste and season with salt; it should be quite salty to balance the neutral flavor of the tofu."},{"n":4,"title":null,"text":"Carefully drain the liquid from each package of tofu, and gently tip the blocks onto a clean kitchen towel. (Try to keep each block in one piece, but don’t worry if it falls apart.) Pat with another clean kitchen towel, removing as much liquid as possible. Transfer the blocks to one large plate or two smaller plates and cut into 1-inch blocks. Season with salt and pepper."},{"n":5,"title":null,"text":"Add the bok choy on top and around the tofu and spoon over the ginger-scallion oil. To serve, top with sesame seeds and eat as is or serve with rice."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["bok choy","tofu"],"item_tags":["ginger","rice vinegar","scallions","sesame oil","soy sauce"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Beans","Bok Choy","Chinese","Dinner","Easy","Fresh Ginger","Lunch","Main Course","Quick","Scallion","Sesame Oil","Silken Tofu","Small Plate","Spring","Stovetop","Summer","Vegan","Weeknight"],"issues":null,"front":"nyt_1025700.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1025700-ginger-scallion-tofu-and-greens","rating":{"value":4,"count":414},"date":"2024-09-05"},{"pair":1024204,"title":"White Beans and Asparagus With Charred Lemon","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"817","fat":"33 g","carbohydrates":"100 g","protein":"40 g"},"description":"These velvety, vegan beans get a lift from lemon, but they also hold a smoky secret. Aromatics are often sweated in fat to bring out their sweetness, but crank the heat and char them instead for, as Tejal Rao wrote, “serious, almost meatlike depth of flavor.” This is a common technique in pho, black-eyed peas and other long simmers, but it also develops flavor in quicker dishes. After searing lemon wedges, their blackened bits scatter throughout beans, asparagus and coconut milk, creating a creamy bowl that’s subtly smoky and comforting. When asparagus isn’t in season, replace it with a dark, leafy green like kale or chard. Serve solo, or with rice.","from_your_kitchen":null,"ingredients":["3 tablespoons extra-virgin olive oil or coconut oil","1 large or 2 small lemons, quartered lengthwise and seeds removed","1 (14-ounce) can full-fat coconut milk","3 cups cooked, rinsed white beans (homemade or two 15-ounce cans)","1 bunch asparagus (about 1 pound), tough ends trimmed, stalks cut into 1-inch lengths","Salt","Handful of cilantro or basil leaves, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil in a large skillet over medium heat until shimmering. Add the lemon wedges, peel-side down, and cook for 1 or 2 minutes to release their oils. Flip onto cut sides and cook until the flesh is browned and charred in spots, 3 to 6 minutes. Flip onto the other cut sides and repeat."},{"n":2,"title":null,"text":"Remove the lemon wedges, pour in the coconut milk and scrape to release all the charred bits stuck to the skillet. Stir in the beans and asparagus, season well with salt, and simmer until the asparagus is crisp-tender, 5 to 8 minutes. At first, the mixture might look thick, but there’s no need to add more liquid; the asparagus will release liquid as it cooks."},{"n":3,"title":null,"text":"Remove from heat and squeeze in the lemon. Season to taste with salt and serve topped with herbs."}],"tips":[],"cuisine_tags":["Mediterranean"],"ingredient_tags":["asparagus","white beans"],"item_tags":["cilantro","coconut milk","lemon"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Asparagus","Beans","Coconut Milk","Dinner","Easy","Five Ingredient","Healthy","Lemon","Main Course","One Pot","Quick","Side Dish","Skillet","Vegan","Weeknight","White Bean"],"issues":null,"front":"nyt_1024204.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1024204-white-beans-and-asparagus-with-charred-lemon","rating":{"value":4,"count":541},"date":"2023-05-16"},{"pair":1022724,"title":"Mushroom Stroganoff","subtitle":null,"author":"Hetty Lui McKinnon","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"268","fat":"15 g","carbohydrates":"24 g","protein":"9 g"},"description":"The first recipe for beef stroganoff dates back to the 1800s and is rumored to have Russian aristocratic origins. This version is a bold, modern vegetarian reimagination that is rich and decadent, thanks to the magic of mushrooms, which deliver walloping umami. A variety of mushrooms adds a nice mix of textures, but a similarly intense dish can be created with just one type. Achieve even deeper layers of flavor by soaking a handful of dried porcini mushrooms in one cup of hot water for 10 to 15 minutes, then adding the mushrooms and soaking liquid, which can replace the vegetable stock, to the dish. Crème fraîche is naturally thick and imparts a velvety tang to the dish, but use sour cream if you prefer. (Vegans can use cashew or coconut cream). To get vegetarian recipes like this one delivered to your inbox, sign up for The Veggie newsletter.","from_your_kitchen":null,"ingredients":["2 tablespoons extra-virgin olive oil","1 yellow onion, finely diced","Salt","1 ½ pounds mixed mushrooms (oyster, shiitake, cremini or button), stemmed and sliced into ¼-inch pieces","2 sprigs fresh thyme","2 garlic cloves, finely chopped","½ cup white wine","1 cup vegetable stock","2 tablespoons soy sauce","1 ½ teaspoons Dijon mustard","½ cup crème fraîche or sour cream","Black pepper","Sweet paprika, for dusting","Handful of chopped parsley leaves, for serving","Mashed potatoes, wide egg noodles or rice, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place a large (12-inch) skillet on medium-high heat. Add olive oil and onion, season with salt, and cook for 2 to 3 minutes until softened. Add the mushrooms, thyme and garlic, and stir to combine. Cook for 8 to 10 minutes, leaving it undisturbed for 2 to 3 minutes at a time before stirring, to allow the mushrooms to caramelize."},{"n":2,"title":null,"text":"Pour in the wine to deglaze the pan, scraping up any browned bits on the bottom, then cook for about 1 minute. Add the vegetable stock and soy sauce, and cook for 5 to 7 minutes until the liquid has reduced and is slightly thickened."},{"n":3,"title":null,"text":"Take the pan off the heat, and stir in the mustard and crème fraîche. Taste, and season with salt and black pepper. Dust with paprika, scatter with parsley and serve with your choice of mashed potatoes, wide egg noodles or rice."}],"tips":[],"cuisine_tags":["Comfort Food","Eastern European"],"ingredient_tags":["egg noodles","mushrooms"],"item_tags":["dijon mustard","sour cream","soy sauce","white wine"],"course_tags":["Dinner"],"keywords":["Dijon Mustard","Dinner","Main Course","Mushroom","Soy Sauce","Vegetables","Vegetarian","Weeknight","White Wine"],"issues":null,"front":"nyt_1022724.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022724-mushroom-stroganoff","rating":{"value":5,"count":4868},"date":"2021-11-01"},{"pair":1021590,"title":"Red Lentil Loaf","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"2 hours, plus cooling","nutrition":{"calories":"274","fat":"10 g","carbohydrates":"34 g","protein":"13 g"},"description":"Vegetarian lentil loaf has a long history of masquerading as meatloaf. With its brownish-grey color and a red ketchup glaze, it does its best to look and taste like meat (though it never does). This delicate red lentil loaf is not at all like that. It’s all about the lentil flavor — sweet and vegetal. The seasoning veers a little bit Turkish, with lemon, cumin, cilantro, dill and yogurt. It is delicious served at room temperature or warm.","from_your_kitchen":null,"ingredients":["1 cup red lentils","Kosher salt and black pepper","3 tablespoons extra-virgin olive oil, plus more for drizzling","1 medium onion, diced (about 1 cup)","1 teaspoon toasted and ground cumin seeds","2 garlic cloves, minced","2 medium carrots, finely chopped","2 teaspoons grated lemon zest","3 tablespoons lemon juice","Pinch of ground cayenne","2 eggs","3 tablespoons roughly chopped cilantro","½ cup rolled oats","1 cup plain yogurt","2 Persian cucumbers, thinly sliced","3 scallions, thinly slivered, for garnish","¼ cup roughly chopped dill, for garnish","Red-pepper flakes, for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Rinse lentils. Put them in a medium saucepan. Add water just to cover and a good pinch of salt. Bring to a boil high, then reduce heat to a simmer. Cook for about 30 minutes, until very soft. Drain well."},{"n":2,"title":null,"text":"Meanwhile, put 3 tablespoons olive oil in a skillet over medium-high heat. Add onion and cook, stirring, until softened, about 5 minutes. Add cumin, garlic and carrots, seasoning mixture well with salt and pepper. Add lemon zest and juice, and cayenne."},{"n":3,"title":null,"text":"Transfer drained red lentils and onion mixture to the bowl of a food processor. Pulse until it’s the consistency of soft mashed potato, a bit lumpy. The mixture should be bright, peppery, lemony and well salted. Taste and adjust seasoning."},{"n":4,"title":null,"text":"In a small bowl, beat the eggs with a fork. Add the cilantro and beat together. Pour egg mixture into lentil mixture and pulse to incorporate. Add oats and mix in."},{"n":5,"title":null,"text":"Heat oven to 375 degrees. Lightly grease a loaf pan with olive oil. Lay a wide strip of parchment paper into the pan, leaving an overhang on two sides to help in removing cake later. Pour lentil mixture into the pan, smoothing the top. Fold excess parchment over the top. Bake until nicely browned, about 1 hour. Remove from pan and let cool. (The loaf is easier to cut if cooled.) Cut into 1-inch slices."},{"n":6,"title":null,"text":"In a small bowl, mix together yogurt and cucumbers, and season with salt. Warm the slices up briefly in a 350-degree oven, if desired. Even better: Griddle the slices with a bit of oil in a nonstick or cast-iron pan until crisp and golden on both sides. Or simply serve at room temperature."},{"n":7,"title":null,"text":"Spoon yogurt-cucumber sauce over each slice and sprinkle with scallion, dill and red-pepper flakes. Drizzle with extra-virgin olive oil, if you wish."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["carrot","lentils"],"item_tags":["cumin","dill","red chile flakes","yogurt"],"course_tags":["Dinner"],"keywords":["Bake","Beans","Carrot","Cucumber","Cumin","Lentil","Main Course","Vegetarian","Yogurt"],"issues":null,"front":"nyt_1021590.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021590-red-lentil-loaf","rating":{"value":4,"count":756},"date":"2020-11-04"},{"pair":1015866,"title":"3-Bean Good Luck Salad With Cumin Vinaigrette","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 45 minutes","nutrition":{"calories":"322","fat":"13 g","carbohydrates":"40 g","protein":"13 g"},"description":"This is a colorful variation of the black-eyed peas salad I always serve at my New Year’s Day open house. You can cook the black beans and red beans together or separately. The black-eyed peas cook more quickly so should be cooked separately.","from_your_kitchen":null,"ingredients":["¾ cup dried black beans, washed, picked over and soaked for 6 hours or overnight in 3 cups water","¾ cup dried red beans or kidney beans, washed, picked over and soaked for 6 hours or overnight in 3 cups water","2 onions, halved","4 garlic cloves, minced","Salt to taste","¾ cup black-eyed peas, washed and picked over","1 bay leaf","¼ cup red wine vinegar or sherry vinegar","1 garlic clove, minced","Salt and freshly ground pepper to taste","2 teaspoons lightly toasted cumin, ground","1 teaspoon Dijon mustard","½ cup broth from the beans","⅓ cup extra virgin olive oil","1 red bell pepper, diced","½ cup chopped cilantro"],"ingredient_groups":[{"at":0,"title":"FOR THE BEANS"},{"at":7,"title":"FOR THE DRESSING AND SALAD"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Place a strainer over a bowl and drain the black beans. Add enough water to the soaking water to measure 6 cups. Drain the red beans and discard the soaking water. Combine the black and red beans, water, all but ½ onion, and 3 of the garlic cloves in a large, heavy pot and bring to a gentle boil. Reduce the heat, cover and simmer 1 hour. Add salt to taste (beans take a lot of salt) and continue to simmer for another 30 minutes, or until the beans are tender but intact. Remove and discard the onions. Set a strainer over a bowl and drain. Measure out ¼ cup of the broth."},{"n":2,"title":null,"text":"Meanwhile in a separate pot combine the black-eyed peas, remaining ½ onion and garlic clove, the bay leaf and 3 cups water. Bring to a boil, add salt to taste, cover, reduce the heat and simmer 45 minutes, or until the beans are tender but intact. Remove and discard the bay leaf and onion. Set a strainer over a bowl and drain. Measure out ¼ cup of the broth and add to the black and red bean broth."},{"n":3,"title":null,"text":"In a bowl or measuring cup, whisk together the dressing ingredients. Combine all of the beans in a large bowl and toss with the dressing. Taste and adjust salt. At this point the mixture can be refrigerated, or the salad can be served warm or at room temperature."},{"n":4,"title":null,"text":"Stir the peppers and cilantro into the beans and serve."}],"tips":["The beans will keep for 5 days in the refrigerator; toss them with the vinaigrette, but if you aren't serving them right away, wait and add the cilantro and red pepper just before serving."],"cuisine_tags":["American","Southern"],"ingredient_tags":["black beans","black-eyed peas","kidney beans"],"item_tags":["cilantro","cumin","dijon mustard"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Beans","Dairy-Free","Dinner","Gluten-Free","Healthy","High Fiber","Low Sugar","Low-Fat","Lunch","Main Course","Salad","Side Dish","Vegan","Vegetarian"],"issues":null,"front":"nyt_1015866.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015866-3-bean-good-luck-salad-with-cumin-vinaigrette","rating":{"value":5,"count":543},"date":"2013-12-30"},{"pair":1025053,"title":"Miso-Mushroom Barley Soup","subtitle":null,"author":"Yasmin Fahr","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"297","fat":"9 g","carbohydrates":"48 g","protein":"12 g"},"description":"This hearty vegan dish uses miso and soy to add a tremendous amount of depth and flavor to a relatively quick, one-pot mushroom barley soup. Quartering the mushrooms allows them to retain bite, but you can thinly slice them if you’d prefer everything to be soft and tender. Resist the urge to salt heavily during the bulk of the cooking, as the miso and soy — both sodium-heavy ingredients — will be added at the end to bring the soup together. This is a soup that will thicken, so add more water or broth when reheating. It’s as accommodating as it is comforting: You can empty your pantry or fridge by swapping the barley for farro and spinach for chopped bok choy or other greens.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil","1½ pounds cremini mushrooms, trimmed and quartered","Kosher salt and freshly ground black pepper","1 bunch scallions, trimmed, light green and white parts thinly sliced","¼ to ½ teaspoon crushed red pepper, depending on heat preference","4 cups low-sodium vegetable broth","1 cup pearl barley","1 tablespoon plus 1 teaspoon white miso","1 tablespoon soy sauce (or more as needed)","5 ounces baby spinach (about 5 packed cups)","1 lime (optional), halved"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large pot, heat the oil over medium-high until shimmering. Add the mushrooms and season lightly with salt and a few grinds of pepper. Cook, stirring occasionally, until the mushrooms shrink down and release their juices, 6 to 7 minutes."},{"n":2,"title":null,"text":"Stir in the scallions and crushed red pepper and cook until softened, about 2 minutes."},{"n":3,"title":null,"text":"Pour in the vegetable broth, 2 cups of water and the barley. Raise the heat to bring the liquid to a boil, then lower it to maintain a simmer. Cook, stirring occasionally, until the barley is tender, about 30 minutes."},{"n":4,"title":null,"text":"During the last 5 minutes of cooking, stir in the miso and soy sauce. (Use a rubber spatula or wooden spoon to seek out any miso clumps, flattening them against the side of the pot to help dissolve.)"},{"n":5,"title":null,"text":"Add the spinach in batches, adding a handful and stirring in until wilted. Taste and season with more soy sauce or salt as needed. Squeeze in half a lime, if using, and cut the rest into wedges for serving. Finish with some black pepper and serve."}],"tips":[],"cuisine_tags":["Comfort Food","Fusion"],"ingredient_tags":["barley","mushrooms","spinach"],"item_tags":["miso","red chile flakes","scallions","soy sauce"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Cremini","Dinner","Easy","Great Leftovers","Lunch","Main Course","Miso","One Pot","Pearl Barley","Scallion","Simmer","Soup","Spinach","Stovetop","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1025053.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1025053-miso-mushroom-barley-soup","rating":{"value":5,"count":1673},"date":"2024-02-16"},{"pair":1019600,"title":"Loaded Sweet Potatoes With Black Beans and Cheddar","subtitle":null,"author":"Sarah Jampel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"50 minutes","nutrition":{"calories":"196","fat":"6 g","carbohydrates":"36 g","protein":"8 g"},"description":"To make a halved sweet potato into a more substantial side, load it with black beans and sharp Cheddar, then send it back into the oven until the cheese melts and sizzles. Pair it with something a bit lighter, like fish tacos or a green salad, or build it into its own meal by adding sliced avocado, torn cilantro, a squeeze of lime juice, or even a fried egg.","from_your_kitchen":null,"ingredients":["2 medium sweet potatoes (8 to 10 ounces each), scrubbed and dried","1 tablespoon olive oil","Kosher salt","1 cup cooked black beans (if canned, rinsed and drained)","1 cup shredded sharp Cheddar","Black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 425 degrees and line a sheet pan with parchment paper. Halve sweet potatoes lengthwise, then brush all over with olive oil and sprinkle both sides with salt."},{"n":2,"title":null,"text":"Place cut side down on prepared sheet and roast for 30 to 40 minutes, or until completely cooked through. Take sweet potatoes out of the oven, turn them over and let cool slightly. Use a fork to rough up the flesh and slightly flatten the potatoes. Season with salt and pepper."},{"n":3,"title":null,"text":"Divide half the cheese among the potato halves. Spoon the black beans over them, then cover with the remaining cheese. Return the pan to the oven and bake for another 5 minutes, until the cheese has melted and the beans have warmed through. Season with salt and pepper. Serve warm."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["black beans","sweet potato"],"item_tags":["cheddar"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Black Bean","Cheddar","Fall","Five Ingredient","Main Course","Roast","Side Dish","Sweet Potato","Vegetables","Vegetarian","Winter"],"issues":null,"front":"nyt_1019600.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019600-loaded-sweet-potatoes-with-black-beans-and-cheddar","rating":{"value":5,"count":7132},"date":"2018-09-21"},{"pair":1022671,"title":"Chocolate-Cherry Ginger Cookies","subtitle":null,"author":"Yossy Arefi","servings":null,"yield_text":"24 cookies","yield_count":24,"cook_time":"45 minutes","nutrition":{"calories":"166","fat":"6 g","carbohydrates":"26 g","protein":"2 g"},"description":"These are the kind of cookies that make you want to cozy up under a warm blanket with a cup of tea and a good book. Packed full of warming spices, they have soft, chewy centers and crisp edges, and are punctuated by melty puddles of milk chocolate and tart dried cherries. They come together quickly too; no need to soften butter or chill dough. Feel free to substitute dark chocolate for a more deeply chocolaty cookie, but in either case, use chopped bar chocolate and not chips for the meltiest, tastiest bites. You can also substitute dried cranberries for the cherries.","from_your_kitchen":null,"ingredients":["½ cup/100 grams turbinado sugar","¾ cup/150 grams granulated sugar","6 tablespoons/85 grams unsalted butter, melted and warm","2 tablespoons grapeseed or other neutral oil","2 tablespoons Dutch-process cocoa powder","2 ¼ teaspoons ground ginger","1 teaspoon ground cinnamon","½ teaspoon freshly grated nutmeg","¼ teaspoon ground cloves","¾ teaspoon fine salt","¼ cup/75 grams unsulfured molasses","1 large egg","1 ¾ cups/225 grams all-purpose flour","1 ¾ teaspoons baking soda","1 cup/140 grams roughly chopped milk chocolate bar","½ cup/75 grams dried cherries or cranberries, roughly chopped"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place racks in the top and bottom thirds of the oven and heat oven to 325 degrees. Line 2 sheet pans with parchment paper. Put the turbinado sugar in a shallow bowl and set aside."},{"n":2,"title":null,"text":"To a large bowl, add the granulated sugar, butter, oil, cocoa powder, ginger, cinnamon, nutmeg, cloves, and salt, and whisk to combine."},{"n":3,"title":null,"text":"Add the molasses and egg to the bowl, and whisk until smooth. Add the flour and baking soda, and stir with a rubber spatula until a few streaks of flour remain."},{"n":4,"title":null,"text":"Add the chopped chocolate and cherries, and stir until well-combined and the flour is completely incorporated and no longer streaky."},{"n":5,"title":null,"text":"Portion the cookies into 24 balls that are roughly 2 tablespoons/35 grams each, roll them in the turbinado sugar, and place them on the prepared baking sheets, 12 cookies per sheet."},{"n":6,"title":null,"text":"Bake the cookies for 15 to 17 minutes, rotating the sheets from front to back and top to bottom halfway through, until crackly on top but still quite soft in the center. Cool the cookies completely on the baking sheets, then store in an airtight container at room temperature for up to 4 days."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate","dried cherries"],"item_tags":["cinnamon","ginger","molasses","nutmeg"],"course_tags":["Dessert"],"keywords":["Bake","Cherry","Chocolate","Christmas","Christmas Cookie","Dessert","Ginger","Make-Ahead","Molasses"],"issues":null,"front":"nyt_1022671.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022671-chocolate-cherry-ginger-cookies","rating":{"value":5,"count":1278},"date":"2021-12-08"},{"pair":1021604,"title":"Flourless Beet Brownies","subtitle":null,"author":"Jerrelle Guy","servings":null,"yield_text":"9 brownies","yield_count":9,"cook_time":"40 minutes","nutrition":{"calories":"345","fat":"16 g","carbohydrates":"49 g","protein":"5 g"},"description":"Despite being flourless, these beet brownies bridge the gap between fudgy and cakey, offering the best of both worlds. Raw beets make the brownies dense and moist, helping them stay luscious and soft long after they’ve finished baking. Though the beets bring their own natural sweetness, pulsing the chopped raw beets in a food processor with some additional granulated sugar breaks down the hard root into a vibrant red base. In fact, the food processor does most of the work in this recipe. Baked until just cooked through, the resulting brownies are rich, subtly sweet and deeply chocolatey. If you prefer your brownies a little sweeter, sub the bittersweet chocolate baking chips for semi-sweet baking chips. You can top them with a little flaky sea salt out of the oven. Serve them warm with ice cream for dessert or at room temperature with a cup of coffee in the morning.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil, plus more for greasing","1 cup/70 grams unsweetened regular or Dutch-process cocoa powder","1 teaspoon baking soda","1 medium red beet (about ¼ pound), peeled and cut into ½-inch pieces","½ cup/100 grams granulated sugar","2 teaspoons vanilla extract (optional)","1 cup plus 3 tablespoons/7 ounces bittersweet or dark (60 percent cacao) baking chocolate chips","2 large eggs","Flaky sea salt, for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 350 degrees. Lightly grease an 8-by-8-inch baking pan with olive oil and set aside."},{"n":2,"title":null,"text":"In a small bowl, whisk the cocoa powder and baking soda together. Set aside."},{"n":3,"title":null,"text":"Add the chopped beets, sugar and vanilla, if using, to the bowl of a food processor, and pulse until the beets are just puréed but before they begin to liquefy, scraping down the sides of the bowl as needed."},{"n":4,"title":null,"text":"In a small microwave-safe bowl, add 1 cup/6 ounces chocolate chips and the remaining 2 tablespoons olive oil. Heat in the microwave in 15-second intervals, stirring between each round, until the chocolate is almost completely melted, up to 75 seconds total. Remove the chocolate from the microwave, stir until completely smooth, then immediately add it to the food processor. Blend it with the beets on high until smooth. Add the eggs, blend to incorporate, then add the dry ingredients and blend until just combined, stopping to scrape down the sides of the bowl as needed."},{"n":5,"title":null,"text":"Remove the blade, and using a rubber spatula, scrape the brownie batter into the prepared pan, then smooth it into an even layer. Sprinkle the remaining 3 tablespoons/1 ounce chocolate chips on top and bake until the brownies have puffed and set on top but are still a little fudgy when a toothpick is inserted inside, about 25 to 30 minutes."},{"n":6,"title":null,"text":"Remove the brownies from the oven and allow to cool for at least 30 minutes before cutting into squares and topping with flaky sea salt."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["beets","chocolate"],"item_tags":["cocoa powder","vanilla"],"course_tags":["Dessert"],"keywords":["American","Bake","Beet","Brownie","Chocolate Chip","Christmas","Cocoa Powder","Dessert","Gluten-Free","New Year’s Day","Olive Oil","Snack","Super Bowl","Valentine’s Day"],"issues":null,"front":"nyt_1021604.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021604-flourless-beet-brownies","rating":{"value":4,"count":625},"date":"2021-02-10"},{"pair":1845,"title":"Tuscan Farro Soup","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 1/2 hours","nutrition":{"calories":"558","fat":"13 g","carbohydrates":"86 g","protein":"29 g"},"description":"Simple yet amazing. This healthy soup, a kind of minestrone with farro, is ubiquitous in Lucca, a city in Tuscany. The farro is traditional, but you could use spelt or barley with good results.","from_your_kitchen":null,"ingredients":["2 tablespoons extra virgin olive oil","1 large onion, sliced","2 celery stalks, trimmed and chopped","2 carrots, peeled and chopped","Salt and pepper","1 tablespoon minced garlic","1 cup farro, spelt or barley","1 cup dried white beans, soaked for several hours or overnight","2 cups chopped tomatoes (canned are fine; do not drain)","6 cups stock or water, more as necessary","¼ cup chopped fresh parsley","¼ cup chopped fresh basil, optional","Freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put oil in a large, deep saucepan over medium heat; a minute later add onion, celery, carrots, a large pinch of salt and some pepper. Cook until vegetables are glossy and onion is softened, 5 to 10 minutes. Add garlic, and stir; add farro, beans, tomatoes and stock, and stir."},{"n":2,"title":null,"text":"Bring to a boil, then adjust heat so mixture simmers steadily. Cook until farro and beans are tender, at least an hour, adding stock or water as necessary if mixture becomes too thick. Stir in parsley and basil (if using), then cook another 5 minutes. Taste and adjust seasoning, then serve with lots of Parmesan."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["farro","tomato","white beans"],"item_tags":["basil","parmesan"],"course_tags":["Dinner"],"keywords":["Boil","Dinner","Farro","Great Leftovers","Italian","Main Course","Plan-Ahead","Saute","Soup","Tomato","Vegetarian","Weeknight","White Bean"],"issues":null,"front":"nyt_1845.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1845-tuscan-farro-soup","rating":{"value":5,"count":7190},"date":"2004-12-01"},{"pair":1022771,"title":"Peppermint Brownie Cookies","subtitle":null,"author":"Vaughn Vreeland","servings":null,"yield_text":"12 cookies","yield_count":12,"cook_time":"40 minutes","nutrition":{"calories":"265","fat":"13 g","carbohydrates":"38 g","protein":"3 g"},"description":"Brownies can be contentious. You may be an edge person or someone who loves middle pieces, a fudgy fanatic or a cakey purist. These cookies will please all brownie lovers, with chewy edges, tender centers and crunch from crushed peppermint candies. While any unsweetened cocoa powder will work in this recipe, Dutch-processed cocoa will make the cookies taste more chocolaty and round out their peppermint flavor. Whisking the eggs and sugars for a long time may seem fussy, but this process gives the cookie body, makes the batter easier to scoop and ensures a shiny top, the hallmark of any good brownie.","from_your_kitchen":null,"ingredients":["4 ounces/113 grams semisweet chocolate, finely chopped (¾ cup)","½ cup/42 grams unsweetened cocoa powder, preferably Dutch-processed","½ cup/113 grams unsalted butter","2 large eggs, at room temperature","¾ cup/150 grams granulated sugar","½ packed cup/107 grams dark brown sugar","1 teaspoon kosher salt (Diamond Crystal)","1 ½ teaspoons peppermint extract","¾ cup/90 grams all-purpose flour","¼ cup/41 grams crushed peppermint candy"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 350 degrees. Line 2 baking sheets with parchment paper."},{"n":2,"title":null,"text":"Put chocolate and ¼ cup/21 grams cocoa powder in a small heatproof bowl or glass measuring cup. Melt butter in a skillet or saucepan over medium-low heat until bubbly but not browned, and pour over the chocolate. Without stirring, let the mixture sit so the residual heat can melt the chocolate thoroughly while you whip the eggs and sugar."},{"n":3,"title":null,"text":"Put the eggs, both sugars and the salt in the bowl of a stand mixer fitted with a whisk attachment. Whisk on medium-high speed until the mixture is pillowy and the sugars have begun to dissolve, 6 to 8 minutes."},{"n":4,"title":null,"text":"Stir the chocolate mixture until glossy and smooth. If any solid pieces remain, you can microwave the mixture in 10-second bursts until everything is melted."},{"n":5,"title":null,"text":"With the mixer on low speed, add the peppermint extract and then the chocolate mixture. Scrape the sides and bottom of the bowl with a spatula, then add the flour and remaining ¼ cup/21 grams cocoa, and mix on low until a few streaks of flour and cocoa remain. Use the spatula to finish folding in the dry ingredients to avoid overmixing. The dough will be looser than traditional cookie dough but not as thin as brownie batter."},{"n":6,"title":null,"text":"Use a ¼-cup cookie scoop or measuring cup to scoop 12 (2-ounce) balls of batter onto the prepared sheets and bake. After 10 minutes, take the sheets out of the oven and bang them once on the counter to create a craggy surface and dense texture. Sprinkle a bit of crushed peppermint candy in the center of each cookie and return to the oven for another 2 minutes."},{"n":7,"title":null,"text":"Let cool completely on the baking sheets. The cookies will keep for 4 days in an airtight container at room temperature."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate","peppermint"],"item_tags":["brown sugar","cocoa powder"],"course_tags":["Dessert"],"keywords":["Bake","Christmas","Christmas Cookie","Cocoa Powder","Cookie","Dessert","Make-Ahead","Peppermint Candy","Peppermint Extract","Semisweet Chocolate","Winter"],"issues":null,"front":"nyt_1022771.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022771-peppermint-brownie-cookies","rating":{"value":5,"count":4205},"date":"2021-12-08"},{"pair":1014809,"title":"Lentil Salad With Fresh Favas","subtitle":null,"author":"Martha Rose Shulman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"About 2 hours","nutrition":{"calories":"352","fat":"12 g","carbohydrates":"50 g","protein":"18 g"},"description":"According to Jo Robinson, a food and nutrition writer whose informative new book, Eating on the Wild Side,” cites a federal survey of phytonutrient content of common fruits and vegetables, lentils have the most antioxidant activity of all legumes, with black beans a close second.","from_your_kitchen":null,"ingredients":["1 cup lentils, rinsed and picked over","3 large garlic cloves, 2 of them crushed and left in the skin, 1 of them minced","½ onion, intact","1 bay leaf","Salt to taste","1 tablespoon fresh lemon juice","2 tablespoons red wine vinegar or cider vinegar","3 tablespoons extra virgin olive oil","1 teaspoon cumin seeds, lightly toasted and ground","½ teaspoon mild chili powder or Aleppo pepper","Freshly ground black pepper to taste","½ pound fresh fava beans, shelled and skinned","2 medium tomatoes, in season only, diced","¼ cup diced celery","¼ cup chopped flat-leaf parsley","¼ cup chopped fresh mint","1 bunch scallions, chopped"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place the lentils, whole crushed garlic cloves, onion half and bay leaf in a large, heavy saucepan and cover by 1 inch with water. Bring to a boil, add salt to taste, reduce the heat, cover and simmer until lentils are tender but still firm, about 30 minutes. Remove from the heat, remove the lid and allow the lentils to cool for 30 minutes. Remove and discard the onion. Remove the garlic cloves and squeeze the cooked garlic out of the skins and back into the lentils. Drain off any liquid remaining in the pot."},{"n":2,"title":null,"text":"Transfer the lentils to a large bowl. Whisk together the lemon juice, vinegar, salt to taste, cumin, chili powder or Aleppo pepper, freshly ground pepper and olive oil. Toss with the lentils. Add the remaining ingredients and toss together. Let marinate in the refrigerator for at least 30 minutes before serving."}],"tips":["Advanced preparation: The salad will be good for 2 to 3 days, but the color of the favas will fade."],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["fava beans","lentils"],"item_tags":["cumin","mint","parsley"],"course_tags":["Lunch","Sides & Appetizers"],"keywords":["Boil","Dairy-Free","Fava Bean","Gluten-Free","Healthy","High Fiber","Lentil","Low-Sodium","Marinate","Salad","Summer","Vegan","Vegetarian"],"issues":null,"front":"nyt_1014809.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014809-lentil-salad-with-fresh-favas","rating":{"value":4,"count":61},"date":"2013-06-18"},{"pair":1024036,"title":"Thai-Style Crunchy Vegetable Salad","subtitle":null,"author":"Kay Chun","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"174","fat":"11 g","carbohydrates":"17 g","protein":"5 g"},"description":"Inspired by Thai green papaya salad, this vibrant dish boasts a colorful medley of thinly sliced raw veggies; they’re electrified by a lime-and-fish sauce vinaigrette. This recipe builds upon a base of fresh asparagus, which is supercrisp, with a sweet, mildly grassy flavor, and cherry tomatoes. You can combine them with any mix of vegetables that are on hand: Radishes, cucumbers, carrots, snap peas, cabbage and yellow bell peppers are all great additions, each bringing their unique flavor and texture to the party. The just-tossed salad is bright and crunchy, but if you happen to wind up with leftovers, let the vegetables marinate in the dressing overnight and they transform into a pickled side dish that’s delightful in sandwiches or with grilled steak.","from_your_kitchen":null,"ingredients":["3 tablespoons extra-virgin olive oil","2 tablespoons lime juice","1 tablespoon fish sauce","1 tablespoon minced shallot","½ teaspoon minced garlic","1 bird’s eye or serrano chile, thinly sliced","Kosher salt (such as Diamond Crystal) and pepper","8 ounces asparagus, trimmed, halved lengthwise and thinly sliced at an angle","4 ounces cherry tomatoes, halved","3 cups thinly sliced mixed vegetables (such as carrots, radishes and cucumbers)","½ cup cilantro leaves and tender stems, coarsely chopped"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, combine oil, lime juice, fish sauce, shallot, garlic and chile; season with salt and pepper. Whisk well."},{"n":2,"title":null,"text":"Add the asparagus, tomatoes and other mixed vegetables and season with salt and pepper. Toss to evenly coat and let stand at room temperature for 5 minutes, tossing occasionally."},{"n":3,"title":null,"text":"Fold in cilantro and serve."}],"tips":[],"cuisine_tags":["Thai"],"ingredient_tags":["asparagus","tomato"],"item_tags":["cilantro","fish sauce","lime","shallot"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Asparagus","Cherry Tomato","Cilantro","Dinner","Easy","Fish Sauce","Healthy","Lime Juice","Lunch","No Cook","Quick","Salad","Serrano","Side Dish","Spring","Summer","Vegetables","Weeknight"],"issues":null,"front":"nyt_1024036.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1024036-thai-style-crunchy-vegetable-salad","rating":{"value":4,"count":876},"date":"2023-04-25"},{"pair":1016062,"title":"Red Lentil Soup","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"296","fat":"11 g","carbohydrates":"39 g","protein":"13 g"},"description":"This is a lentil soup that defies expectations of what lentil soup can be. Based on a Turkish lentil soup, mercimek corbasi, it is light, spicy and a bold red color (no murky brown here): a revelatory dish that takes less than an hour to make. The cooking is painless. Sauté onion and garlic in oil, then stir in tomato paste, cumin and chile powder and cook a few minutes more to intensify flavor. Add broth, water, red lentils (which cook faster than their green or black counterparts) and diced carrot, and simmer for 30 minutes. Purée half the mixture and return it to the pot for a soup that strikes the balance between chunky and pleasingly smooth. A hit of lemon juice adds an up note that offsets the deep cumin and chile flavors.","from_your_kitchen":null,"ingredients":["3 tablespoons olive oil, plus more for drizzling","1 large onion, chopped","2 garlic cloves, minced","1 tablespoon tomato paste","1 teaspoon ground cumin","Salt and black pepper","Pinch of chili powder or ground cayenne, plus more to taste","1 quart chicken or vegetable broth","1 cup red lentils","1 large carrot, peeled and diced","Juice of ½ lemon, more to taste","3 tablespoons chopped fresh cilantro"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large pot, heat 3 tablespoons oil over high until hot and shimmering. Add onion and garlic, and sauté until golden, about 4 minutes."},{"n":2,"title":null,"text":"Stir in tomato paste, cumin, ¼ teaspoons each salt and black pepper and the chili powder, and sauté for 2 minutes longer."},{"n":3,"title":null,"text":"Add broth, 2 cups water, lentils and carrot. Bring to a simmer, then partly cover pot and turn heat to medium-low. Simmer until lentils are soft, about 30 minutes. Taste and add salt if necessary."},{"n":4,"title":null,"text":"Using an immersion or regular blender or a food processor, purée half the soup, then add it back to pot. The soup should be somewhat chunky."},{"n":5,"title":null,"text":"Reheat soup if necessary, then stir in lemon juice and cilantro. Serve soup drizzled with good olive oil and dusted lightly with chili powder, if desired."}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["carrot","red lentils"],"item_tags":["cilantro","cumin","lemon"],"course_tags":["Lunch","Sides & Appetizers"],"keywords":["Appetizer","Easy","Food Processor","Freezer Friendly","Great Leftovers","Lunch","Quick","Red Lentil","Soup","Vegan","Vegetarian"],"issues":null,"front":"nyt_1016062.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016062-red-lentil-soup","rating":{"value":5,"count":41747},"date":"2008-01-09"},{"pair":1020839,"title":"Vegetarian Swedish Meatballs","subtitle":null,"author":"Kay Chun","servings":null,"yield_text":"2 dozen meatballs","yield_count":24,"cook_time":"50 minutes","nutrition":{"calories":"87","fat":"3 g","carbohydrates":"11 g","protein":"4 g"},"description":"Cremini mushrooms, chickpeas and bulgur wheat mimic the texture of ground meat in this vegetarian version of the classic Swedish meatball dish. Seasoned generously with allspice and nutmeg and blanketed in a velvety mushroom gravy, they are excellent served over egg noodles or mashed potatoes — or spooned onto a toasted hero (add sliced tangy pickles to balance out the richness). Leftover cooked meatballs can be frozen and reheated in a 425-degree oven until warmed through, about 15 minutes.","from_your_kitchen":null,"ingredients":["2 tablespoons bulgur wheat","4 cremini mushrooms, stemmed and quartered","1 (15-ounce) can chickpeas, rinsed (about 1 ½ cups)","⅓ cup plain bread crumbs","¼ cup sour cream","1 large egg","1 ½ teaspoons kosher salt","¾ teaspoon ground allspice","½ teaspoon black pepper","½ teaspoon onion powder","½ teaspoon freshly ground nutmeg","Canola oil, for greasing","2 tablespoons unsalted butter","2 tablespoons all-purpose flour","1 ½ cups mushroom stock (or vegetable stock)","1 tablespoon sour cream","1 tablespoon finely chopped fresh parsley","1 teaspoon Dijon mustard","Kosher salt and freshly ground black pepper"],"ingredient_groups":[{"at":0,"title":"FOR THE MEATBALLS"},{"at":12,"title":"FOR THE GRAVY"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the meatballs: Heat oven to 375 degrees. Bring ¼ cup water to a boil in a small saucepan. Add the bulgur, remove from heat, cover and let sit until tender, 15 minutes. Drain, pressing to remove excess water. Cool."},{"n":2,"title":null,"text":"Meanwhile, in a food processor, pulse mushrooms until finely chopped with some pea-size pieces remaining (do not purée); transfer to a large bowl. Repeat with the chickpeas: Pulse, then add them to the large bowl. Add the bread crumbs, sour cream, egg, salt, allspice, pepper, onion powder, nutmeg and the cooled bulgur and mix until well blended. Form into 1 ¼-inch meatballs (about 2 teaspoons each; you should have about 24). Arrange on a greased baking sheet and bake, turning halfway, until golden, 18 to 20 minutes."},{"n":3,"title":null,"text":"Make the gravy: While the meatballs bake, in a large nonstick saucepan, melt butter over medium heat. Add flour and cook, whisking constantly, until smooth and lightly golden, 2 minutes. Add stock and bring to a simmer. Cook, whisking, until thickened, 2 minutes. Whisk in sour cream, parsley and mustard; season to taste with salt and pepper (you should have about 1 cup gravy). Add meatballs and simmer, spooning sauce over meatballs, until nicely coated, about 2 minutes more. Serve warm."}],"tips":[],"cuisine_tags":["Comfort Food","Scandinavian"],"ingredient_tags":["chickpeas","mushrooms"],"item_tags":["allspice","dijon mustard","nutmeg","sour cream"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Allspice","American","Appetizer","Bake","Bread Crumb","Chickpea","Dinner","Fall","Finger Foods","Great Leftovers","Main Course","Meatballs","Mushroom","Nutmeg","Side Dish","Vegetables","Vegetarian","Winter"],"issues":null,"front":"nyt_1020839.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020839-vegetarian-swedish-meatballs","rating":{"value":4,"count":1922},"date":"2020-01-28"},{"pair":1015487,"title":"Seven Vegetable Couscous","subtitle":null,"author":"Tara Parker-Pope","servings":"8","yield_text":"8 servings","yield_count":8,"cook_time":"1 hour","nutrition":{"calories":"305","fat":"7 g","carbohydrates":"53 g","protein":"10 g"},"description":"Seven-vegetable couscous is a well-known offering at Sephardic Jewish New Year celebrations, but since it's a bountiful, colorful tribute to the harvest, it makes a great meat-free main dish for Thanksgiving as well. Despite the long ingredient list, it's as easy as can be to make. Tara Parker-Pope","from_your_kitchen":null,"ingredients":["1 ½ cups couscous, uncooked","1 tablespoon vegan margarine","1 teaspoon turmeric","1 teaspoon salt","2 tablespoons extra-virgin olive oil","2 medium onions, chopped","1 cup finely shredded white cabbage","1 medium turnip, peeled and diced","1 medium yellow summer squash, halved lengthwise and thinly sliced","1 medium zucchini, halved lengthwise and thinly sliced","1 15- to 16-ounce can chickpeas, drained and rinsed","1 ½ cups diced ripe tomatoes","2 teaspoons grated fresh or jarred ginger, or more, to taste","1 teaspoon ground cumin","½ teaspoon ground coriander","Dried hot red pepper flakes, to taste, optional","Salt and freshly ground pepper, to taste","½ cup golden raisins (for garnish)","⅓ cup minced fresh parsley (for garnish)","Sliced or slivered toasted almonds (for garnish)"],"ingredient_groups":[{"at":17,"title":"GARNISH"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Combine the couscous and 3 cups boiling water in a heatproof bowl. Cover and let stand until the water is absorbed, about 15 minutes. Fluff with a fork, then stir in the margarine, turmeric and salt. Cover and set aside."},{"n":2,"title":null,"text":"For the vegetable stew, heat the oil in a large saucepan or soup pot. Add the onions and sauté over medium heat until translucent. Stir in cabbage and sauté until both it and the onion are lightly golden."},{"n":3,"title":null,"text":"Add the remaining stew ingredients. Bring to a simmer, then cover and reduce the heat to medium-low. Cook, stirring occasionally, for 15 to 20 minutes. Add water as needed to produce a moist, but not soupy, consistency. The vegetables should be just tender, but still firm."},{"n":4,"title":null,"text":"To serve, arrange the couscous on the outer edge of a large serving platter and make a well in the center. Pour the vegetable mixture in the center, then sprinkle with the garnishes, topping with sliced or slivered toasted almonds. Let each guest place a mound of couscous on his or her dinner plate and top it with the vegetable mixture."}],"tips":[],"cuisine_tags":["Jewish","Moroccan"],"ingredient_tags":["chickpeas","couscous","turnip","zucchini"],"item_tags":["coriander","cumin","golden raisins","turmeric"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Cabbage","Chickpea","Couscous","Dairy-Free","Dinner","Golden Raisin","Lunch","Main Course","Pastas","Side Dish","Thanksgiving","Tomato","Turnip","Vegan","Vegetarian","Zucchini"],"issues":null,"front":"nyt_1015487.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015487-seven-vegetable-couscous","rating":{"value":4,"count":363},"date":"2011-11-30"},{"pair":1017523,"title":"Zucchini Parmesan","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"About 1½ hours","nutrition":{"calories":"224","fat":"15 g","carbohydrates":"15 g","protein":"11 g"},"description":"This is a simple layered casserole with three elements: roasted zucchini, a really good homemade tomato sauce and Parmesan. Roasting, rather than frying the zucchini, allows you to cut down on olive oil and time.","from_your_kitchen":null,"ingredients":["2 to 2½ pounds fresh ripe tomatoes","1 tablespoon extra-virgin olive oil","1 small onion, chopped","2 to 4 garlic cloves (to taste)","Salt and pepper","⅛ teaspoon sugar","2 sprigs fresh basil","1 tablespoon chopped fresh basil","2 to 2¼ pounds zucchini","Salt and pepper","3 tablespoons extra-virgin olive oil","½ to 1 teaspoon red pepper flakes (pepperoncini), to taste","¾ cup freshly grated Parmesan"],"ingredient_groups":[{"at":0,"title":"FOR THE TOMATO SAUCE"},{"at":8,"title":"FOR THE ZUCCHINI PARMESAN"}],"tools":null,"steps":[{"n":1,"title":null,"text":"If you have a food mill, quarter tomatoes. If not, peel, seed and chop them. (See step 5.)"},{"n":2,"title":null,"text":"To make tomato sauce, heat 1 tablespoon olive oil in a large, heavy skillet over medium heat and add onion. Cook, stirring often, until tender, about 5 minutes."},{"n":3,"title":null,"text":"Add garlic. Cook, stirring, until fragrant, 30 seconds to a minute, and add tomatoes, salt, pepper, sugar and basil sprigs. Increase heat to medium-high. When tomatoes are bubbling briskly, stir and reduce heat to medium. Cook, stirring often, until tomatoes have cooked down and are beginning to stick to pan, 15 to 25 minutes, depending on consistency. Remove basil sprigs; taste and adjust seasoning."},{"n":4,"title":null,"text":"Heat oven to 450 degrees. Line 2 sheet pans with parchment. Trim ends off zucchini and cut in half crosswise, then into lengthwise slices, about ¼ to ⅓ inch thick. Season on both sides with salt and pepper and toss with 2 tablespoons olive oil. Arrange zucchini slices on baking sheets in one layer and sprinkle with red pepper flakes. Roast for 12 minutes, until lightly browned and easily pierced with a knife. Remove from oven and reduce heat to 375 degrees."},{"n":5,"title":null,"text":"If using a food mill, put sauce through medium blade. If not, pulse sauce in a food processor fitted with steel blade until just coarsely puréed. Stir in chopped basil."},{"n":6,"title":null,"text":"To assemble the dish, oil a 2-quart gratin with olive oil. Spread ¼ cup tomato sauce over bottom of dish. Arrange a third of the zucchini in an even layer over tomato sauce. Spoon a third of remaining sauce over zucchini and sprinkle with ¼ cup Parmesan. Repeat with 2 more layers, ending with ¼ cup Parmesan. Drizzle on remaining tablespoon olive oil. Bake 30 to 35 minutes, until bubbling and browned on the top and edges. Remove from heat and allow to sit for 5 to 10 minutes before serving."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["tomato","zucchini"],"item_tags":["basil","parmesan","red chile flakes"],"course_tags":["Dinner","Lunch"],"keywords":["Bake","Casseroles","Dinner","Italian","Lunch","Main Course","Roast","Simmer","Tomato","Zucchini"],"issues":null,"front":"nyt_1017523.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017523-zucchini-parmesan","rating":{"value":5,"count":4963},"date":"2015-07-15"},{"pair":1022302,"title":"Dulce de Leche Icebox Cake","subtitle":null,"author":"Laurie Ellen Pellicano","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"30 minutes, plus 6 hours’ chilling","nutrition":{"calories":"339","fat":"23 g","carbohydrates":"30 g","protein":"4 g"},"description":"Icebox cake, so named because it sets in the fridge or freezer, comes together with a little mixing and stacking. All it needs after that is time to chill, making it ideal for hot days. This version combines store-bought sandwich cookies with dulce de leche whipped cream for a cookies-and-cream meets salted caramel flavor. If you’d like, garnish with crumbled cookies.","from_your_kitchen":null,"ingredients":["1 ½ cups heavy cream","1 cup crème fraîche or sour cream","½ teaspoon fine sea salt","2 tablespoons granulated sugar","⅓ cup store-bought or homemade dulce de leche","1 (10-ounce) pack (about 40) thin chocolate sandwich cookies (such as Oreos)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Line a 9-by-5-inch loaf pan with a double layer of plastic wrap, pressing it into the corners and leaving several inches of overhang on each side."},{"n":2,"title":null,"text":"In a large bowl and with an electric mixer, beat together the heavy cream, crème fraîche and salt on medium-high until stiff peaks form, 3 to 5 minutes. Transfer 2 cups of the whipped cream to a medium bowl and stir in the sugar. Add the dulce de leche to the remaining whipped cream in the large bowl and beat on medium-high for 1 to 2 minutes until stiff peaks form. Season to taste with more salt."},{"n":3,"title":null,"text":"Using a spoon, flick small dollops of both cream mixtures across the bottom and sides of your lined pan. Using a spatula, smooth it into a ¼-inch layer along the edges and bottom."},{"n":4,"title":null,"text":"Cover the bottom with 8 cookies, gently pressing them into the cream. Flick more small dollops of both cream mixtures across the surface of the cookies, then smooth the surface."},{"n":5,"title":null,"text":"Press a row of cookies upright along the long edge of the pan. Generously scoop the whipped creams using the cookies, alternating flavors, and press them upright against the vertical row. Continue forming rows until the pan is full. Tap the pan against the counter to settle the cookies into the cream. Cover the cookies by flicking the remaining cream across the surface, then smooth it out."},{"n":6,"title":null,"text":"Enclose the loaf in the plastic overhang and freeze until completely firm, at least 6 hours. The cake will keep frozen for up to 1 month. To serve, unwrap the top of the loaf, invert the loaf onto a platter, remove the pan and plastic and slice with a serrated knife."}],"tips":[],"cuisine_tags":["American","Latin American"],"ingredient_tags":["chocolate cookies","dulce de leche"],"item_tags":["cream","crème fraîche"],"course_tags":["Dessert"],"keywords":["American","Crème Fraîche","Dessert","Five Ingredient","Heavy Cream","Icebox Cake","Oreo Cookie"],"issues":null,"front":"nyt_1022302.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022302-dulce-de-leche-icebox-cake","rating":{"value":4,"count":779},"date":"2021-06-07"},{"pair":1022465,"title":"One-Pot Orzo With Tomatoes, Corn and Zucchini","subtitle":null,"author":"Lidey Heuck","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"283","fat":"14 g","carbohydrates":"27 g","protein":"12 g"},"description":"This recipe is inspired by the tail end of summer, when fresh produce and herbs abound but the heat waves are finally starting to relent. And while this dish makes a wonderful stage for the season’s produce at its peak, it can also turn sad-looking February vegetables into a sauce that makes it feel like summer. The trick is to sauté the tomatoes slowly, until they’ve collapsed and become deeply sweet and fragrant. The orzo cooks right in the sauce, which cuts down on the dishes and allows the pasta to absorb the flavor as it cooks. If you prefer a larger pasta shape, stick to the traditional method of boiling pasta for best results, and save some pasta water to help loosen the sauce. To get vegetarian recipes like this one delivered to your inbox, sign up for The Veggie newsletter.","from_your_kitchen":null,"ingredients":["3 tablespoons olive oil","1 Vidalia or yellow onion, chopped","1 ½ teaspoons kosher salt, plus more for seasoning","Black pepper, to taste","1 medium zucchini (about 8 ounces), halved lengthwise, seeded and ½-inch diced","3 garlic cloves, minced","2 pints cherry tomatoes, halved","⅓ cup torn fresh basil leaves, plus more for serving","¼ teaspoon red-pepper flakes, plus more to taste","2 tablespoons balsamic vinegar","1 tablespoon tomato paste","1 ¼ cups orzo","Kernels from one ear of corn (about ½ cup)","1 cup torn or medium-diced fresh mozzarella (about 5 ounces)","¼ cup grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat olive oil in a large (12-inch) skillet, for which you have a lid, set over medium. And the onions, lightly season with salt and pepper, and cook, stirring occasionally, until tender, about 8 minutes. Turn the heat to medium-low, add the zucchini and garlic, and cook for 2 more minutes, stirring often."},{"n":2,"title":null,"text":"Add the tomatoes, basil, red-pepper flakes, 1 teaspoon salt and black pepper to taste. Cook, stirring occasionally, until the tomatoes have completely collapsed, 12 to 15 minutes. Add the balsamic vinegar and tomato paste and cook for 2 more minutes, stirring occasionally."},{"n":3,"title":null,"text":"Add 2 ½ cups water and bring to a simmer over medium heat. Add the orzo, corn, and ½ teaspoon salt, mix well, and turn the heat to low. Cover and simmer for 10 to 12 minutes, stirring and scraping the bottom of the pan 3 or 4 times, until the pasta is cooked. The pasta should look “saucy” as it cooks; if at any point it looks dry, add another ¼ cup water."},{"n":4,"title":null,"text":"Off the heat, add the mozzarella and Parmesan and stir gently until just combined. Top with fresh basil and more red-pepper flakes if desired, and serve hot."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["corn","orzo","tomato","zucchini"],"item_tags":["basil","mozzarella","parmesan","red chile flakes"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Basil","Cherry Tomato","Corn","Dinner","Easy","Lunch","Main Course","Mozzarella","Orzo","Pastas","Side Dish","Skillet","Summer","Vegetarian","Zucchini"],"issues":null,"front":"nyt_1022465.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022465-one-pot-orzo-with-tomatoes-corn-and-zucchini","rating":{"value":5,"count":4911},"date":"2021-08-10"},{"pair":1022250,"title":"Blueberry Poppy Seed Cake","subtitle":null,"author":"Yossy Arefi","servings":null,"yield_text":"One 9-inch round or 8-inch square cake","yield_count":1,"cook_time":"1 1/4 hours, plus cooling","nutrition":null,"description":"This simple one-bowl recipe highlights blueberries and poppy seeds in a fluffy vanilla- and almond-scented batter that comes together in a flash. It travels well, which makes it a perfect picnic dessert or beach snack, and it’s just as good for breakfast the next day. The combination of butter and oil gives the cake great flavor, but, more important, keeps it moist for days on the counter. For those who are not fans of almond extract, feel free to leave it out and replace it with more vanilla extract.","from_your_kitchen":null,"ingredients":["Nonstick cooking spray","¾ cup/150 grams granulated sugar","¼ cup/62 grams unsalted butter, softened","¼ cup/60 milliliters canola or other neutral oil","2 large eggs","¾ cup/165 grams sour cream","1 ¼ teaspoons almond extract (optional)","1 teaspoon vanilla extract","¾ teaspoon kosher salt (Diamond Crystal)","1 ½ cups/190 grams all-purpose flour","1 ½ teaspoons baking powder","¼ teaspoon baking soda","3 tablespoons poppy seeds","1 ⅓ cups/186 grams fresh blueberries","1 tablespoon turbinado sugar"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Set a rack in the center of the oven and heat oven to 350 degrees. Spray an 8-inch square pan or 9-inch round pan with cooking spray and line the base with parchment paper."},{"n":2,"title":null,"text":"In a large bowl, with an electric mixer on medium-high, beat the granulated sugar, butter and oil until light and fluffy, about 3 minutes. Add the eggs and beat until well combined, then add the sour cream, almond extract (if using), vanilla extract and salt. Beat until well combined."},{"n":3,"title":null,"text":"Add the flour, baking powder, baking soda and poppy seeds. Mix on low speed until just combined, then fold in 1 cup/140 grams blueberries with a rubber spatula. Pour the batter into the prepared baking pan. Sprinkle the remaining ⅓ cup/46 grams blueberries on top, then sprinkle on the turbinado sugar."},{"n":4,"title":null,"text":"Bake until golden and puffed, and a tester inserted into the center comes out clean, 35 to 45 minutes."},{"n":5,"title":null,"text":"Let the cake cool in the pan on a wire rack for 15 minutes, then invert the cake onto the rack and remove the parchment paper. Place a plate or another wire rack on top of the cake and invert it again so the sugared side is up. The cake will keep loosely wrapped at room temperature for up to 3 days."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["blueberries","poppy seeds"],"item_tags":["almond extract","sour cream","vanilla"],"course_tags":["Breakfast","Dessert"],"keywords":["Blueberry","Breakfast","Dessert","Easy","Make-Ahead","One Bowl","Picnic","Poppy Seed","Sour Cream"],"issues":null,"front":"nyt_1022250.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022250-blueberry-poppy-seed-cake","rating":{"value":4,"count":677},"date":"2021-05-17"},{"pair":1020217,"title":"Cucumber Salad With Roasted Peanuts and Chile","subtitle":null,"author":"Sue Li","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"15 minutes","nutrition":{"calories":"152","fat":"11 g","carbohydrates":"10 g","protein":"6 g"},"description":"Easy to assemble but far from basic, this cucumber salad delivers a riot of flavors and textures with snappy cucumbers, velvety peanut sauce, crunchy cilantro-peanut topping and zingy chile oil. The details make all the difference: First, salting the cucumbers mutes the fruit’s subtly bitter notes while heightening flavor. Next, the simple peanut sauce adds richness to the cool cucumbers. (Make a large batch and store it in the fridge to drizzle over vegetables, chicken and salads.) Finally, a flurry of finely chopped peanuts, cilantro and red-pepper flakes gets dusted over the salad in layers to disperse flavor.","from_your_kitchen":null,"ingredients":["6 Persian cucumbers (about 1 pound), cut lengthwise into thin spears, then cut crosswise into 2-inch pieces","Kosher salt (such as Diamond Crystal)","¼ cup salted, roasted peanuts","¼ cup cilantro leaves","1 teaspoon red-pepper flakes","3 tablespoons natural unsalted peanut butter","2 tablespoons soy sauce","2 tablespoons unseasoned rice vinegar","1 teaspoon granulated sugar","1 small garlic clove, grated","Chile oil, store-bought or homemade, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Toss cucumbers with ½ teaspoon kosher salt in a colander. Set aside to drain."},{"n":2,"title":null,"text":"Chop peanuts, cilantro and red-pepper flakes together until very fine. Set aside."},{"n":3,"title":null,"text":"In a large bowl, whisk together peanut butter, soy sauce, rice vinegar, sugar, garlic and ½ teaspoon kosher salt. Add up to 1 tablespoon water, if needed, to thin mixture. Transfer salted cucumbers to the bowl with dressing and toss to coat."},{"n":4,"title":null,"text":"To serve, place half of the cucumber salad on the plate, sprinkle with half of the peanut mixture. Repeat with the remaining cucumber salad and peanut mixture. Drizzle with chile oil, if using, and serve immediately."}],"tips":[],"cuisine_tags":["Thai"],"ingredient_tags":["cucumber","peanuts"],"item_tags":["chile oil","cilantro","peanut butter","red chile flakes","rice vinegar"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["American","Appetizer","Asian","Cilantro","Cucumber","Dinner","Easy","No Cook","Peanut","Peanut Butter","Quick","Salad","Side Dish","Snack","Vegetables","Weeknight"],"issues":null,"front":"nyt_1020217.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020217-cucumber-salad-with-roasted-peanuts-and-chile","rating":{"value":5,"count":4591},"date":"2019-05-06"},{"pair":1019214,"title":"Mango Royale","subtitle":null,"author":"Ligaya Mishan","servings":null,"yield_text":"One 9 1/2-inch pie","yield_count":9,"cook_time":"30 minutes, plus freezing and thawing","nutrition":null,"description":"For the chef Isa Fabro of IsaMADE in Los Angeles, the use of super-ripe Manila mangoes (native to the Philippines) is central to this no-bake dessert, as the fruit has a unique deep honey taste, a creamy texture with virtually no fibers, and a heavy aroma. If using Kent or Haden mangoes, remove any excess fiber and add lime; the extra acid complements their flavor, but will compete with the Manila mangoes. As long as the mangoes are super-ripe, even over-ripe, the dish will be fine. If not, the mango flavor will become dulled and lost in the cold of the freezer. If ripe mangoes aren’t available, frozen ones can be used once defrosted. Ligaya Mishan","from_your_kitchen":null,"ingredients":["¾ cups/170 grams unsalted butter (1 ½ stick)","2 sleeves/269 grams graham crackers (about 9 ½ ounces)","2 cups heavy whipping cream","½ cup sweetened condensed milk","6 to 8 soft ripe Manila mangoes (a.k.a. Ataulfo or Champagne) or 3 to 4 soft ripe large mangoes (Haden or Kent)","1 to 2 tablespoons lime juice (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a small pan, melt the butter over medium heat. Cook the butter, occasionally scraping the pan, until it turns deep golden brown, being careful not to let it burn. Remove from the heat and let cool."},{"n":2,"title":null,"text":"Pulse crackers in a food processor until finely ground. Pour into a medium bowl and add brown butter. Mix until well combined and texture is like wet sand. Let cool."},{"n":3,"title":null,"text":"Generously spray a 9 ½-inch glass pie plate with cooking spray. In a stand mixer fitted with the whisk attachment, pour the cream into the mixing bowl and whip on medium speed. Slowly drizzle in sweetened condensed milk, then beat to stiff peaks. (Beating on medium takes longer, but helps build a stable structure.) Set aside and chill until ready to use."},{"n":4,"title":null,"text":"Cut cheeks from mangoes parallel to center pits. Scoop out flesh from cheeks with a spoon and slice flesh from pits. Coarsely purée fruit in a clean food processor. Measure 2 cups (save extra for other uses). If you like, add lime juice so purée tastes sweet-tart."},{"n":5,"title":null,"text":"Sprinkle about ⅔ of the graham crumbs into the pie plate. Using your fingers and the palm of your hand, press to create an even layer on the bottom and sides of the plate."},{"n":6,"title":null,"text":"Dollop half the whipped cream mixture on top, carefully spreading the cream evenly without stirring up crumbs. Spoon half of the mango purée on top and spread evenly."},{"n":7,"title":null,"text":"Sprinkle all but a few tablespoons of the remaining crumbs on top. Repeat cream and mango layers. Sprinkle top with remaining crumbs but don't smooth down."},{"n":8,"title":null,"text":"Loosely wrap dessert with plastic wrap and freeze until firm, about 8 hours, or overnight. Can be made ahead up to this point and kept frozen for 2 weeks."},{"n":9,"title":null,"text":"To serve, let thaw in fridge the night before serving, or let stand at room temperature for 45 minutes to 1 hour. Serve in wedges or scoops, making sure to scrape up the crumbs from the bottom of the plate."}],"tips":[],"cuisine_tags":["Filipino"],"ingredient_tags":["graham crackers","mango"],"item_tags":["condensed milk","lime"],"course_tags":["Dessert"],"keywords":["Dessert","Filipino","Freezer Friendly","Graham Cracker","Icebox Cake","Make-Ahead","Mango"],"issues":null,"front":"nyt_1019214.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019214-mango-royale","rating":{"value":4,"count":1052},"date":"2018-03-14"},{"pair":1020415,"title":"Oat Milk Chocolate Pudding","subtitle":null,"author":"Ali Slagle","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"15 minutes","nutrition":{"calories":"350","fat":"9 g","carbohydrates":"62 g","protein":"11 g"},"description":"Chocolate pudding is equal parts comfort and romance, which means it’s great accompanied by sweatpants, candlelight or both. This 15-minute version is inspired by a recipe from Alice Medrich, the cookbook author, in which she uses both cocoa powder and chocolate, and cornstarch instead of eggs for a pure chocolate flavor (eggs can dilute the subtle notes). Here, nondairy milk is swapped in for the milk and the cream with equally wonderful results. When developing this recipe, we found that oat milk created a pudding with the plushest texture. Soy, almond and coconut milks work, too, although they might impart their own flavor and the pudding texture may vary.","from_your_kitchen":null,"ingredients":["⅓ cup/65 grams granulated sugar","⅓ cup/30 grams unsweetened cocoa powder","2 tablespoons cornstarch","⅛ teaspoon fine sea salt","2 cups/480 milliliters nondairy milk, preferably oat","3 to 4 ounces/85 to 115 grams bittersweet bar chocolate, finely chopped (see Tip 1)","1 teaspoon vanilla extract"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a medium saucepan, use a wooden spoon or silicone spatula to stir together the sugar, cocoa, cornstarch and salt. Slowly stir in the milk and keep stirring until smooth and combined."},{"n":2,"title":null,"text":"Stir the mixture constantly over medium-low heat, scraping the bottom, sides and corners of the pan, until the pudding thickens, begins to bubble, and coats the back of the spoon or spatula, 5 to 10 minutes. (If the pudding is coating the bottom of the pan too quickly, reduce the heat.)"},{"n":3,"title":null,"text":"Add the chocolate and stir vigorously until the pudding is very thick and smooth, about 30 seconds longer."},{"n":4,"title":null,"text":"Remove from the heat and stir in the vanilla. Spoon the pudding into a serving bowl or individual cups or ramekins. Serve warm, at room temperature or chilled (see Tip 2). It will thicken as it cools."}],"tips":["Use 4 ounces of chocolate with 60 to 65 percent cacao, or 3 ounces of chocolate with 66 to 70 percent cacao.","Before refrigerating, press plastic wrap onto the surface of the pudding to prevent a “skin” from forming on top. The pudding will keep in the refrigerator for up to 3 days."],"cuisine_tags":["American"],"ingredient_tags":["chocolate","oat milk"],"item_tags":["cocoa powder","cornstarch","vanilla"],"course_tags":["Dessert"],"keywords":["Bittersweet Chocolate","Cocoa Powder","Cornstarch","Custards and Puddings","Dairy-Free","Dessert","Easy","Kid-Friendly","Non-Dairy Milk","Oat Milk","Quick","Vegan","Vegan Thanksgiving","Weeknight"],"issues":null,"front":"nyt_1020415.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020415-oat-milk-chocolate-pudding","rating":{"value":5,"count":6047},"date":"2019-08-21"},{"pair":1022038,"title":"Creamy Asparagus Pasta","subtitle":null,"author":"Eric Kim","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"796","fat":"38 g","carbohydrates":"94 g","protein":"22 g"},"description":"In this quick pasta dinner, umami-rich seaweed stars twice: first, in the form of dasima (dried kelp), which seasons the pasta water and sauce with seaside savor; second, as gim (roasted seaweed), which lends deep nuttiness and some salty crunch, too. The pasta finishes cooking in a blush of heavy cream and a splash of the dasima broth, transforming into a dreamy emulsion balanced by rice vinegar. In this recipe’s final moments, a rich glug of sesame oil glosses the chewy rigatoni and echoes the toasted flavor of the gim, which sings.","from_your_kitchen":null,"ingredients":["20 grams gim, often labeled as roasted seaweed","2 (4-inch) squares dasima or kombu (dried kelp)","1 tablespoon kosher salt","1 pound rigatoni","1 ½ cups heavy cream","1 small red onion, halved and thinly sliced","2 large garlic cloves, finely grated","1 teaspoon freshly ground black pepper, plus more to taste","1 teaspoon rice vinegar","½ pound asparagus, thinly sliced at an angle","1 tablespoon toasted sesame oil","Flaky sea salt, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Fold the gim in half and, with very sharp kitchen shears or a chef’s knife, slice into thin strips. Set aside for serving."},{"n":2,"title":null,"text":"In a large pot, combine 1 dasima square with 8 cups cold tap water. Bring the water to a boil and season with the kosher salt. Tumble in the pasta and cook for half the time the package tells you is al dente. Reserve 1 cup of the pasta water. Drain the pasta, then add it back to the pot. (Discard the dasima.)"},{"n":3,"title":null,"text":"Add the remaining dasima square, cream, red onion, garlic, black pepper and reserved pasta water to the pasta. Bring to a boil over high heat, then immediately reduce the heat to a gentle simmer. Stirring occasionally, cook the pasta until the onion-infused cream has thickened significantly, thinly coating the noodles, 4 to 5 minutes."},{"n":4,"title":null,"text":"Turn off the heat. Add the vinegar and asparagus, and stir to combine for 1 minute. The residual heat from the pasta will gently cook the asparagus to tender-crisp. Stir in the sesame oil and season with more black pepper, if desired. Divide the pasta among serving dishes, discarding the dasima, and shower with the reserved gim and sprinkle with flaky sea salt. Serve immediately, before the gim wilts and turns soggy."}],"tips":[],"cuisine_tags":["Fusion","Italian"],"ingredient_tags":["asparagus","pasta"],"item_tags":["rice vinegar","seaweed","sesame oil"],"course_tags":["Dinner"],"keywords":["Asparagus","Boil","Dinner","Gim","Kombu","Pastas","Quick","Rigatoni","Seaweed","Sesame Oil","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1022038.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1022038-creamy-asparagus-pasta","rating":{"value":4,"count":2138},"date":"2021-03-31"},{"pair":1021826,"title":"Olive-Walnut Pasta","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"1100","fat":"72 g","carbohydrates":"98 g","protein":"24 g"},"description":"Double down on the olive oil flavor in this dish by warming a generous amount with torn green olives to dress your pasta. While you can use just one kind of olive, like mild Castelvetrano, a variety will create depth of flavor. Adding chopped walnuts provides texture and a nice dose of protein to this vegan dish, while lemon zest and juice perk everything up. It would also be good with soft herbs like oregano, dill or basil, a salty cheese like feta or Parmesan, or shrimp that's been cooked with the pasta in the last few minutes of boiling.","from_your_kitchen":null,"ingredients":["Kosher salt and black pepper","1 pound short pasta, like orecchiette, cavatelli, fusilli or elbows","½ cup extra-virgin olive oil","2 cups chopped walnuts","1 ¼ cups Castelvetrano olives (or a mixture of green olives), pitted and torn","1 small garlic clove, peeled","1 lemon, zested and juiced (about 3 tablespoons juice)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil. When the water’s boiling, add the pasta and cook until al dente. Reserve 1 cup of pasta water, then drain."},{"n":2,"title":null,"text":"While the pasta’s cooking, in a large Dutch oven, stir together the olive oil, walnuts and olives. Set over medium heat and cook, stirring often, until fragrant and the walnuts are toasted, 3 to 5 minutes. Turn off the heat, finely grate in the garlic clove and season with 1 ½ teaspoons salt and a few grinds of black pepper. Stir to combine."},{"n":3,"title":null,"text":"Add the pasta and ¼ cup pasta water to the walnut mixture. Cook over medium-low, stirring and adding pasta water as needed, until the pasta is well coated. Remove from heat and stir in half the lemon zest and all the lemon juice. Season to taste with salt and pepper and more lemon zest."}],"tips":[],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["pasta","walnuts"],"item_tags":["castelvetrano olives","lemon"],"course_tags":["Dinner"],"keywords":["Dinner","Five Ingredient","Main Course","Olive","Pasta","Pastas","Vegan","Vegetarian","Walnut","Weeknight"],"issues":null,"front":"nyt_1021826.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021826-olive-walnut-pasta","rating":{"value":4,"count":1454},"date":"2021-01-28"},{"pair":1021158,"title":"Kimchijeon (Kimchi Pancake)","subtitle":null,"author":"Samin Nosrat","servings":null,"yield_text":"2 (10-inch) pancakes","yield_count":2,"cook_time":"15 minutes","nutrition":{"calories":"585","fat":"25 g","carbohydrates":"79 g","protein":"12 g"},"description":"At Pyeong Chang Tofu House in Oakland, Calif., Young S. Kim’s golden kimchijeon are a revelation. Tart with pungent kimchi, the pancakes are both satisfyingly chewy and shatteringly crisp. At the Tofu House, where Mrs. Kim turns 1,400 pounds of Napa cabbage into kimchi each month, her homemade kimchi is the secret to her kimchijeon’s unsurpassed flavor. Use the most flavorful traditionally prepared kimchi you can find — it’ll make all the difference in this simple recipe. This version, adapted from Mrs. Kim’s original recipe, comes together quickly: Just combine kimchi and its juice with a few dry ingredients into a simple batter, then fry it in a cast-iron skillet into a mouth-watering pancake. Serve it to a crowd as an appetizer, or eat it on its own as a filling meal. Samin Nosrat","from_your_kitchen":null,"ingredients":["¼ cup citrus ponzu sauce","1 tablespoon toasted white sesame seeds","1 scallion, thinly sliced","½ cup potato starch","½ cup all-purpose flour","1 teaspoon garlic powder","½ teaspoon baking powder","Pinch of sea salt","1 heaping cup kimchi (about 10 ounces), plus ¼ cup kimchi juice","2 scallions, chopped","2 tablespoons gochujang","1 tablespoon granulated sugar","1 teaspoon fish sauce","3 tablespoons neutral oil, such as canola"],"ingredient_groups":[{"at":0,"title":"FOR THE DIPPING SAUCE"},{"at":3,"title":"FOR THE PANCAKES"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the dipping sauce: In a small bowl, combine ponzu sauce, sesame seeds and scallion. Set aside."},{"n":2,"title":null,"text":"Prepare the pancakes: In a large bowl, whisk together potato starch, flour, garlic powder, baking powder and salt. Set aside."},{"n":3,"title":null,"text":"Dice kimchi into ½-inch pieces. In a medium bowl, stir together kimchi and kimchi juice, scallions, gochujang, sugar, fish sauce and ½ cup water. Add kimchi mixture to flour mixture, and stir to combine."},{"n":4,"title":null,"text":"Set a 10-inch cast-iron pan over medium heat. When it’s hot, add 1 ½ tablespoons oil. When oil shimmers, add half the batter, and spread from the center out to the edges of the pan. After about 1 minute, once you sense the pancake is setting, use a thin metal spatula to make sure pancake is not sticking. When the bottom of the pancake is brown and the top fades from glossy to matte, after another 30 to 60 seconds, carefully flip the pancake using the metal spatula. (Alternatively, slide the pancake onto a rimless plate, and flip it back into the pan.) Continue cooking for another 60 to 90 seconds on second side until set, then carefully slide pancake onto a plate."},{"n":5,"title":null,"text":"Use remaining oil and batter to make a second pancake. Cut into wedges, and serve hot with dipping sauce."}],"tips":[],"cuisine_tags":["Korean"],"ingredient_tags":["kimchi","scallions"],"item_tags":["fish sauce","gochujang","potato starch","sesame seeds"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Dinner","Finger Foods","Gochujang","Kimchi","Korean","Lunch","Main Course","Pancakes","Scallion","Side Dish","Snack"],"issues":null,"front":"nyt_1021158.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021158-kimchijeon-kimchi-pancake","rating":{"value":4,"count":959},"date":"2020-06-14"},{"pair":1020204,"title":"Ricotta Dumplings With Buttered Peas and Asparagus","subtitle":null,"author":"Alison Roman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"564","fat":"34 g","carbohydrates":"44 g","protein":"22 g"},"description":"These dumplings are a way to get the satisfaction of making your own pasta without having to make your own pasta. This recipe doesn’t require you to drain the ricotta, but if you notice that yours is especially wet, you may want to add a tablespoon or two more of flour to make sure the dough stays together. It should be like a very wet biscuit dough (and not pourable or soupy). As for the vegetables, this dish is a truly excellent canvas for anything seasonal (asparagus and peas in the spring, cherry tomatoes in the summer, mushrooms in the fall, squash in the winter), so adjust as you like.","from_your_kitchen":null,"ingredients":["2 cups whole-milk ricotta","2 large eggs","Kosher salt and black pepper","¾ cup all-purpose flour","4 tablespoons unsalted butter","2 tablespoons olive oil, plus more for serving","1 large leek, white and light green parts only, thinly sliced","1 bunch asparagus, woody ends removed, cut into 2-inch pieces","2 cups shelled fresh or frozen peas","3 cups pea shoots or leaves, thick stems removed","¼ cup parsley or mint leaves, for serving","Parmesan or pecorino, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil."},{"n":2,"title":null,"text":"Combine ricotta and eggs in a large bowl. Season with salt and pepper and, using a large wooden or metal spoon, gently mix in the flour, taking care not to overmix (which could result in tough dumplings)."},{"n":3,"title":null,"text":"Meanwhile, heat butter and 2 tablespoons olive oil in a large skillet over medium-high. Add leeks and season with salt and pepper. Cook, stirring occasionally, until leeks have softened completely and are starting to pick up some color, 5 to 8 minutes."},{"n":4,"title":null,"text":"Add asparagus and peas to the skillet and season with salt and pepper. Cook, tossing occasionally, until asparagus is just tender and bright green, 2 to 4 minutes, depending on its thickness. Remove from heat while you cook the dumplings."},{"n":5,"title":null,"text":"When the water is at a nice steady boil, drop the ricotta mixture into the pot by the heaping spoonful. (The dumplings will expand in the water, so make them slightly smaller than you’d like them to end up.) Be careful not to crowd the pot; cook the dumplings in batches if need be."},{"n":6,"title":null,"text":"Once the dumplings rise to the top, let them boil until cooked through, 4 to 5 minutes. (You can always pull one out and cut it in half to test its doneness; the texture will go from dense and doughy to light and pillowy.)"},{"n":7,"title":null,"text":"As the dumplings finish cooking, use a slotted spoon to transfer them to the skillet with the peas and asparagus. Once they’re all in there, give everything a quick toss over medium heat just to evenly coat the dumplings in the buttery sauce. Add pea shoots and toss just to wilt slightly."},{"n":8,"title":null,"text":"Transfer to a large serving bowl or platter and top with parsley, cheese and more olive oil, if you like."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["asparagus","peas","ricotta"],"item_tags":["leek","parmesan","parsley"],"course_tags":["Dinner"],"keywords":["Asparagus","Dinner","Main Course","Pastas","Pea","Pea Shoot","Ricotta","Spring","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020204.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020204-ricotta-dumplings-with-buttered-peas-and-asparagus","rating":{"value":4,"count":2479},"date":"2019-05-08"},{"pair":1020994,"title":"Spring Minestrone With Kale and Pasta","subtitle":null,"author":"Kay Chun","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"514","fat":"21 g","carbohydrates":"61 g","protein":"22 g"},"description":"This one-pot springtime minestrone combines asparagus, peas and kale with a healthy dose of fresh ginger. The ginger is optional, but it energizes the broth. This recipe is fairly flexible overall: You can swap green vegetables according to taste, use vegetable or chicken stock and toss in any type of short pasta. The pesto and Parmesan swirled in at the end provide brightness and richness, but you could also finish the soup with tapenade, sour cream, ricotta or even a splash of your favorite hot sauce.","from_your_kitchen":null,"ingredients":["¼ cup extra-virgin olive oil","2 large shallots or 1 small onion, thinly sliced","2 celery stalks, thinly sliced","Kosher salt and black pepper","2 tablespoons minced fresh ginger (optional)","2 tablespoons minced garlic","2 quarts low-sodium chicken or vegetable stock","1 cup ditalini or other small shaped pasta (about 5 ounces)","8 ounces asparagus, trimmed and sliced into ½-inch pieces (1 ½ cups), thinly sliced zucchini or chopped broccoli","1 cup fresh or frozen peas","5 ounces baby kale, baby spinach or torn spinach (about 4 cups)","Storebought pesto and grated Parmesan, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a heavy soup pot or Dutch oven, heat the oil over medium. Add shallots and celery and season with salt and pepper. Cook, stirring occasionally, until softened, about 5 minutes."},{"n":2,"title":null,"text":"Add the ginger, if using, and garlic and stir until very fragrant, about 2 minutes. Add stock and bring to a simmer."},{"n":3,"title":null,"text":"Stir in pasta and cook according to package instructions until al dente. Stir in asparagus and peas and cook until vegetables and pasta are tender, about 3 minutes longer. Stir in kale and season with salt and pepper."},{"n":4,"title":null,"text":"Divide soup among bowls. Swirl in some pesto and top with Parmesan."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["asparagus","kale","pasta","peas"],"item_tags":["basil pesto","ginger","parmesan"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["American","Appetizer","Asparagus","Celery","Dinner","Easy","Ginger","Great Leftovers","Kale","Main Course","Pasta","Pastas","Pea","Pesto","Simmer","Soup","Spring","Vegetable Broth","Weeknight"],"issues":null,"front":"nyt_1020994.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020994-spring-minestrone-with-kale-and-pasta","rating":{"value":5,"count":2404},"date":"2020-04-09"},{"pair":1017431,"title":"April Bloomfield's Pot-Roasted Artichokes With White Wine","subtitle":null,"author":"The New York Times","servings":"4 to 6","yield_text":"4 to 6 servings as a side","yield_count":4,"cook_time":"50 minutes","nutrition":{"calories":"253","fat":"9 g","carbohydrates":"29 g","protein":"9 g"},"description":"This beautiful recipe for pot-roasted artichokes with white wine and capers appears in the chef April Bloomfield's 2015 cookbook \"A Girl and Her Greens.\" It's tremendous. \"The fleshy artichokes get browned and crispy tops and look like strange, beautiful roses,\" she writes. \"The acidity in the white wine cuts through the rich, dense veg and, along with the salty pops from the capers, highlights the artichokes’ unique herbaceousness.\" The New York Times","from_your_kitchen":null,"ingredients":["¼ cup extra-virgin olive oil","3 ½ pounds baby artichokes (about 18)","2 medium garlic cloves, thinly sliced","1 ½ teaspoons Maldon or other flaky sea salt","1 ½ cups dry white wine, such as Sauvignon Blanc","1 heaping tablespoon drained capers","A five-finger pinch of mint leaves (preferably black mint), torn at the last minute (see note)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil in a heavy pot (wide enough to hold the artichokes with room to spare) over medium-high heat until it just begins to smoke."},{"n":2,"title":null,"text":"Stand the artichokes cut sides down in the oil, wait a minute, then reduce the heat to medium-low, sprinkle in the garlic and salt, and cook, without stirring, just until the garlic turns golden and smells toasty, about 3 minutes."},{"n":3,"title":null,"text":"Pour in the wine, cover the pot and cook, without stirring, at a vigorous simmer until you can insert a sharp knife into the thick artichoke bottoms with barely any resistance, about 25 minutes. Five minutes or so before they’re fully tender, scatter on the capers and cover again."},{"n":4,"title":null,"text":"Uncover, raise the heat to medium-high, and bring the liquid to a boil."},{"n":5,"title":null,"text":"Cook until all the wine has evaporated (the bubbling sound will become a sizzle), about 3 minutes. Add the mint and keep cooking the artichokes in the oil (it’s OK if a few of them tip over), until the cut sides of the artichokes are deep golden brown, 3 to 5 minutes. Lower the heat if necessary to prevent the artichokes from getting too dark."},{"n":6,"title":null,"text":"Arrange the artichokes prettily on a plate, and scoop the capers, oil and slightly crispy mint over top. Serve straightaway or at room temperature."}],"tips":["A five-finger pinch is as much as you can grab with just the tips of all five fingers."],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["artichokes","white wine"],"item_tags":["capers","mint"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Baby Artichoke","Boil","Caper","Dinner","Lunch","Side Dish","Simmer","Vegetables","Vegetarian","White Wine"],"issues":null,"front":"nyt_1017431.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017431-april-bloomfields-pot-roasted-artichokes-with-white-wine","rating":{"value":4,"count":405},"date":"2015-05-26"},{"pair":1021960,"title":"Sheet-Pan Roasted Mushrooms and Spinach","subtitle":null,"author":"Millie Peartree","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"128","fat":"7 g","carbohydrates":"14 g","protein":"6 g"},"description":"If you love to cook but don’t always feel like cooking, this minimalist recipe is the recipe for you. Great with just about any protein — salmon, steak, chicken or even eggs, wrapped into an omelet — it comes together in under a half-hour, and develops loads of character from its time spent in the oven. While this versatile vegan side pairs well with protein, it’s also great over rice or noodles.","from_your_kitchen":null,"ingredients":["1 pound cremini mushrooms (or any combination of mushrooms you like), trimmed and sliced","3 small shallots, peeled and sliced","4 garlic cloves, peeled and chopped","2 tablespoons olive oil, plus more as needed","Kosher salt and black pepper","2 (5-ounce) containers baby spinach"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. On a rimmed baking sheet, toss together mushrooms, shallots, garlic and 2 tablespoons olive oil. Season with salt and pepper and spread in an even layer. Roast until golden brown, about 15 to 20 minutes."},{"n":2,"title":null,"text":"Add spinach to the sheet pan, toss with mushrooms, and roast until wilted, about 5 minutes, turning once after 2 or 3 minutes and drizzling with a bit of olive oil if the mixture seems dry. Taste, and adjust seasoning. Serve hot or at room temperature."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["mushrooms","spinach"],"item_tags":["shallot"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Cremini","Dinner","Easy","Five Ingredient","Healthy","Quick","Roast","Sheet-Pan","Side Dish","Spinach","Vegan","Vegetables","Weeknight"],"issues":null,"front":"nyt_1021960.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021960-sheet-pan-roasted-mushrooms-and-spinach","rating":{"value":4,"count":2343},"date":"2021-03-04"},{"pair":1021097,"title":"Vegan Coconut-Ginger Black Beans","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"515","fat":"34 g","carbohydrates":"42 g","protein":"16 g"},"description":"The velvety combination of beans and coconut milk is found in a number of African and Caribbean dishes, like Nigerian frejon and Haitian sos pwa nwa. In this recipe, black beans are simmered in coconut milk with a healthy dose of fresh ginger, then finished with lime juice. The result is a light vegan main or side dish. Finish with crushed plantain chips seasoned with lime zest for sweetness and crunch, or top with coconut flakes or tortilla chips, which are also excellent.","from_your_kitchen":null,"ingredients":["2 (15-ounce) cans black beans","2 tablespoons coconut oil or extra-virgin olive oil","1 ½ teaspoons ground cumin or coriander","1 (3-inch piece) fresh ginger, peeled and finely grated (about 3 tablespoons)","1 (13-ounce) can full-fat coconut milk","Kosher salt and black pepper","½ cup plantain chips or toasted coconut flakes","1 teaspoon lime zest plus 2 tablespoons juice (from 1 lime)","Hot sauce, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Rinse 1 can of black beans, and set aside. In a large saucepan, heat the coconut oil over medium. Add the cumin and half of the ginger and cook until fragrant, stirring constantly, 1 to 2 minutes. Add the rinsed black beans and the remaining whole can of black beans (including the liquid), and the coconut milk; season generously with salt and pepper."},{"n":2,"title":null,"text":"Bring to a boil over medium-high, then reduce heat to a simmer and cook, stirring occasionally, until the beans are soft and the mixture is flavorful, 15 to 20 minutes. (If you want a thicker consistency, smash some of beans with the back of a spoon as the mixture cooks, and simmer longer.)"},{"n":3,"title":null,"text":"Meanwhile, in a small bowl, crumble the plantain chips into bite-size pieces. Add the lime zest and a few generous grinds of black pepper, and stir to combine."},{"n":4,"title":null,"text":"Remove the beans from the heat. Stir in the remaining ginger and season with salt and pepper to taste. Stir in the lime juice a little at a time until the beans taste bright but the coconut flavor is still rich. Top with the seasoned plantain chips and serve with hot sauce for more kick."}],"tips":[],"cuisine_tags":["African","Caribbean"],"ingredient_tags":["black beans"],"item_tags":["coconut milk","cumin","ginger","lime"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Beans","Black Bean","Budget","Coconut Milk","Cumin","Dinner","Easy","Ginger","Great Leftovers","Lime","Lunch","Main Course","Side Dish","Simmer","Soups and Stews","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021097.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021097-vegan-coconut-ginger-black-beans","rating":{"value":5,"count":3203},"date":"2020-05-20"},{"pair":1017022,"title":"Mushroom Risotto With Peas","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"About 50 minutes","nutrition":{"calories":"360","fat":"10 g","carbohydrates":"53 g","protein":"12 g"},"description":"If you are ever at a loss for what to make for an impromptu dinner party, especially if there will be vegetarians at the table, consider this luxurious mushroom risotto. I added peas because I wanted to introduce some color, and also because the sweetness of the peas fits right in with the flavors of this dish. But this satisfying, elegant dish is fine without peas, too. You’ll get a vibrant dash of green from the parsley added at the end of cooking.","from_your_kitchen":null,"ingredients":["6 to 7 cups chicken, vegetable or garlic broth or stock, as needed","Salt and black pepper","2 tablespoons extra-virgin olive oil","½ cup finely chopped onion, or 2 shallots, minced","¾ to 1 pound wild mushrooms, cleaned if necessary and torn or sliced into smaller pieces if thick (small wild mushrooms should be left whole, mushrooms like maitake can just be separated into small pieces)","2 garlic cloves, minced","2 teaspoons fresh thyme leaves or chopped sage","1 ½ cups arborio or carnaroli rice","½ cup dry white wine, such as pinot grigio or sauvignon blanc","1 cup frozen peas, thawed (optional)","2 tablespoons chopped fresh parsley","½ cup grated Parmesan cheese, or a mixture of Parmesan and Pecorino Romano"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring stock or broth to a simmer in a saucepan, with a ladle nearby. Make sure stock is well seasoned, and keep it simmering on the stove."},{"n":2,"title":null,"text":"Heat oil in a wide, heavy nonstick skillet or saucepan over medium heat. Add onions or shallots and cook gently until just tender, 3 to 5 minutes."},{"n":3,"title":null,"text":"Turn up heat and add mushrooms. Cook, stirring, until they begin to sweat, about 3 minutes, then add garlic and thyme or sage. Cook, stirring, until fragrant, about 30 seconds. Season mushrooms with salt and pepper and continue to cook over medium heat until they are soft. Taste and adjust seasoning."},{"n":4,"title":null,"text":"Add rice and stir until grains begin to crackle. Add wine and cook, stirring, until wine is no longer visible in pan. Stir in enough simmering stock to just cover the rice. The stock should bubble slowly. Cook, stirring often and vigorously, until stock is just about absorbed. Add another ladleful or two of stock and continue cooking, not too fast and not too slowly, stirring often and adding more stock when rice is almost dry, for 15 minutes."},{"n":5,"title":null,"text":"Add peas, if using, and continue adding stock and stirring for another 10 minutes. Rice should be tender all the way through but still al dente. Taste now and adjust seasoning."},{"n":6,"title":null,"text":"Add another ladleful or two of stock to rice. Stir in parsley and Parmesan, and remove from heat. Season with black pepper and serve right away in wide soup bowls or on plates."}],"tips":["Advance preparation: You can begin up to several hours before serving: proceed with the recipe and cook halfway through Step 4, for about 10 minutes. The rice should still be hard in the middle when you remove it from the heat, and there should not be any liquid in the pan. Spread it in an even layer in the pan or on a baking sheet and keep it away from the heat until you resume cooking. 15 minutes before serving, resume cooking as instructed."],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["mushrooms","peas","rice"],"item_tags":["parmesan","parsley","thyme","white wine"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Arborio Rice","Christmas","Dinner","Dry White Wine","Easter","Fall","Gluten-Free","Italian","Low Sugar","Main Course","Mediterranean","Mushroom","Party","Pea","Risotto","Side Dish","Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_1017022.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017022-mushroom-risotto-with-peas","rating":{"value":5,"count":7787},"date":"2014-11-27"},{"pair":1021800,"title":"Old-Fashioned Butterscotch Pudding","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes, plus 2 hours’ chilling","nutrition":{"calories":"570","fat":"34 g","carbohydrates":"55 g","protein":"9 g"},"description":"This creamy pudding, thickened with cornstarch and egg yolks and stirred together on the stove, is as homey as it gets. Spiking the mixture with a little bourbon or Scotch isn’t strictly traditional, but it does add a pop of flavor. Choose bourbon to underscore the caramelized notes of the brown sugar, or Scotch for a savory smokiness and a nod to the name. Here’s a tip: Make sure to bring the pudding to a full, vigorous boil to activate the cornstarch. Otherwise, it may not set. If you’ve ever ended up with thin, runny pudding, undercooking may have been the issue.","from_your_kitchen":null,"ingredients":["4 large egg yolks","3 tablespoons cornstarch","½ teaspoon fine sea salt","¾ packed cup/165 grams dark brown sugar","1 tablespoon unsalted butter","2 cups/480 milliliters whole milk","1 cup/240 milliliters heavy cream","1 tablespoon bourbon or Scotch whisky (optional)","2 teaspoons vanilla extract","Whipped cream, sour cream or crème fraîche, for serving","Chopped candied ginger, sliced almonds, Demerara sugar, shaved chocolate, cocoa nibs or flaky sea salt (or a combination), for garnish (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put egg yolks, cornstarch and salt into a large heatproof bowl, and whisk until the mixture is smooth and there are no lumps."},{"n":2,"title":null,"text":"In a medium pot over medium heat, combine brown sugar and butter, whisking, until the brown sugar melts, 1 to 2 minutes. Let cook, whisking constantly, until the mixture starts to smell like hot caramel and darkens slightly, about 1 minute longer. (Don’t walk away, or the mixture may burn.)"},{"n":3,"title":null,"text":"Immediately pour the milk and cream into the pot. (It will bubble fiercely and seize up.) Continue to cook, whisking constantly, until the clumps melt, 2 to 4 minutes."},{"n":4,"title":null,"text":"Slowly whisk about ½ cup of the hot cream mixture into the bowl with the egg yolks, whisking yolks until smooth, then whisk in the remaining hot cream mixture. Pour the egg-cream mixture back into the saucepan and place it over medium heat."},{"n":5,"title":null,"text":"Cook pudding, whisking constantly especially around the bottom and edges of the pot, until it comes to a full boil. (Don’t worry about the eggs curdling. You’re going to strain the mixture later.) Reduce heat to medium-low and cook, stirring the mixture constantly, until it thickens enough to mound thickly on the spoon, 4 to 7 minutes. If at any point the pudding looks curdled, whisk to help smooth it out."},{"n":6,"title":null,"text":"Strain mixture through a fine sieve into a heatproof container or bowl, then stir in the Scotch or bourbon, if using, and vanilla. To prevent a skin from forming, press plastic wrap directly onto the surface of the pudding. (If you like the skin, don’t cover pudding until it cools.) Chill for at least 2 hours and up to 2 days."},{"n":7,"title":null,"text":"When serving, spoon pudding into dishes. Top with dollops of whipped cream, sour cream or crème fraîche, and any of the optional garnishes."}],"tips":["Make sure to bring the pudding to a full, vigorous boil to activate the cornstarch. Otherwise, it may not set. If you’ve ever ended up with thin, runny pudding, undercooking may have been the issue."],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["brown sugar","eggs"],"item_tags":["bourbon","vanilla"],"course_tags":["Dessert"],"keywords":["Brown Sugar","Cream","Custards and Puddings","Dessert","Egg Yolk","Milk","Simmer","Thanksgiving"],"issues":null,"front":"nyt_1021800.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021800-old-fashioned-butterscotch-pudding","rating":{"value":4,"count":1706},"date":"2021-01-20"},{"pair":1021339,"title":"Ramen With Charred Scallions, Green Beans and Chile Oil","subtitle":null,"author":"Hetty Lui McKinnon","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"476","fat":"18 g","carbohydrates":"68 g","protein":"13 g"},"description":"Scallions can be so much more than a garnish. Raw scallions bring an assertive pungency, but when cooked, they take on a sweet tenderness that is very pleasing to the palate. In this vegan recipe, treat scallions as you would a bunch of greens. Take cues from the Chinese cooking technique used for stir-fries, and add the scallions to very hot oil to let them “bao” (to crack, explode or burst), drawing out their natural aroma. Those packets of ramen noodles stashed in your pantry are perfect for this quick yet intensely satisfying weeknight noodle dish. The chile oil makes just enough for this dish, so if you want extra for future meals, make double.","from_your_kitchen":null,"ingredients":["2 tablespoons red-pepper flakes (see Tip)","1 ½ teaspoons kosher salt","½ cup neutral oil, such as grapeseed, vegetable or canola","1 (1-inch) piece ginger, peeled and finely chopped","2 garlic cloves, finely chopped","2 teaspoons toasted white sesame seeds","1 teaspoon sesame oil","Kosher salt","4 (3-ounce) packages ramen noodles, seasoning packs discarded","2 bunches scallions (10 to 12 scallions), white and green parts separated and cut into 2-inch pieces","2 to 3 tablespoons neutral oil, such as grapeseed, vegetable or canola","10 ounces green beans, trimmed and halved diagonally","1 (2-inch) piece ginger, peeled and julienned","White pepper","1 tablespoon toasted white sesame seeds"],"ingredient_groups":[{"at":0,"title":"FOR THE CHILE OIL"},{"at":7,"title":"FOR THE NOODLES"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the chile oil: Add the red-pepper flakes and salt to a heatproof bowl. Place the oil, ginger and garlic in a small saucepan, and heat over medium until it bubbles, 2 to 3 minutes. Remove from the heat and very carefully pour the hot oil over the red-pepper flakes. Add the sesame seeds and sesame oil, and stir well. Set aside while you make the rest of the dish. (Chile oil can be stored in an airtight jar at room temperature for up to a month and indefinitely in the refrigerator.)"},{"n":2,"title":null,"text":"Prepare the noodles: Bring a large pot of salted water to a boil. Add the ramen and cook according to package instructions, about 3 minutes, until the noodles are just tender. Drain, rinse with cold water and drain well again."},{"n":3,"title":null,"text":"Slice the white parts of your scallions lengthwise, in half or quarters, depending on thickness, to make cooking faster."},{"n":4,"title":null,"text":"Heat a wok or large (12-inch), deep skillet on high. When smoking hot, add 1 tablespoon of oil, toss in the green beans and season with salt. Cook, tossing the beans, for 2 to 3 minutes, until charred. Remove the beans from the wok, and set aside."},{"n":5,"title":null,"text":"Heat the same wok or skillet over high, and when smoking, add 1 to 2 tablespoons of oil, along with the scallions (white and green parts) and the ginger. Allow the scallions and ginger to sizzle for 20 to 30 seconds, to release their aromas, then stir-fry for 2 to 3 minutes, until the scallions have a nice scorch."},{"n":6,"title":null,"text":"Add the green beans and noodles back to the pan, along with 2 or 3 tablespoons of the chile oil (reserve some for serving), and season with salt and pepper. Toss well to combine, just until the noodles are heated through. To serve, divide the noodles into bowls, top with toasted sesame seeds and more chile oil."}],"tips":["If you want to add a tingly heat to your ramen, you can add 1 tablespoon Sichuan peppercorns and/or 1 tablespoon gochugaru (Korean red-pepper flakes) to the bowl with the red-pepper flakes when preparing the oil. To save on time, skip making your own chile oil, and use store-bought Sichuan chile oil."],"cuisine_tags":["Chinese","Fusion"],"ingredient_tags":["green beans","noodles"],"item_tags":["ginger","red chile flakes","scallions","sesame oil"],"course_tags":["Dinner"],"keywords":["Dinner","Green Bean","Main Course","Noodles","Quick","Ramen Noodle","Red Pepper Flake","Scallion","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021339.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021339-ramen-with-charred-scallions-green-beans-and-chile-oil","rating":{"value":4,"count":3359},"date":"2020-08-04"},{"pair":1021815,"title":"Vegan Creamy Leek Pasta","subtitle":null,"author":"Alexa Weibel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"708","fat":"29 g","carbohydrates":"97 g","protein":"16 g"},"description":"This four-ingredient leek pasta coaxes as much flavor and texture as possible out of a few leeks, a box of pasta, some olive oil and lemon (plus salt and pepper). Though it doesn’t take long, this recipe is not fast — it’s even a little bit fussy. You’ll julienne and fry the leek whites to create a crispy garnish, then blend the resulting leek oil with boiled leek greens to create a silky sauce. You could absolutely make this dish on a weeknight, but since the recipe revolves around technique, it’s best not to rush. It’s about enjoying the process as much as the results.","from_your_kitchen":null,"ingredients":["Kosher salt and black pepper","3 medium leeks (about 1 to 1 ¼ pounds total)","½ cup extra-virgin olive oil","1 pound bucatini, fettuccine or linguine","1 lemon"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil over high."},{"n":2,"title":null,"text":"Meanwhile, prepare your leeks: Trim ½ inch off both ends, then cut each leek crosswise, separating the bottom third of the white portion from the top two-thirds of light and dark leek greens. Halve the greens lengthwise, wash them, then set them aside."},{"n":3,"title":null,"text":"Halve your leek whites lengthwise, cut them crosswise into 2-inch segments, then slice those segments thinly lengthwise to create matchsticks. (If you notice any grit in the sliced leek whites, wash them thoroughly, transfer them to a dish towel, squeezing to remove excess moisture, then spread them out to dry.)"},{"n":4,"title":null,"text":"In a small, deep saucepan, heat the olive oil over medium-high and line a baking sheet with paper towels. Working in three to four batches for even cooking, add about ¼ of the white leek strips and cook, stirring frequently, until golden, about 4 minutes. The key here is to keep residual cooking in mind: Since your delicate leeks will continue cooking after being removed from the hot oil, you want to pull them from the hot oil when about a third of each batch is fully golden, a third is lightly golden and another third is still green. (They won’t cook perfectly evenly; it’s not you, it’s them and the nature of cooking.) Remove them swiftly, using a slotted spoon and tilting the saucepan to transfer the leeks to the paper towel-lined plate. Season to taste with salt. Repeat with the remaining batches. Set the oil aside to cool."},{"n":5,"title":null,"text":"Add the pasta and leek greens to the boiling water, reduce the heat to medium-high and cook, stirring occasionally, until the pasta is just shy of al dente, about 8 minutes. Reserve 1 cup pasta cooking water. Using tongs, transfer the leek greens to a blender, then pour the pasta into a colander set in the sink."},{"n":6,"title":null,"text":"Add the reserved leek oil to the leek greens, along with ⅔ cup pasta water and a generous pinch each of salt and pepper, and blend until creamy. Add the sauce to the pot and stir in the pasta. Season to taste with salt and pepper, and add more pasta water, if desired, to thin the sauce. Divide among plates and sprinkle with frizzled leeks. Grate fresh lemon zest on top, if desired, then squeeze with lemon. Serve immediately."}],"tips":[],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["leeks","pasta"],"item_tags":["lemon"],"course_tags":["Dinner"],"keywords":["Dinner","Fall","Fettuccine","Five Ingredient","Leek","Lemon","Main Course","Pastas","Vegan","Winter"],"issues":null,"front":"nyt_1021815.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021815-vegan-creamy-leek-pasta","rating":{"value":4,"count":1206},"date":"2021-01-27"},{"pair":1021588,"title":"Smoky Lentil Stew With Leeks and Potatoes","subtitle":null,"author":"David Tanis","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour","nutrition":{"calories":"397","fat":"8 g","carbohydrates":"68 g","protein":"17 g"},"description":"Rustic with deep flavor, this stew improves after a day in the fridge. Make the whole recipe, and eat it over several days — or freeze it for later. If you can’t get small Spanish Pardina lentils or French lentilles du Puy, use any size green or brown lentil. (Carnivores may want to add chorizo or jamón.) The stew is rather brothy at first, but thickens upon sitting. Thin with a little water when reheating, as necessary. For optimum results, be sure to use fruity, zesty-tasting extra virgin olive oil — it really makes a difference.","from_your_kitchen":null,"ingredients":["1 ½ cups small lentils, such as Pardina or Puy (12 ounces), or use any size green or brown lentil","1 medium onion, halved, plus 2 bay leaves and 2 whole cloves","Kosher salt and black pepper","4 or 5 medium potatoes, peeled and sliced ¾-inch thick","3 tablespoons extra-virgin olive oil, plus more for drizzling","2 medium leeks, white and tender green parts, chopped in ½-inch pieces","1 teaspoon chopped garlic","1 large thyme or rosemary sprig","2 tablespoons pimentón dulce or smoked sweet paprika","⅛ teaspoon ground cayenne, or to taste","Small pinch of saffron (about 12 strands), soaked in ¼ cup cold water","1 cup chopped canned tomato with juice","2 tablespoons sherry vinegar","Chopped parsley (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Rinse lentils. Put them in a Dutch oven or large, heavy-bottomed pot and add 8 cups water. Pin a bay leaf to each onion half using a whole clove and add to the pot. Bring to a boil over high heat, add a large pinch of salt, then reduce heat to a simmer. Cook with lid ajar for about 30 minutes, until soft. Turn off heat."},{"n":2,"title":null,"text":"Meanwhile, bring a medium pot of salted water to boil, and cook the potato slices until just done, about 10 minutes, then drain and spread out on a baking sheet to cool."},{"n":3,"title":null,"text":"Put 3 tablespoons olive oil in a large skillet over medium-high heat. When the oil is wavy, add leeks and stir to coat. Season with salt and pepper. Let leeks cook briskly, stirring frequently until soft but still bright green, about 5 to 8 minutes. Turn heat to medium, stir in chopped garlic, thyme, pimentón and cayenne."},{"n":4,"title":null,"text":"Add saffron and soaking water, the chopped tomato and vinegar. Turn heat to high and let everything simmer for a few minutes. Pour contents of skillet into Dutch oven with lentils. Add the reserved potatoes."},{"n":5,"title":null,"text":"Bring to a boil, then reduce to a simmer. Cook covered with lid ajar for about 10 minutes. Taste and adjust seasoning, then cook for 10 more minutes. The lentils will be quite soft and the potatoes will start to break. Discard onion and thyme sprig."},{"n":6,"title":null,"text":"Finish with a drizzle of extra-virgin olive oil and chopped parsley, if you wish."}],"tips":[],"cuisine_tags":["Spanish"],"ingredient_tags":["lentils","potato"],"item_tags":["leek","saffron","sherry vinegar","smoked paprika"],"course_tags":["Dinner"],"keywords":["Dinner","Great Leftovers","Green Lentil","Leek","Main Course","Make-Ahead","Paprika","Potato","Saffron","Spanish","Stew","Vegan","Vegetarian"],"issues":null,"front":"nyt_1021588.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021588-smoky-lentil-stew-with-leeks-and-potatoes","rating":{"value":4,"count":6388},"date":"2020-11-04"},{"pair":1021758,"title":"New York Sour Shot","subtitle":null,"author":"Rebekah Peppler","servings":null,"yield_text":"8 shots","yield_count":8,"cook_time":null,"nutrition":{"calories":"53","carbohydrates":"3 g"},"description":"A wine-spiked whiskey sour, the New York Sour is a potent combination of bourbon, lemon, sugar and sometimes egg whites. Top each of these shots with dry red wine for a more classic experience — both in looks and in taste — or swap out the wine entirely for sweet red vermouth. The slightly more herbal flavor makes up for what it lacks in striking visuals. This alternative float is especially ideal if you don’t have or don’t want to open a full 750-milliliter bottle of red only to put a few ounces to use. (That’s less of an issue if you plan on drinking wine later in the night, but you do you.)","from_your_kitchen":null,"ingredients":["Ice","4 ounces bourbon or rye","2 ounces fresh lemon juice","1 ounce simple syrup","2 dashes Angostura bitters","2 ounces dry, fruity red wine or sweet red vermouth"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a cocktail shaker filled with ice, combine the bourbon or rye with lemon juice, simple syrup and bitters. Cover and shake until very cold, then strain into 8 small glasses."},{"n":2,"title":null,"text":"Working shot by shot, gently pour ¼ ounce wine (1 ½ teaspoons) over the back of a small spoon held just above each drink’s surface so the wine floats on top."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["bourbon","red wine"],"item_tags":["bitters","lemon"],"course_tags":["Drinks"],"keywords":["Bitters","Bourbon","Cocktails","Lemon","New Year’s Day","Vermouth"],"issues":null,"front":"nyt_1021758.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021758-new-york-sour-shot","rating":{"value":4,"count":290},"date":"2020-12-30"},{"pair":1021757,"title":"Bamboo Shot","subtitle":null,"author":"Rebekah Peppler","servings":null,"yield_text":"8 shots","yield_count":8,"cook_time":null,"nutrition":{"calories":"36","fat":"1 g","carbohydrates":"2 g","protein":"0 g"},"description":"The Bamboo Shot takes the famous 19-century sherry cocktail and turns it into a shot. The original Bamboo — sherry, dry vermouth and a few drops of orange and Angostura bitters — is credited to the German bartender Louis Eppinger of the Grand Hotel in Yokohama, Japan. Dry and complex, it looks and tastes like a high-proof drink, but the low-A.B.V. ingredients keep its impact in check, making it an ideal shot to start a celebration — or a Tuesday night. Eating briny, buttery Castelvetrano olives as a chaser completes the shot experience — and helps round out the drink’s drier tones.","from_your_kitchen":null,"ingredients":["3 ½ ounces fino or manzanilla sherry","3 ½ ounces dry or bianco vermouth","3 dashes Angostura bitters","3 dashes orange bitters","2 orange peels","2 lemon peels","Very small pinch of flaky sea salt (optional)","Ice","Big green olives, such as Castelvetrano, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"To a cocktail shaker or mixing glass, add the sherry, vermouth and bitters."},{"n":2,"title":null,"text":"Hold one of the lemon peels by its long edges, skin facing down into the cocktail shaker. Pinch the peel to express the citrus oils in. Repeat with the remaining lemon peel and the orange peels."},{"n":3,"title":null,"text":"Add salt and ice, and stir until chilled. Strain into eight small glasses and serve immediately with olives."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["sherry"],"item_tags":["bitters","lemon","orange","vermouth"],"course_tags":["Drinks"],"keywords":["Bitters","Cocktails","Lemon","New Year’s Day","Orange","Sherry","Vermouth"],"issues":null,"front":"nyt_1021757.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021757-bamboo-shot","rating":{"value":4,"count":112},"date":"2020-12-30"},{"pair":1020900,"title":"Creamy Swiss Chard Pasta With Leeks, Tarragon and Lemon Zest","subtitle":null,"author":"Alexa Weibel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"1046","fat":"48 g","carbohydrates":"132 g","protein":"42 g"},"description":"This creamy vegetarian pasta is hearty enough for chilly temperatures while still nodding toward spring with the addition of bright-green chard, leeks and fresh herbs. For texture, it’s topped with toasted panko, a garnish that can go many ways: Instead of using nutritional yeast, which adds tangy flavor here, you can melt a finely chopped anchovy with the butter and toss it with the panko. You could also add some ground coriander, Italian seasoning or herbes de Provence. Toasted panko, plain bread crumbs or even crushed croutons are a solid back-pocket trick to add crunch to any pasta, especially the creamiest kind. Don’t skip the tarragon and lemon zest garnish, which add a fresh note to an otherwise-rich dish.","from_your_kitchen":null,"ingredients":["¾ pound green Swiss chard (1 large bunch), washed and trimmed","2 large leeks (10 to 12 ounces each)","5 tablespoons unsalted butter","½ cup panko bread crumbs","Kosher salt and black pepper","3 tablespoons nutritional yeast","3 garlic cloves, thinly sliced","2 teaspoons fresh thyme leaves","2 cups chicken or vegetable stock","1 cup heavy cream","16 ounces linguine or fettuccine","¾ cup finely grated Parmesan","Fresh tarragon leaves, for garnish","1 lemon, for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil. Prepare the chard: Tear the leaves off the stems, separating the leaves and stems. Thinly slice the stems, then coarsely tear the leaves into bite-size pieces. Set both aside in separate bowls."},{"n":2,"title":null,"text":"Prepare the leeks: Trim off the bottom and the dark green portion at the top, halve the remaining white and pale green portion lengthwise, then thinly slice them crosswise. Wash and drain the sliced leeks. Set aside."},{"n":3,"title":null,"text":"Prepare the bread crumbs: In a large skillet, melt 2 tablespoons butter over medium. Add the panko, season lightly with salt and generously with pepper, and cook, stirring occasionally, until golden and toasted, 3 to 4 minutes. Stir in nutritional yeast, then transfer to a paper towel-lined plate."},{"n":4,"title":null,"text":"Wipe out the skillet. Add the remaining 3 tablespoons butter and melt over medium-high. Add the leeks, chard stems, garlic and thyme, season with salt and pepper, and cook, stirring occasionally, until leeks start to wilt and soften, about 5 minutes. Add the torn chard, season with salt and pepper, and cook, stirring, until just wilted, 2 minutes."},{"n":5,"title":null,"text":"Add the stock and heavy cream, and boil over high until thickened, about 10 minutes."},{"n":6,"title":null,"text":"Once the mixture is simmering, add the pasta to the pot of boiling water and cook until al dente. Drain pasta."},{"n":7,"title":null,"text":"Transfer chard mixture to the empty pasta pot. Stir in the cooked pasta, then sprinkle with the Parmesan, stirring vigorously to melt it into the sauce. Season to taste with salt and pepper."},{"n":8,"title":null,"text":"Divide among shallow bowls or plates. Sprinkle generously with the prepared bread crumbs, top with tarragon and grate fresh lemon zest on top. Serve immediately."}],"tips":[],"cuisine_tags":["French","Italian"],"ingredient_tags":["pasta","swiss chard"],"item_tags":["lemon","panko breadcrumbs","parmesan","tarragon"],"course_tags":["Dinner"],"keywords":["Dinner","Garlic","Heavy Cream","Leek","Lemon Zest","Main Course","Panko","Parmesan","Pasta","Pastas","Swiss Chard","Tarragon","Thyme","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020900.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020900-creamy-swiss-chard-pasta-with-leeks-tarragon-and-lemon-zest","rating":{"value":4,"count":2585},"date":"2020-02-25"},{"pair":1021715,"title":"Eggnog Snickerdoodles","subtitle":null,"author":"Vaughn Vreeland","servings":null,"yield_text":"24 cookies","yield_count":24,"cook_time":"About 45 minutes","nutrition":{"calories":"205","fat":"8 g","carbohydrates":"31 g","protein":"2 g"},"description":"These pillowy, festive cookies are great to have in your back pocket when you’re in the mood for a quick holiday treat. Rum extract, widely available during the holidays, is the secret to replicating that classic eggnog flavor. An extra egg yolk in the dough and a dusting of nutmeg-sugar yield a cookie that’s custard-like on the inside and crisp on the outside. These are even better the second day, and keep very well in an airtight container at room temperature. This season, forgo the eggnog altogether and enjoy these cookies with a bourbon neat. (Watch Vaughn Vreeland make his Eggnog Snickerdoodles.)","from_your_kitchen":null,"ingredients":["3 ½ cups/445 grams all-purpose flour","1 ½ teaspoons cream of tartar","1 teaspoon baking soda","1 cup/225 grams unsalted butter (2 sticks), at room temperature","1 ¾ cup/350 grams granulated sugar, plus ¼ cup/50 grams for rolling","1 teaspoon kosher salt","1 large egg plus 2 yolks, at room temperature","1 tablespoon rum extract","2 teaspoons freshly grated nutmeg"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a medium bowl, whisk together the flour, cream of tartar and baking soda, and set aside. In the bowl of a stand mixer fitted with the paddle attachment, cream together the butter, 1 ¾ cups sugar and the salt on medium-high until very smooth and fluffy, 3 to 4 minutes."},{"n":2,"title":null,"text":"Scrape down the sides of the bowl, return the mixer to medium speed and add the egg and egg yolks, incorporating each before adding the next. Add the rum extract. Scrape down the sides of the bowl and continue to beat for another minute or two."},{"n":3,"title":null,"text":"Add the flour mixture and beat on low speed until combined. (You may want to start by “pulsing” the flour, so that it doesn’t go everywhere.) Set the dough aside to hydrate for about 10 minutes while you prepare to bake."},{"n":4,"title":null,"text":"Heat oven to 350 degrees and line 2 rimmed baking sheets with parchment paper. Make the nutmeg-sugar mixture by combining the remaining ¼ cup/50 grams sugar with the nutmeg in a small bowl."},{"n":5,"title":null,"text":"Roll the dough into balls, each one the size of a golf ball or about 45 grams, then roll each dough ball in the nutmeg-sugar. Transfer the balls to the baking sheets, about 2 inches apart, and bake 10 to 13 minutes, rotating pans and switching racks halfway through, until slightly puffed and just set."},{"n":6,"title":null,"text":"Let the cookies cool slightly on the baking sheet before transferring them to a wire rack to cool completely. These cookies are even better the day after they're made, and will keep for 4 days sealed in an airtight container."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["eggs"],"item_tags":["cream of tartar","nutmeg","rum extract"],"course_tags":["Dessert"],"keywords":["American","Christmas","Christmas Cookie","Cookie","Dessert","Make-Ahead","Nutmeg","Winter"],"issues":null,"front":"nyt_1021715.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021715-eggnog-snickerdoodles","rating":{"value":5,"count":4170},"date":"2020-12-08"},{"pair":1020907,"title":"Toor Dal (Split Yellow Pigeon Peas)","subtitle":null,"author":"Tejal Rao","servings":"4 to 6","yield_text":"4 to 6 servings (about 3 cups)","yield_count":4,"cook_time":"1 1/4 hours, plus soaking","nutrition":{"calories":"161","fat":"13 g","carbohydrates":"10 g","protein":"4 g"},"description":"Dal can be made with all kinds of lentils and cooking methods. These vary not just from region to region, but also from day to day, mood to mood. Some cooks like dal soupy, others chunky. There are dals for special occasions, seasoned with charcoal smoke and butter or padded out luxuriously with cream, as well as lighter, leaner dals that can restore you when you’re not feeling well.The flavor of this everyday, Gujarati-style dal comes from the pure nuttiness of split pigeon peas, boiled until tender and bolstered with spices bloomed in hot ghee. This fat-tempering technique, called vaghar in Gujarati, has many names and many uses across the country. In this case, the tempering is a great introduction to the resourcefulness and finesse of Indian home cooks: Just a few tablespoons of carefully seasoned fat, tipped in at the very last moment, transform an entire pot.","from_your_kitchen":null,"ingredients":["1 cup toor dal (split yellow pigeon peas)","2 Roma tomatoes, roughly chopped","¼ teaspoon ground turmeric","½ teaspoon kosher salt","¼ cup raw whole peanuts","¼ cup/55 grams ghee","1 sprig fresh curry leaves","3 small pieces Indian cinnamon or 1 cinnamon stick","3 red dried chiles, such as chile de árbol","3 cloves","¼ teaspoon black mustard seeds","Pinch of asafoetida"],"ingredient_groups":[{"at":0,"title":"FOR THE DAL"},{"at":5,"title":"FOR THE TEMPERING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the dal: Soak the pigeon peas in a large bowl of warm water for about 1 hour. (They will have swelled a little.) Thoroughly rinse the soaked pigeon peas with fresh water, then tip the drained pigeon peas into a pot."},{"n":2,"title":null,"text":"Add tomatoes, turmeric, salt and 5 cups water, and bring to a boil over high. Reduce the heat to medium and simmer until very tender, 25 to 30 minutes."},{"n":3,"title":null,"text":"Use an immersion blender to purée some of the dal, leaving some intact and getting some very smooth, or whisk vigorously to break up some of the soft dal. Stir in the peanuts and continue to simmer, stirring occasionally, until the dal is very tender, about 30 minutes. Taste and adjust with salt. If the dal has become too thick for your liking, stir in a splash of water."},{"n":4,"title":null,"text":"Prepare the tempering: In a small saucepan over medium heat, warm the ghee. When hot, carefully add all of the tempering ingredients (the mustard seeds will sputter!) and swirl the pan until you can smell all the toasted spices, about 30 seconds. Pour everything over the hot dal."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["lentils","peanuts"],"item_tags":["cinnamon","curry leaves","ghee","turmeric"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Cinnamon","Curry Leaf","Dinner","Freezer Friendly","Ghee","Great Leftovers","Indian","Main Course","Side Dish","Simmer","Soups and Stews","Tomato","Turmeric","Vegetarian"],"issues":null,"front":"nyt_1020907.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020907-toor-dal-split-yellow-pigeon-peas","rating":{"value":4,"count":1249},"date":"2020-03-11"},{"pair":1021641,"title":"Cranberry Lemon Bars","subtitle":null,"author":"Genevieve Ko","servings":null,"yield_text":"2 dozen bars","yield_count":24,"cook_time":"1 hour, plus cooling and chilling","nutrition":{"calories":"180","fat":"7 g","carbohydrates":"28 g","protein":"2 g"},"description":"Cranberries that are quick-cooked into jam add a striking magenta color and complex tartness to these two-toned lemon bars. A thin layer of the classic lemon filling coats the cranberry mix like icing, and lemon zest boiled with the berries echoes the citrus taste of the lemony top. (Its pectin also thickens the jam.) To achieve a sturdy crust that isn’t tough, melted butter is stirred into a flour blend and simply patted into the pan. That vanilla cookie base, generously salted to balance the tangy sweetness on top, comes out crisp and holds up well even as the bars keep in the refrigerator for up to five days.","from_your_kitchen":null,"ingredients":["1 (12-ounce/340-gram) bag fresh or frozen cranberries","¾ cup/150 grams granulated sugar","2 to 3 large lemons","Nonstick cooking spray","1 ½ cups/190 grams all-purpose flour","⅓ cup/65 grams granulated sugar","1 teaspoon fine sea salt","1 teaspoon vanilla extract","¾ cup/170 grams unsalted butter (1 ½ sticks), melted and cooled","1 cup/200 grams granulated sugar","¼ cup/30 grams all-purpose flour","⅛ teaspoon fine sea salt","3 large eggs, at room temperature","Powdered sugar (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE CRANBERRY LAYER"},{"at":3,"title":"FOR THE CRUST"},{"at":9,"title":"FOR THE LEMON LAYER"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Start preparing the cranberry layer: Combine the cranberries, sugar and 3 tablespoons water in a medium saucepan. Zest 2 of the lemons directly into the saucepan; reserve the lemons."},{"n":2,"title":null,"text":"Bring to a boil over medium-high heat, stirring occasionally. Continue boiling, stirring occasionally, until the berries burst and the mixture is jammy, 7 to 9 minutes. Remove from the heat and reserve."},{"n":3,"title":null,"text":"Make the crust: Heat oven to 350 degrees. Line the bottom and sides of a 9-by-13-inch baking pan with one large sheet of heavy aluminum foil, making sure there are no gaps or holes, then generously coat with cooking spray."},{"n":4,"title":null,"text":"Whisk the flour, sugar and salt in a medium bowl. Whisk the vanilla into the butter, then pour over the flour mixture. Stir until the dough comes together in a mass. Press into an even layer in the prepared pan. Bake until golden brown around the edges and dry and golden on top, 17 to 20 minutes."},{"n":5,"title":null,"text":"While the crust bakes, begin preparing the lemon layer: Squeeze the juice from the 2 reserved zested lemons. You should have ½ cup. Squeeze the juice from another lemon, if needed."},{"n":6,"title":null,"text":"Whisk the sugar, flour and salt in a medium bowl. Add the eggs and whisk gently just until incorporated. Add the lemon juice and stir gently with the whisk just until smooth."},{"n":7,"title":null,"text":"Let the crust cool for 5 minutes, then spread the cranberry mixture evenly over the crust. Carefully and slowly pour the lemon mixture on top to create two distinct layers."},{"n":8,"title":null,"text":"Return the pan to the oven and bake until the filling is set, 18 to 22 minutes. Cool completely in the pan on a wire rack, then refrigerate until cold and firm, at least 2 hours. Using the foil, slide the bars out of the pan and onto a cutting board. Cut into 24 squares, wiping your knife between cuts for clean slices. If desired, sift powdered sugar over the tops just before serving."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["cranberries"],"item_tags":["lemon","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Bar Cookie","Christmas","Cranberry","Dessert","Fall","Lemon","Make-Ahead","Plan-Ahead","Thanksgiving"],"issues":null,"front":"nyt_1021641.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021641-cranberry-lemon-bars","rating":{"value":4,"count":7659},"date":"2020-11-18"},{"pair":1021483,"title":"Salt-Baked New Potatoes With Pink-Peppercorn Butter","subtitle":null,"author":"Gabrielle Hamilton","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"45 minutes","nutrition":{"calories":"197","fat":"12 g","carbohydrates":"22 g","protein":"3 g"},"description":"This way of cooking recently harvested new potatoes, by burying them in a plaster of damp salt and baking them, is a triple pleasure: effortless, tasty and very fun. The salt crust seasons the potatoes perfectly, just as it would if you’d boiled or steamed them in salted water, but the airtight seal concentrates their special flavor and texture. They come out dense, waxy and almost creamy. Bring the pan of cooked potatoes to the table right from the oven as is, so everyone can puzzle over the curious-looking white crust, and then delight over the discovery of the piping hot little beauties revealed inside once the surface is cracked. Dig them out and swoop through the butter before popping into your mouth, their skins so paper-thin they snap when you bite into them. Their appeal is irresistible.","from_your_kitchen":null,"ingredients":["2 pounds small, yellow-fleshed waxy potatoes (it’s fine if skins are red or purple or yellow)","2 pounds kosher salt","2 tablespoons fresh rosemary needles, stripped from their branch","2 tablespoons pink peppercorns","1 tablespoon pink peppercorns","1 or 2 soft, velvety branches of rosemary (versus the very stiff, broom-bristle kind)","4 ounces salted Irish butter, tempered at room temperature until cool and waxy"],"ingredient_groups":[{"at":0,"title":"FOR THE POTATOES"},{"at":4,"title":"FOR THE COMPOUND BUTTER"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 400 degrees. Wash the potatoes."},{"n":2,"title":null,"text":"In a large bowl, mix the salt, rosemary needles, peppercorns and 1 cup water together with your hands, crushing the peppercorns a little between your fingers and bruising the rosemary needles to release their sticky oil, making a moist, fragrant and pink-and-green speckled sand. (You might have to add a few splashes of water if the mixture needs more moisture to feel like wet sand.)"},{"n":3,"title":null,"text":"Transfer a little less than half this salt mixture into the bottom of a wide, shallow, heavy ovenproof skillet or casserole to make a salt bed about ½-inch thick."},{"n":4,"title":null,"text":"Nestle the potatoes into the sand, close to one another but not quite touching, if possible."},{"n":5,"title":null,"text":"Pack the rest of the salt mixture over the nestled potatoes, and rub and brush and smooth it with your hands until you have tightly encased the potatoes in a little salt sarcophagus. The rounded tops of the potatoes will just show as bumps under the salt cast."},{"n":6,"title":null,"text":"Bake the potatoes for 30 to 40 minutes, until a cake tester easily pierces the potatoes and tests warm on your chin or the back of your hand. The salt casing will dry and harden like clay — and smell delicious while baking."},{"n":7,"title":null,"text":"While the potatoes roast, prepare the compound butter: Grind the peppercorns in a mortar and pestle with the whole branches of rosemary to create an oily, coarse powder. Remove the bruised rosemary sprigs, shaking off any clinging pink peppercorns, and discard. (You just want to extract the oily flavor from the rosemary, not the needles themselves.) In a small bowl, mash the oily peppercorn powder with the salted butter using a fork until well blended."},{"n":8,"title":null,"text":"To serve, rap the salt-packed potatoes forcefully on a sturdy surface that can handle it, to crack the salt crust from the force. A few solid raps will loosen the potatoes inside. If the cast needs a little more help, use a regular dinner knife like a spade to just pop open the salt crust along its fault lines. The potatoes are easily plucked from the dry salt. Set out with the compound butter in a small bowl on the side."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["potato"],"item_tags":["pink peppercorns","rosemary"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["American","Bake","Dinner","Five Ingredient","Potato","Rosemary","Side Dish","Vegetables","Vegetarian","Waxy Potato"],"issues":null,"front":"nyt_1021483.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021483-salt-baked-new-potatoes-with-pink-peppercorn-butter","rating":{"value":4,"count":1293},"date":"2020-10-04"},{"pair":1021609,"title":"Herby Bread-and-Butter Stuffing for Two","subtitle":null,"author":"Melissa Clark","servings":"2","yield_text":"2 servings","yield_count":2,"cook_time":"45 minutes","nutrition":{"calories":"322","fat":"21 g","carbohydrates":"26 g","protein":"9 g"},"description":"This fairly classic stuffing recipe has been scaled down to feed two (generously). Filled with buttery sautéed shallots and plenty of herbs, it’s rich and soft in the center, and golden and crunchy on top. A small shallow gratin dish, about 6 inches in diameter, is your best option for baking, but any dish, loaf pan, or skillet with a 3- to 4-cup capacity will work.","from_your_kitchen":null,"ingredients":["3 tablespoons unsalted butter, plus more for greasing the pan","1 large or 2 small shallots, diced","¼ teaspoon kosher salt, plus a large pinch","1 teaspoon chopped fresh marjoram or thyme leaves (or use a large pinch of dried)","½ to ¾ cup turkey, chicken or vegetable broth","1 egg","¼ cup chopped fresh soft herbs (use 2 or 3 of the following: parsley, tarragon, chives, mint, basil, cilantro, dill or celery leaves)","About 2 ½ cups torn-up stale white or whole-wheat bread, not too crusty (3 ounces)","Black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 375 degrees. Grease a small, shallow gratin dish, casserole dish or loaf pan with a 3- to 4-cup capacity."},{"n":2,"title":null,"text":"In a small skillet, melt 2 tablespoons butter over medium heat. Stir in shallots and a large pinch of salt. Cook until soft and just starting to brown, 3 to 4 minutes. Stir in marjoram and cook for 1 minute longer."},{"n":3,"title":null,"text":"In a medium bowl, whisk together ½ cup broth, egg, chopped herbs and ¼ teaspoon salt. Fold in bread and shallots, letting the bread absorb the liquid. It should be very moist. (If the mixture seems dry, add more stock a little at a time, using up to another ¼ cup.)"},{"n":4,"title":null,"text":"Spoon stuffing into the prepared baking dish and grind some black pepper onto the top. Cut the remaining tablespoon butter into small pieces and scatter over the top. Bake until golden brown and firm, about 30 minutes. Serve hot or warm."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["bread"],"item_tags":["parsley","shallot","thyme"],"course_tags":["Sides & Appetizers"],"keywords":["Bake","Broth","Christmas","Fall","Shallot","Side Dish","Stuffing and Dressing","Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_1021609.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021609-herby-bread-and-butter-stuffing-for-two","rating":{"value":4,"count":1412},"date":"2020-11-11"},{"pair":1020731,"title":"Mushroom Potpie","subtitle":null,"author":"Alexa Weibel","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 1/2 hours","nutrition":{"calories":"785","fat":"57 g","carbohydrates":"60 g","protein":"13 g"},"description":"Dried porcini mushrooms and caramelized fresh mushrooms give this dish plenty of deep, earthy flavor. Sweet parsnips, garlicky kale, carrots and potatoes round out the mushroom filling, but if those don’t suit you, the filling is fully flexible. Substitute butternut squash, celery root or just about any root vegetable for the carrots, parsnips and potatoes. The entire dish cooks in a large ovenproof skillet, but you could also transfer the filling to buttered ramekins for individual pies, or divide the mixture between two 8-inch pie dishes for two separate pies. Rich and creamy, it feeds a crowd, and can easily be prepared in advance: Refrigerate the cooked filling overnight, then warm it on the stovetop, assemble and bake. The results justify the effort.","from_your_kitchen":null,"ingredients":["½ cup dried porcini mushrooms (½ ounce)","4 tablespoons olive oil, plus more as needed","½ pound fresh oyster mushrooms, torn into separate pieces (or shiitake mushrooms, stemmed and halved)","Kosher salt and black pepper","½ pound cremini mushrooms, stemmed and quartered (or cut into sixths if large)","4 tablespoons unsalted butter","1 large yellow onion, finely chopped","¼ pound lacinato kale, stemmed, leaves thinly sliced crosswise","4 garlic cloves, chopped","1 tablespoon fresh thyme leaves","2 teaspoons chopped fresh rosemary","¼ cup all-purpose flour, plus more for dusting","1 ½ cups chicken or vegetable stock","¾ cup heavy cream","1 cup diced peeled carrots (from 2 medium carrots, cut into ½-inch pieces)","1 cup diced peeled parsnips (from 2 medium parsnips, cut into ½-inch pieces)","1 cup diced red potatoes (from 2 small potatoes, cut into ½-inch pieces)","1 (14- to 16-ounce) package puff pastry, thawed","1 large egg"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Bring 2 cups of water to boil in a small pot. Place the porcini mushrooms in a medium bowl and pour the boiling water on top; set aside to soak and soften."},{"n":2,"title":null,"text":"Meanwhile, in a large (12-inch) ovenproof skillet, heat 2 tablespoons oil over medium-high. Working in two batches so the mushrooms brown evenly, add half the oyster mushrooms, season with salt and pepper and cook, undisturbed, until browned underneath, about 3 minutes. Stir the mushrooms, then continue to cook until browned all over, about 3 minutes. Transfer to a medium bowl. Repeat with 2 tablespoons oil and the remaining oyster mushrooms; transfer them to the medium bowl. Add another 2 tablespoons oil, then add the cremini mushrooms, season with salt and pepper and cook, stirring occasionally, until browned and tender, 6 to 8 minutes, lowering the heat as needed to avoid burning. Transfer to the bowl."},{"n":3,"title":null,"text":"Reduce the heat to medium and add the butter to the skillet. Once the butter is melted, add the onion and cook until starting to soften, about 5 minutes. Add the kale, garlic, thyme and rosemary, season with salt and pepper and cook, stirring occasionally, until softened, about 3 minutes, adding 1 to 2 tablespoons oil if the pan seems dry. Sprinkle with the flour and cook, stirring, until flour is dispersed and lightly toasted, 2 minutes."},{"n":4,"title":null,"text":"Stirring constantly, gradually add the stock, cream and ¾ cup of the liquid from the soaking porcini mushrooms. Cook over medium heat, stirring occasionally, until thickened, about 5 minutes. Remove from heat, then stir in the carrots, parsnips, potatoes, and the sautéed mushrooms and any accumulated juices. Strain the soaked porcini mushrooms, discarding any remaining liquid, then roughly chop the mushrooms and stir them into the filling. Season to taste with salt and pepper. (If making ahead, the filling can be refrigerated a day in advance; just warm it up slightly before assembling and baking.)"},{"n":5,"title":null,"text":"On a lightly dusted work surface using a lightly floured rolling pin, roll out the puff pastry into a roughly 14-inch circle. Transfer to the top of the skillet, allowing slight overhang, folding under and pinching any overhang just below the rim of the skillet. In a small bowl, whisk the egg with 1 teaspoon water. Lightly brush the egg wash over the top of the puff pastry, then cut 5 (2-inch) slits into the puff pastry, starting near the center and radiating outward, like the rays of the sun, or create a stripe or crisscross pattern in the puff pastry by gently scoring it with a paring knife without fully cutting through. Crimp the edges using the tines of a fork, if desired."},{"n":6,"title":null,"text":"Set the skillet on top of an aluminum foil-lined baking sheet and transfer to the middle rack of the oven. Bake until the puff pastry is puffed and golden, about 30 minutes. Let sit 10 minutes before serving."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["carrot","kale","mushrooms","parsnip","potato"],"item_tags":["puff pastry","rosemary","thyme"],"course_tags":["Dinner"],"keywords":["Carrot","Cremini","Dinner","Dried Porcini","Fall","Kale","Main Course","Oyster Mushroom","Parsnip","Potpie","Puff Pastry","Red Potato","Shiitake","Winter"],"issues":null,"front":"nyt_1020731.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020731-mushroom-potpie","rating":{"value":4,"count":2833},"date":"2022-10-22"},{"pair":1021372,"title":"Sabudana Khichdi (Maharashtrian Tapioca Pilaf)","subtitle":null,"author":"Samin Nosrat","servings":"4","yield_text":"4 servings as a side or 1 to 2 as a main","yield_count":4,"cook_time":"45 minutes, plus 4 to 5 hours’ soaking","nutrition":{"calories":"508","fat":"20 g","carbohydrates":"77 g","protein":"10 g"},"description":"Sabudana khichdi, which loosely translates to “tapioca mixture,” is a delightfully chewy Maharashtrian pilaf studded with the crunch of toasted peanuts, creamy bits of potato, and the occasional cumin seed. A hit of sweetness is balanced with salt, lemon and the alternating flames of ginger and green chile, and then everything is showered with a generous amount of chopped cilantro. The result is seductive in both texture and flavor. The key to this simple dish is to thoroughly soak the sabudana, or medium-sized tapioca pearls, until you can easily smash one between your thumb and forefinger. Then, use a microwave to cook the sabudana, stopping to check for doneness in 15-second increments. As soon as the pearls are translucent and chewy, they’re done. Samin Nosrat","from_your_kitchen":null,"ingredients":["1 cup medium tapioca pearls (look for sabudana at an Indian grocer)","3 or 4 small-medium yellow potatoes (about 8 ounces), such as Yukon Gold or Yellow Finn","Fine sea salt","½ cup raw peanuts","4 to 5 Thai chiles, stems removed, roughly chopped","1 (3-inch) piece fresh ginger, peeled and sliced into ¼-inch coins","3 tablespoons neutral oil, such as canola","1 teaspoon cumin seeds","1 to 2 teaspoons granulated sugar","1 to 2 tablespoons freshly squeezed lemon juice","2 tablespoons roughly chopped cilantro, for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place tapioca in a large bowl and cover with water. Swirl to release starch, then drain. Repeat a few times until water runs mostly clear, then drain well. Return tapioca to bowl, along with ¾ cup water. Soak for 4 to 5 hours, or until water is mostly absorbed and tapioca pearls are easily squashed when pressed between your thumb and forefinger. Drain well, and place into a large microwave-safe bowl."},{"n":2,"title":null,"text":"Place whole potatoes in a small pot and cover with water. Season generously with salt and set over high heat. Bring to a boil, then reduce to a simmer and cook until completely tender, about 25 to 35 minutes, depending on size. Remove potatoes from water, allow to cool, then peel, and dice into ½-inch cubes. Add to tapioca."},{"n":3,"title":null,"text":"Set a frying pan over medium heat and add peanuts. Swirling constantly, toast them until shiny, aromatic and golden brown, about 4 minutes. Pour immediately onto a plate to prevent overcooking. Wipe pan, and return to stove."},{"n":4,"title":null,"text":"In a food processor, pulse chiles and ginger together until finely minced, stopping to scrape down the sides with a rubber spatula once or twice. (If you don’t have a food processor, you can do this step by hand.) Remove 1 tablespoon chile-ginger mixture, and set aside. Add cooled peanuts to food processor, and continue to pulse just long enough to roughly chop nuts. Scrape peanut-chile mixture into tapioca-potato mixture."},{"n":5,"title":null,"text":"Heat frying pan over a medium flame and add oil. When oil shimmers, add cumin. When cumin begins to sizzle, stir in reserved chile-ginger mixture, and allow to sizzle but not brown, then immediately pour into tapioca mixture. Add 1 teaspoon sugar, toss and season with salt to taste."},{"n":6,"title":null,"text":"Microwave tapioca mixture on high for 2 minutes, then stir. Continue cooking for another 2 minutes, then stir again. Cook for another 1 to 2 minutes in 15-second increments, until tapioca is translucent and chewy, but not quite transparent and clumpy."},{"n":7,"title":null,"text":"Taste and adjust seasoning with salt, sugar and lemon juice. Garnish with cilantro, and serve hot."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["peanuts","potato","tapioca"],"item_tags":["cumin seeds","ginger","thai chile"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Cumin","Dinner","Ginger","Indian","Lunch","Main Course","Peanut","Potato","Side Dish","Vegan","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021372.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021372-sabudana-khichdi-maharashtrian-tapioca-pilaf","rating":{"value":4,"count":760},"date":"2020-08-23"},{"pair":1020083,"title":"Creamy White Bean and Fennel Casserole","subtitle":null,"author":"Aaron Hutcherson","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"424","fat":"23 g","carbohydrates":"44 g","protein":"14 g"},"description":"This one-pan recipe melds roasted fennel, creamy white beans and salty Parmesan, and tops it with crunchy lemon-zested panko. Fennel is often dismissed because of its perceived licorice notes, but the anise flavor is significantly muted after the vegetable is cooked. Tuck fresh, sliced sausages into the mixture before baking to imitate a simplified cassoulet, turn it into a side dish by pairing it with meat or let the dish live as a main, served with a simple green salad and some rustic bread to sop up the sauce. Reserve the fresh fennel fronds for garnish, which add concentrated fennel flavor and a pop of green.","from_your_kitchen":null,"ingredients":["6 tablespoons olive oil","2 large fennel bulbs (about 2 pounds)","Kosher salt and black pepper","2 garlic cloves, minced","2 (14-ounce) cans white beans, such as cannellini, great Northern or navy","½ cup heavy cream","1 teaspoon fresh lemon zest plus 2 tablespoons juice (from 1 lemon)","½ cup panko","½ packed cup finely grated Parmesan (about 1 ounce)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 425 degrees. Trim the fennel. Cut it in half lengthwise and slice it crosswise, about ¼-inch thick (reserve about ¼ cup roughly chopped fennel fronds). Heat 2 tablespoons oil in a large cast-iron skillet over medium. Add the sliced fennel, season with salt and pepper and cook, stirring occasionally, until softened but still retaining a little bite, about 12 minutes. Stir in the garlic and cook until fragrant, 1 to 2 minutes."},{"n":2,"title":null,"text":"Meanwhile, pour 1 can white beans and its liquid into a blender. Add the heavy cream, lemon juice and 2 tablespoons olive oil and purée until smooth. Drain and rinse the remaining can of beans and transfer it to the skillet along with the bean purée. Season generously with salt and pepper."},{"n":3,"title":null,"text":"Mix the panko with the remaining 2 tablespoons olive oil in a small bowl. Add the Parmesan, lemon zest and ½ teaspoon pepper and toss to coat. Sprinkle evenly over the fennel-white bean mixture."},{"n":4,"title":null,"text":"Bake until bubbly and lightly golden on top, about 15 minutes. Broil until topping is browned in spots, 1 to 2 minutes, if desired. Top with reserved fennel fronds and serve."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["fennel","white beans"],"item_tags":["lemon","panko breadcrumbs","parmesan"],"course_tags":["Sides & Appetizers"],"keywords":["American","Casseroles","Easy","Fall","Fennel","Great Leftovers","Heavy Cream","Panko","Parmesan","Side Dish","Thanksgiving","Vegetables","White Bean","Winter"],"issues":null,"front":"nyt_1020083.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020083-creamy-white-bean-and-fennel-casserole","rating":{"value":4,"count":2540},"date":"2019-03-06"},{"pair":1021273,"title":"White Bean Caprese Salad","subtitle":null,"author":"Colu Henry","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"10 minutes","nutrition":{"calories":"289","fat":"15 g","carbohydrates":"24 g","protein":"16 g"},"description":"Beloved pantry white beans add substance to this take on caprese salad, which comes together in no time. It’s a perfect side for grilled chicken or fish, and can be easily doubled to work as a main course when it’s too hot to turn on the oven. If you’re so inclined, a handful of spicy arugula, thinly sliced roasted red peppers or ribbons of prosciutto — or all three — would also be nice additions. This dish is easily transportable and tastier when eaten while sitting in a lawn chair.","from_your_kitchen":null,"ingredients":["1 (14-ounce) can white beans, such as cannellini, rinsed","5 ounces cherry or grape tomatoes, halved","5 ounces ciliegine (small mozzarella balls), at room temperature, halved lengthwise, or good-quality fresh mozzarella, torn into bite-size pieces","¼ cup loosely packed basil leaves, torn if large","2 tablespoons olive oil, plus more as needed","Kosher salt and black pepper","2 teaspoons good-quality balsamic vinegar, plus more as needed","Flaky salt"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a medium bowl, combine the beans, tomatoes, cheese and half the basil. Gently toss together."},{"n":2,"title":null,"text":"Add the olive oil and season the mixture well with salt and pepper. Gently stir to combine."},{"n":3,"title":null,"text":"Drizzle the salad with the balsamic vinegar and top with the remaining basil. Taste and adjust seasonings to your liking. Add a drizzle or so more of oil and vinegar if needed. Finish with flaky salt."}],"tips":[],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["tomato","white beans"],"item_tags":["balsamic vinegar","basil","mozzarella"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Basil","Cherry Tomato","Dinner","Easy","Five Ingredient","Grape Tomato","Lunch","Main Course","Mozzarella","No Cook","Picnic","Quick","Salad","Side Dish","Summer","Vegetarian","Weeknight","White Bean"],"issues":null,"front":"nyt_1021273.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021273-white-bean-caprese-salad","rating":{"value":5,"count":4880},"date":"2020-07-23"},{"pair":1020976,"title":"Lentils Cacciatore","subtitle":null,"author":"Ali Slagle","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"180","fat":"5 g","carbohydrates":"24 g","protein":"8 g"},"description":"Chicken cacciatore is an Italian hunter’s stew that’s made by braising chicken with tomato, aromatics and vegetables, like red peppers, onions, carrots, rosemary, olives and so on. This braise’s cozy, deep flavors are equally tasty with red lentils in place of the poultry. In less than half an hour, red lentils break down to create a creamy, rich vegetarian stew. Carrots and red peppers make it a hearty meal, but you could also eat it over pasta, polenta or farro. If serving with pasta, thin the cacciatore with a little pasta water before tossing with the noodles.","from_your_kitchen":null,"ingredients":["2 tablespoons extra-virgin olive oil","2 large carrots, peeled and cut into ¼-inch pieces","1 red bell pepper, stems and seeds removed, thinly sliced lengthwise","Kosher salt and black pepper","¼ cup capers, drained","3 tablespoons tomato paste","5 garlic cloves, thinly sliced","1 ½ teaspoons fresh rosemary or ½ teaspoon dried rosemary","½ cup red wine or stock (or 2 tablespoons red wine vinegar, apple cider vinegar or sherry vinegar)","1 (14-ounce) can crushed or diced tomatoes","¾ cup red lentils (see Tip)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large Dutch oven or pot, heat the oil over medium-high. Add the carrots and bell pepper, season with salt and pepper, and cook until just softened, 3 minutes."},{"n":2,"title":null,"text":"Add the capers, tomato paste, garlic and rosemary and cook, stirring occasionally, until the tomato paste begins to stick to the bottom of the pot, 2 to 3 minutes."},{"n":3,"title":null,"text":"Add the wine, season with salt and pepper, and cook until nearly all the liquid has evaporated, 2 to 3 minutes."},{"n":4,"title":null,"text":"Add the tomatoes, red lentils and 2 ½ cups water. Bring to a boil, partly cover, then reduce the heat and simmer until the lentils start to break down and lose their shape, 20 to 25 minutes. Stir vigorously from time to time to scrape any stuck lentils from the bottom of the pot. Season generously with salt and pepper."}],"tips":["You could also use canned white beans, or dried brown lentils, which won’t break down as much as red lentils."],"cuisine_tags":["Italian"],"ingredient_tags":["bell pepper","carrot","red lentils"],"item_tags":["capers","red wine","rosemary","tomato paste"],"course_tags":["Dinner"],"keywords":["Bell Pepper","Caper","Carrot","Dinner","Garlic","Great Leftovers","Main Course","Quick","Red Lentil","Red Wine","Rosemary","Stew","Tomato","Tomato Paste","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020976.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020976-lentils-cacciatore","rating":{"value":4,"count":3380},"date":"2020-04-02"},{"pair":1020596,"title":"Vegetarian Mushroom Wellington","subtitle":null,"author":"Alexa Weibel","servings":"8","yield_text":"8 servings","yield_count":8,"cook_time":"3 hours","nutrition":null,"description":"Classic beef Wellington is a technical feat in which a tenderloin is topped with foie gras or mushroom duxelles, then wrapped in puff pastry and baked. This vegetarian version is less exacting yet just as impressive. Seared portobello mushrooms are layered with apple cider-caramelized onions and sautéed mushrooms, which are seasoned with soy sauce for flavor and bolstered with walnuts for texture. The rich mushroom filling is vegan, and the entire dish can easily be made vegan, too. Swap in vegan puff pastry, a butter substitute in the port reduction and caramelized onions, and an egg substitute for brushing the puff pastry. You can assemble and refrigerate the dish up to 1 day before baking it. Prepare the port reduction as the Wellington bakes, or skip it entirely and serve with cranberry sauce for a touch of tangy sweetness.","from_your_kitchen":null,"ingredients":["4 large portobello mushrooms, each about 3 inches wide (8 to 10 ounces total)","½ cup plus 5 tablespoons olive oil","Kosher salt and black pepper","2 pounds mixed mushrooms, such as shiitake, oyster and cremini","Ice, for cooling","4 shallots, finely chopped (about 1 packed cup)","6 garlic cloves, finely chopped","2 tablespoons finely chopped fresh rosemary","⅓ cup port, or 1 to 2 tablespoons good-quality aged balsamic vinegar","2 tablespoons soy sauce","1 tablespoon fresh thyme leaves","1 cup finely chopped toasted walnuts (about 4 ounces)","3 tablespoons unsalted butter","2 small yellow onions, cut into ¼-inch rounds","¾ teaspoon light or dark brown sugar","1 ¼ teaspoons kosher salt","¾ teaspoon black pepper","1 cup apple cider or apple juice","1 tablespoon good-quality aged balsamic vinegar (optional)","All-purpose flour, for dusting","1 (14-ounce) package puff pastry","1 large egg, beaten","2 tablespoons olive oil","1 large shallot, minced","2 garlic cloves, minced","2 teaspoons whole black peppercorns","1 ½ cups good-quality port","1 ½ cups vegetable stock","3 fresh thyme sprigs","3 tablespoons unsalted butter","Kosher salt and black pepper"],"ingredient_groups":[{"at":0,"title":"FOR THE MUSHROOM FILLING"},{"at":12,"title":"FOR THE ONIONS"},{"at":19,"title":"FOR ASSEMBLING"},{"at":22,"title":"FOR THE PORT REDUCTION (OPTIONAL)"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Wipe the portobello mushrooms clean using moist paper towels. Remove the stems, then slice off the excess rim that curls over the gills, creating a flat surface so the mushrooms can sear. Reserve the stems and scraps for use in Step 2. Brush the caps on both sides with 3 tablespoons olive oil and season generously with salt and pepper. Heat 2 tablespoons olive oil in a large nonstick skillet over medium-high and cook the mushrooms, gill-side down, until caramelized, 5 minutes, then flip and cook another 5 minutes. Transfer to a wire rack, gill-side down, to cool."},{"n":2,"title":null,"text":"Prepare the mushroom filling: Separate and reserve any mushroom stems. (If using shiitake mushrooms, save their woody stems for another use.) Roughly chop about two-thirds of the mixed mushrooms, then working in batches, transfer the roughly chopped mushrooms to a food processor and pulse into small, ¼- to ½-inch pieces; transfer to a large bowl. By hand, finely chop the remaining mixed mushrooms and stems (including the reserved portobello mushroom stems and trimmings) into ¼-inch pieces; add them to the bowl."},{"n":3,"title":null,"text":"Prepare an ice bath in a large bowl. (If preparing the mushrooms in advance, you can simply let the mixture cool to room temperature, then refrigerate.) Wipe out the skillet. Working in two batches, warm ¼ cup olive oil over medium-high. Add half the mushrooms, shallots, garlic and rosemary, and season with salt and pepper. Cook, stirring occasionally, until caramelized and tender, about 10 minutes. Transfer to a medium bowl. Repeat with the remaining ¼ cup oil and the remaining mushrooms, shallots, garlic and rosemary. Return the first batch to the skillet. Add the port, soy sauce and thyme leaves and cook over medium-high, stirring occasionally, until the liquid evaporates, 3 to 4 minutes. Transfer the mixture back to the medium bowl and stir in the walnuts. Set the bowl over the ice bath to cool, stirring occasionally, at least 20 minutes."},{"n":4,"title":null,"text":"Prepare the onions: Wipe out the skillet, then melt the butter over medium heat. Add the onions, sugar, salt and pepper, and cook, stirring occasionally, 5 minutes. Add the cider and cook, stirring occasionally, until the liquid evaporates and the onions are caramelized, about 15 minutes. Stir in the vinegar, if using, then let cool."},{"n":5,"title":null,"text":"Heat the oven to 400 degrees. Place a large piece of parchment paper on your work surface and lightly dust it with flour. Unfold your thawed puff pastry on the parchment. Using a lightly floured rolling pin, roll the pastry out into a 13-by-16-inch rectangle. Transfer the parchment paper and puff pastry to a large sheet pan. Rotate as needed so that one of the 16-inch sides is closest to you. Arrange half the cooked mushroom mixture in a 4-by-10-inch strip in the center of the puff pastry, leaving a 1½-inch border at the ends. Arrange the caramelized onions in a 3-inch-wide strip on top. Lay the portobello mushrooms on top of the onions in a single line, stem-side down. (If the portobellos are too large, square off edges.) Spoon the remaining mushroom mixture on top, covering the portobello mushrooms, then gently pack the mushroom mixture to form an even layer on top, shaping it like a freeform meatloaf."},{"n":6,"title":null,"text":"Lift one side of the puff pastry over the filling to almost completely cover it. Brush the surface of the puff pastry covering the mushrooms with the beaten egg. Lift the remaining puff pastry flap over the egg-washed puff pastry, gently stretching it if need be to create a second layer of puff pastry on top, then gently press the top layer of pastry onto the lower layer to seal. Brush the insides of the short ends of the puff pastry and press to seal, tucking both sides underneath. Trim any parchment paper that extends beyond the sheet pan. (You can refrigerate the pastry for up to 1 day at this point.)"},{"n":7,"title":null,"text":"Brush the exposed puff pastry on top with the remaining beaten egg. Decorate the top of the puff pastry as you like: Create a cross-hatch pattern by gently slicing through only the top layer of puff pastry in parallel lines, then cutting parallel lines in another direction. (Apply very little pressure, as you only want to cut through the top layer of puff pastry.) You can also slice small decorative vents (be sure to slice all the way through both layers of puff pastry), or top with additional strips or shapes made from egg-washed puff pastry. Bake until puff pastry is deep golden and flaky, 45 to 50 minutes. Let cool slightly on the baking sheet, about 10 minutes."},{"n":8,"title":null,"text":"While the Wellington bakes, prepare the optional port reduction: In a medium saucepan, heat the oil over medium. Add the shallot, garlic and peppercorns, and cook, stirring occasionally, 3 minutes. Add the port, stock and thyme; cook over medium-high until the sauce is glossy, 25 to 30 minutes. Strain the sauce; you should have about ½ cup. When ready to serve, reheat over medium, whisk in the butter, and season with salt and pepper."},{"n":9,"title":null,"text":"To serve the mushroom Wellington, cut it crosswise into 8 even slabs. (Each slab will include a pretty cross-section showcasing the halved portobello mushroom in the center; this is considered the presentation side.) Serve each piece presentation-side up. Pass with port reduction for drizzling on top."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["mushrooms","onion","walnuts"],"item_tags":["balsamic vinegar","port","rosemary","soy sauce","thyme"],"course_tags":["Dinner"],"keywords":["American","Apple Cider","Balsamic Vinegar","Christmas","Dinner","Fall","Food Processor","Main Course","Mushroom","New Year’s Day","Port","Portobello","Project","Puff Pastry","Thanksgiving","Vegan Thanksgiving","Vegetables","Vegetarian","Walnut","Winter","Yellow Onion"],"issues":null,"front":"nyt_1020596.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020596-vegetarian-mushroom-wellington","rating":{"value":4,"count":6628},"date":"2019-11-11"},{"pair":1021033,"title":"Sheet-Pan Gnocchi With Asparagus, Leeks and Peas","subtitle":null,"author":"Susan Spungen","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"554","fat":"22 g","carbohydrates":"74 g","protein":"20 g"},"description":"This sunny dinner cooks entirely in the oven on two sheet pans, so both the vegetables and gnocchi are cooked properly with minimal effort. Asparagus, shallots, leeks and peas balance out the rich, caramelized gnocchi, but you could experiment with your vegetable choices: Cut delicate vegetables in larger pieces and firmer vegetables in smaller pieces so they cook at similar rates. Refrigerated gnocchi (often labeled “skillet gnocchi”) work best here, but shelf-stable gnocchi are also fine. Simply boil them first.","from_your_kitchen":null,"ingredients":["2 (12-ounce) packages gnocchi (preferably fresh, refrigerated, precooked gnocchi)","3 tablespoons olive oil","2 tablespoons unsalted butter","Kosher salt and black pepper","1 bunch asparagus (about 1 pound), trimmed and cut into thirds","2 small leeks, trimmed, halved lengthwise, then sliced ½-inch thick (about 2 cups)","2 shallots, trimmed and sliced lengthwise ¼-inch thick","1 cup frozen peas, thawed (or fresh peas)","1 lemon, scrubbed","½ cup grated Parmesan","¼ cup sliced fresh chives or parsley (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. On a large rimmed baking sheet, toss gnocchi with 2 tablespoons oil, 1 tablespoon butter and ½ teaspoon salt."},{"n":2,"title":null,"text":"On another rimmed baking sheet, toss asparagus, leeks and shallots with remaining 1 tablespoon oil and 1 tablespoon butter. Season with ½ teaspoon salt and a few generous grinds of pepper."},{"n":3,"title":null,"text":"Put both pans in the oven, with the gnocchi on the bottom rack and the vegetables above. Stir the gnocchi and vegetables after 5 minutes to distribute the butter. Stir the vegetables once or twice more, but leave the gnocchi undisturbed. Roast until vegetables are golden and getting crispy on the edges, about 15 minutes total, and the gnocchi are golden brown on one side, 20 to 25 minutes total. Stir the peas into the vegetables in the last 5 minutes of cooking."},{"n":4,"title":null,"text":"Combine the gnocchi and vegetables on one tray, then grate the lemon zest over the top. Sprinkle with half the Parmesan and chives, if using, saving some for serving. Season to taste with salt and pepper. Toss to combine, and transfer to a serving bowl or platter. Sprinkle with remaining Parmesan and chives, and serve immediately."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["asparagus","gnocchi","leeks","peas"],"item_tags":["chives","lemon","parmesan"],"course_tags":["Dinner"],"keywords":["American","Asparagus","Gnocchi","Leek","Lemon","Main Course","One Pot","Parmesan","Pastas","Pea","Roast","Spring","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021033.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021033-sheet-pan-gnocchi-with-asparagus-leeks-and-peas","rating":{"value":4,"count":5631},"date":"2020-04-23"},{"pair":1020859,"title":"White Beans au Vin","subtitle":null,"author":"Lidey Heuck","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"424","fat":"10 g","carbohydrates":"63 g","protein":"19 g"},"description":"This recipe uses canned white beans in place of chicken for a quick and totally vegetarian riff on classic coq au vin. Mushrooms, red wine, Cognac and a splash of balsamic vinegar stirred in just before serving help this dish develop an impressive depth of flavor in just a short time. The quality of your vegetable broth makes a big difference here; use an organic or other good-quality brand for best results.","from_your_kitchen":null,"ingredients":["3 tablespoons unsalted butter","3 medium carrots, diced into ½-inch pieces (about 1 ½ cups)","5 medium shallots, chopped (about 1 cup)","Kosher salt and black pepper","8 ounces cremini mushrooms, trimmed and quartered","5 thyme sprigs","3 garlic cloves, minced (about 1 tablespoon)","½ cup dry red wine, such as Côtes du Rhône","2 teaspoons tomato paste","2 (15-ounce) cans cannellini beans, rinsed and drained","2 cups low-sodium vegetable broth","1 tablespoon Cognac or brandy","2 tablespoons chopped fresh parsley, plus more to taste","1 teaspoon balsamic vinegar"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a Dutch oven, melt the butter over medium heat. Add the carrots and shallots, season to taste with salt and pepper, and cook, stirring occasionally, for 5 minutes."},{"n":2,"title":null,"text":"Add the mushrooms and cook, stirring occasionally, until all the vegetables are tender, 5 to 7 minutes."},{"n":3,"title":null,"text":"Add the thyme sprigs and garlic, and cook until fragrant, about 30 seconds. Add the wine and tomato paste and cook, stirring occasionally, until the wine is almost completely evaporated, 2 to 3 minutes."},{"n":4,"title":null,"text":"Add the beans, broth, Cognac, 1 teaspoon salt and ½ teaspoon pepper, and bring to a boil over medium-high heat. Turn the heat to low, partly cover, and simmer, stirring occasionally, until the sauce has reduced and thickened, 25 to 30 minutes."},{"n":5,"title":null,"text":"Remove and discard the thyme sprigs. Off the heat, stir in the parsley and balsamic vinegar; season to taste with salt and pepper. Divide among shallow bowls and sprinkle with more parsley, if desired."}],"tips":[],"cuisine_tags":["Comfort Food","French"],"ingredient_tags":["cannellini beans","carrot","mushrooms"],"item_tags":["balsamic vinegar","brandy","red wine","shallot","thyme","tomato paste"],"course_tags":["Dinner"],"keywords":["Balsamic Vinegar","Beans","Brandy","Cannellini Bean","Carrot","Dinner","Garlic","Main Course","Mushroom","Red Wine","Shallot","Thyme","Tomato Paste","Vegetable Broth","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020859.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020859-white-beans-au-vin","rating":{"value":5,"count":3025},"date":"2020-02-05"},{"pair":1021511,"title":"Brown Butter Lentil and Sweet Potato Salad","subtitle":null,"author":"Yossy Arefi","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"357","fat":"18 g","carbohydrates":"38 g","protein":"12 g"},"description":"This simple lentil salad has a little secret: a toasty, brown butter vinaigrette perfumed with sage. The dish has as much texture as it does flavor. French green lentils or black lentils are the ideal choice, as they hold their shape well after cooking, but brown lentils will work too, though they’ll be a bit softer. Start testing your lentils for doneness after about 15 minutes of cooking; you want them cooked through but not mushy, and they’re best if they retain some bite. Roasted until tender, the sweet potatoes add richness, but feel free to substitute just about any roasted vegetables. Carrots, beets or red bell peppers would all be delicious in their stead.","from_your_kitchen":null,"ingredients":["1 pound sweet potatoes, butternut squash or carrots, peeled and cut into ¾-inch pieces (about 4 cups)","2 tablespoons olive oil","Kosher salt and black pepper","1 cup French green lentils or black lentils, rinsed","½ cup chopped fresh parsley leaves and tender stems","½ cup crumbled goat cheese (optional)","1 tablespoon minced fresh sage leaves","4 tablespoons unsalted butter","1 tablespoon extra-virgin olive oil","2 tablespoons red wine vinegar","1 teaspoon maple syrup","Kosher salt and black pepper"],"ingredient_groups":[{"at":0,"title":"FOR THE SALAD"},{"at":6,"title":"FOR THE BROWN BUTTER VINAIGRETTE"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 375 degrees and set a rack in the center."},{"n":2,"title":null,"text":"Prepare the sweet potatoes: On a baking sheet, toss the sweet potatoes with the olive oil and a sprinkle of salt and pepper. Spread into an even layer and roast, stirring occasionally, until golden and tender, 15 to 25 minutes."},{"n":3,"title":null,"text":"While the sweet potatoes cook, prepare the lentils: Add the lentils to a medium pot and cover with about 6 cups water. Salt the water generously and bring the mixture to a boil. Turn the heat down to a simmer and cook the lentils until just tender, 15 to 25 minutes. Drain the lentils then return them to the pot. Cover to keep warm."},{"n":4,"title":null,"text":"Prepare the vinaigrette: Add the sage to a small bowl. Melt the butter in a small skillet set over medium heat. (Use a pan with a light interior so you can easily see the milk solids change color.) Cook the butter a few minutes, stirring occasionally and scraping the milk solids off the bottom and sides of the pan as needed, until the milk solids turn golden brown and smell toasty."},{"n":5,"title":null,"text":"Pour the hot browned butter and all of the toasty bits over the sage; it will crackle and foam a bit. Let the mixture sit for 1 minute to let the foam subside, then whisk in the olive oil, followed by the red wine vinegar and maple syrup. Season with salt and pepper to taste."},{"n":6,"title":null,"text":"Add the cooked sweet potatoes to the pot with the warm lentils. Pour the dressing over the top and stir gently to combine. Add the parsley, season with more salt and pepper, if desired, and toss to combine."},{"n":7,"title":null,"text":"Transfer the mixture to a serving dish and sprinkle with goat cheese, if using. Serve warm."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["lentils","sweet potato"],"item_tags":["brown butter","goat cheese","maple syrup","parsley","sage"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["American","Beans","Brown Butter","Butternut Squash","Dinner","Fall","Goat Cheese","Lentil","Lunch","Main Course","Parsley","Sage","Salad","Side Dish","Sweet Potato","Thanksgiving","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021511.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021511-brown-butter-lentil-and-sweet-potato-salad","rating":{"value":5,"count":8611},"date":"2020-11-02"},{"pair":1021068,"title":"Lemony Orzo With Asparagus and Garlic Bread Crumbs","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"362","fat":"20 g","carbohydrates":"35 g","protein":"11 g"},"description":"Every spoonful of this pasta has a happy jumble of lemony orzo, grassy asparagus, garlicky bread crumbs, fresh herbs and salty Parmesan. The pasta and thinly sliced asparagus cook together in the same pot, then rest in a lemony dressing while the garlic bread crumbs are toasted, so the pasta has time to absorb as much flavor as possible.","from_your_kitchen":null,"ingredients":["Salt and black pepper","1 cup orzo","1 pound asparagus, trimmed and thinly sliced on a diagonal (about ¼-inch thick)","5 tablespoons extra-virgin olive oil","1 teaspoon lemon zest plus 3 tablespoons lemon juice, plus more as needed (from about 1 large lemon)","½ cup panko or homemade bread crumbs","1 small garlic clove, finely grated","¼ cup finely grated Parmesan, plus more for serving","½ cup fresh dill, mint or parsley leaves (or any combination), torn if large"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a medium pot of salted water to a boil. Add the orzo and cook until al dente according to package directions. Two minutes before the orzo is done, add the asparagus. Drain the orzo and asparagus. Wipe out and reserve the pot."},{"n":2,"title":null,"text":"While the orzo and asparagus cook, make the dressing: In a large bowl, stir together 3 tablespoons oil and the lemon zest and juice; season to taste with salt and pepper. Add the drained orzo and asparagus and toss to coat. Set aside while you toast the bread crumbs."},{"n":3,"title":null,"text":"In the reserved pot, heat the remaining 2 tablespoons oil over medium. Add the panko and cook, stirring, until golden brown, 3 to 5 minutes. Remove from heat, then stir in the garlic and season with salt and pepper."},{"n":4,"title":null,"text":"Stir the Parmesan and herbs into the orzo, taste, then season with salt, pepper and additional lemon juice, if desired. Top with the toasted bread crumbs and more Parmesan if you like. Serve warm or at room temperature."}],"tips":[],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["asparagus","orzo"],"item_tags":["garlic","lemon","panko breadcrumbs","parmesan"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Asparagus","Brunch","Dinner","Kid-Friendly","Lemon Juice","Lunch","Main Course","Orzo","Panko","Pastas","Quick","Spring","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021068.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021068-lemony-orzo-with-asparagus-and-garlic-bread-crumbs","rating":{"value":5,"count":17585},"date":"2020-05-06"},{"pair":1020572,"title":"Creamy Double-Garlic Mashed Potatoes","subtitle":null,"author":"Alexa Weibel","servings":"8 to 12","yield_text":"8 to 12 servings (8 cups)","yield_count":8,"cook_time":"1 1/4 hours","nutrition":{"calories":"677","fat":"56 g","carbohydrates":"40 g","protein":"7 g"},"description":"Roasted garlic is the secret to these deeply flavored mashed potatoes with a lively crunch from garlic chips. This dish takes a little more planning and prep than your average mashed potatoes, but it is well worth the effort. You can roast and fry the garlic and peel the potatoes ahead of time, storing the prepared potatoes submerged in water in the refrigerator for up to 12 hours before cooking. Feel free to use either red or russet potatoes here: Red potatoes will make a thick and creamy mash, while russets will yield a lighter and fluffier result (see Tip). If you run short on time, trim the garlic chips from your to-do list. Canned fried onions from your local supermarket, or fried shallots or fried garlic flakes from most Asian markets provide the same jolt of texture on top.","from_your_kitchen":null,"ingredients":["3 heads garlic","6 teaspoons olive oil","1 cup neutral oil, such as canola or vegetable oil","6 garlic cloves, thinly sliced crosswise","Kosher salt","4 pounds red or russet potatoes (see Tip)","2 cups heavy cream","2 fresh bay leaves, or 4 dried bay leaves","1 tablespoon minced fresh rosemary, plus more for garnish","1 tablespoon fresh thyme leaves, plus more for garnish","Kosher salt and black pepper","¾ cup unsalted butter (1 ½ sticks), cut into small cubes, plus more for serving"],"ingredient_groups":[{"at":0,"title":"FOR THE ROASTED GARLIC"},{"at":2,"title":"FOR THE GARLIC CHIPS"},{"at":5,"title":"FOR THE POTATOES"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of water to a boil over high. Heat the oven to 400 degrees."},{"n":2,"title":null,"text":"Prepare the roasted garlic: Set each head of garlic on its side and cut off (and discard) the top ¼ portion at the pointed end. Transfer each head of garlic to a separate piece of aluminum foil, cut-side up, and drizzle each head with 2 teaspoons oil. Pull up the surrounding aluminum foil and crimp tightly to seal. Transfer to the oven and roast until the garlic is softened and caramelized, 40 minutes to 1 hour, depending on the size of the heads. Set aside to cool."},{"n":3,"title":null,"text":"Prepare the garlic chips: Line a plate with paper towels. In a small shallow saucepan or frying pan, heat the canola oil over medium-high until shimmering. Working in batches, fry the sliced garlic, stirring often, until just starting to turn golden, 30 seconds to 1 minute. (They’ll continue to darken from the residual heat, so you’ll want to remove them from the hot oil before they’re fully golden brown.) Transfer garlic chips to the plate using a slotted spoon. Season with salt and repeat with remaining sliced garlic. Set aside."},{"n":4,"title":null,"text":"Prepare the boiled potatoes: Fill a large pot with water and season generously with salt. Bring to a boil over high heat. Fill a medium bowl about three-quarters full with water. Working with one potato at a time, peel each potato, then add it to the bowl of water. Next, working with one potato at a time, dice each into 1-inch pieces, returning each to the bowl of water after chopping. Drain the diced potatoes, then carefully add them to the pot of boiling water. Return the water to a boil, reduce the heat to medium-high and cook until potatoes are soft and can easily be pierced with a fork, 13 to 15 minutes. Transfer to a colander to drain."},{"n":5,"title":null,"text":"Meanwhile, prepare the herbed cream: Add the cream, bay leaves, rosemary and thyme to a medium saucepan and bring to a boil over medium-high, about 5 minutes. (The mixture will bubble up vigorously, which helps reduce the liquid and concentrate the flavor.) Strain the mixture, discarding the solids, and rinse out the saucepan. Return the infused cream to the saucepan and season with salt and pepper. Cover and set aside. (You should have about 1 ⅓ cups.)"},{"n":6,"title":null,"text":"Return the cooked potatoes to the pot along with the herbed cream and cubed butter. Squeeze the roasted garlic cloves from two heads into the potato mixture, discarding the skins, and mash until creamy. Season to taste with salt and pepper, and add more roasted garlic, if desired. (Store leftover roasted garlic in the refrigerator for 1 week.)"},{"n":7,"title":null,"text":"Transfer mashed potatoes to a serving bowl, dot with a generous pat of butter and sprinkle with rosemary, thyme and black pepper. Top with garlic chips, and serve immediately."}],"tips":["If you use russet potatoes, rinse and drain the peeled and cubed potatoes three times before boiling, then give them a quick rinse in warm water after boiling to remove as much starch as possible. Pass them through a rice mill before mashing for the fluffiest results."],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["potato"],"item_tags":["cream","garlic","rosemary","thyme"],"course_tags":["Sides & Appetizers"],"keywords":["Butter","Christmas","Easter","Garlic","Heavy Cream","Mashed Potato","Potato","Rosemary","Side Dish","Thanksgiving","Thyme"],"issues":null,"front":"nyt_1020572.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020572-creamy-double-garlic-mashed-potatoes","rating":{"value":4,"count":1991},"date":"2019-10-29"},{"pair":1020729,"title":"Vegan Cacio e Pepe","subtitle":null,"author":"Alexa Weibel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"718","fat":"24 g","carbohydrates":"100 g","protein":"30 g"},"description":"This speedy vegan take on cacio e pepe utilizes a classic technique: Cook the pasta just short of al dente, reserve some of the starchy pasta water to add body to the sauce, then simmer the pasta in its sauce with a splash of pasta water, stirring vigorously until the sauce is emulsified. While many dairy-free pasta recipes look to puréed, soaked cashews for their creaminess, this one cuts corners by using store-bought cashew butter. A spoonful of miso adds depth, and tangy nutritional yeast adds umami. Toasting the peppercorns boosts their flavor and softens them.","from_your_kitchen":null,"ingredients":["Kosher salt","⅓ cup nutritional yeast","¼ cup cashew butter","2 tablespoons white miso paste","1 tablespoon whole black peppercorns","16 ounces dried spaghetti","¼ cup extra-virgin olive oil, plus more for drizzling","½ lemon, squeezed as needed (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of lightly salted water to a boil over high. (Go easy on the salt here, since the miso paste added in Step 4 is high in salt.) Add the nutritional yeast, cashew butter and miso to a small bowl and stir into a thick paste. Crush the peppercorns using the flat side of a knife. (Alternatively, you can roughly chop them, or use a pepper grinder set to a coarse setting.)"},{"n":2,"title":null,"text":"Add the pasta to the boiling water, reduce the temperature to medium, and cook, stirring occasionally, about 2 minutes before al dente according to package instructions. Reserve 2 ½ cups pasta cooking water, then drain the pasta."},{"n":3,"title":null,"text":"Add ¼ cup olive oil to the empty pot and heat over medium. Add about two-thirds of the crushed black peppercorns and toast, stirring frequently, until fragrant, 2 to 3 minutes."},{"n":4,"title":null,"text":"Add the miso mixture, and stir, then whisk in 1 ¾ cups reserved pasta water until sauce is smooth. Add the pasta to the sauce and cook over medium-high, tossing it constantly and vigorously with tongs, until the sauce is glossy and the pasta is fully al dente, 1 to 2 minutes. Add an extra splash of reserved pasta water to keep the sauce glossy, if needed."},{"n":5,"title":null,"text":"Divide among bowls. Drizzle with olive oil, sprinkle with remaining crushed pepper and serve immediately."}],"tips":[],"cuisine_tags":["Fusion","Italian"],"ingredient_tags":["pasta"],"item_tags":["cashew butter","miso","nutritional yeast"],"course_tags":["Dinner","Lunch"],"keywords":["Black Peppercorn","Cashew Butter","Dairy-Free","Dinner","Lunch","Main Course","Miso","Nutritional Yeast","Pastas","Quick","Spaghetti","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020729.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020729-vegan-cacio-e-pepe","rating":{"value":4,"count":3322},"date":"2020-01-01"},{"pair":1020827,"title":"Jamie Oliver’s Vegetarian Black Bean Burgers","subtitle":null,"author":"The New York Times","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"593","fat":"21 g","carbohydrates":"85 g","protein":"23 g"},"description":"Beans have been a staple in the human diet for more than 4,000 years, and in recent history, they’ve formed the foundation of countless vegetarian burgers. There are white bean burgers, kidney bean burgers and a plethora of other veggie burgers. Most have two things in common: beans and binders. This version from the chef Jamie Oliver’s new book “Ultimate Veg” (Flatiron Books, 2020) combines black beans, rye bread, fresh mushrooms and ground coriander. Mr. Oliver tops his burgers with tangy yogurt, mangoes and salsa, but these crisp, oven-roasted patties are equally delicious with just lettuce and ketchup. The New York Times","from_your_kitchen":null,"ingredients":["1 ½ red onions","½ pound mixed fresh mushrooms","3 ½ ounces rye bread, torn into ½-inch pieces (about 2 ½ cups)","1 (15-ounce) can black beans, drained and roughly mashed with a fork","1 teaspoon ground coriander, plus more for dusting","Kosher salt and black pepper","Olive oil, as needed","2 ounces sharp Cheddar, grated (about 1 cup)","4 large brioche rolls, potato rolls or burger buns","4 ounces cherry tomatoes, chopped (about 1 cup)","1 lime","Chipotle hot sauce, as needed","1 ripe mango","1 ripe avocado","¼ cup plain yogurt","4 fresh cilantro sprigs"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 400 degrees. Peel and roughly chop 1 onion, then place it in a food processor. Add the mushrooms and pulse until just finely chopped. (Be careful not to overprocess into a paste.) Transfer mixture to a large bowl and wipe out the bowl of the food processor. Add torn bread to the processor, pulse until it forms fine crumbs, then transfer crumbs to the mushroom mixture."},{"n":2,"title":null,"text":"Add black beans and coriander, season well with salt and pepper, then mix together until thoroughly combined. Divide into 4 equal portions and shape into 1-inch-thick patties. Rub all over with oil and dust with ground coriander, then place on an oiled baking sheet."},{"n":3,"title":null,"text":"Roast patties until dark and crisp, 35 to 45 minutes. Sprinkle the burgers with the Cheddar. Let burgers cool slightly to firm up. While the burgers cool, transfer the buns to the hot oven and heat for a few minutes until toasted."},{"n":4,"title":null,"text":"Meanwhile, peel and very finely chop the remaining ½ onion. Transfer to a medium bowl. Add the tomatoes. Zest the lime on top, then halve the lime and squeeze lime juice on top, to taste. Add a few shakes of hot sauce and season with salt and pepper to taste. Pit, peel and finely slice the mango and avocado."},{"n":5,"title":null,"text":"Spread the yogurt on the bases of the rolls or buns, then top with half the salsa, the mango and the avocado. Add the burgers, the remaining salsa, extra Tabasco and cilantro leaves, then pop the lids on, press down lightly and serve immediately."}],"tips":[],"cuisine_tags":["American","Latin American"],"ingredient_tags":["black beans","mushrooms"],"item_tags":["cheddar","chipotle","cilantro","coriander","lime","mango"],"course_tags":["Dinner","Lunch"],"keywords":["Beans","Black Bean","Burgers","Cheddar","Coriander","Dinner","Lunch","Main Course","Mushroom","Roast","Vegetarian"],"issues":null,"front":"nyt_1020827.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020827-jamie-olivers-vegetarian-black-bean-burgers","rating":{"value":4,"count":1739},"date":"2020-01-22"},{"pair":1019759,"title":"Spicy Peanut and Pumpkin Soup","subtitle":null,"author":"Yewande Komolafe","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"446","fat":"38 g","carbohydrates":"27 g","protein":"8 g"},"description":"This recipe is a promise of warmth on those cool autumn nights. Habanero chiles and peanuts both feature heavily in Nigerian cuisine, and this soup is an adaptation of a long-simmered stew common to much of West Africa. Don’t be afraid of a chile with seeds: The fragrant oils from these peppers are worth every bite. The peanut butter and coconut milk mellow the warmth of the chile to a gentle, lingering heat, but you can also take the chile out before the soup is puréed. An optional spoon of honey to the soup will round out the flavors, and a dollop of crème fraîche or yogurt will further temper the heat. Serve with a baguette or sourdough bread for dipping.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil","1 medium onion, peeled and diced (about 1 ½ cups)","4 garlic cloves, smashed","1 (1-inch) piece ginger, peeled and chopped","½ habanero or bird's eye chile","1 (14-ounce) can pumpkin purée","3 cups water (or use chicken or vegetable stock)","1 (13-ounce) can coconut milk","1 tablespoon agave or honey (optional)","¼ cup unsweetened natural peanut butter","Salt","2 tablespoons sliced fresh chives (optional)","¼ cup crème fraîche or yogurt (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large stock pot, heat oil over medium heat. Add onion, garlic and ginger, and cook, stirring frequently until softened and just beginning to brown around the edges, about 4 minutes. Stir in the chile and pumpkin purée, and whisk in the water or stock. Bring to a boil, reduce the heat and allow to simmer on low, giving an occasional stir, for 20 minutes or until slightly reduced and thickened. Remove the chile after the soup simmers if you don’t care for much spice."},{"n":2,"title":null,"text":"Add coconut milk, agave or honey (if using), and peanut butter to the pot. Using an immersion blender or working in batches in a standing blender, purée the soup until smooth. Season with salt and keep warm over low heat. Do not bring soup up to a simmer or boil at this point. (This reduces the risk of the oils in the peanut butter separating and breaking the soup's smooth texture.)"},{"n":3,"title":null,"text":"Divide soup between bowls, sprinkle with the chives and a dollop of crème fraîche or yogurt, or a drizzle of olive oil to make it vegan. Serve with a warm crusty baguette or chunks of warm sourdough for dipping."}],"tips":[],"cuisine_tags":["African"],"ingredient_tags":["pumpkin"],"item_tags":["agave","coconut milk","ginger","habanero","peanut butter"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["African","Appetizer","Chile","Coconut Milk","Dinner","Fall","Great Leftovers","Kwanzaa","Main Course","Peanut Butter","Pumpkin Purée","Soup","Thanksgiving","Vegan Thanksgiving","Weeknight","Winter"],"issues":null,"front":"nyt_1019759.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019759-spicy-peanut-and-pumpkin-soup","rating":{"value":4,"count":3293},"date":"2022-09-25"},{"pair":1021370,"title":"Crispy Bean Cakes With Harissa, Lemon and Herbs","subtitle":null,"author":"Yewande Komolafe","servings":"4","yield_text":"4 servings (10 bean cakes)","yield_count":4,"cook_time":"30 minutes, plus 15 minutes’ chilling","nutrition":{"calories":"450","fat":"23 g","carbohydrates":"47 g","protein":"17 g"},"description":"This recipe embraces any beans you’ve got in your pantry. Canned beans are easiest, but fresh shelled beans can be ready to go with a quick blanching, and dried beans can be used, too, if they’ve been soaked and cooked in advance. Toss the well-drained beans with harissa (or any red chile paste), scallions, herbs, lemon zest, cornstarch and a lightly whipped egg white. (The egg white and cornstarch give these bean cakes their crispness.) Shape them into patties for frying, and slice some lemon wedges for serving. Eat the patties as a vegetarian main dish, a side to roast chicken or fish, or as a snack with a dash of harissa.","from_your_kitchen":null,"ingredients":["2 (15-ounce) cans beans, such as black-eyed peas, chickpeas, pinto, kidney or black beans, drained (about 3 cups)","½ cup fresh cilantro leaves and tender stems, chopped, plus more for garnish","¼ cup fresh dill, chopped, plus more for garnish","¼ cup sliced scallions","3 tablespoons cornstarch","1 tablespoon harissa, plus more for serving","¾ teaspoon ground coriander","½ teaspoon ground cumin","2 teaspoons kosher salt","1 teaspoon black pepper","1 lemon, zested and cut into wedges","1 egg white","6 tablespoons olive oil, plus more as needed","Labneh or full-fat Greek yogurt, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place the drained beans in a large bowl and crush using a fork or your fingers until coarsely mashed. Add the cilantro, dill, scallions, cornstarch, harissa, coriander, cumin, salt and pepper. Add the lemon zest and stir to incorporate. Alternatively, you can incorporate ingredients using a food processor and pulse to combine."},{"n":2,"title":null,"text":"In a small bowl, whisk the egg white until foamy and fold it into the bean mixture. Cover the mixture and refrigerate to chill slightly, at least 15 minutes, before shaping and frying."},{"n":3,"title":null,"text":"Heat 3 tablespoons oil in a medium (10-inch) nonstick skillet or a well-seasoned cast-iron skillet over medium-high. Working in batches, use a ¼-cup measure to scoop portions of the bean mixture into the oil. Using the flat surface of the cup, press each scooped portion to tightly pack and shape it into a ¼-inch-thick patty. Cook until the bottom is golden brown, about 3 minutes. Turn using a wide spatula, and brown the other side, about 2 minutes."},{"n":4,"title":null,"text":"Remove cooked cakes from oil and drain on a plate lined with paper towels or a cooling rack on a baking sheet. Repeat until all the bean mixture is used, adding the remaining oil and removing any loose bits from the skillet as necessary. Return the bowl to the refrigerator in between batches to keep the mixture chilled."},{"n":5,"title":null,"text":"Serve lemon wedges alongside the crispy cakes for squeezing. Garnish with dollops of labneh, if using, additional fresh herbs and harissa for dipping."}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["chickpeas"],"item_tags":["cilantro","cumin","dill","harissa","lemon","scallions"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Bean","Beans","Cilantro","Coriander","Cumin","Dill","Dinner","Egg","Harissa","Kid-Friendly","Lemon","Lunch","Main Course","Scallion","Side Dish","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021370.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021370-crispy-bean-cakes-with-harissa-lemon-and-herbs","rating":{"value":4,"count":2466},"date":"2020-08-26"},{"pair":1021587,"title":"Brussels Sprouts With Pickled Shallots and Labneh","subtitle":null,"author":"Nik Sharma","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"223","fat":"11 g","carbohydrates":"25 g","protein":"10 g"},"description":"Pickled onions and labneh lend brightness to this brussels sprouts dish that’s full of flavors and textures, making it a show-stopping addition to the Thanksgiving table. (But why limit yourself there?) This recipe calls for date syrup, available at Middle Eastern grocery stores or online, or pekmez, a type of molasses made from grapes (and sometimes other fruit) used in Turkish cooking. If you can’t find either, use the same amount of maple syrup or honey. Some of the fruity and woody flavors will be missing, but these substitutes will provide much-needed sweetness to the rest of the dish.","from_your_kitchen":null,"ingredients":["¼ cup apple cider vinegar","1 teaspoon granulated sugar","½ teaspoon black pepper","½ teaspoon fine sea salt","1 large shallot, peeled and sliced into rings","1 pound brussels sprouts","2 tablespoons extra-virgin olive oil, plus more for finishing","Fine sea salt","1 teaspoon black pepper","1 cup labneh","1 garlic clove, peeled and grated","½ teaspoon black pepper","Fine sea salt","2 tablespoons date syrup or pekmez (or even maple syrup or honey), for serving"],"ingredient_groups":[{"at":0,"title":"FOR THE PICKLED SHALLOTS"},{"at":5,"title":"FOR THE BRUSSELS SPROUTS"},{"at":9,"title":"FOR THE LABNEH"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the pickled shallots: In a small jar or bowl, mix the vinegar, sugar, black pepper and salt. Stir until the sugar and salt are completely dissolved. Add the shallots and cover the jar with a lid or plastic wrap. Let sit for 30 minutes at room temperature."},{"n":2,"title":null,"text":"Prepare the brussels sprouts: Heat the oven to 400 degrees. Trim the brussels sprouts, discarding any stalks or damaged leaves. Halve the sprouts lengthwise, and toss with 2 tablespoons oil. Season with salt to taste and 1 teaspoon black pepper. Spread them out in a single layer on a rimmed baking sheet or roasting pan. Roast for 22 to 30 minutes, until golden brown, slightly charred in some spots and a little crispy."},{"n":3,"title":null,"text":"As brussels sprouts cook, prepare the labneh: In a medium bowl, mix the labneh with the garlic and black pepper, then taste and season with salt."},{"n":4,"title":null,"text":"Spread the labneh on a serving dish or plate, and spoon the sprouts over. Drain and discard the liquid from the pickled shallots, and place them on top of the sprouts. Drizzle with the date syrup and 1 to 2 tablespoons olive oil. Serve immediately."}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["brussels sprouts"],"item_tags":["apple cider vinegar","date syrup","labneh","shallot"],"course_tags":["Sides & Appetizers"],"keywords":["Brussels Sprout","Fall","Garlic","Labneh","Roast","Side Dish","Thanksgiving","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021587.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021587-brussels-sprouts-with-pickled-shallots-and-labneh","rating":{"value":5,"count":1933},"date":"2020-11-11"},{"pair":1021421,"title":"Spinach and Chermoula Pie","subtitle":null,"author":"Yotam Ottolenghi","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"2 hours, plus cooling and chilling","nutrition":{"calories":"308","fat":"25 g","carbohydrates":"20 g","protein":"6 g"},"description":"This pie is a great way to use up your freezer staples: that one bag of frozen spinach and that packet of puff pastry sitting in the back. Feel free to make this pie your own by playing around with the herbs and spices. You can also veganize it by leaving out the feta and using a vegan-friendly puff pastry. Typically used as a marinade or condiment, chermoula is a North African spice paste with a multitude of variations. Here, it is used twice, once to flavor the base and then again as a sauce to drizzle alongside.","from_your_kitchen":null,"ingredients":["5 garlic cloves, finely chopped","¾ cup/30 grams roughly chopped fresh cilantro (coriander)","½ fresh mild red chile (about 10 grams), roughly chopped, seeds and all","2 teaspoons cumin seeds, toasted and roughly crushed using a mortar and pestle","1 teaspoon sweet paprika","Kosher salt and freshly ground black pepper","4 tablespoons/60 milliliters olive oil","4 tablespoons/60 milliliters olive oil","1 large yellow onion (about 12 ounces/360 grams), halved and thinly sliced","12 ounces/350 grams frozen spinach, thawed, then squeezed to remove excess water","Kosher salt and freshly ground black pepper","⅓ cup/15 grams roughly chopped fresh dill","1 ½ teaspoons fresh lemon zest, plus 1 ½ tablespoons lemon juice","All-purpose flour, for dusting","1 sheet frozen all-butter puff pastry, at least 9 inches/24 centimeters wide, thawed","1 cup/130 grams roughly crumbled Greek feta","1 baking potato (about 9 ounces/250 grams), skin-on, scrubbed clean"],"ingredient_groups":[{"at":0,"title":"FOR THE CHERMOULA PASTE"},{"at":7,"title":"FOR THE PIE"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the chermoula paste: Add the garlic, cilantro, chile, cumin, paprika, ½ teaspoon salt, a good grind of pepper and 3 tablespoons oil to a food processor. Pulse into a coarse paste and set aside."},{"n":2,"title":null,"text":"Prepare the pie: Add 3 tablespoons oil to a large skillet and heat over medium-high. Once hot, add the onion and cook, stirring occasionally, until softened and well browned, about 12 minutes. Add half the chermoula paste (reserve the rest), the spinach, 1 teaspoon salt and a good grind of pepper, and cook for 2 minutes more, stirring to combine. Remove from the heat, then add the dill and lemon zest. Set aside to cool, about 20 minutes."},{"n":3,"title":null,"text":"Line a 9-inch/24-centimeter pie or tart pan (tin) with a removable base with a piece of parchment paper large enough to cover the base and a little bit over the sides. (The excess will help you lift the tart when it’s baked.) On a lightly floured work surface, roll out the pastry with a floured rolling pin to a 12-inch/30-centimeter square. Lay the puff pastry on the parchment, pressing in the pastry to fit the base and sides of the pan and cutting away any excess so it overhangs by about ¾ inch/2 centimeters."},{"n":4,"title":null,"text":"Poke the base all over with a fork (about 10 times), then spread the cooled spinach mixture over the base evenly. Sprinkle the feta on top, then fold and scrunch the sides over the filling to create a rim. (Don’t worry if it’s not perfect.) Refrigerate the pie for at least 20 minutes, or up to overnight, covered."},{"n":5,"title":null,"text":"Heat the oven to 400 degrees Fahrenheit/200 degrees Celsius."},{"n":6,"title":null,"text":"Trim and discard the ends of the potato and use a mandolin or very sharp knife to cut the potato into paper-thin slices. Toss together in a bowl with 1 tablespoon oil, plus ½ teaspoon salt and a good grind of pepper. Fan out the slices on top of the spinach and feta in a circular pattern, overlapping slightly, to cover the filling but not the pastry rim."},{"n":7,"title":null,"text":"Place the chilled pie on a baking sheet and bake until cooked through and nicely colored, about 50 minutes. Set aside to cool, about 15 minutes, before gently transferring to a wooden board or serving plate."},{"n":8,"title":null,"text":"When ready to serve, stir the lemon juice and remaining 1 tablespoon oil into the reserved chermoula. Spoon half of the chermoula all over the pie and serve the remaining in a bowl alongside. Serve warm, or at room temperature."}],"tips":[],"cuisine_tags":["Moroccan"],"ingredient_tags":["potato","spinach"],"item_tags":["chermoula","cilantro","cumin","dill","feta","lemon"],"course_tags":["Breakfast","Dinner","Lunch","Sides & Appetizers"],"keywords":["Bake","Brunch","Cilantro","Dill","Dinner","Feta","Frozen Spinach","Lunch","Main Course","Potato","Puff Pastry","Savory Pie","Side Dish","Spinach","Vegetables"],"issues":null,"front":"nyt_1021421.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021421-spinach-and-chermoula-pie","rating":{"value":4,"count":751},"date":"2020-09-23"},{"pair":1021285,"title":"Smoky Eggplant Croquettes","subtitle":null,"author":"Gabrielle Hamilton","servings":null,"yield_text":"About 16 croquettes","yield_count":16,"cook_time":"1 1/2 hours, plus freezing","nutrition":{"calories":"146","fat":"6 g","carbohydrates":"20 g","protein":"4 g"},"description":"By placing whole, unwashed, plain and naked globe eggplants directly onto the stovetop burner grate and letting them burn until charred, hissing and collapsed, you bring a haunting smokiness and profound silkiness to the interior flesh that will have you hooked for the rest of your life. This way of cooking eggplant is a revelation in itself — easy, yet exciting and engaging — and requires nothing more of the home cook than a little seasoning at the end to be enjoyed, as is. But biting into a warm, crisp, golden fried croquette with that smoky, silken purée at its center is what restaurant-level complexity and satisfaction is all about. One key ingredient, but 11 steps to prepare it — that about sums up the difference between home cooking and restaurant excitement.","from_your_kitchen":null,"ingredients":["2 large globe eggplants (about 2 ½ pounds total)","3 tablespoons extra-virgin olive oil","4 garlic cloves, peeled","Kosher salt","1 cup all-purpose flour","3 whole eggs, beaten with ¼ cup water","2 cups panko bread crumbs, ground as fine as freeze-dried instant milk, or plain fine bread crumbs","Canola, grapeseed or other neutral oil, for stovetop shallow frying","Lemon wedges, for serving"],"ingredient_groups":[{"at":0,"title":"FOR THE SMOKY EGGPLANT"},{"at":4,"title":"FOR THE CROQUETTES"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Place the whole eggplants directly on the burner grids of the stovetop, and turn the flames to high. Let each eggplant start to blister, and steam, and char, turning each one a quarter turn every 3 or 4 minutes, until softened and hissing inside, the skins utterly blackened and cracked, and the flesh collapsing, 12 to 15 minutes. (You could also blister them under the broiler, set on an aluminum-foil-lined baking sheet a couple of inches from the heat and cook until charred all over.)"},{"n":2,"title":null,"text":"Remove the eggplants to a bowl. Cover with a lid or overturned bowl, and let them rest until cool enough to handle, about 30 minutes. Give this the time it takes; it will help with peeling them later and also lets them steep in their smoky juices. You can do this step ahead and let them cool in the refrigerator overnight as well, to be peeled the next day, which works beautifully."},{"n":3,"title":null,"text":"Remove the scorched, carbonized skin from the soft, cooked-through eggplant. Discard all the black, bitter charred bits."},{"n":4,"title":null,"text":"Strain the remaining eggplant, and save all the viscous smoky liquid that accumulates. I usually “rinse” the peeled eggplants in this strained liquid to remove any lingering flakes or chips of charred skin from the eggplant flesh. (Sometimes people are tempted to run the eggplant under the faucet for a second to remove the flecks, but using the liquid in the bowl is much better at retaining flavor.)"},{"n":5,"title":null,"text":"Chop the flesh to a fine dice, and place in a bowl. (I generally never remove the seeds unless I have bought an intensely loaded eggplant, in which case I’ll remove them if the seed sacs are pronounced and distracting.)"},{"n":6,"title":null,"text":"Stir in 3 tablespoons of the reserved smoky liquid, and the olive oil, then Microplane the garlic into the mixture. Season with salt, and stir well until the mixture is a bit creamy. Taste, and season to your palate by adding a few more drops of the smoky liquid or a few more of olive oil. I like mine rather smoky, rather salty, rather unctuous."},{"n":7,"title":null,"text":"Spread the eggplant mixture into an 8-inch square, about ½ inch thick, on a quarter sheet pan lined with a quarter-cut Silpat mat. Most people will not have these two things, so alternatively you can form a neat square or rectangle on a cookie sheet, or spoon the mixture into generally quenelled shapes onto a cookie sheet. Freeze overnight."},{"n":8,"title":null,"text":"Prepare the croquettes: Set up a standard breading procedure of three containers: flour, egg and water mixture, and the ground panko."},{"n":9,"title":null,"text":"Cut the frozen block of smoky eggplant into 2-inch squares, or batons or planks if you prefer. Refreeze for a bit if needed after cutting; they tend to defrost rather quickly. Bread each piece with care, dipping in flour, egg mixture then panko, leaving no bald spots, and refreeze the finished, breaded croquettes. (These can live in your freezer for months.)"},{"n":10,"title":null,"text":"Add enough neutral oil to a deep-sided sauté pan to reach a depth of 1 ½ to 2 inches, and heat over medium until shimmering, or when a thermometer reads 350 degrees. Working in batches, fry the frozen croquettes until golden on all sides and piping hot in the center, raising and lowering the heat under the oil accordingly. Adding frozen products to hot oil brings the temperature down, as does crowding, so it is up to the cook to control the temperature of the fry oil accordingly. Remove cooked croquettes with a slotted spoon, and drain on a baker’s rack to maintain crispness (rather than a paper towel or plate, which will encourage steaming and sogginess)."},{"n":11,"title":null,"text":"Sprinkle with a little salt while still very hot, and serve with a squeeze of lemon."}],"tips":[],"cuisine_tags":["American","Mediterranean"],"ingredient_tags":["eggplant"],"item_tags":["garlic","lemon","panko breadcrumbs"],"course_tags":["Sides & Appetizers"],"keywords":["All-Purpose Flour","American","Appetizer","Eggplant","Finger Foods","Garlic","Lemon","Olive Oil","Panko","Project","Side Dish","Stovetop","Vegetables"],"issues":null,"front":"nyt_1021285.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021285-smoky-eggplant-croquettes","rating":{"value":4,"count":541},"date":"2020-08-02"},{"pair":1021278,"title":"Spicy Cucumbers With Yogurt, Lemon and Herbs","subtitle":null,"author":"Yewande Komolafe","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"346","fat":"30 g","carbohydrates":"14 g","protein":"9 g"},"description":"This recipe brings together two contrasting components to create a bright summer dish. A simple yogurt sauce is dressed up with herbs and zest, then topped with cucumbers that have marinated in a spicy oil. Coriander, cumin and red-pepper flakes bloom in a neutral oil, and the cucumbers take on the flavors as they sit. For the yogurt, a variety of garden fresh herbs work well, but dill and mint are crucial. Both the yogurt and the cucumbers can be prepared up to a day in advance and kept refrigerated until serving. When you’re ready, spread the yogurt sauce in a wide bowl or plate. Spoon the cucumbers on top evenly so each each bite gets a little yogurt and a little cucumber: One will temper the spiciness of the other. Save a handful of the herbs for a fresh garnish.","from_your_kitchen":null,"ingredients":["1 ½ pounds Persian cucumbers (about 8), ends trimmed and quartered lengthwise into spears, then crosswise into 2-inch pieces","1 teaspoon kosher salt, plus more to taste","¼ cup grapeseed oil or other neutral oil, such as canola, safflower, sunflower oil","1 teaspoon ground coriander","½ teaspoon ground cumin","1 teaspoon red-pepper flakes","2 scallions, trimmed and thinly sliced","2 teaspoons apple cider vinegar","1 cup full-fat Greek yogurt","½ cup mint leaves, thinly sliced","¼ cup dill, chopped","¼ cup parsley leaves and tender stems, chopped","1 lemon","2 tablespoons olive oil","Black pepper","¼ cup pine nuts (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Toss the cucumber pieces with 1 teaspoon salt and set in a colander in the sink to drain."},{"n":2,"title":null,"text":"In a small pot, heat the oil over medium heat. Add the coriander and cumin, and toast until fragrant, stirring to avoid scorching, about 1 minute. Remove oil from heat, add red-pepper flakes and allow to cool."},{"n":3,"title":null,"text":"In a medium bowl, toss the salted cucumber pieces with the scallions, spiced oil and apple cider vinegar. Allow to marinate in the refrigerator for 15 minutes or overnight while you prepare the yogurt."},{"n":4,"title":null,"text":"In a small bowl, combine the yogurt, half of the herbs (mint, dill and parsley), zest and juice of the lemon and the olive oil. Stir to incorporate, and season to taste with salt and pepper."},{"n":5,"title":null,"text":"Spread the yogurt mixture on a plate or the bottom of a shallow bowl. Using a slotted spoon to drain the cucumbers and scallions of excess liquid, evenly place the cucumbers and scallions on top of the yogurt. Finish with the remaining chopped herbs and pine nuts (if using), and serve immediately."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["cucumber"],"item_tags":["cumin","dill","lemon","mint","parsley","yogurt"],"course_tags":["Sides & Appetizers"],"keywords":["Cucumber","Dill","Easy","Mint","Parsley","Salad","Side Dish","Summer","Vegetables","Vegetarian","Yogurt"],"issues":null,"front":"nyt_1021278.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021278-spicy-cucumbers-with-yogurt-lemon-and-herbs","rating":{"value":4,"count":1819},"date":"2020-07-29"},{"pair":1020744,"title":"Black Bean Tacos With Avocado and Spicy Onions","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"390","fat":"15 g","carbohydrates":"53 g","protein":"16 g"},"description":"Spicy pickled onions add brightness and tang to these hearty black bean tacos. The filling is a bit like chili but without the tomato, and perfect to wrap up in a tortilla. You can make the black beans up to 5 days ahead; they even freeze well. Then just warm them up, along with the tortillas, right before serving. The spicy onions will last for weeks in the fridge. Use them on everything: soups, salads, even grilled cheese sandwiches.","from_your_kitchen":null,"ingredients":["1 lime","1 small red onion or large shallot, thinly sliced","1 jalapeño, seeded and thinly sliced","Large pinch of fine sea salt","Small pinch of granulated sugar","2 tablespoons olive oil, plus more as needed","1 large onion, chopped","½ cup diced red or green bell pepper","2 garlic cloves, minced","1 jalapeño, seeded and minced","1 tablespoon tomato paste","½ tablespoon chili powder","½ teaspoon dried oregano","½ teaspoon ground cumin","2 (15-ounce) cans black beans, drained and rinsed","Fine sea salt","Corn tortillas, warmed","1 avocado, peeled, pitted and sliced","Fresh cilantro, salsa and sour cream, for garnish (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE SPICY ONIONS"},{"at":5,"title":"FOR THE BLACK BEANS"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the spicy onions: Squeeze the lime into a bowl and add the onion or shallot, jalapeño, salt and sugar to the juice. Set aside while you make the black beans."},{"n":2,"title":null,"text":"Prepare the beans: Heat a large skillet, then add 2 tablespoons oil. When oil is hot, add the onion and bell pepper and sauté until soft and golden, about 10 minutes. If the pan looks dry, drizzle in a little more oil."},{"n":3,"title":null,"text":"Add the garlic and jalapeño and sauté until fragrant, 1 minute. Stir in tomato paste, chili powder, oregano and cumin, and sauté until fragrant. Add the beans and a few large pinches of salt and let simmer until the flavors meld, about 15 minutes."},{"n":4,"title":null,"text":"Taste and add more salt, chili powder and oregano to taste. Serve beans with tortillas and avocado and top with the pickled onions and jalapeño and some of their liquid, adding any of the garnishes you like."}],"tips":[],"cuisine_tags":["Mexican"],"ingredient_tags":["avocado","black beans","red onion","tortilla"],"item_tags":["cilantro","cumin","jalapeño","lime"],"course_tags":["Dinner"],"keywords":["Black Bean","Dinner","Main Course","Mexican","Red Onion","Tacos","Tortilla","Vegan","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020744.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020744-black-bean-tacos-with-avocado-and-spicy-onions","rating":{"value":5,"count":2392},"date":"2020-01-01"},{"pair":1020937,"title":"Asaro (Yam and Plantain Curry)","subtitle":null,"author":"Yewande Komolafe","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"50 minutes","nutrition":{"calories":"516","fat":"26 g","carbohydrates":"74 g","protein":"6 g"},"description":"This recipe is an adaptation of asaro, the Yoruba word for a dish of starchy root vegetables simmered in a seasoned tomato- and chile-based sauce. Regional versions of asaro are served all year round across the south of Nigeria and in other parts of West Africa. Traditionally, the dish is made with the West African yam, but you can also use white or purple taro root or unripe plantains. Here, firm, green plantains are combined with white yams in a sauce rich with caramelized shallots, garlic and ginger. There is a slight but welcome heat from a single red habanero dropped in whole to infuse the stew. Coconut milk and an optional spoonful of red palm oil — a floral, slightly smoky oil that is pressed from the fruit of oil palm trees — round out the flavors, and hearty greens cut the richness. Serve topped with crunchy shallots, fresh herbs and a wedge of lime.","from_your_kitchen":null,"ingredients":["¼ cup neutral oil, such as canola or grapeseed","4 medium shallots, peeled and thinly sliced (about 1 cup)","Kosher salt","4 garlic cloves, smashed and peeled","1 (2- to 3-inch) piece fresh ginger, grated (about 2 tablespoons)","2 teaspoons ground turmeric","2 tablespoons tomato paste","1 whole red habanero or Scotch bonnet chile, pierced all over with a knife","1 (14-ounce) can whole peeled tomatoes with their juices","1 ½ pounds white or orange yams, peeled and cut into 1 ½-inch pieces","2 green (unripe) plantains (about 1 pound total), peeled and cut into 1 ½-inch pieces","1 (13-ounce) can full-fat coconut milk","1 tablespoon red palm oil (optional)","4 cups julienned hearty greens, such as dandelion greens, collards or lacinato kale, tough stems removed","¼ cup fresh basil leaves, torn","¼ cup fresh cilantro leaves and tender stems","1 lime, sliced into wedges for squeezing"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat a medium pot, large saucepan or Dutch oven over medium. Pour in the neutral oil, add the sliced shallots and cook, stirring frequently, until shallots are caramelized and golden brown, about 5 minutes. Remove shallots from the oil and allow to drain on paper towels or a cooling rack. Season with salt and set aside."},{"n":2,"title":null,"text":"Drain all but 2 tablespoons of the cooking oil out of the pot. (Reserve extra oil for another use.) Over medium-low heat, add the garlic, ginger and turmeric to the pot and sauté until softened and fragrant, about 2 minutes. Add the tomato paste and cook, stirring constantly, for an additional 2 minutes or until it begins to stick to the bottom of the pot."},{"n":3,"title":null,"text":"Drop in the chile and add the whole peeled tomatoes with their juices, crushing the whole tomatoes with your hands as they go in. Stir to combine ingredients and dissolve the tomato paste, then add 3 cups water and bring to a boil over high heat."},{"n":4,"title":null,"text":"Once boiling, season with salt, reduce heat to medium, add the yams and simmer until the yams are just beginning to soften, about 10 minutes. Add the plantains and cook until both are tender but hold their shape, and the liquid is slightly reduced and thickened, 15 to 18 minutes."},{"n":5,"title":null,"text":"Stir in the coconut milk and red palm oil, if using, season with more salt and let simmer for another 10 minutes. Add the greens and cook until tender, 2 to 3 minutes."},{"n":6,"title":null,"text":"To serve, remove and discard the cooked chile. Ladle the curry into bowls, top with the caramelized shallots, a scattering of basil and cilantro, and several squeezes of lime juice."}],"tips":[],"cuisine_tags":["African"],"ingredient_tags":["kale","plantain","yam"],"item_tags":["coconut milk","ginger","shallot","turmeric"],"course_tags":["Dinner"],"keywords":["Canned Tomato","Coconut Milk","Curry","Dinner","Ginger","Great Leftovers","Main Course","Plantain","Shallot","Simmer","Stew","Turmeric","Vegetables","Vegetarian","Weeknight","Yam"],"issues":null,"front":"nyt_1020937.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020937-asaro-yam-and-plantain-curry","rating":{"value":4,"count":1800},"date":"2020-05-27"},{"pair":1020983,"title":"Pierogi Ruskie (Potato and Cheese Pierogi)","subtitle":null,"author":"Amelia Nierenberg","servings":null,"yield_text":"24 to 30 pierogi","yield_count":24,"cook_time":"1 1/2 hours","nutrition":{"calories":"147","fat":"10 g","carbohydrates":"11 g","protein":"3 g"},"description":"Pierogi are always on the menu at milk bars, historic Polish restaurants that were once socialist canteens. This recipe for pierogi ruskie, stuffed with potatoes and cheese, comes from the Bar Prasowy, which is one of the most famous milk bars in Warsaw, and a place where fist-size dumplings can be filled with mushrooms and meat, spinach and cheese, or any number of combinations. These pierogi can be made from kitchen staples, though you’d be doing yourself a favor if you sought out the salty quark cheese that would be used in Poland. Be patient with your first few pierogi: Sealing the filling inside the dumpling takes some practice, but the practice itself is enjoyable. You can snack on the pierogi straight after boiling, or pan-fry them with butter until crisp and serve with barszcz, a light Polish borscht. Amelia Nierenberg","from_your_kitchen":null,"ingredients":["2 cups/255 grams all-purpose flour (preferably unbleached), plus more as needed","1 teaspoon kosher salt","3 tablespoons unsalted butter","1 large egg, beaten","½ pound waxy or all-purpose potatoes","Salt and pepper","3 tablespoons unsalted butter","3 medium yellow onions (about 8 ounces each), finely chopped","½ cup quark cheese, cottage cheese or sour cream (about 4 ounces)","Butter, for pan-frying (optional)","Sour cream, for garnish","Chopped fresh parsley or dill, for garnish"],"ingredient_groups":[{"at":0,"title":"FOR THE DOUGH"},{"at":4,"title":"FOR THE FILLING"},{"at":9,"title":"FOR SERVING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the dough: Add the flour and salt to a large bowl; whisk to combine. In a small saucepan, heat ½ cup water and the butter over medium-high until butter is melted, about 3 minutes. Pour the buttery liquid into the flour gradually, stirring it in as you add it. (The dough will be quite crumbly and flaky at this point, like a biscuit dough.) Stir in the egg until combined then move the dough to a lightly floured surface and knead until smooth, 5 to 7 minutes. Cover the dough with a dampened towel or plastic wrap and let rest at room temperature for 30 minutes."},{"n":2,"title":null,"text":"Prepare the filling: Peel the potatoes and cut into 1-inch cubes. Add them to a large pot, sprinkle with 1 tablespoon salt and cover with cold water by about 2 inches. Bring to a boil over high and continue to cook at a simmer until potatoes are tender, about 25 minutes."},{"n":3,"title":null,"text":"While the potatoes cook, prepare the onions: In a large skillet, melt the butter over medium-high. Add the onions, season generously with salt and pepper, and cook, stirring occasionally, until golden-brown and softened, about 12 minutes. Set aside about 1 cup of onions for garnish and add the rest to a medium bowl."},{"n":4,"title":null,"text":"Transfer the cooked potatoes to a colander to drain, then transfer to the medium bowl with the onions. Add the cheese, stir to combine, season generously with salt and pepper, then let cool."},{"n":5,"title":null,"text":"Bring a large pot of heavily salted water to a boil over high."},{"n":6,"title":null,"text":"Prepare the wrappers: Cut the dough into two even pieces. (You’ll want to leave one piece under the towel to stay moist while you work with the other piece.) You’ll also want a small bowl of flour, a small bowl of water and a towel handy for keeping your hands clean. Dust some flour onto a baking sheet (for holding the pierogi) and your work surface, then roll out one portion of dough until ⅛-inch thick. Using a 3-inch cookie cutter or inverted glass, punch 12 to 15 disks of dough. (Save and refrigerate the scraps to boil as a rustic pasta, in soup or another use.)"},{"n":7,"title":null,"text":"Assemble the pierogi: Working with one disk at time, spoon a scant tablespoon of filling onto the middle of it. Fold the dough in half to enclose the filling, bringing the edges together to form a crescent shape. Pinch the two sides together at the top, then work your way down on both sides, pinching the dough over the filling and pushing in the filling as needed, making sure the potato mixture does not break the seal. If needed, you can dip your fingertip into water and moisten the dough in spots as needed to help the two sides adhere together."},{"n":8,"title":null,"text":"To form a rustic pattern on the curved seal, pinch the rounded rim underneath using your pointer finger and middle finger and press an indentation on top with your thumb, working your way along the rounded rim. Transfer to the prepared baking sheet. (If you’ve gotten some filling on your fingers, dip your fingertips into the bowl of water then dry them off on the towel.)"},{"n":9,"title":null,"text":"Repeat with remaining disks, then repeat the entire process with the remaining portion of dough. You’ll want to work fairly quickly, as the pierogi can be harder to seal if they start to dry out. (If cooking the pierogi at a later point, transfer them on the baking sheet to the freezer until frozen solid, then transfer the pierogi to a resealable bag and freeze.)"},{"n":10,"title":null,"text":"To cook the pierogi, add a single layer of pierogi to the pot of boiling water. Let them cook until they rise to the surface, about 2 minutes, then cook another 2 to 3 minutes until puffy. (With frozen dumplings, you will need to increase the cooking time by a couple of minutes.) Use a slotted spoon to transfer cooked dumplings to a colander to drain, then boil remaining dumplings."},{"n":11,"title":null,"text":"If you want to pan-fry your pierogi, working in batches, melt 1 to 2 tablespoons of butter in a large skillet over medium-high until crackling. Add a few boiled pierogi in a single layer to avoid overcrowding, and cook until crisp and golden, 1 to 2 minutes per side. Repeat with remaining pierogi, adding butter as needed."},{"n":12,"title":null,"text":"Serve hot. Top with any browned butter from the pan, warmed reserved onions, sour cream and herbs."}],"tips":[],"cuisine_tags":["Eastern European"],"ingredient_tags":["potato"],"item_tags":["cottage cheese","sour cream"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Appetizer","Boil","Cottage Cheese","Dinner","Dumplings","Main Course","Pan-Fry","Polish","Project","Side Dish","Sour Cream","Vegetarian","Waxy Potato"],"issues":null,"front":"nyt_1020983.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020983-pierogi-ruskie-potato-and-cheese-pierogi","rating":{"value":5,"count":2808},"date":"2020-04-22"},{"pair":1016072,"title":"Mediterranean Smashed Chickpeas","subtitle":null,"author":"David Tanis","servings":null,"yield_text":"About 3 1/2 cups chickpea spread","yield_count":3,"cook_time":"30 minutes","nutrition":{"calories":"307","fat":"8 g","carbohydrates":"45 g","protein":"16 g"},"description":"You smash half the chickpeas in this recipe to make a spread, sort of a warm rustic hummus enhanced with garlic cumin and hot pepper, along with a liberal drizzle of olive oil. You can use either freshly cooked dried beans or canned chickpeas (also known as garbanzo beans), though freshly cooked is always preferable. Tuck some into a pita for a vegetarian sandwich or serve as a dip to eat with bread and olives; a dollop of minty yogurt and a drizzle of tahini sauce make nice additions.","from_your_kitchen":null,"ingredients":["Extra-virgin olive oil","1 medium onion, diced","Salt and pepper","4 garlic cloves, minced","½ teaspoon coarsely ground toasted cumin","½ teaspoon red pepper flakes","1 cup finely diced celery","4 cups chickpeas (garbanzo beans), cooked or canned","2 tablespoons lemon juice","4 hard-cooked eggs, peeled and quartered (optional)","Minted yogurt (optional), see notes","Tahini sauce (optional), see notes"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put 3 tablespoons olive oil in a heavy-bottomed saucepan over medium heat. Add onion, season with salt and pepper, and cook gently until softened, about 10 minutes. Raise heat to medium-high. Add garlic, cumin, red pepper flakes and celery. Stir to combine let sizzle without browning for 1 minute."},{"n":2,"title":null,"text":"Add chickpeas and let them heat through. With a potato masher or wooden spoon, crush about half the beans. Stir well, taste and adjust seasoning. Add ½ cup water (or bean cooking liquid if you have it) and let mixture simmer briskly for a minute or two. Stir in lemon juice and 2 tablespoons olive oil. Serve warm in pita or as a dip or side dish. Garnish with quartered eggs, accompanied by minted yogurt and tahini sauce, if desired."}],"tips":["To make minted yogurt, stir 2 tablespoons chopped mint and 1 minced garlic clove into a cup of thick yogurt. Season with salt and pepper.","To make tahini sauce, mix 1/4 cup Middle Eastern sesame paste with 2 tablespoons lemon juice, 2 minced garlic cloves, 1/2 teaspoon salt and 3 tablespoons olive oil."],"cuisine_tags":["Greek","Mediterranean","Middle Eastern"],"ingredient_tags":["chickpeas"],"item_tags":["cumin","lemon","tahini"],"course_tags":["Sides & Appetizers"],"keywords":["Appetizer","Chickpea","Condiments","Dips and Spreads","Greek","Kid-Friendly","Mediterranean","Middle Eastern","Quick"],"issues":null,"front":"nyt_1016072.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016072-mediterranean-smashed-chickpeas","rating":{"value":5,"count":456},"date":"2014-02-26"},{"pair":1021237,"title":"Superiority Burger’s Crispy Fried Tofu Sandwich","subtitle":null,"author":"Alexa Weibel","servings":null,"yield_text":"6 sandwiches","yield_count":6,"cook_time":"45 minutes, plus marinating","nutrition":null,"description":"Ranging from silken and creamy to firm and chewy, tofu comes in many forms and is prized around the world for its versatility. In this recipe, which is adapted from the “Superiority Burger Cookbook” (W.W. Norton & Company, 2018) by chef Brooks Headley, extra-firm tofu is pressed, marinated, breaded and fried, to make the “tofu-fried tofu” sandwich at Superiority Burger, his popular vegetarian restaurant in New York City. To achieve a dense tofu patty with plenty of flavor and bite, Mr. Headley starts with extra-firm tofu, presses out any excess liquid, then marinates it in a spicy pickle juice brine. It’s then double-battered and deep-fried until crisp. This sandwich is best enjoyed on a sunlit stoop in the East Village, just steps outside Superiority Burger, but it’s also achievable in any home kitchen. Alexa Weibel","from_your_kitchen":null,"ingredients":["1 (14-ounce) package extra-firm tofu, drained","1 ½ cups pickle juice","1 tablespoon hot sauce","1 tablespoon Dijon mustard","1 teaspoon gochugaru or red-pepper flakes","2 tablespoons grapeseed oil or other neutral oil","½ cup Dijon mustard","2 cups all-purpose flour","½ teaspoon baking powder","1 teaspoon smoked paprika","½ teaspoon onion powder","½ teaspoon garlic powder","½ teaspoon ground cayenne","1 teaspoon kosher salt, plus more as needed","1 teaspoon black pepper","Grapeseed oil or other neutral oil, for frying","6 potato buns or other soft rolls","Vegan mayonnaise and hot sauce, as needed","Thinly shredded green cabbage and dill pickles, for serving"],"ingredient_groups":[{"at":0,"title":"FOR THE MARINATED TOFU"},{"at":6,"title":"FOR THE FRIED TOFU"},{"at":16,"title":"FOR ASSEMBLY"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the marinated tofu: Line a baking sheet with paper towels or a clean kitchen towel. Cut the tofu crosswise into two rectangles that are each about 2 ½ inches wide and 4 inches long. Slice each rectangle into three ½-inch thick slabs and arrange in a single layer on the baking sheet. Cover the sliced tofu with more towels and gently press each piece to extract some of the moisture."},{"n":2,"title":null,"text":"In a large bowl, combine the pickle juice, hot sauce, mustard and gochugaru."},{"n":3,"title":null,"text":"Heat the grapeseed oil in a large nonstick or cast-iron skillet over high heat until shimmering. Sear the tofu to form a golden-brown crust, 4 to 5 minutes per side. Immediately drop the hot tofu into the pickle juice mixture. Refrigerate and let the tofu marinate for at least a few hours, or even overnight."},{"n":4,"title":null,"text":"Prepare the fried tofu: In a medium shallow bowl, stir the mustard with ¼ cup water until it’s the consistency of heavy cream and set aside. In a large shallow bowl, whisk together the flour, baking powder, spices, salt and pepper."},{"n":5,"title":null,"text":"In a Dutch oven or sturdy pot, heat 2 inches of grapeseed oil over medium heat and set a wire rack on top of a baking sheet. Remove the tofu from the brine and pat dry. Dip the tofu in the mustard mixture, turning until coated all over, then the flour mixture; dip it again in the mustard then flour until twice coated. When the oil temperature reaches 350 degrees, carefully place the battered tofu into the hot oil and fry, flipping as needed, until golden brown, about 5 minutes. Transfer the fried tofu to the wire rack and sprinkle with a little salt."},{"n":6,"title":null,"text":"To serve, toast the buns and spread generously with mayo and dot with hot sauce, if desired. Top with fried tofu, cabbage and dill pickles, and eat immediately."}],"tips":[],"cuisine_tags":["American","Fusion"],"ingredient_tags":["tofu"],"item_tags":["dijon mustard","gochugaru","smoked paprika"],"course_tags":["Dinner","Lunch"],"keywords":["All-Purpose Flour","American","Deep Fry","Dijon Mustard","Dinner","Extra-Firm Tofu","Gochugaru","Lunch","Main Course","Marinate","Plan-Ahead","Sandwiches","Vegan","Vegetarian"],"issues":null,"front":"nyt_1021237.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021237-superiority-burgers-crispy-fried-tofu-sandwich","rating":{"value":4,"count":4957},"date":"2020-07-09"},{"pair":1020993,"title":"Tofu and Green Beans With Chile Crisp","subtitle":null,"author":"Sam Sifton","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"192","fat":"10 g","carbohydrates":"17 g","protein":"12 g"},"description":"I love to cook with chile crisp, a fiery hot-pepper condiment born in the Sichuan Province of China that generally relies on fried shallots and garlic for texture, and on any number of umami-rich special ingredients for distinction and oomph. It’s magical: a boon to noodle soups and kitchen-sink stir-fries, to eggs and cucumbers, to plain steamed fish. Here, I use it as the base of a marinade and topping for baked tofu and green beans, with black vinegar, a little sesame oil, a wisp of honey, minced garlic and ginger, along with scallions and cilantro. But you could use the mixture on a mitten and have a very nice meal.","from_your_kitchen":null,"ingredients":["3 tablespoons chile-crisp condiment, plus more for serving","3 tablespoons soy sauce","1 ½ tablespoons Chinese black vinegar","1 ½ teaspoons sesame oil","1 teaspoon honey","2 garlic cloves, peeled and minced","2 tablespoons chopped scallions","2 tablespoons chopped cilantro","1 (14-ounce) package extra-firm tofu, drained and sliced crosswise into 8 (½-inch-thick) slabs","¾ pound green beans","1 tablespoon neutral oil, like canola or grapeseed","White rice, for serving","1 tablespoon minced fresh ginger"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 450 degrees. In a baking dish or casserole, whisk together the chile crisp, soy sauce, vinegar, sesame oil, honey, garlic, ginger, scallions and cilantro."},{"n":2,"title":null,"text":"Add the tofu slices to the dish, and coat them with the sauce, then allow to marinate for as long as it takes to heat the oven and trim the green beans."},{"n":3,"title":null,"text":"Add the green beans to a large sheet pan, then drizzle the neutral oil on top and toss to coat. Slide the green beans to the sides of the pan, and arrange the slices of tofu in an even layer in the center of the pan. Pour remaining marinade over the tofu, and place in oven."},{"n":4,"title":null,"text":"Roast until the green beans start to blister, 20 to 25 minutes. Serve immediately with rice and extra chile crisp on the side."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["green beans","rice","tofu"],"item_tags":["black vinegar","chili crisp","ginger","sesame oil","soy sauce"],"course_tags":["Dinner"],"keywords":["Asian","Chile Paste","Dinner","Easy","Green Bean","Main Course","One Pot","Rice","Roast","Roasts","Sesame Oil","Soy Sauce","Tofu","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020993.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020993-tofu-and-green-beans-with-chile-crisp","rating":{"value":5,"count":7153},"date":"2020-04-19"},{"pair":1021227,"title":"Frozen Tom Collins","subtitle":null,"author":"Rebekah Peppler","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"10 minutes, plus at least 4 hours’ freezing","nutrition":{"calories":"118","fat":"0 g","carbohydrates":"12 g","protein":"0 g"},"description":"Think of this frozen drink as a Tom Collins meets Italian lemon ice: It’s refreshingly sweet-tart, boozy and fully capable of giving you brain freeze in a painfully nostalgic way. Since colder temperatures can shift the way we perceive sweetness, frozen drinks read less sweet on the palate and thus require a bit more added sugar to balance flavors. This recipe employs a final flourish of syrupy maraschino cherries, stirred in to taste. If you’re skipping the cherries or don’t have time to run out to stock up, you can simply add a bit more simple syrup to taste while blending. You’ll lose the brilliant color contrast — and the outright fun of snacking on ice-cold, candylike cherries — but, like most good drinks, this one’s adaptable.","from_your_kitchen":null,"ingredients":["8 ounces gin","6 ounces fresh lemon juice (from 3 to 4 large lemons)","4 ounces simple syrup (1:1 granulated sugar and water)","5 to 6 cups cracked or crushed ice cubes","Maraschino cherries and syrup, preferably Luxardo, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In an airtight container, combine the gin, lemon juice and simple syrup. Seal and refrigerate until thoroughly chilled, at least 4 hours or overnight."},{"n":2,"title":null,"text":"Transfer the chilled mixture to the blender, add the ice and blend until smooth and slushy."},{"n":3,"title":null,"text":"Divide the mixture among 6 lowball glasses; garnish each with a few cherries and a drizzle of cherry syrup. Serve immediately, and store any extras in the freezer in a covered container until ready to enjoy."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["gin","lemon"],"item_tags":["maraschino cherries","simple syrup"],"course_tags":["Drinks"],"keywords":["Cocktails","Gin","Lemon Juice"],"issues":null,"front":"nyt_1021227.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021227-frozen-tom-collins","rating":{"value":4,"count":565},"date":"2020-07-15"},{"pair":1021091,"title":"Sweet-and-Spicy Grilled Vegetables With Burrata","subtitle":null,"author":"Melissa Clark","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"45 minutes","nutrition":{"calories":"242","fat":"12 g","carbohydrates":"27 g","protein":"11 g"},"description":"A colorful platter of soft, grilled vegetables in a sweet-and-spicy sauce can be the centerpiece of a light summery meal; just add some creamy cheese for richness and crusty bread to round things out. This recipe is extremely adaptable. You mix and match the vegetables, increasing the amounts of your favorites (or the ones you can get your hands on), and skipping anything you don’t have. And if your grill is large enough, you can make several different kinds of vegetables at the same time. Just don’t crowd them so they cook evenly.","from_your_kitchen":null,"ingredients":["¼ cup chopped raisins, preferably golden, or dried apricots","⅔ cup white wine vinegar or cider vinegar (or a combination)","2 tablespoons honey, plus more to taste","1 tablespoon fish sauce or colatura (optional)","¼ teaspoon red-pepper flakes","Pinch of fine sea salt","Extra-virgin olive oil","2 to 3 bell peppers, quartered, stems and seeds removed","1 to 2 zucchini or summer squash, sliced diagonally ½-inch thick","1 small eggplant, sliced diagonally ½-inch thick","2 to 4 ears yellow corn, shucked","8 ounces mushrooms, trimmed and halved or quartered","1 bunch thick asparagus, ends snapped","8 ounces cherry tomatoes, preferably still on the vine","2 small burrata or fresh mozzarella balls, or 2 cups fresh ricotta","Flaky sea salt and freshly ground black pepper","Basil or mint leaves, for serving","Crusty bread slices"],"ingredient_groups":[{"at":0,"title":"FOR THE SWEET-AND-SPICY SAUCE"},{"at":6,"title":"FOR THE VEGETABLES (USE ANY OR ALL)"},{"at":14,"title":"FOR SERVING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the sauce: Put raisins or apricots in a small heatproof bowl. In a small saucepan, combine vinegar, honey, fish sauce or colatura (if using), red-pepper flakes and salt. Bring to a boil, then let simmer until the mixture reduces slightly, about 3 minutes. Immediately pour over the raisins and let cool. Taste and stir in a little more honey if the sauce is too harsh. (Sauce can be made up to 1 week ahead and stored in the refrigerator.)"},{"n":2,"title":null,"text":"Prepare the vegetables: Oil the grill grate and light the grill. Have a serving platter at the ready."},{"n":3,"title":null,"text":"Grill the peppers, zucchini, eggplant and corn directly on the grate, in batches if necessary, and turning them as needed. Move them around the grate so they cook evenly. Cook until they are lightly charred, watching them carefully, 5 to 12 minutes, depending on the vegetable."},{"n":4,"title":null,"text":"To grill the mushrooms and asparagus, place them in a grilling basket if you have one, or put directly on the grill. (Arrange the asparagus perpendicular to the grates so they don’t fall through.) Grill, turning as needed, until charred all over, 6 to 10 minutes. Grill the cherry tomatoes, using the vine as a handle if possible, for 1 to 2 minutes, until they start to burst and char slightly. Transfer all the vegetables as they cook directly to the serving platter."},{"n":5,"title":null,"text":"Add the cheese to the platter next to the vegetables. Immediately drizzle everything with some of the sauce, stirring it up to get the raisins, and with olive oil. Sprinkle with flaky sea salt and pepper and scatter the herbs generously on top. Serve the extra sauce and the bread alongside for making crostini with some of the vegetables and more of the tangy sauce."}],"tips":["To make this using a broiler, spread the vegetables on a rimmed sheet pan, drizzle with oil and broil until browned on top, then flip and broil until browned on the other side. The timing will depend on the vegetable, so stick with one kind per baking pan. You’ll need to do this in batches. You can also use a grill pan."],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["asparagus","bell pepper","corn","eggplant","mushrooms","zucchini"],"item_tags":["basil","honey","mozzarella","raisins"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Asparagus","Bell Pepper","Cherry Tomato","Corn","Dinner","Eggplant","Fourth of July","Grill","Honey","Labor Day","Main Course","Memorial Day","Mozzarella","Mushroom","Raisin","Side Dish","Summer","Vegetables","Vegetarian","Zucchini"],"issues":null,"front":"nyt_1021091.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021091-sweet-and-spicy-grilled-vegetables-with-burrata","rating":{"value":4,"count":2300},"date":"2020-05-20"},{"pair":1021036,"title":"Focaccia","subtitle":null,"author":"Amelia Nierenberg","servings":null,"yield_text":"One 9-by-13-inch pan","yield_count":1,"cook_time":"30 minutes, plus resting and rising","nutrition":{"calories":"2030","fat":"60 g","carbohydrates":"323 g","protein":"44 g"},"description":"Seasoned with little more than olive oil and crunchy sea salt, focaccia is an ancient bread that is unexpectedly easy to make. Once a staple at Caroline Fidanza’s now-closed sandwich shop, Saltie, in Williamsburg, Brooklyn, this recipe from the “Saltie: A Cookbook” is perfect on its own, but also serves as a base upon which you can experiment. If you want to alter its flavor, sprinkling some aromatic dry herbs on top of the dough provides deep savory notes. Or decorate it vibrantly with the vegetables and fresh herbs of your choosing for an Instagram-worthy focaccia garden (see Tip). Amelia Nierenberg","from_your_kitchen":null,"ingredients":["3 ¼ cups/415 grams all-purpose flour","1 tablespoon kosher salt","½ teaspoon active dry yeast","1 ¾ cups/420 milliliters warm water","4 tablespoons extra-virgin olive oil, plus more for greasing","1 ½ teaspoons coarse sea salt","Whole or chopped fresh rosemary leaves, dried oregano, fennel seeds, herbes de Provence or other dried herbs, for garnish (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, whisk together the flour, kosher salt and yeast. Add the warm water to the flour mixture and stir until all the flour is incorporated and a sticky dough forms. (Expect a very wet dough; no kneading required.) Pour 2 tablespoons oil into a medium bowl. Transfer the dough to the bowl, turn to coat, and cover tightly with a lid or plastic wrap. Place in the refrigerator to rest for at least 24 hours or for up to 2 days."},{"n":2,"title":null,"text":"When you’re ready to bake, brush the inside of a 9-by-13-inch baking sheet with oil. Remove the dough from the refrigerator and transfer to the prepared pan. Using your hands, spread the dough out as much as possible, adding oil to the dough if needed to keep it from sticking. (Don’t worry if the dough doesn’t yet cover the full pan; it will once it relaxes and rises.) Place the dough in a warm place and let rise until about doubled in bulk. The rising time will vary considerably depending on the season. (In the summer, it may take only 20 minutes for the dough to warm up and rise; in the winter, it can take 1 hour or more.) When the dough is ready, it should be room temperature, spread out on the sheet and fluffy."},{"n":3,"title":null,"text":"Heat the oven to 450 degrees. Using your palms, pat down the focaccia to an even thickness of about 1 inch, then, using your fingertips, dimple the entire dough. Drizzle it with the remaining 2 tablespoons olive oil. Sprinkle the entire surface of the focaccia evenly with the sea salt and herbs, if using."},{"n":4,"title":null,"text":"Bake, rotating once front to back, until the top is uniformly golden brown, 20 to 25 minutes. Transfer the focaccia on the baking sheet to a wire rack to cool, then slide out of the pan. Enjoy it hot. (Focaccia deteriorates in quality after the first day. If there is some left over, wrap it tightly in plastic and store at room temperature for another day. Day-old focaccia is delicious in soup.)"}],"tips":["To make a focaccia garden, prepare your vegetables as the dough rises in Step 2. Be creative in working with what you have: Peppers make great petals. Tomatoes do, too, but you might want to drain them before you put them on the dough. Chives and scallions make great stems. Experiment with olives and seeds, purple potatoes, and red onions. Whatever your fancy, cut your decorations a little thick, about 1/8 inch, and dip any fresh herbs in lemon water to keep the colors vibrant as they bake. Arrange the vegetables over the focaccia after you dimple the dough in Step 3. Press them into the dough gently, then drizzle with the remaining 2 tablespoons olive oil, and proceed with the rest of the recipe. You may need to increase your baking time, depending on your amount of decorative toppings."],"cuisine_tags":["Italian"],"ingredient_tags":["focaccia"],"item_tags":["rosemary"],"course_tags":["Breakfast","Dinner","Lunch","Sides & Appetizers"],"keywords":["Active Dry Yeast","All-Purpose Flour","American","Appetizer","Bake","Breads","Breakfast","Brunch","Dinner","Five Ingredient","Flatbread","Lunch","Olive Oil","Rosemary","Side Dish","Snack","Vegetarian"],"issues":null,"front":"nyt_1021036.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021036-focaccia","rating":{"value":4,"count":2635},"date":"2020-04-29"},{"pair":1019982,"title":"Creamy Braised White Beans","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"502","fat":"16 g","carbohydrates":"69 g","protein":"24 g"},"description":"Everything you need to make this humble-but-satisfying meal is probably in your kitchen at this very moment. Two cans of beans (chickpeas and white beans) are simmered with milk, a whole head of garlic, herbs and nutmeg for a rich and creamy vegetarian dinner that can be on the table in under a half-hour. Be sure to use whole milk here — it's the most flavorful and will yield the best results. Feel free to wilt greens like chard, watercress, arugula or basil into the beans, and serve with grated Parmesan and red-pepper flakes. A slice of crusty bread slicked with caramelized garlic is the perfect crunchy accompaniment to velvety beans.","from_your_kitchen":null,"ingredients":["1 tablespoon unsalted butter","1 head garlic, halved crosswise","1 cup whole milk","1 (15-ounce) can chickpeas, with their liquid","1 (15-ounce) can white beans, such as cannellini or Great Northern, drained and rinsed","1 thyme sprig, 2 sage leaves or 1 bay leaf","⅛ teaspoon ground nutmeg, allspice or garam masala","Kosher salt and black pepper","4 slices crusty bread or thick toast","Extra-virgin olive oil, for serving","Freshly grated Parmesan, for serving","Aleppo pepper or red-pepper flakes, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a medium saucepan, melt the butter over medium-high heat. Add the garlic, cut side down, and cook until golden brown, 1 to 2 minutes."},{"n":2,"title":null,"text":"Add the milk, chickpeas and their liquid, white beans, thyme and nutmeg and stir to combine. Season generously with salt and pepper. When the mixture begins to bubble around the edges of the pan (you don’t want it to come to a full boil), reduce the heat to low and let it simmer, stirring occasionally, until it has thickened and tastes great to you, about 15 minutes. Season with salt and pepper, to taste."},{"n":3,"title":null,"text":"Use a fork to remove the garlic halves from the beans. Set aside until cool enough to handle, then use the fork to remove the cloves from the skins. Spread the cloves on bread or toast."},{"n":4,"title":null,"text":"If you would like the beans to be more stew-like, mash some of the beans using a potato masher or the back of a spoon. Serve beans and milk in bowls. Garnish as you wish, with a drizzle of oil, a sprinkle of Parmesan and a pinch of Aleppo pepper and black pepper. Serve with the bread alongside for dipping."}],"tips":["You can reheat leftovers the next day over low heat; the sauce will have thickened, but the beans will still be delicious."],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["chickpeas","white beans"],"item_tags":["aleppo pepper","garlic","parmesan","sourdough bread"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Beans","Chickpea","Dinner","Easy","Garlic","Lunch","Main Course","Milk","Quick","Side Dish","Vegetarian","Weeknight","White Bean"],"issues":null,"front":"nyt_1019982.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019982-creamy-braised-white-beans","rating":{"value":4,"count":7142},"date":"2020-03-18"},{"pair":1021211,"title":"Chopped Cucumber and Tomato Salad","subtitle":null,"author":"David Tanis","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"40 minutes","nutrition":{"calories":"202","fat":"14 g","carbohydrates":"15 g","protein":"6 g"},"description":"Here’s an easy summer salad that’s always a winner. There are many similar chopped salads served throughout the Eastern Mediterranean, but this version with halved sweet cherry tomatoes is especially attractive. Your own take can be a variation on this one: Feel free to use large tomatoes, chop the vegetables as small or large as you like (roughly chopped has its charms), add other herbs like basil, mint or dill, or swap the feta for mozzarella.","from_your_kitchen":null,"ingredients":["1 cup diced red onion","2 garlic cloves, smashed to a paste with a little salt","3 tablespoons red wine vinegar","¼ cup extra-virgin olive oil","2 roasted peppers, preferably orange or yellow, chopped","3 cups halved cherry tomatoes","3 cups chopped thin-skinned cucumber, such as Persian, skin on, in ½-inch cubes","½ cup chopped celery hearts, plus leaves","Kosher salt and black pepper","3 tablespoons roughly chopped flat-leaf parsley","4 ounces feta or queso fresco, crumbled (about 1 cup)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put onion, garlic, vinegar and olive oil in a large mixing bowl. Let macerate for 10 minutes."},{"n":2,"title":null,"text":"Add roasted peppers, cherry tomatoes, cucumbers and celery. Season to taste with salt and pepper, and toss well. Let macerate for at least 20 minutes, tossing several times with the dressing. You can also prepare the ingredients in advance, and assemble the salad up to 1 hour before serving."},{"n":3,"title":null,"text":"To serve, toss once more and transfer to a deep platter or wide bowl. Sprinkle with parsley and feta."}],"tips":[],"cuisine_tags":["Mediterranean"],"ingredient_tags":["cucumber","tomato"],"item_tags":["feta","parsley","red onion"],"course_tags":["Sides & Appetizers"],"keywords":["Cucumber","Parsley","Salad","Side Dish","Summer","Tomato","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021211.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021211-chopped-cucumber-and-tomato-salad","rating":{"value":4,"count":1200},"date":"2020-07-15"},{"pair":1021200,"title":"Crispy Tofu With Cashews and Blistered Snap Peas","subtitle":null,"author":"Yewande Komolafe","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"422","fat":"32 g","carbohydrates":"24 g","protein":"18 g"},"description":"A ginger and coconut milk reduction can coat pretty much anything that browns nicely on its own. Here, it’s pieces of pan-seared tofu, but small morsels of chicken and pork will work just as well. The soy and the teaspoons of molasses give the sauce a little caramelization, and a little shine and gloss. For a fresh side, add some blistered snap peas, tossed with sliced scallions, a little mint and a splash of rice vinegar. Snow peas, green beans, broccoli or asparagus? If it’s fresh and green, it’ll work just fine.","from_your_kitchen":null,"ingredients":["1 (14-ounce) block firm or extra-firm tofu, drained","3 tablespoons neutral oil, such as grapeseed, vegetable or canola, plus more as needed","Kosher salt and black pepper","¾ pound snap peas, trimmed","1 (2-inch) piece fresh ginger, peeled and grated (about 2 tablespoons)","2 garlic cloves, grated","1 (13-ounce) can unsweetened coconut milk (light or full-fat)","1 tablespoon soy sauce","2 teaspoons molasses, dark brown sugar or honey","½ cup toasted cashews","1 tablespoon rice vinegar","4 scallions, trimmed and thinly sliced","¼ cup mint leaves, torn if large","½ to 1 teaspoon red-pepper flakes (optional)","Rice or any steamed grain, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Slice the tofu in half horizontally, and leave on paper towels to dry any excess liquid."},{"n":2,"title":null,"text":"In a medium skillet or cast-iron pan, heat 1 tablespoon oil over medium-high until it shimmers. Season both sides of the tofu with salt and black pepper, place in the pan and sear without moving until tofu is browned and golden on both sides, turning once halfway through, about 8 minutes total. Move the tofu to a plate."},{"n":3,"title":null,"text":"Add 1 tablespoon oil to the pan, and add the snap peas. Cook, stirring occasionally, until blistered and just tender, about 3 minutes. Season with salt and move to a bowl."},{"n":4,"title":null,"text":"Heat the remaining 1 tablespoon oil, add the ginger and garlic, and cook until fragrant, about 30 seconds. Pour in the coconut milk, soy sauce and molasses. Simmer, stirring frequently until the sauce reduces and its color deepens to a dark brown, about 6 to 8 minutes. It should coat a spoon without running right off. Stir in the cashews, break the tofu into 1-inch pieces and toss in the pan to coat with sauce. Remove from heat, and taste and adjust seasoning, if necessary."},{"n":5,"title":null,"text":"Toss the snap peas with the rice vinegar, scallions, mint and red-pepper flakes, if using. Divide among plates, along with the tofu and cashews. Serve with rice or any steamed grain."}],"tips":[],"cuisine_tags":["Chinese","Fusion"],"ingredient_tags":["cashews","sugar snap peas","tofu"],"item_tags":["coconut milk","ginger","mint","rice vinegar","soy sauce"],"course_tags":["Dinner"],"keywords":["Beans","Cashew","Cast Iron","Coconut Milk","Dairy-Free","Dinner","Extra-Firm Tofu","Firm Tofu","Fresh Ginger","Main Course","Skillet","Spring","Sugar Snap Pea","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021200.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021200-crispy-tofu-with-cashews-and-blistered-snap-peas","rating":{"value":4,"count":10422},"date":"2020-07-01"},{"pair":1021000,"title":"Pasta With Garlicky Spinach and Buttered Pistachios","subtitle":null,"author":"Dawn Perry","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"554","fat":"22 g","carbohydrates":"73 g","protein":"19 g"},"description":"If you want to get the timing just right on this one — no wasted time! — start the sauce a few minutes after you’ve dropped the pasta into the boiling water. Your spinach should be wilted right around the time the pasta is al dente. If that feels too stressful, or the spinach wilts before the pasta is ready, simply turn the heat under the skillet all the way down to low and keep it warm while the pasta finishes. Don’t count this recipe out if you’re not fond of capers. They add a hint of salty brininess without being in-your-face caper-y. A pound of pasta is a lot to toss around, especially with 2 bunches of spinach in the mix, so save that extra quarter-box for your next pot of pasta e fagioli.","from_your_kitchen":null,"ingredients":["Kosher salt and black pepper","12 ounces mezze rigatoni or other short pasta","4 tablespoons unsalted butter","½ cup roasted salted pistachios, almonds or hazelnuts, chopped","4 garlic cloves, chopped","2 tablespoons capers, drained","12 ounces spinach, stems trimmed to 1-inch length, or Swiss chard, trimmed and chopped","Grated Parmesan, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil. Add pasta and cook according to package instructions until al dente."},{"n":2,"title":null,"text":"After pasta has been cooking for about 2 minutes, melt the butter in a large skillet over medium-high heat. Add the pistachios, garlic and capers and cook, stirring to keep the garlic from scorching, until fragrant, about 1 minute."},{"n":3,"title":null,"text":"Add spinach to skillet one handful at a time, season with salt and cook, tossing, until wilted, about 1 or 2 minutes."},{"n":4,"title":null,"text":"Using a slotted spoon, transfer pasta to the skillet along with ½ cup pasta water. Season with salt and pepper and cook over medium-high, tossing, until liquid reduces and coats the pasta, 2 to 3 minutes; season with salt and pepper. Serve topped with Parmesan."}],"tips":[],"cuisine_tags":["American","Italian"],"ingredient_tags":["pasta","spinach"],"item_tags":["capers","garlic","parmesan","pistachios"],"course_tags":["Dinner"],"keywords":["American","Butter","Caper","Dinner","Easy","Garlic","Main Course","Parmesan","Pasta","Pastas","Pistachio","Spinach","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021000.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021000-pasta-with-garlicky-spinach-and-buttered-pistachios","rating":{"value":5,"count":4364},"date":"2020-04-15"},{"pair":1015464,"title":"Chanterelles on Toast","subtitle":null,"author":"Tara Parker-Pope","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"542","fat":"16 g","carbohydrates":"81 g","protein":"20 g"},"description":"Mushrooms are like sponges full of water. When subjected to heat, they release their liquid, and after some of it evaporates, they will suck the rest back up. So in this recipe from the chef Hugh Acheson start by letting the chanterelles hit the hot oil, sizzle and then color a bit. Liquid will exude into the pan, partly evaporate and then return into the mushrooms. Once the pan is pretty much liquid-free, it’s time to reintroduce flavorful liquids, which the mushrooms will also take up. Tara Parker-Pope","from_your_kitchen":null,"ingredients":["2 tablespoons extra-virgin olive oil","1 pound fresh chanterelles","2 tablespoons sherry vinegar","1 tablespoon freshly squeezed lemon juice","1 cup vegetable stock","½ teaspoon finely chopped fresh rosemary","1 teaspoon finely chopped fresh thyme","1 tablespoon chopped flat-leaf parsley","1 tablespoon cold butter","¼ teaspoon kosher salt","Freshly ground pepper, to taste","4 slices toasted sourdough, for serving","4 tablespoons shaved vegetarian Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat your largest fry pan over medium-high heat, and when it is hot, add the olive oil. Once the olive oil is hot, add the chanterelles. Cook for 4 minutes without moving them around too much."},{"n":2,"title":null,"text":"Add the sherry vinegar and the lemon juice and cook down until fully reduced. Add the stock and reduce by half (you are not exactly reducing so much as hydrating the mushrooms). Add the rosemary, thyme, parsley and butter. Stir with a wooden spoon to incorporate the butter. Season with salt and pepper."},{"n":3,"title":null,"text":"Evenly spoon the chanterelles over the 4 pieces of toasted bread and garnish with shaved Parmesan."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["mushrooms","sourdough bread"],"item_tags":["parmesan","parsley","rosemary","sherry vinegar","thyme"],"course_tags":["Dinner"],"keywords":["Chanterelle Mushroom","Main Course","Rosemary","Sherry Vinegar","Sourdough","Thyme","Vegetarian"],"issues":null,"front":"nyt_1015464.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015464-chanterelles-on-toast","rating":{"value":5,"count":914},"date":"2011-11-30"},{"pair":1020031,"title":"Baked Barley Risotto With Mushrooms and Carrots","subtitle":null,"author":"Kay Chun","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"523","fat":"23 g","carbohydrates":"66 g","protein":"19 g"},"description":"Wholesome and nutty, barley is a superb alternative to arborio rice in this risotto, since it’s naturally plump and chewy when cooked. The grated Parmesan and butter stirred in at the end release the barley’s starches, creating a silky, creamy texture. Make sure to use pearl barley, not hulled, since it cooks much faster and is more tender. As for the mushrooms, white button, cremini and earthy shiitakes are a tasty, accessible mix, though any combination of oyster, king trumpet and maitake would raise the bar. Still, the best thing about this risotto, which is a satisfying vegetarian weeknight dinner (or side to any large roast or fish) is that it’s baked, taking away the pressure of constant stirring at the stove.","from_your_kitchen":null,"ingredients":["3 tablespoons extra-virgin olive oil","½ small white or yellow onion, finely chopped (about ½ cup)","5 garlic cloves, thinly sliced","1 pound mixed mushrooms, such as white button, cremini and shiitakes, halved if small, quartered if large (about 7 cups total)","Salt and black pepper","10 ounces pearl barley (about 1 ½ cups)","1 medium carrot, very thinly sliced into rounds (about 1 cup)","2 ounces grated Parmesan (about ½ cup), plus more for serving","2 tablespoons unsalted butter","¼ cup chopped chives"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. In a large Dutch oven or heavy pot, heat 2 tablespoons oil over medium. Add onion and garlic, and cook, stirring occasionally, until softened, about 3 minutes. Add mushrooms and remaining 1 tablespoon oil, and season with salt and pepper. Cook, stirring occasionally, until mushrooms start to soften, about 3 minutes."},{"n":2,"title":null,"text":"Stir in barley, carrot and 4 ½ cups water, and bring to a boil over high heat. Cover, transfer to the oven and bake until barley is tender and chewy and almost all of the liquid is absorbed, about 30 minutes."},{"n":3,"title":null,"text":"Stir in Parmesan and the butter until slightly thickened and creamy. Season with salt and pepper."},{"n":4,"title":null,"text":"Divide among shallow bowls. Sprinkle with chives and more Parmesan, to taste."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["barley","carrot","mushrooms"],"item_tags":["chives","parmesan"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Bake","Cremini","Dinner","Main Course","Mushroom","Parmesan","Pearl Barley","Risotto","Shiitake","Side Dish","Thanksgiving","Vegetables"],"issues":null,"front":"nyt_1020031.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020031-baked-barley-risotto-with-mushrooms-and-carrots","rating":{"value":4,"count":1816},"date":"2019-02-12"},{"pair":1020403,"title":"Grilled Corn and Avocado Salad With Feta Dressing","subtitle":null,"author":"Sue Li","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"447","fat":"24 g","carbohydrates":"56 g","protein":"14 g"},"description":"This lively salad of corn, scallions, jalapeño and avocado tossed with a tangy buttermilk-feta dressing is like summer on a plate. The sweetness of peak-summer corn and the richness of creamy avocado balance out the tartness of the dressing. To choose the perfect corn, make sure that the corn husk is bright green and slightly dewy to the touch, and that the silks peeking out at the top are yellow, not browned. Finally, the corn should be heavy for its size: the heavier the corn, the plumper the kernels.","from_your_kitchen":null,"ingredients":["6 ears corn (about 3 pounds), shucked and silk removed","1 bunch scallions (about 6), trimmed","1 jalapeño, stemmed and halved lengthwise","3 tablespoons olive oil","Kosher salt and black pepper","4 ounces feta cheese, crumbled (about ¾ cup)","⅓ cup buttermilk","1 teaspoon freshly grated lemon zest plus 1 tablespoon lemon juice","1 small garlic clove, grated","¼ cup sliced fresh chives","¼ cup finely chopped fresh parsley","1 medium head romaine lettuce, torn into bite-size pieces (about 8 cups)","2 avocados, sliced"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat a grill or grill pan over medium-high. Brush corn, scallions and jalapeño with the oil and season with salt and pepper. Arrange on the grill and cook, turning occasionally, until corn kernels are browned in spots, 6 to 8 minutes, and the scallions and jalapeño are charred all over and tender, 9 to 10 minutes. Transfer vegetables to a cutting board and let cool slightly."},{"n":2,"title":null,"text":"In a medium bowl, using a whisk, mash the feta into a coarse paste. Whisk in buttermilk, lemon zest and juice and garlic, then stir in chives and parsley. Finely chop the charred jalapeño and stir it into the feta dressing; season with salt and pepper."},{"n":3,"title":null,"text":"In a large bowl, toss lettuce with half the feta dressing and arrange on a platter. Cut corn kernels off the cob and slice scallions into bite-size pieces. Arrange avocado slices, corn and scallions on top of the lettuce. Serve with remaining dressing."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["avocado","corn","romaine lettuce"],"item_tags":["buttermilk","chives","feta","jalapeño","lemon","parsley","scallions"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["American","Avocado","Buttermilk","Corn","Dinner","Easy","Feta","Grill","Jalapeño","Main Course","Romaine","Salad","Scallion","Side Dish","Summer","Weeknight"],"issues":null,"front":"nyt_1020403.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020403-grilled-corn-and-avocado-salad-with-feta-dressing","rating":{"value":5,"count":5472},"date":"2019-08-15"},{"pair":1020739,"title":"Indian Butter Chickpeas","subtitle":null,"author":"Melissa Clark","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"1 hour 10 minutes","nutrition":{"calories":"515","fat":"27 g","carbohydrates":"58 g","protein":"15 g"},"description":"A vegetarian riff on Indian butter chicken, this fragrant stew is spiced with cinnamon, garam masala and fresh ginger, and is rich and creamy from the coconut milk. You could add cubed tofu here for a soft textural contrast, or cubed seitan for a chewy one. Or serve it as it is, over rice to catch every last drop of the glorious sauce. You won’t want to leave any behind.","from_your_kitchen":null,"ingredients":["4 tablespoons unsalted butter","1 large onion, minced","1 ½ teaspoons kosher salt, plus more to taste","4 garlic cloves, finely grated or minced","1 tablespoon grated fresh ginger","2 teaspoons ground cumin","2 teaspoons sweet paprika","2 teaspoons garam masala","1 small cinnamon stick","1 (28-ounce) can whole peeled plum tomatoes","1 (15-ounce) can coconut milk","2 (15-ounce) cans chickpeas, drained","Ground cayenne (optional)","Cooked white rice, for serving","½ cup cilantro leaves and tender stems, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Melt butter in a large heavy-bottomed pot or Dutch oven over medium heat. Stir in onion and ½ teaspoon salt; cook until golden and browned around the edges, stirring occasionally, about 20 minutes. (Don’t be tempted to turn the heat up to medium-high; keeping the heat on medium ensures even browning without burning the butter.)"},{"n":2,"title":null,"text":"Stir in garlic and ginger, and cook another 1 minute. Stir in cumin, paprika, garam masala and cinnamon stick, and cook another 30 seconds."},{"n":3,"title":null,"text":"Add tomatoes with their juices. Using a large spoon or flat spatula, break up and smash the tomatoes in the pot (or you can use a pair of kitchen shears to cut the tomatoes while they are still in the can). Stir in coconut milk and the remaining 1 teaspoon salt. Bring to a simmer, and continue to cook for 10 minutes, stirring occasionally, and continuing to mash up the tomatoes if necessary to help them break down."},{"n":4,"title":null,"text":"Stir in chickpeas and a pinch of cayenne if you like. Bring the pot back up to a simmer and cook, stirring occasionally, for another 10 minutes. Taste and add more salt if necessary."},{"n":5,"title":null,"text":"Serve spooned over white rice, and topped with cilantro."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["chickpeas","tomato"],"item_tags":["cilantro","cinnamon","coconut milk","cumin","garam masala","ginger"],"course_tags":["Dinner"],"keywords":["Beans","Butter","Chickpea","Coconut Milk","Curry","Easy","Garam Masala","Garlic","Ginger","Great Leftovers","Indian","Main Course","Simmer","Tomato","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020739.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020739-indian-butter-chickpeas","rating":{"value":5,"count":7041},"date":"2020-01-01"},{"pair":1019904,"title":"Root Vegetable Tagine With Herbed Couscous","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":null,"description":"A pot of warm, fragrant root vegetables spooned over bright, lemony couscous is as good as gold on a winter day. Studded with chickpeas, raisins and meaty morsels of stewed tomatoes, this dish balances traditional tagine spices — cinnamon, coriander and turmeric — with a bright boost of ginger and lemon. Given a little time on the stove for the flavors to deepen and the vegetables to turn spoon-tender, this tagine is a worthwhile investment. Double it for a week of leftovers. You don’t need a traditional terracotta tagine to pull this dish off. A Dutch oven mimics the same high heat conduction and similarly traps steam to keep the vegetables tender and moist, and bathed in flavor from the broth.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil","1 large white or yellow onion, roughly chopped","Kosher salt","3 garlic cloves, smashed and peeled","1 cinnamon stick","1 (1-inch) piece fresh ginger, peeled and finely chopped","2 teaspoons ground coriander","2 teaspoons ground turmeric","2 cups vegetable stock","1 medium butternut squash (about 2 ¼ pounds), peeled and cut into bite-size pieces","4 small carrots, peeled and cut into bite-size pieces","1 (28-ounce) can whole peeled tomatoes, with their juices, tomatoes roughly chopped","1 lemon, peel removed in strips with a vegetable peeler and reserved, remaining lemon cut into wedges","1 (14-ounce) can chickpeas, drained and rinsed","⅓ cup golden or brown raisins","1 tablespoon honey","Black pepper","Fresh pomegranate seeds, for garnish","Roughly chopped parsley or cilantro leaves, for garnish","2 ½ cups vegetable stock","2 ¼ cups whole-wheat couscous (14 ounces)","Zest from 1 lemon","1 ½ teaspoons salt","1 packed cup chopped parsley leaves"],"ingredient_groups":[{"at":0,"title":"FOR THE ROOT-VEGETABLE TAGINE"},{"at":19,"title":"FOR THE HERBED COUSCOUS"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil in a large pot or Dutch oven over medium heat. Add the onion and a pinch of salt and cook until beginning to soften, 4 to 5 minutes. Stir in the garlic, cinnamon, ginger, coriander and turmeric, and cook, stirring occasionally, until the spices are toasted, 2 to 3 minutes."},{"n":2,"title":null,"text":"Add the stock, squash, carrots, tomatoes and their juices, and lemon peel. Stir to release any spice bits from the bottom of the pan. Bring to a simmer over high heat. Reduce the heat to medium, cover and cook until the vegetables are almost tender and break easily with a spoon, 20 to 25 minutes."},{"n":3,"title":null,"text":"Stir in the chickpeas, raisins and honey and simmer, covered, until the chickpeas are warmed through and the raisins are plump, about 5 minutes. Season with salt and pepper to taste."},{"n":4,"title":null,"text":"Meanwhile, prepare the couscous: Bring the stock to a boil in a medium saucepan over high heat. Combine the couscous, lemon zest and salt in a large bowl; pour the boiling stock on top. Cover with a lid or plastic wrap to steam, about 5 minutes. Fluff with a fork, and stir in the parsley."},{"n":5,"title":null,"text":"Divide the herbed couscous among the bowls and spoon the warm tagine on top. Sprinkle generously with pomegranate seeds and parsley or cilantro, and serve with lemon wedges on the side, for squeezing over."}],"tips":[],"cuisine_tags":["Moroccan"],"ingredient_tags":["butternut squash","carrot","chickpeas","couscous"],"item_tags":["cinnamon","coriander","ginger","golden raisins","lemon","turmeric"],"course_tags":["Dinner"],"keywords":["Butternut Squash","Carrot","Chickpea","Cinnamon Stick","Couscous","Dinner","Fall","Main Course","Simmer","Tagine","Winter"],"issues":null,"front":"nyt_1019904.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019904-root-vegetable-tagine-with-herbed-couscous","rating":{"value":4,"count":375},"date":"2019-01-09"},{"pair":1018123,"title":"Grilled Asparagus With Caper Salsa","subtitle":null,"author":"Sam Sifton","servings":"6","yield_text":"Serves 6","yield_count":6,"cook_time":"25 minutes","nutrition":{"calories":"111","fat":"8 g","carbohydrates":"7 g","protein":"6 g"},"description":"Caprino fresco is a soft, tangy Italian goat cheese, and here, it lends a deep creaminess to a caper salsa that is draped over grilled asparagus. The recipe, from the chef Yotam Ottolenghi, is quickly prepared. Bread may be needed to sop up the rest of the salsa. (If caprino fresco isn’t available, try another soft goat cheese, like chèvre.) Sam Sifton","from_your_kitchen":null,"ingredients":["3 bunches asparagus, approximately 1 pound, woody ends trimmed and discarded","2 tablespoons extra-virgin olive oil","Kosher salt and freshly cracked black pepper to taste","¼ cup capers, ideally small, drained, rinsed and patted dry","Grated zest of 1 lemon","2 teaspoons lemon juice","1 small garlic clove, peeled, crushed and minced","⅓ cup parsley leaves, roughly chopped","½ cup crumbled caprino fresco cheese, or another soft goat cheese like chèvre"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Fill a medium-size pot with cold water, and place it over high heat. When the water boils, add the asparagus, and blanch for 1 minute. Drain the asparagus, and rinse it immediately under cold water. Drain the asparagus again and place in a medium bowl, with 1 tablespoon of the oil, a pinch of salt and a generous grind of black pepper. Mix gently, and set aside."},{"n":2,"title":null,"text":"Light a charcoal or gas grill, or place a grill pan on the stove over high heat. Once it is hot, add the asparagus in batches, and grill for approximately 2 to 3 minutes, turning a few times, until the spears are lightly charred. Transfer to a large platter with all the tips facing in one direction."},{"n":3,"title":null,"text":"Meanwhile, make the salsa. Mix together the capers with the remaining tablespoon of oil, the lemon zest, lemon juice, garlic and parsley. Add the goat cheese to the mixture, stir gently and spoon over the asparagus."}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["asparagus"],"item_tags":["capers","goat cheese","lemon","parsley"],"course_tags":["Sides & Appetizers"],"keywords":["Asparagus","Caper","Middle Eastern","Side Dish","Vegetables"],"issues":null,"front":"nyt_1018123.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1018123-grilled-asparagus-with-caper-salsa","rating":{"value":5,"count":693},"date":"2016-05-22"},{"pair":1020910,"title":"Aloo Masala (Spiced Potatoes)","subtitle":null,"author":"Tejal Rao","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"260","fat":"10 g","carbohydrates":"40 g","protein":"6 g"},"description":"A little bowl of simply spiced half-mashed potatoes and onion, glistening with fat, is a standard side dish at bustling restaurants that serve dosas. It’s also one of the best vegetable dishes — inexpensive, quick and delicious — to add to your repertoire as a home cook. The key to these potatoes is water, not fat. Overcooking them just slightly ensures that they’re tender, and that they hold enough moisture so when you drop them into the hot pan, they break up and meld into the sautéed onion mix, becoming almost indistinguishable from it. Though aloo masala is great with a hot dosa, it’s a versatile dish that can also work as a side with other meals.","from_your_kitchen":null,"ingredients":["2 large Yukon Gold potatoes, peeled and cut into 1-inch cubes (about 4 cups)","2 tablespoons neutral oil, such as grapeseed or canola","1 tablespoon urad dal (split black gram)","½ teaspoon cumin seeds","¼ teaspoon black mustard seeds","2 tablespoons roughly chopped roasted cashews","1 green finger chile (or serrano chile), finely chopped","1 (1-inch) piece fresh ginger, peeled and finely chopped","1 medium yellow onion, chopped","½ teaspoon kosher salt, plus more as needed","¼ teaspoon ground turmeric","¼ cup chopped cilantro leaves and tender stems","½ lemon, for squeezing"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a pot of water to boil over high. Once the water boils, add the potatoes. Cook until tender, about 10 minutes, then drain in a colander."},{"n":2,"title":null,"text":"In a heavy pot, heat the oil over medium. Add the urad dal, cumin and mustard seeds, and fry until cumin seeds are browned and dal is crisp, 1 to 2 minutes. Stir in the cashews, chile and ginger, and cook for another 2 minutes. Add the onion, salt and turmeric, and lower the heat. Cook, stirring occasionally, until the onion is translucent and tender but not browned, about 5 minutes."},{"n":3,"title":null,"text":"Tip the cooked potatoes, half the cilantro and ¼ cup water into the pot, and stir well to coat. As you stir, let some of the potato get mashed. If the mixture seems dry, add a splash more of water. Cook over low, stirring occasionally, until the potatoes are heated through, about 5 minutes, then season to taste with salt. Scrape into a serving dish; top with a generous squeeze of lemon and the remaining cilantro."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["cashews","potato"],"item_tags":["brown mustard seeds","cilantro","cumin","ginger","lemon","turmeric"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Cilantro","Cumin","Dinner","Ginger","Indian","Lemon","Potato","Quick","Side Dish","Turmeric","Vegan","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1020910.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020910-aloo-masala-spiced-potatoes","rating":{"value":5,"count":1933},"date":"2020-03-11"},{"pair":1019469,"title":"One-Pan Bruschetta Spaghetti","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"523","fat":"13 g","carbohydrates":"80 g","protein":"21 g"},"description":"Spaghetti in the dead of summer, when tomatoes are at peak ripeness and break down quickly to coat any pasta in irresistible flavor, is the best time to eat spaghetti. You won’t need a lot of time to make this, just one big pan (use your largest and deepest) and the resolve not to eat the whole pile of noodles yourself. You'll want a slightly larger cast-iron skillet here — either a 12-inch version, or a deep 10-inch — to avoid spillage. Make sure to cover the pasta with a lid or foil so it cooks faster, and to stir from time to time. Since you’re not draining the noodles as you would in a traditional pasta dish, it’s good to know that different noodle shapes, sizes and brands may soak up liquid differently and that some tomatoes may be juicier than others. Simmer as long as needed get the sauce to a consistency that’s just right for you.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil","1 yellow onion, thinly sliced","4 garlic cloves, thinly sliced","Pinch of red-pepper flakes, to taste","1 tablespoon cider vinegar","12 ounces thin spaghetti or linguine, broken in half","2 pounds Roma or Campari tomatoes, chopped (about 8 to 12 tomatoes)","1 teaspoon kosher salt","½ teaspoon black pepper","2 ounces finely grated Parmesan (about ½ cup), plus more for serving","About 1 cup basil leaves, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oil in a very large, deep cast-iron skillet (or a Dutch oven) over medium-low. Add onion and cook until softening, stirring occasionally, about 5 minutes. Add the garlic and cook until fragrant, 3 to 5 minutes more. Add red-pepper flakes and vinegar, and stir until the vinegar evaporates."},{"n":2,"title":null,"text":"Add pasta, followed by the tomatoes, and pour 2 ¾ cup water over the top. Sprinkle with salt and pepper. Cover with a lid and bring to a boil. Simmer over medium-low heat until the pasta is just tender, about 10 minutes, stirring as needed so the pasta doesn’t stick. Uncover, and continue cooking until the liquid has evaporated to a loose sauce, just enough to coat your noodles with flavor, 5 to 8 minutes more. (If there’s still too much liquid at the bottom of your pan for your tastes, simmer a little longer.)"},{"n":3,"title":null,"text":"Taste and add more salt and pepper as needed. Toss with cheese and basil to melt the cheese. Serve warm."}],"tips":["Some cast-iron skillets come with a matching lid, which makes the skillet operate a bit like a miniature stovetop oven, cooking evenly and basting the food with flavor and steam. If you don’t have one, use a lid from another pan, or two layers of thick foil, folded at the center and large enough to cover your pan."],"cuisine_tags":["Italian"],"ingredient_tags":["pasta","tomato"],"item_tags":["basil","parmesan","red chile flakes"],"course_tags":["Dinner"],"keywords":["Dinner","Main Course","Parmesan","Pastas","Spaghetti","Summer","Tomato","Weeknight"],"issues":null,"front":"nyt_1019469.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019469-one-pan-bruschetta-spaghetti","rating":{"value":4,"count":1188},"date":"2018-09-26"},{"pair":1021415,"title":"Vegetarian Kofta Curry","subtitle":null,"author":"Tejal Rao","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"503","fat":"30 g","carbohydrates":"50 g","protein":"14 g"},"description":"Kofta curry — a saucy dish of gently spiced meatballs — is often made with meat. But this one, based on my grandfather’s, swaps in a mash of beans. Bound with bread crumbs and seasoned with ginger, garlic, green chile and herbs, it’s a variation full of flavor and texture. Have it with some flatbread and some sliced cucumber in yogurt, or spooned over a bowl of rice. It’s also delicious in a sandwich the next day. Note: To make it with lamb, as in his original version, substitute 1 ½ pounds ground lamb for the beans. Soak the bread crumbs in ½ cup whole milk first, then squeeze out any extra liquid before adding them to the mixing bowl.","from_your_kitchen":null,"ingredients":["4 garlic cloves","1 (2-inch) piece fresh ginger, peeled","2 green chiles (such as jalapeño or serrano), stems removed","1 (14-ounce) can black beans, rinsed and drained","4 spring onions or scallions, trimmed and chopped","1 bunch fresh cilantro, chopped, 1 tablespoon reserved for garnish","1 bunch fresh mint, chopped, 1 tablespoon reserved for garnish","½ cup bread crumbs","1 egg","1 teaspoon garam masala, plus more for garnish","½ teaspoon red chile powder","1 teaspoon sea salt, plus more as needed","½ cup neutral oil, such as canola or grapeseed","1 medium white onion, finely chopped","8 to 10 ripe Roma tomatoes (about 3 pounds) or 1 (28-ounce) can crushed tomatoes","1 teaspoon ground coriander","1 teaspoon ground cumin","Black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put the garlic, ginger and green chiles in a food processor, and pulse until you have a coarse paste. Put half the paste into a large bowl. Set the rest aside."},{"n":2,"title":null,"text":"Add the beans, spring onions, fresh herbs, bread crumbs, egg, garam masala, chile powder and salt to the large bowl with the paste. Mix well with a fork, mashing up the beans as you go into small pieces."},{"n":3,"title":null,"text":"Heat the oven to 400 degrees and line a sheet pan with parchment paper. Shape the mixture into 1-inch balls and arrange on the pan. Drizzle with 2 tablespoons oil, and bake until lightly browned, about 25 minutes. Set aside."},{"n":4,"title":null,"text":"Meanwhile, heat the remaining oil in a large skillet over medium. Sauté the onion until soft and translucent, about 5 minutes. Add the remaining garlic, ginger and chile paste, and sauté until light golden brown, about 10 minutes. If using fresh tomatoes, purée them until smooth in the food processor. Stir the tomato purée or crushed tomatoes, coriander and cumin into the skillet, and simmer for about 20 minutes, stirring occasionally."},{"n":5,"title":null,"text":"Add the kofta to the skillet, and turn the heat to low. If necessary, add enough water for the liquid to come about two-thirds of the way up the sides of the meatballs, then simmer another 15 minutes, stirring occasionally, until the kofta are warmed through and the sauce has thickened. Season with salt and pepper, and garnish with a light dust of garam masala and some extra herbs."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["black beans","eggs","tomato"],"item_tags":["cilantro","coriander","cumin","garam masala","ginger","mint"],"course_tags":["Dinner"],"keywords":["Beans","Black Bean","Cilantro","Dinner","Ginger","Indian","Main Course","Mint","Spring Onion","Tomato","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021415.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021415-vegetarian-kofta-curry","rating":{"value":4,"count":1852},"date":"2020-09-13"},{"pair":1018736,"title":"Shaved Asparagus Salad With Ginger and Sesame","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"67","fat":"3 g","carbohydrates":"8 g","protein":"3 g"},"description":"Succulent, fat, fresh asparagus is thinly sliced by hand for this raw salad — easier than you'd think, and safer than using a mandoline. It’s very refreshing and bright tasting.","from_your_kitchen":null,"ingredients":["2 tablespoons rice vinegar","1 tablespoon grated ginger","1 teaspoon minced garlic","1 tablespoon light brown sugar","1 jalapeño pepper, seeds removed and finely diced (optional)","2 teaspoons toasted sesame oil","Salt and pepper","1 ½ pounds fat asparagus","Salt and pepper","½ cup slivered scallions","Squeeze of lime juice, to taste","Mint leaves, for garnish","Cilantro sprigs, for garnish","1 tablespoon toasted sesame seeds","1 tablespoon black sesame seeds"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Make the dressing: In a small bowl, stir together rice vinegar, ginger, garlic and brown sugar. Add jalapeño and sesame oil, then season to taste with salt and pepper."},{"n":2,"title":null,"text":"Snap or cut off the tough bottoms of each asparagus spear. With a vegetable peeler, peel each tough-skinned spear, starting halfway down from tip and peeling toward bottom end."},{"n":3,"title":null,"text":"Cut the asparagus at a long diagonal into very thin slices (not paper thin — about the width of a thinly sliced onion). Place asparagus slices in a wide salad bowl. Season with salt and pepper and toss lightly. Add the ginger dressing and toss to coat well. Taste and adjust. Add scallions and lime juice and toss again."},{"n":4,"title":null,"text":"Garnish with mint leaves and cilantro sprigs. Sprinkle with sesame seeds and serve."}],"tips":[],"cuisine_tags":["Fusion"],"ingredient_tags":["asparagus"],"item_tags":["cilantro","ginger","mint","scallions","sesame oil","sesame seeds"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Asparagus","Dinner","Ginger","Lunch","Mother’s Day","No Cook","Salad","Scallion","Sesame Oil","Spring","Vegan","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1018736.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1018736-shaved-asparagus-salad-with-ginger-and-sesame","rating":{"value":5,"count":251},"date":"2017-04-26"},{"pair":1016668,"title":"The Ultimate Veggie Burger","subtitle":null,"author":"Melissa Clark","servings":null,"yield_text":"6 burgers","yield_count":6,"cook_time":"1 1/2 hours, plus at least 2 hours to chill","nutrition":{"calories":"386","fat":"24 g","carbohydrates":"28 g","protein":"19 g"},"description":"You make a veggie burger because you want the hamburger experience without the meat. This one delivers. It’s got a firm, beefy texture that takes on the char and smoke of the grill, but is adaptable enough to cook inside on your stove. The enemy of a veggie burger is mushiness, which stems from a high moisture content. To combat that, the very watery ingredients – mushrooms, tofu, beans and beets – are roasted to both dehydrate them somewhat and intensify their flavors. Yes, the ingredient list here is long; you need a diverse lot to make a good veggie burger. And each one adds something in terms of flavor and/or texture. Garnish this any way you like, and don’t forget to toast the buns.","from_your_kitchen":null,"ingredients":["4 ounces extra-firm tofu, drained","Olive oil","½ pound cremini mushrooms, trimmed and sliced","¾ teaspoon kosher salt, more as needed","Black pepper, as needed","1 (15-ounce) can kidney beans, drained","1 medium beet, peeled and coarsely grated (¾ cup)","¾ cup tamari almonds or cashews","⅓ cup panko bread crumbs","2 ounces Cotija cheese or queso blanco, crumbled or grated (about ½ cup)","2 large eggs","2 tablespoons mayonnaise","2 scallions, sliced","3 garlic cloves, finely chopped","¾ teaspoon dulce pimentón or sweet smoked paprika","4 ounces tempeh, crumbled","½ cup cooked brown rice"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Slice tofu into ¼-inch-thick slabs and pat dry with paper towel. Arrange tofu on one half of a rimmed baking sheet; brush both sides with oil. Spread mushrooms on the other half of the baking sheet; toss with 2 tablespoons oil and salt and pepper."},{"n":2,"title":null,"text":"On a second rimmed baking sheet, toss beans and grated beet with 1 tablespoon oil and salt and pepper, then spread the mixture into one layer."},{"n":3,"title":null,"text":"Transfer both baking sheets to the oven. Roast bean-beet mixture, tossing occasionally, until beans begin to split and beets are tender and golden, about 15 minutes. Roast mushrooms and tofu until golden and most of the liquid has evaporated, about 25 minutes. Let everything cool."},{"n":4,"title":null,"text":"Place nuts in a food processor and pulse until coarsely ground. Add cooled bean-beet mixture, mushrooms, tofu, panko, cheese, eggs, mayonnaise, scallion, garlic, pimentón and ¾ teaspoon salt. Pulse until ingredients are just combined. Pulse in tempeh and rice but do not overprocess. You want small chunks, not a smooth mixture. Scrape mixture into a bowl and chill at least 2 hours or up to 5 days (you can also freeze the burger mix)."},{"n":5,"title":null,"text":"When you are ready to make the burgers, divide mixture into 6 equal portions and form each portion into a patty about 1 inch thick. Return to the fridge until just before grilling. They grill better when they start out cold."},{"n":6,"title":null,"text":"Heat the grill. Cook the burgers over a low fire until they are charred on both sides and firm when you press on them, 4 to 6 minutes per side. If they start to burn before they firm up, move them to the sides of the grill to finish cooking over indirect heat. Alternatively, you can cook these on a grill pan or in a skillet over low heat."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["beets","kidney beans","mushrooms","tempeh","tofu"],"item_tags":["cotija","eggs","mayonnaise","smoked paprika"],"course_tags":["Dinner","Lunch"],"keywords":["Burgers","Dinner","Grill","Lunch","Main Course","Mushroom","Roast","Tofu"],"issues":null,"front":"nyt_1016668.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016668-the-ultimate-veggie-burger","rating":{"value":4,"count":2562},"date":"2014-07-23"},{"pair":1019241,"title":"Beans and Garlic Toast in Broth","subtitle":null,"author":"Tejal Rao","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"2 1/4 hours, plus optional soaking","nutrition":{"calories":"601","fat":"20 g","carbohydrates":"79 g","protein":"26 g"},"description":"A simple dish of creamy, thin-skinned beans and broth on toast is easy to make, and a comfort to eat alone or feed a crowd. If you make the beans ahead of time, they can keep in the fridge for 3 days, but may need a splash of water added when you heat them up. The broth is a great way to make use of parmigiano rinds, if you happen to be saving those, but if you don’t have any lying around, you can still make it rich with umami: Whisk a heaped tablespoon of white miso with a little of the bean broth to make it smooth and lump-free, then add it back to the pot. It will add a similar, savory depth. The dish seems plain, but it won’t be if you season the broth well, and garnish each bowl generously with olive oil, grated cheese and herbs, just before you eat it.","from_your_kitchen":null,"ingredients":["1 cup dried beans, such as cannellini or cranberry","1 small onion, peeled","2 garlic cloves, peeled","Up to 4 ounces Parmesan rinds","2 tablespoons extra-virgin olive oil","1 teaspoon kosher salt","4 thick slices crusty sourdough bread","Extra-virgin olive oil","1 garlic clove, peeled","2 tablespoons parsley leaves, chopped","1 tablespoon marjoram leaves, chopped","Flaky sea salt, finely grated Parmesan and freshly ground black pepper, for serving"],"ingredient_groups":[{"at":0,"title":"FOR THE BEANS"},{"at":6,"title":"FOR ASSEMBLY"}],"tools":null,"steps":[{"n":1,"title":null,"text":"If you remember, soak the beans in cold water overnight, or for 10 to 12 hours. Rinse beans, and place in a large heavy-bottomed pot with onion, garlic, Parmesan rinds, olive oil and salt. Cover beans with water, so the water level is a couple of inches above the beans, and bring to a boil, then turn heat down so it’s simmering gently. Put a lid on the pot, and cook until beans are tender, adding more water as needed to keep the beans submerged. This could take 1 to 2 hours or more, depending on the beans and whether or not you soaked them. (If you’re using an electric pressure cooker: Add 5 cups water, set the machine to high pressure and cook for 25 minutes, then allow the machine to slowly depressurize on its own.)"},{"n":2,"title":null,"text":"Use a spoon to fish out the onion, garlic and cheese rinds; discard. Taste a couple of beans along with the broth. It should be opaque and slightly creamy; adjust the seasoning with more salt if needed."},{"n":3,"title":null,"text":"Brush both sides of each piece of bread with olive oil, and place on a foil-lined sheet pan. Run the pan under the broiler for 2 minutes, so the bread is crisp at the edges and nicely toasted, then flip bread and repeat. While the bread is still hot, rub a garlic clove along one side of each piece, as if you were grating the garlic on the bread, pushing just firmly enough for the clove to fray and dissolve slightly into the bread."},{"n":4,"title":null,"text":"To assemble, place a piece of bread at the bottom of four wide, shallow bowls and ladle hot beans and broth on top. Wait a few seconds for the bread to absorb some broth, then ladle a little extra on each one, so it’s swimming. Garnish the bowls generously: Drizzle olive oil all over the beans, sprinkle with herbs and flaky sea salt, cover with finely grated Parmesan and grind a little black pepper on top."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["cannellini beans","sourdough bread"],"item_tags":["marjoram","parmesan","parsley"],"course_tags":["Dinner","Lunch"],"keywords":["Bean","Beans","Dinner","Garlic","Lunch","Main Course","Parmesan","Simmer","Sourdough","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019241.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019241-beans-and-garlic-toast-in-broth","rating":{"value":4,"count":2384},"date":"2020-03-18"},{"pair":1013525,"title":"Ricotta and Spinach Frittata With Mint","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"Six servings","yield_count":6,"cook_time":"30 minutes","nutrition":{"calories":"172","fat":"13 g","carbohydrates":"5 g","protein":"9 g"},"description":"I have a lot of spinach in my garden right now, and what doesn’t wind up in salads is going into frittatas. This one is lightly speckled with steamed spinach and seasoned with fresh mint.","from_your_kitchen":null,"ingredients":["6 ounces fresh spinach, stemmed and washed, or ½ 6-ounce bag baby spinach","6 eggs","Salt","freshly ground pepper","1 cup fresh ricotta","1 tablespoon chopped fresh mint","1 garlic clove, minced","2 tablespoons olive oil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Steam the spinach above 1 inch of boiling water just until it wilts, about two minutes. Rinse with cold water, squeeze out excess moisture and chop fine."},{"n":2,"title":null,"text":"In a medium bowl, beat together the eggs, salt, pepper, ricotta, garlic, spinach and mint."},{"n":3,"title":null,"text":"Heat the olive oil over medium-high heat in a heavy 10-inch nonstick skillet. Drop a bit of egg into the pan; if it sizzles and cooks at once, the pan is ready. Pour in the egg mixture. Tilt the pan to distribute the eggs and filling evenly over the surface. Shake the pan gently, tilting it slightly with one hand while lifting up the edges of the frittata with the spatula in your other hand, to let the eggs run underneath during the first few minutes of cooking."},{"n":4,"title":null,"text":"Turn the heat down to low, cover and cook 10 minutes, shaking the pan gently every once in a while. From time to time, remove the lid, tilt the pan and loosen the bottom of the frittata with a wooden spatula so that the bottom doesn’t burn. It should turn a golden color. The eggs should be just about set; cook a few minutes longer if they’re not."},{"n":5,"title":null,"text":"Meanwhile, heat the broiler. Uncover the pan and place under the broiler, not too close to the heat, for one to three minutes, watching very carefully to make sure the top doesn’t burn (at most, it should brown very slightly and puff under the broiler). Remove from the heat, shake the pan to make sure the frittata isn’t sticking, and allow it to cool for at least five minutes and for as long as 15 minutes. Loosen the edges with a wooden or plastic spatula. Carefully slide from the pan onto a large round platter. Cut into wedges or into smaller bite-size diamonds. Serve hot, warm, at room temperature or cold."}],"tips":["Advance preparation: In Mediterranean countries, flat omelets are served at room temperature, which makes them perfect do-ahead dishes. They’ll keep in the refrigerator for a few days, and they make terrific lunchbox fare. They do not reheat well."],"cuisine_tags":["Italian"],"ingredient_tags":["eggs","ricotta","spinach"],"item_tags":["mint"],"course_tags":["Breakfast","Dinner"],"keywords":["Breakfast","Broil","Brunch","Dinner","Easy","Egg","Gluten-Free","Healthy","Main Course","Quick","Spinach","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1013525.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013525-ricotta-and-spinach-frittata-with-mint","rating":{"value":5,"count":476},"date":"2011-03-23"},{"pair":1013350,"title":"Raw Butternut Squash Salad With Raisins and Ginger","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"5 minutes, plus several hours' refrigeration","nutrition":{"calories":"236","fat":"14 g","carbohydrates":"29 g","protein":"2 g"},"description":"This is a very simple yet very delicious salad, and it appeals to ominvores and vegans. The natural sweetness of raisins and squash are cut through by sherry vinegar and black pepper, and ginger lends complexity.","from_your_kitchen":null,"ingredients":["1 butternut squash about 1 ½ pounds, peeled, seeded and grated","½ cup raisins","¼ cup vegetable oil","1 to 2 tablespoons sherry vinegar, or to taste","1 tablespoon minced fresh ginger","Salt","Freshly ground black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Combine the squash, raisins, oil, vinegar and ginger in a salad bowl; sprinkle with salt and pepper. Toss, then taste and adjust the seasoning. Serve immediately, or cover and refrigerate for up to several hours."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["butternut squash"],"item_tags":["ginger","raisins","sherry vinegar"],"course_tags":["Sides & Appetizers"],"keywords":["Butternut Squash","Christmas","Easter","Easy","Fall","Gluten-Free","New Year’s Day","Quick","Raisin","Salad","Thanksgiving","Vegan","Vegetables","Vegetarian","Winter"],"issues":null,"front":"nyt_1013350.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013350-raw-butternut-squash-salad-with-raisins-and-ginger","rating":{"value":4,"count":69},"date":"2010-11-17"},{"pair":1020176,"title":"Roasted Broccoli and Potato Tacos With Fried Eggs","subtitle":null,"author":"Kay Chun","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"832","fat":"60 g","carbohydrates":"58 g","protein":"25 g"},"description":"These weeknight tacos are packed with nutrient-dense broccoli and comforting potatoes for a satisfying meal that comes together in just 45 minutes. The secret to its flavor lies in roasting the vegetables over high heat without stirring, which allows their edges to become smoked and crisp. Creamy egg yolks and deep, smoky paprika meld here, to create a rich sauce. If you’re short on time, you can roast the vegetables ahead of time and rewarm them, or even serve them at room temperature. Corn tortillas are used here, but flour tortillas can also be used. And feel free to customize them as you like, using all the suggested toppings or just some.","from_your_kitchen":null,"ingredients":["1 pound large broccoli florets (about 8 cups)","1 pound fingerling or baby white potatoes, sliced crosswise ¼-inch thick (about 4 cups)","1 bunch scallions (8 ounces), cut into 1-inch pieces (about 2 cups)","3 large garlic cloves, thinly sliced","2 teaspoons smoked paprika","10 tablespoons extra-virgin olive oil","Kosher salt and black pepper","8 (6-inch) corn tortillas","8 large eggs","2 avocados, cut into wedges","Salsa, sour cream, cilantro sprigs and lime wedges, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 450 degrees. On a large rimmed baking sheet, combine broccoli, potatoes, scallions and garlic with the paprika and 6 tablespoons oil. Season with salt and pepper, toss to coat, then spread in an even layer. Roast, undisturbed, until tender and charred in spots, 30 minutes."},{"n":2,"title":null,"text":"Stack tortillas and wrap tightly in aluminum foil. Five minutes before the vegetables are done, transfer foil-wrapped tortillas to the oven to warm up."},{"n":3,"title":null,"text":"Just before serving, heat 2 tablespoons oil over medium heat in a 12-inch nonstick or cast-iron skillet. Crack in 4 eggs and fry until whites are set and yolks are still runny, about 5 minutes. Transfer to a large plate. Repeat with remaining oil and eggs."},{"n":4,"title":null,"text":"Divide vegetable filling and avocado among the tortillas and top each with an egg. Spoon over some salsa and sour cream and garnish with cilantro sprigs. Fold over tortillas to form tacos or enjoy with forks and knives. Serve with lime wedges."}],"tips":[],"cuisine_tags":["Mexican"],"ingredient_tags":["avocado","broccoli","eggs","potato","tortilla"],"item_tags":["scallions","smoked paprika"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Avocado","Broccoli","Brunch","Dinner","Easy","Egg","Lunch","Main Course","Potato","Scallion","Tacos","Tortilla","Vegetables"],"issues":null,"front":"nyt_1020176.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020176-roasted-broccoli-and-potato-tacos-with-fried-eggs","rating":{"value":4,"count":558},"date":"2019-04-12"},{"pair":1020774,"title":"Creamy Farro With Crispy Mushrooms and Sour Cream","subtitle":null,"author":"Alison Roman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"484","fat":"17 g","carbohydrates":"76 g","protein":"15 g"},"description":"Similar in texture to a risotto (without the constant stirring), this creamy, saucy farro is about half the work, with almost no technique required. While the porridgelike texture is a delight all on its own, the meaty, golden brown mushrooms and frizzled leeks are the real reason you are here. Using plenty of olive oil to make sure the mushrooms crisp and brown without sticking will be the secret to success in that department.","from_your_kitchen":null,"ingredients":["¼ cup olive oil, plus more as needed","4 medium leeks, white and light green parts, thinly sliced","1 pound mix of mushrooms, such as maitake, oyster, cremini or chanterelle, torn into bite-size pieces (about 5 cups)","Kosher salt and freshly ground black pepper","1 ¾ cups pearled or semi-pearled farro or barley","4 cups vegetable broth or chicken broth","½ cup finely chopped chives (from about 1 bunch)","1 cup fresh dill leaves, coarsely chopped","1 tablespoon finely grated lemon zest, plus lemon wedges for squeezing","Sour cream, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat olive oil in a large Dutch oven over medium-high heat. Add half the leeks and half the mushrooms, and season with salt and pepper. Cook, stirring occasionally, until the mushrooms are browned and crisped, 12 to 15 minutes. (They will start giving off moisture and steaming a little before this happens, so be patient.)"},{"n":2,"title":null,"text":"Using a slotted spoon, transfer them to a medium bowl leaving any olive oil behind. (They will have absorbed the oil as they cook, and released it back as they crisp.) Add a bit more olive oil so there’s another ¼ cup or so in the pot. Cook the remaining leeks and mushrooms, adding them to the bowl with the other mushrooms."},{"n":3,"title":null,"text":"Without wiping the pot, add farro and season with salt and pepper. Cook over that same medium-high heat, stirring frequently, until farro is toasted on the outside (it will go from pale golden brown to a toastier golden brown), about 5 minutes. Add vegetable broth and 2 cups water; season with salt and pepper."},{"n":4,"title":null,"text":"Bring to a strong simmer and reduce heat to medium-low. Simmer gently, stirring occasionally, until farro is fully cooked and most (but not all) of the liquid has been absorbed, 20 to 25 minutes. It should still look a bit loose, like risotto or a porridge. Remove from heat and add half the chives."},{"n":5,"title":null,"text":"Toss dill, remaining chives and lemon zest together in a small bowl. To serve, season farro with salt and pepper and ladle into bowls. Top with sour cream, mushrooms and leeks, and dill mixture. Serve lemon wedges alongside for squeezing."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["farro","leeks","mushrooms"],"item_tags":["chives","dill","lemon","sour cream"],"course_tags":["Dinner"],"keywords":["Dinner","Farro","Grains and Rice","Leek","Main Course","Mushroom","Saute","Simmer","Sour Cream","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020774.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020774-creamy-farro-with-crispy-mushrooms-and-sour-cream","rating":{"value":4,"count":2514},"date":"2020-01-15"},{"pair":1013229,"title":"Tomato Frittata With Fresh Marjoram or Thyme","subtitle":null,"author":"Martha Rose Shulman","servings":"4 to 6","yield_text":"Four to six servings","yield_count":4,"cook_time":"45 minutes","nutrition":{"calories":"137","fat":"9 g","carbohydrates":"5 g","protein":"10 g"},"description":"One of my summer favorites, this frittata makes a perfect and substantial meal served cold or at room temperature.","from_your_kitchen":null,"ingredients":["1 ¼ pounds ripe, locally grown tomatoes","1 or 2 garlic cloves (to taste), minced or puréed","Salt","freshly ground pepper","1 tablespoon fresh marjoram leaves or 2 teaspoons fresh thyme leaves","8 large eggs","2 tablespoons low-fat milk","1 tablespoon extra virgin olive oil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Divide the tomatoes into two batches. Slice one batch into rounds (about ⅓ inch thick), and seed and chop the other batch. Toss the chopped tomatoes in a bowl with the garlic and salt and pepper to taste."},{"n":2,"title":null,"text":"Beat the eggs in a bowl, and stir in salt and pepper to taste, milk and half the marjoram or thyme. Stir in the chopped tomatoes."},{"n":3,"title":null,"text":"Heat the olive oil over medium-high heat in a 10-inch heavy nonstick skillet. Hold your hand above it; it should feel hot. Drop a bit of egg into the pan; if it sizzles and cooks at once, the pan is ready. Pour in the egg mixture. Tilt the pan to distribute the eggs evenly over the surface. Shake the pan gently, tilting it slightly with one hand while lifting up the edges of the frittata with a wooden or plastic spatula in your other hand, so as to let layers of eggs form during the first few minutes of cooking. Once a few layers of egg have cooked, arrange the tomato slices on top of the frittata, turn the heat down to low and cover the pan. (Use a pizza pan if you don’t have a lid that will fit your skillet.) Cook 10 minutes, shaking the pan gently every once in a while. From time to time, remove the lid and loosen the bottom of the frittata with the spatula, tilting the pan so that the bottom doesn’t burn. The eggs should be just about set; cook a few minutes longer if they’re not."},{"n":4,"title":null,"text":"Meanwhile, heat the broiler. Uncover the pan and place under the broiler, not too close to the heat, for one to three minutes, watching carefully to make sure the top doesn’t burn. (At most, it should brown very slightly and puff under the broiler.) Remove from the heat, shake the pan to make sure the frittata isn’t sticking, and allow it to cool for 5 to 15 minutes. Sprinkle on the remaining marjoram or thyme. Loosen the edges with the spatula. Carefully slide from the pan onto a large round platter. Cut into wedges. Serve hot, warm, at room temperature or cold."}],"tips":["Advance preparation: You can prepare the tomatoes several hours before you make the frittata. Pour off the juice that accumulates in the bowl before mixing the tomatoes with the eggs. The frittata will hold in the refrigerator for up to a day."],"cuisine_tags":["Italian"],"ingredient_tags":["eggs","tomato"],"item_tags":["marjoram","thyme"],"course_tags":["Breakfast","Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Breakfast","Broil","Brunch","Dinner","Egg","Gluten-Free","Healthy","Italian","Lunch","Main Course","Summer","Tomato","Vegetarian"],"issues":null,"front":"nyt_1013229.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013229-tomato-frittata-with-fresh-marjoram-or-thyme","rating":{"value":4,"count":317},"date":"2010-08-24"},{"pair":1015119,"title":"Broccoli Salad With Hazelnut Romesco","subtitle":null,"author":"Melissa Clark","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"264","fat":"17 g","carbohydrates":"25 g","protein":"8 g"},"description":null,"from_your_kitchen":null,"ingredients":["2 medium red bell peppers, halved and cored","1 plum tomato, halved","3 garlic cloves, peeled","½ cup toasted, peeled hazelnuts, more for garnish","½ cup dried breadcrumbs","¼ cup extra-virgin olive oil","1 tablespoon sherry vinegar, more as needed","1 tablespoon pomegranate molasses or 1 teaspoon honey, more as needed","1 ½ teaspoons hot smoked paprika","1 teaspoon kosher salt, more as needed","2 pounds broccoli, cut into bite-sized florets"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the broiler. Arrange an oven rack in the position closest to flame. Place peppers (cut side down), tomato halves (cut-side up) and garlic on a rimmed baking sheet. Broil until peppers and garlic are slightly charred, 3 to 5 minutes. Turn garlic (but do not turn peppers or tomato); broil 1 to 2 minutes longer until garlic is well browned but not burned. Transfer garlic to a large bowl. Continue broiling peppers and tomatoes until both are well charred, 4 to 5 minutes longer. Transfer tomato and peppers to the bowl with the garlic. Cover bowl with plastic wrap. Let stand until vegetables are cool enough to handle but still warm, then peel peppers and tomatoes."},{"n":2,"title":null,"text":"In the bowl of a food processor fitted with the blade attachment, pulse hazelnuts until coarsely ground. Add peppers, tomato, garlic, breadcrumbs, oil, vinegar, pomegranate molasses, paprika and salt. Purée until smooth. Taste and adjust seasonings. Scrape romesco into a bowl."},{"n":3,"title":null,"text":"Bring a large pot of salted water to a boil. Have ready a large bowl of ice water. Boil broccoli until just tender, 2 to 3 minutes. Use a slotted spoon to transfer to ice water; drain."},{"n":4,"title":null,"text":"In a large bowl, toss broccoli with enough romesco to coat vegetables well. (Reserve any remaining romesco for dipping or for another use.) Garnish with hazelnuts and serve warm or at room temperature."}],"tips":[],"cuisine_tags":["Spanish"],"ingredient_tags":["bell pepper","broccoli","hazelnuts"],"item_tags":["pomegranate molasses","sherry vinegar","smoked paprika"],"course_tags":["Sides & Appetizers"],"keywords":["Boil","Broccoli","Broil","Easy","Hazelnut","Quick","Side Dish","Spanish"],"issues":null,"front":"nyt_1015119.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015119-broccoli-salad-with-hazelnut-romesco","rating":{"value":5,"count":190},"date":"2013-09-18"},{"pair":1021035,"title":"Baked Rajma (Punjabi-Style Red Beans With Cream)","subtitle":null,"author":"Tejal Rao","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"408","fat":"17 g","carbohydrates":"46 g","protein":"21 g"},"description":"Punjabi-style rajma, or red beans, in a thick, spicy tomato gravy is comforting, quick and comes together with what you have in the pantry. This one-pan baked version is inspired by it, but deviates from tradition in several ways. First, it lets the oven do the work of reducing the sauce. When the dish comes out, scatter with cilantro, if you’ve got it, and some quick-pickled onion. The key is to take your time with the base, letting the onion mixture cook out properly, so the final sauce is mellow and deeply flavored. But you can try the same technique with different beans, from chickpeas to cannellini. Eating the dish with a side of yogurt or a glug of cream is common, but it’s also a treat with a little melted cheese, the edges browned in the pan. Use what you’ve got. Serve the rajma over rice, ideally, but if you’re in a pinch, a side of hot flour tortillas or even buttered toast will make it into a delicious meal.","from_your_kitchen":null,"ingredients":["1 red onion","4 garlic cloves","1 fresh green chile","1 (1-inch) piece fresh ginger, peeled","2 tablespoons neutral oil","¼ teaspoon cumin seeds","1 teaspoon sea salt","1 (28-ounce) can crushed, diced, chopped or whole tomatoes","2 (15-ounce) cans kidney beans, drained","½ teaspoon red chile powder","¼ teaspoon garam masala","½ cup heavy cream or 1 cup diced mozzarella cheese","¼ cup roughly chopped fresh cilantro leaves","1 teaspoon granulated sugar","1 teaspoon kosher salt","¼ cup white wine vinegar"],"ingredient_groups":[{"at":13,"title":"FOR THE PICKLE"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 350 degrees. Quarter the onion, then thinly slice one portion. Set aside sliced onion. Add the remaining onion to a food processor, along with the garlic, chile and ginger. Purée until fairly smooth, scraping down the sides of the bowl as needed."},{"n":2,"title":null,"text":"In a large, deep ovenproof skillet, heat the oil over medium. Add the cumin seeds and cook until lightly toasted, about 30 seconds. Add the onion mixture and salt, and cook, stirring occasionally, until the excess liquid has evaporated and the mixture is just starting to take on a golden color, 8 to 10 minutes."},{"n":3,"title":null,"text":"While the mixture cooks, purée the canned tomatoes and their juices, if using diced, chopped or whole tomatoes."},{"n":4,"title":null,"text":"Add the beans and chile powder to the onion mixture, and mix well. Use a fork to mash a tablespoon or so of the beans against the side of the skillet to help thicken the sauce."},{"n":5,"title":null,"text":"Add the crushed or puréed tomatoes and garam masala to the beans, and mix well. Drizzle the top with cream or scatter with cheese, then slide into the oven and bake, uncovered, until the sauce has thickened and the top is lightly browned, 30 to 40 minutes."},{"n":6,"title":null,"text":"Prepare the pickle: While the beans are baking, bring a small saucepan of water to a boil. Transfer ¼ cup hot water to a small bowl. Stir in the sugar and salt until dissolved. Add the reserved onion slices to the boiling water in the saucepan, turn off the heat and, after 1 minute, drain the onion. Transfer the softened onion to the small bowl and stir in the vinegar."},{"n":7,"title":null,"text":"When the beans are ready, fish out the pickled onion slices and arrange on top, letting a few drops of the pickling liquid flick over the beans to season them. Garnish with cilantro and serve with hot rice, buttered toast or flour tortillas."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["kidney beans","tomato"],"item_tags":["cilantro","cream","cumin","garam masala","ginger"],"course_tags":["Dinner"],"keywords":["Beans","Canned Tomato","Cilantro","Dinner","Ginger","Indian","Kidney Bean","Main Course","One Pot","Onion","Vegetables"],"issues":null,"front":"nyt_1021035.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021035-baked-rajma-punjabi-style-red-beans-with-cream","rating":{"value":5,"count":2536},"date":"2020-05-03"},{"pair":1019980,"title":"Pasta With Brown Butter and Parmesan","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"786","fat":"37 g","carbohydrates":"82 g","protein":"30 g"},"description":"Sometimes you just want a big bowl of pasta with butter and Parmesan. Starchy, silky and salty, it’s always good — and practically foolproof. To make it a little more grown up, just take it one step further: Brown the butter. When you slide the butter into the skillet, let it cook until the milk solids turn a toasty brown. It adds a rich, nutty flavor that makes the dish a bit more sophisticated with very little extra work.","from_your_kitchen":null,"ingredients":["Kosher salt","1 pound spaghetti, linguine or other long noodle","8 tablespoons unsalted butter","1 cup freshly grated Parmesan, plus more for serving","Freshly ground black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of heavily salted water (2 heaping tablespoons kosher salt to about 7 quarts water) to a boil. Add pasta to boiling water and cook according to package directions until al dente. Reserve ½ cup of the pasta cooking water, then drain the pasta, but don’t shake it fully dry."},{"n":2,"title":null,"text":"In a skillet or Dutch oven large enough to hold the pasta (and preferably with a light-colored bottom so you can see the butter solids brown), melt the butter over medium heat. Cook, swirling occasionally, until the foam subsides, the milk solids turn golden-brown and it smells nutty and toasty, 3 to 4 minutes. (Watch carefully to see that it does not burn. If it does, start over.) Remove from heat immediately."},{"n":3,"title":null,"text":"Add the cooked pasta to the skillet and toss with the brown butter. Stir in the cheese until melted. Stir in pasta water, 1 tablespoon at a time, until the pasta is glossy with sauce (you probably won’t need the full ½ cup)."},{"n":4,"title":null,"text":"Serve with black pepper and more Parmesan on top."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["pasta"],"item_tags":["brown butter","parmesan"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Brown Butter","Budget","Butter","Easy","Five Ingredient","Italian","Kid-Friendly","Main Course","Parmesan","Pasta","Pastas","Quick","Side Dish","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019980.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019980-pasta-with-brown-butter-and-parmesan","rating":{"value":4,"count":2640},"date":"2019-02-04"},{"pair":1020959,"title":"Crispy Potato Kugel","subtitle":null,"author":"Alison Roman","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"1 hour 20 minutes","nutrition":{"calories":"291","fat":"17 g","carbohydrates":"29 g","protein":"7 g"},"description":"At its core, kugel is a casserole. It comes in both savory and sweet varieties, often made with egg noodles and vaguely sweetened. This version, made with potatoes, is decidedly salty and savory, with onions in the mixture and chives to finish. It can best be described as something between a Spanish tortilla and a giant latke; the potatoes are shredded, not sliced, there are eggs but no flour, and it’s got crispy edges and a creamy interior. Sounds dreamy, doesn’t it? The most annoying parts of this kugel are also the most important: grating the potatoes (I use a box grater, but you can use a food processor with the shredding blade) and wringing out their moisture. For that, I use my hands and a colander or strainer to save a kitchen towel or a cheesecloth, but you can use those, if you like. Traditionally made in a casserole-style baking dish, this kugel starts off in a cast-iron skillet, but a stainless-steel skillet would do the job, and honestly so would a baking dish, just know you may be sacrificing that crunchy underside.","from_your_kitchen":null,"ingredients":["4 pounds russet potatoes (about 5 to 7 potatoes), peeled","1 large yellow onion","6 large eggs","10 tablespoons chicken fat, melted, or use vegetable oil","Kosher salt and freshly ground black pepper","⅓ cup finely chopped chives, for serving","Flaky sea salt, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Using a box grater or the shredding attachment on the food processor, grate the potatoes and onion into a colander fitted inside a large bowl (or in the sink)."},{"n":2,"title":null,"text":"Using your hands and working with a bit at a time, squeeze as much water from the potatoes and onions as humanly possible and transfer the dry potatoes to a large bowl (you can use that same bowl, just make sure it’s drained and dry). For added insurance, you can also do this with cheesecloth or a porous kitchen towel, if you like."},{"n":3,"title":null,"text":"Add eggs and 6 tablespoons chicken fat to the potatoes, and season with salt and plenty of pepper, mixing well. Heat another 2 tablespoons fat in a 9- or 10-inch cast-iron skillet over medium-high. (This recipe will work in a 9- or 10-inch skillet, but the kugel will be slightly taller in a 9-inch.) Delicately place the potato mixture into the skillet, taking care not to pack it in tightly. (You want to keep the kugel light and airy.)"},{"n":4,"title":null,"text":"Cook the potatoes, rotating the skillet occasionally to promote even browning, until it’s golden brown on the edges and up the sides, 10 to 12 minutes."},{"n":5,"title":null,"text":"Drizzle the top of the potatoes with the remaining 2 tablespoons fat and place in the oven. Bake until the top of the kugel is deeply golden brown, the edges are wispy and crispy, and the potatoes are completely and totally tender and cooked through, 45 to 50 minutes."},{"n":6,"title":null,"text":"Remove from oven and top with more pepper, chives and flaky sea salt. Slice and serve warm."}],"tips":["If you don’t have chicken fat and are not keeping kosher, melted butter is great substitute, otherwise, olive oil or a neutral oil like grapeseed or canola will do the trick. But given the limited ingredient list on this recipe, you really do need the rest (potatoes, onion, egg)."],"cuisine_tags":["Jewish"],"ingredient_tags":["eggs","potato"],"item_tags":["chives"],"course_tags":["Sides & Appetizers"],"keywords":["Bake","Egg","Five Ingredient","Jewish","Passover","Potato","Side Dish","Vegetables"],"issues":null,"front":"nyt_1020959.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020959-crispy-potato-kugel","rating":{"value":4,"count":1930},"date":"2020-04-01"},{"pair":1012387,"title":"Panini With Artichoke Hearts, Spinach and Red Peppers","subtitle":null,"author":"Martha Rose Shulman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"15 minutes","nutrition":{"calories":"418","fat":"22 g","carbohydrates":"41 g","protein":"18 g"},"description":"Here’s a great way to pack a lot of nutrients into a sandwich. If you use frozen artichoke hearts, the panini are quickly assembled.","from_your_kitchen":null,"ingredients":["6 ounces (1 bag) baby spinach","3 tablespoons olive oil","2 garlic cloves, minced","12 ounces frozen or fresh cooked artichoke hearts, sliced","1 teaspoon fresh thyme leaves","Salt, preferably kosher salt","freshly ground pepper","1 large or 2 smaller roasted sweet red peppers, sliced","¼ pound fontina or Gruyère, thinly sliced or grated","8 slices whole grain country bread"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of generously salted water to a boil. Fill a bowl with ice water. Add the spinach to the boiling water and blanch for 10 to 20 seconds. Transfer to the ice water to cool for a few minutes, then drain and squeeze out excess water. Chop coarsely."},{"n":2,"title":null,"text":"Heat 1 tablespoon of the oil in a large, heavy skillet over medium heat, and add the garlic. Cook, stirring, until the garlic is fragrant, about 30 seconds, and stir in the artichoke hearts. Stir for a few minutes, until the artichoke hearts are beginning to color, and add the thyme leaves and the spinach. Toss together and season to taste with salt and pepper. Remove from the heat."},{"n":3,"title":null,"text":"Preheat a panini grill. Top four of the bread slices with the artichoke hearts and spinach. Add strips of roasted pepper, then cheese. Top with the remaining bread and press together. Brush the outside of the bread (top and bottom slices) with olive oil. Place in the panini maker and grill for four to five minutes, until the cheese has melted and the bread is toasty. Slice in half and serve hot."}],"tips":["Advance preparation: You can prepare the artichoke filling through step 2 several hours or even a day ahead of assembling the panini."],"cuisine_tags":["Italian"],"ingredient_tags":["artichoke hearts","roasted red peppers","spinach"],"item_tags":["fontina","gruyere","thyme"],"course_tags":["Dinner"],"keywords":["Artichoke Heart","Boil","Dinner","Easy","Healthy","High Fiber","Italian","Main Course","Quick","Saute","Spinach","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1012387.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1012387-panini-with-artichoke-hearts-spinach-and-red-peppers","rating":{"value":5,"count":441},"date":"2009-04-10"},{"pair":1021176,"title":"Maque Choux","subtitle":null,"author":"Gabrielle Hamilton","servings":null,"yield_text":"About 1 generous quart","yield_count":1,"cook_time":"20 minutes","nutrition":{"calories":"1287","fat":"96 g","carbohydrates":"113 g","protein":"18 g"},"description":"This classic Cajun side dish is a sweet, hot, juicy, milky, buttery combination of corn, onions and peppers. It’s often cooked in rendered bacon fat and enriched with heavy cream, but this version relies upon only butter and a little water in their place, which allow the ingredients’ flavors to sing more clearly. While it is commonly understood that Fat Equals Flavor, there is a point at which too much fat actually masks complexities in flavors and dulls their vibrancy. Try the maque choux this way and see if you notice how bold and lively it tastes. If you miss the smokiness that bacon imparts, try instead a pinch of smoked paprika stirred in at the end.","from_your_kitchen":null,"ingredients":["3 fresh ears of corn, shucked","8 tablespoons unsalted butter (1 stick)","½ red onion, cut into small dice","2 celery ribs, cut into small dice","Kosher salt","1 red bell pepper, cored, seeded and cut into small dice","1 small poblano pepper, cored, seeded and cut into small dice","1 small serrano chile, very thinly sliced","Freshly ground black pepper","Smoked paprika (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Working with 1 corn cob at a time, set the ear of corn upright in a medium bowl. Shave the corn from the cob by slicing down the sides using the tip of a sharp chef’s knife, holding the knife almost vertical. (This gives you neat tablets of corn that land squarely in the bowl and keeps the kernels from scattering all over the counter.) Using the back of the knife, scrape each cob to release all the nibs and the “milk” of the kernels into the bowl. Repeat with remaining ears of corn, then snap the cobs in half, and add them to the bowl."},{"n":2,"title":null,"text":"In a large, deep sauté pan, melt 3 tablespoons butter over medium heat until foaming. Add onion and celery, and season with 1 or 2 pinches of kosher salt. Stir constantly until softened and translucent but not browned, about 5 minutes."},{"n":3,"title":null,"text":"Add 2 tablespoons butter and the bell pepper, poblano and serrano, and stir constantly, adding another pinch of kosher salt, letting the butter melt and the peppers soften and become translucent, about 2 or 3 minutes. You will smell the peppers’ sweetness and their mild capsaicin releasing."},{"n":4,"title":null,"text":"Add the final 3 tablespoons butter and the corn mixture from the bowl, cobs included, and another pinch of kosher salt. Stir constantly to coat with the butter and combine thoroughly."},{"n":5,"title":null,"text":"When everything starts to hiss and sound hot, but isn’t cooking so hard as to take color, add ½ cup water and a healthy few grinds of black pepper, and cover the pan for a couple of minutes to steam/shallow braise the mixture."},{"n":6,"title":null,"text":"Remove the lid, and stir well, noticing the corn releasing its liquid and the kernels softening, and the cobs turning somewhat translucent, if however vague. You will notice a general softening and melding together. Return the lid, and let cook a few more minutes, noticing the water evaporating and the remaining liquid reducing and gaining some “body” and gloss. Discard the corn cobs, but do suck them before tossing — those buttery juices make a nice cook’s treat."},{"n":7,"title":null,"text":"Taste for salt, and serve. It should be sweet, spicy, a bit wet and surprisingly complex, given the few ingredients and their ordinariness. If you want a smoky taste, add a good pinch of smoked paprika."}],"tips":[],"cuisine_tags":["Cajun/Creole"],"ingredient_tags":["bell pepper","celery","corn"],"item_tags":["poblano peppers","serrano chile","smoked paprika"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["American","Bell Pepper","Butter","Celery","Corn","Dinner","Easy","Main Course","Poblano","Quick","Red Onion","Saute","Serrano","Side Dish","Summer","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021176.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021176-maque-choux","rating":{"value":4,"count":822},"date":"2020-06-21"},{"pair":1019928,"title":"Curried Red Lentil Soup With Toasted Coconut","subtitle":null,"author":"Colu Henry","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"320","fat":"11 g","carbohydrates":"45 g","protein":"14 g"},"description":"Fresh ginger along with plenty of earthy spices like turmeric and coriander add complexity to this otherwise unassuming lentil soup. The dish is perfect for a weeknight as the legumes here cook fairly quickly. Pairing the lentils with bold, warming spices gives them a big boost of flavor in a short amount of time. To make the soup feel extra special, toast coconut flakes for a crunchy topping, and put out bowls of roughly chopped cilantro, thinly sliced scallions and lime wedges, so guests can top their soup as they please. If you’re feeling ambitious, a topping of fried shallots seasoned with flaky salt would also be nice.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil, plus more as needed","1 medium red onion, finely chopped","1 medium carrot, finely chopped","Kosher salt and black pepper","2 garlic cloves, finely chopped","1 tablespoon grated ginger","1 tablespoon curry powder","1 teaspoon ground turmeric","1 teaspoon ground coriander","1 cup red lentils","5 cups vegetable stock or water","¼ cup unsweetened coconut flakes","Cilantro, scallions and lime wedges, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat 2 tablespoons olive oil in a large pot over medium heat. Add the onion and the carrot, and cook until they begin to soften, about 3 to 5 minutes. Season with salt and pepper. Stir in the garlic and ginger, and cook 1 minute more, adding a small drizzle of olive oil and lowering the heat if necessary to make sure they don’t burn. Stir in the curry powder, turmeric and ground coriander and cook for about 30 seconds more until fragrant."},{"n":2,"title":null,"text":"Add the lentils and vegetable stock, and bring to a gentle simmer. Cook, stirring occasionally, until the flavors have melded and the lentils are soft and cooked through, about 30 minutes. If you prefer your soup looser, add in ½ to 1 cup more water and cook 1 to 2 minutes longer until heated through."},{"n":3,"title":null,"text":"While the soup simmers, heat a medium skillet over low heat. Toast the coconut flakes, stirring frequently, until they are lightly golden and fragrant, about 3 to 5 minutes. Remove from the heat and set aside."},{"n":4,"title":null,"text":"Taste the soup and adjust seasonings. Serve in bowls and pass the coconut flakes at the table. If desired, serve with bowls of cilantro, scallions and lime wedges at the table."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["carrot","red lentils"],"item_tags":["cilantro","coriander","curry powder","ginger","toasted coconut","turmeric"],"course_tags":["Dinner","Lunch"],"keywords":["Coriander","Curry Powder","Dinner","Easy","Ginger","Great Leftovers","Lunch","Main Course","Quick","Red Lentil","Soup","Turmeric","Vegan Thanksgiving","Weeknight"],"issues":null,"front":"nyt_1019928.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019928-curried-red-lentil-soup-with-toasted-coconut","rating":{"value":5,"count":1409},"date":"2019-01-15"},{"pair":12897,"title":"Fuyu Persimmon Salad","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"About 20 minutes","nutrition":{"calories":"148","fat":"12 g","carbohydrates":"8 g","protein":"4 g"},"description":"The Fuyu persimmon, round and squat and rather tomato-shaped, is the kind you can eat raw. You want to buy the ones that have turned truly orange (if they are greenish-gold, let them ripen for a few days), then peel them and slice them. The flesh is firm but sweet. Eat them plain, in the Japanese fashion, with a pot of tea. Fuyus persimmons make wonderful salads, too.","from_your_kitchen":null,"ingredients":["1 shallot, finely diced","Salt and pepper","2 tablespoons lemon juice","1 tablespoon sherry vinegar","4 tablespoons extra-virgin olive oil","3 Fuyu persimmons","½ cup thinly sliced tender celery stalks and leaves","1 head radicchio, leaves torn into 2-inch wide ribbons","Chunk of Parmesan, for shaving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Make the vinaigrette: put diced shallot in a small bowl with a pinch of salt. Add lemon juice and sherry vinegar and leave to macerate for about 5 minutes. Stir in olive oil. Season with additional salt and pepper to taste."},{"n":2,"title":null,"text":"With a sharp paring knife, remove and discard the leafy calyx at the top of each persimmon. Peel persimmons and cut in half vertically. Lay persimmons flat side down and cut into ½-inch wedges."},{"n":3,"title":null,"text":"Put persimmon wedges and celery slices in a low, wide salad bowl. Season with salt and pepper. Whisk vinaigrette, then pour over persimmon and celery and toss to coat well. Add radicchio and toss lightly."},{"n":4,"title":null,"text":"With a vegetable peeler, shave about 1 ounce of Parmesan in thin strips over salad."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["celery","persimmon","radicchio"],"item_tags":["lemon","parmesan","shallot","sherry vinegar"],"course_tags":["Sides & Appetizers"],"keywords":["American","Celery","Easy","Fall","Persimmon","Quick","Radicchio","Salad","Side Dish","Vegetarian","Weeknight"],"issues":null,"front":"nyt_12897.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12897-fuyu-persimmon-salad","rating":{"value":5,"count":157},"date":"2012-10-31"},{"pair":1020956,"title":"Parsley Salad With Fennel and Horseradish","subtitle":null,"author":"Alison Roman","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"10 minutes","nutrition":null,"description":"I have always been the one at the Seder table to eat the parsley dipped in saltwater with enthusiasm. “You going to finish that?” I might ask my neighbor at the table when I see they have left theirs untouched after just a nibble. This salad is an obvious nod to the Seder plate, including both parsley (karpas) and fresh horseradish (maror, or bitter herbs), except it’s less ceremonial and more just a very delicious salad. I love, love parsley and think a well-seasoned bowl of it is something that most tables can benefit from, especially if those tables include braised pots of red meat. While parsley and fennel can be prepared ahead of time, the salad itself is best dressed right before you eat.","from_your_kitchen":null,"ingredients":["2 fennel bulbs, thinly sliced","1 large bunch parsley, tender stems and leaves","¼ cup fresh lemon juice, plus more to taste","Kosher salt and freshly ground black pepper","Olive oil, for drizzling","Fresh horseradish, for grating"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Toss fennel and parsley together in a medium bowl. Add lemon juice, season with salt and pepper, and toss to coat. Season again with salt, pepper and more lemon juice if you like. (It should be fairly lemony.)"},{"n":2,"title":null,"text":"Drizzle with olive oil, toss to coat and grate a bit of fresh horseradish over everything, gently tossing to distribute the horseradish. (Doing it this way prevents clumping.) Transfer to a serving bowl and grate more horseradish over before serving."}],"tips":["The shaved fennel here provides a bit of bulk and crunch, but, if you can’t find fennel, you could easily use thinly sliced radish, cabbage or celery.","Fresh horseradish is one of those things that’s more available than you think, inexplicably included among the exotic mushrooms and other “specialty produce” at many chain grocery stores. That said, if you can’t find it, feel free to use a dab of prepared horseradish when tossing the fennel, or simply skip it, and be sure to give a few extra grinds of black pepper to compensate for its heat."],"cuisine_tags":["Jewish"],"ingredient_tags":["fennel","parsley"],"item_tags":["horseradish","lemon"],"course_tags":["Sides & Appetizers"],"keywords":["Appetizer","Easy","Fennel","Five Ingredient","Jewish","Lemon Juice","Parsley","Passover","Salad","Side Dish","Vegan","Vegetarian"],"issues":null,"front":"nyt_1020956.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020956-parsley-salad-with-fennel-and-horseradish","rating":{"value":4,"count":372},"date":"2020-04-01"},{"pair":1021250,"title":"Broccoli Salad With Peanuts and Tahini-Lime Dressing","subtitle":null,"author":"Lidey Heuck","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"20 minutes, plus 15 minutes’ marinating","nutrition":{"calories":"225","fat":"17 g","carbohydrates":"15 g","protein":"8 g"},"description":"Broccoli stalks, often overlooked or tossed in favor of the florets, take center-stage in this summer picnic salad. While many broccoli slaws are made with mayonnaise-based dressings, this one is inspired by the bright flavors of Thai cuisine, and uses sesame oil, lime juice, salted peanuts, scallions and a dash of hot sauce for heat. (Garnish the slaw with fresh Thai basil, if you like.) Tossed with a creamy vegan tahini-lime dressing, the broccoli softens just enough to lose that raw broccoli flavor without giving up any of its satisfying crunch. A food processor or Mandoline makes quick work of the stems, but with a little bit of patience, a good knife does the trick, too. Finally, this salad is best the day it’s made, though its components can be prepared in advance to save time.","from_your_kitchen":null,"ingredients":["2 pounds broccoli (see Tip)","¾ cup thinly sliced scallions, white and green parts (3 to 5 scallions)","½ cup lightly salted peanuts, finely chopped","⅓ cup tahini","¼ cup fresh lime juice (from about 2 limes)","¼ cup toasted sesame oil","2 tablespoons soy sauce or tamari","2 teaspoons honey or agave","1 garlic clove, finely grated","A few dashes of hot sauce, plus more to taste","⅓ cup chopped fresh cilantro or mint"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Trim the broccoli stalks and peel them to remove the tough outer layer. Cut off the florets, leaving as much of the stalk as possible intact, and set the florets aside. Using the shredding or julienne blade of a food processor, a mandoline or a sharp knife, julienne the stems and place them in a large bowl."},{"n":2,"title":null,"text":"Finely chop or julienne the florets and add them to the bowl, along with the scallions and peanuts."},{"n":3,"title":null,"text":"In a small bowl or glass measuring cup, combine the tahini, lime juice, sesame oil, soy sauce, honey, garlic and hot sauce and whisk until smooth. Pour the dressing over the vegetables and toss thoroughly to coat. Set aside at room temperature for at least 15 minutes, tossing occasionally, to allow the broccoli to soften slightly."},{"n":4,"title":null,"text":"Just before serving, add the fresh herbs and toss well. (You can refrigerate for up to 8 hours before serving.)"}],"tips":["When shopping, avoid broccoli “crowns.” For this salad, you want plenty of stems, too."],"cuisine_tags":["Thai"],"ingredient_tags":["broccoli","peanuts"],"item_tags":["cilantro","lime","scallions","sesame oil","soy sauce","tahini"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Broccoli","Dinner","Fourth of July","Garlic","Honey","Labor Day","Lunch","Memorial Day","Peanut","Salad","Scallion","Sesame Oil","Side Dish","Soy Sauce","Super Bowl","Tahini","Vegan","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021250.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021250-broccoli-salad-with-peanuts-and-tahini-lime-dressing","rating":{"value":4,"count":2980},"date":"2020-07-17"},{"pair":1013107,"title":"Spicy Orange Salad, Moroccan Style","subtitle":null,"author":"Amanda Hesser","servings":"4","yield_text":"Serves 4","yield_count":4,"cook_time":"10 minutes","nutrition":{"calories":"155","fat":"11 g","carbohydrates":"13 g","protein":"1 g"},"description":"Amanda Hesser","from_your_kitchen":null,"ingredients":["3 large seedless oranges","⅛ teaspoon cayenne","1 teaspoon paprika","½ teaspoon garlic","3 tablespoons olive oil","1 tablespoon red-wine or sherry vinegar","Salt","Freshly ground black pepper","⅓ cup chopped parsley","12 pitted black olives, preferably imported Greek or Italian"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Peel the oranges, paring away all the exterior white pulp. Cut each orange into 8 wedges. Cut each wedge into 1-inch pieces. Set aside."},{"n":2,"title":null,"text":"Place the cayenne, paprika, garlic, olive oil and vinegar in a salad bowl. Add salt and pepper to taste and whisk to combine. Add the oranges, parsley and olives. Toss gently to blend. Serve cold or at room temperature."}],"tips":[],"cuisine_tags":["Moroccan"],"ingredient_tags":["oranges"],"item_tags":["black olives","cayenne","paprika","parsley","sherry vinegar"],"course_tags":["Sides & Appetizers"],"keywords":["Easy","Gluten-Free","Moroccan","Olive","Orange","Quick","Salad","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1013107.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013107-spicy-orange-salad-moroccan-style","rating":{"value":5,"count":214},"date":"2010-04-11"},{"pair":1020144,"title":"Kale and Quinoa Salad With Tofu and Miso","subtitle":null,"author":"Corinne Trang","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"30 minutes","nutrition":{"calories":"439","fat":"29 g","carbohydrates":"34 g","protein":"14 g"},"description":"A hearty base of kale, quinoa and crisp tofu give this easy salad enough bite to serve as a meal. Curly kale provides heft and holds up nicely to the sweet, sour and spicy dressing. Use your hands to massage the vinaigrette into the kale, and let it marinate for at least 10 minutes to tenderize the sturdy greens. Finish the dish with a drizzle of sriracha and honey, but use a light touch: The point is to balance the heat and sweetness levels without overwhelming the delicate miso vinaigrette. If you like, double the dressing and refrigerate it for future use; it makes a fantastic dip for grilled chicken or pork, or a glaze to brush on salmon before broiling.","from_your_kitchen":null,"ingredients":["½ cup quinoa, rinsed and drained","2 tablespoons unseasoned rice vinegar","1 ½ tablespoons white miso","1 tablespoon mirin","2 teaspoons toasted sesame oil","6 tablespoons grapeseed oil","½ teaspoon sriracha, plus more for drizzling","1 (1-inch) piece fresh ginger, peeled and finely julienned or grated","1 small bunch curly kale, ribs removed, leaves chopped (about 4 packed cups)","1 (14-ounce) package extra-firm tofu, drained and cut into ¾-inch cubes","Honey or maple syrup, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a small saucepan, combine the quinoa with ¾ cup water. Bring to a boil over high heat, then cover and cook over medium-low until the water is absorbed, 10 to 12 minutes. Turn off the heat and let sit for 10 minutes. Fluff it with a fork."},{"n":2,"title":null,"text":"Meanwhile, in a large bowl, whisk together the vinegar, miso, mirin, sesame oil, 2 tablespoons grapeseed oil and ½ teaspoon sriracha. Stir in the ginger."},{"n":3,"title":null,"text":"Add the kale, massage it with the dressing and set aside to marinate. Spoon the cooked quinoa onto the kale and toss to coat."},{"n":4,"title":null,"text":"In a nonstick skillet, heat the remaining 4 tablespoons grapeseed oil over medium. When the oil shimmers, cook the tofu, turning occasionally, until crisp on all sides, about 15 minutes. Transfer to a paper towel-lined plate to absorb any excess oil, then scatter it over the kale salad. Drizzle lightly with sriracha and honey and serve immediately."}],"tips":[],"cuisine_tags":["Fusion","Japanese"],"ingredient_tags":["kale","quinoa","tofu"],"item_tags":["ginger","miso","rice vinegar","sesame oil","sriracha"],"course_tags":["Dinner","Lunch"],"keywords":["American","Dinner","Easy","Fall","Kale","Lunch","Main Course","Mirin","Miso","Quick","Quinoa","Rice Vinegar","Salad","Spring","Summer","Tofu","Vegetables","Weeknight","Winter"],"issues":null,"front":"nyt_1020144.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020144-kale-and-quinoa-salad-with-tofu-and-miso","rating":{"value":5,"count":3017},"date":"2019-04-02"},{"pair":1013264,"title":"Stir-Fried Sweet Potatoes","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"252","fat":"10 g","carbohydrates":"38 g","protein":"4 g"},"description":"In a 2010 love letter to the food processor, Mark Bittman gave the machine the ultimate compliment: “I upgraded its position in my kitchen from a cabinet to a spot on my itsy-bitsy counter,” he wrote. Here, he uses the machine to chop and grate vegetables, cutting down on prep time (and any possibility of shredding your knuckles on a box grater). The end result is a quick side dish, full of flavor from the ginger and soy sauce.","from_your_kitchen":null,"ingredients":["4 scallions, trimmed and cut into 1-inch pieces","2 garlic cloves","1 piece fresh ginger (1-inch long), peeled","1 small fresh hot chili (like jalapeño or Thai), stem and seeds removed","1 ½ pounds sweet potatoes, peeled and cut into 1- to 2-inch chunks","3 tablespoons peanut oil","Salt","Freshly ground black pepper","1 tablespoon soy sauce, more for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put scallions in food processor and pulse until finely chopped; remove. Add garlic, ginger and chili to the processor and pulse until minced; remove. Fit the processor with grating blade and grate sweet potatoes."},{"n":2,"title":null,"text":"Put oil in a large nonstick or well-seasoned cast-iron skillet over medium-high heat. When hot, add garlic-ginger-chili mixture and fry for 30 seconds. Add half the scallions and all the potatoes and sprinkle with salt and pepper. Cook, stirring or tossing, until the potatoes are lightly browned, about 10 minutes; the potatoes need not be fully tender."},{"n":3,"title":null,"text":"Add soy sauce, toss once, and transfer potatoes to serving platter. Garnish with remaining scallions and serve immediately with additional soy sauce, if desired."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["sweet potato"],"item_tags":["ginger","scallions","tamari"],"course_tags":["Sides & Appetizers"],"keywords":["Asian","Easy","Fall","Quick","Side Dish","Stir-Fry","Sweet Potato","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1013264.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013264-stir-fried-sweet-potatoes","rating":{"value":5,"count":891},"date":"2010-09-15"},{"pair":1016092,"title":"Farro Salad With Beets, Greens and Feta","subtitle":null,"author":"Martha Rose Shulman","servings":"8","yield_text":"8 servings","yield_count":8,"cook_time":"1 hour and 10 minutes","nutrition":{"calories":"270","fat":"20 g","carbohydrates":"18 g","protein":"6 g"},"description":"Farro is a sturdy grain that stands up well to formidable ingredients like beets, their greens and salty feta cheese. That hardiness and versatility, as well as its sweet, nutty flavor, have made farro a popular option for filling out a salad in order to create a main dish. If you’re in doubt, sliced or shredded poached or roasted chicken would make a nice addition. Either way the farro absorbs color from the red beets, giving the dish a pinkish tint that only deepens as hours pass. (In fact, you can make the dish up to a day ahead. And it travels well, making it fine picnic fare.) Soak the grains for an hour before cooking, and be sure to cook until tender, or else the salad will be chewy.","from_your_kitchen":null,"ingredients":["2 medium or 3 small beets (any color) with greens, the beets roasted, the greens stemmed and washed in two changes of water","1 cup farro, soaked for one hour in water to cover and drained","Salt, preferably kosher salt, to taste","2 tablespoons sherry vinegar","1 teaspoon balsamic vinegar","1 small garlic clove, minced or pureed","1 teaspoon Dijon mustard","½ cup extra virgin olive oil (may substitute 1 to 2 tablespoons walnut oil for 1 to 2 tablespoons olive oil)","½ cup broken walnut pieces","2 ounces feta or goat cheese, crumbled (more if desired for garnish)","¼ cup chopped fresh herbs, such as parsley, tarragon, marjoram, chives, mint"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring 2 quarts water to a boil in a medium saucepan. Fill a bowl with ice water. When the water comes to a boil, add salt to taste and the greens. Blanch for two minutes, and transfer to the ice water. Allow to cool for a few minutes, then drain and squeeze out excess water. Chop coarsely and set aside."},{"n":2,"title":null,"text":"Bring the water back to a boil, and add the farro. Reduce the heat, cover and simmer 45 minutes, stirring from time to time, or until the farro is tender. Remove from the heat and allow the grains to swell in the cooking water for 10 minutes, then drain."},{"n":3,"title":null,"text":"While the farro is cooking, make the vinaigrette. Whisk together the vinegars, salt, garlic and mustard. Whisk in the oil(s). Add to the farro. Peel and dice the beets and add, along with the beet greens, feta or goat cheese, herbs and walnuts. Toss together, and serve warm or room temperature with a little more cheese sprinkled over the top if you wish."}],"tips":["The roasted beets and cooked beet greens will keep for three or four days in the refrigerator, and the cooked farro for five days. You can assemble this salad hours or even a day ahead; it will redden with time."],"cuisine_tags":["Mediterranean"],"ingredient_tags":["beets","farro"],"item_tags":["dijon mustard","feta","sherry vinegar","walnuts"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Healthy","Main Course","Side Dish","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1016092.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016092-farro-salad-with-beets-greens-and-feta","rating":{"value":5,"count":1650},"date":"2009-03-27"},{"pair":1021395,"title":"Tian","subtitle":null,"author":"Gabrielle Hamilton","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour, plus resting","nutrition":{"calories":"212","fat":"14 g","carbohydrates":"24 g","protein":"4 g"},"description":"The tian is both a vessel and the name of what’s cooked in it: summer vegetables, sliced quite thin, arranged in careful layers, drenched in quality olive oil and then cooked in a slow oven until each individual vegetable surrenders to the others, becoming one. The true and complete melding of earthy zucchini, sweet onion, waxy potato, juicy and acidic tomatoes is the great achievement of a well-made tian, and resting the finished dish after cooking is no small part of that success. By using a cast-iron pan and starting on the stovetop during the build, covering with a lid along the way, you speed up the cooking significantly. Season every layer and generously drizzle each with olive oil to bring out tremendous flavor and aroma. The Sungold tomatoes are beautiful and bright and quite acidic — perfect against the other flavors — but I find the skins unpleasantly leathery-papery when they are cooked, so simply peel them first. Dropping the tomatoes for 30 seconds into seasoned boiling water splits their skins readily and they slip off effortlessly. I would even say it’s kind of fun.","from_your_kitchen":null,"ingredients":["2 tablespoons unsalted butter","3 medium Yukon Gold potatoes (about 12 ounces)","Kosher salt and freshly ground black pepper","¼ cup extra-virgin olive oil","1 large yellow onion (about 12 ounces)","2 zucchini (about 12 ounces), washed and wiped free of any clinging grit","1 pint yellow Sungold cherry tomatoes","⅓ cup coarse bread crumbs"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a pot, boil 2 inches of water for blanching tomatoes. Place an 8- or 9-inch cast-iron skillet on a burner over low heat, and add butter to melt."},{"n":2,"title":null,"text":"Peel the potatoes, and slice on a Japanese mandoline into ¼-inch-thick disks, then arrange in a single layer circle covering the bottom of the cast-iron skillet with its melted butter, keeping the skillet on the burner and leaving the heat on while you start to build the tian."},{"n":3,"title":null,"text":"Add a second layer of potato slices, and season with salt and pepper, add a drizzle of olive oil and cover with a lid to slightly steam while you slice the yellow onion."},{"n":4,"title":null,"text":"Peel the onion, then slice into even ¼-inch or thinner rounds. The Japanese mandoline is sometimes too narrow to use for this, so you may have to use a sharp knife and do it manually."},{"n":5,"title":null,"text":"Layer abundantly half the onion rings evenly around the pan on top of the steamed potatoes, season with salt and pepper and a drizzle of olive oil, and recover the pan with a lid while you slice the zucchini."},{"n":6,"title":null,"text":"Slice the zucchini into ¼-inch-thick rounds, and layer half of them in concentric, just-overlapping shingled circles over the onions to create a neat layer. Season with salt and pepper, drizzle with oil and recover with the lid while you blanch the tomatoes."},{"n":7,"title":null,"text":"Season the now-boiling water with a few good pinches of salt, and drop the tomatoes into the boiling water. As soon as their skins split — about 30 seconds — retrieve the tomatoes and run under cold water to quickly cool enough to handle; set aside."},{"n":8,"title":null,"text":"Build another ring of potato around the tian on top of the now-steaming zucchini, this time just a single layer. Drizzle with oil, season with salt and pepper and recover with the lid to steam a bit while you slip the skins off the tomatoes."},{"n":9,"title":null,"text":"Layer the other half of the onions as before, season and drizzle and replace the lid as before, while you split the tomatoes in half horizontally with a small sharp knife."},{"n":10,"title":null,"text":"Add final layer of zucchini to the tian, and season with salt and pepper and a drizzle of olive oil. Cover, and let steam while you heat the oven to 375 degrees."},{"n":11,"title":null,"text":"Place the tomatoes around the top of the tian evenly, and sprinkle the bread crumbs over the top evenly. Drizzle with oil, season with salt and pepper and place in the oven to bake for 30 minutes. (If your skillet threatens to bubble over, slip a sheet pan underneath to prevent any burned wreckage in the bottom of your oven.)"},{"n":12,"title":null,"text":"With a spoon, baste, and drizzle the pan juices that accumulate in the tian over the top when you remove it from the oven at the end. Allow the tian to cool, settle and kind of meld for an hour before eating."}],"tips":[],"cuisine_tags":["French","Mediterranean"],"ingredient_tags":["potato","tomato","zucchini"],"item_tags":["bread crumbs"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["American","Bread Crumb","Cherry Tomato","Dinner","Lunch","Main Course","Onion","Potato","Side Dish","Summer","Vegetables","Vegetarian","Zucchini"],"issues":null,"front":"nyt_1021395.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021395-tian","rating":{"value":4,"count":1572},"date":"2020-08-30"},{"pair":1019558,"title":"Kimchi Rice Porridge","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"483","fat":"11 g","carbohydrates":"81 g","protein":"13 g"},"description":"A combination of pungent chopped kimchi, toasted scallions and ginger, and rice that's been bolstered with a hit of kimchi brine, this porridge is fiery and sinus-clearing. The rice isn’t perfectly fluffy; instead, leftover rice simmers until it breaks down from kernel to stew. (You can, of course, use raw rice, too: Cook it in Step 2 for about an hour, partly covered and stirring occasionally.) You'll want to cook the scallions and ginger until nearly burned, and top the whole thing with a fried egg (or make it soft-boiled). Take note that most kimchi gets its funk from shrimp, anchovies and-or fish sauce, so if you’d like to make this dish vegetarian, make sure to use a vegetarian kimchi.","from_your_kitchen":null,"ingredients":["1 tablespoon vegetable oil","6 scallions (about 1 bunch), white and pale green parts roughly chopped, plus more for garnish","2 tablespoons peeled and finely minced ginger","½ cup chopped kimchi, plus 1 tablespoon kimchi brine","2 cups cooked long- or short-grain rice","Kosher salt, to taste","4 eggs, for serving","Toasted sesame oil, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a saucepan, heat the oil over medium-high heat. Once shimmering, add the scallions and ginger and sauté until soft and toasted in spots, about 2 minutes."},{"n":2,"title":null,"text":"Add the kimchi, the rice, and 3 cups of water. Bring to a boil, then reduce heat and simmer, adding more water if necessary, until the rice is broken down and the porridge is the desired consistency (some like their porridge soupy, others thicker with most of the liquid absorbed), 15 to 20 minutes."},{"n":3,"title":null,"text":"Turn off the heat and stir in the kimchi brine. Season with salt and more kimchi brine to taste."},{"n":4,"title":null,"text":"To serve, fry eggs to your liking. Top each bowl of porridge with an egg, chopped scallions and a drizzle of sesame oil."}],"tips":["Make porridge up to three days in advance. Reheat over a low heat on the stove, covered. Add more water to return to desired consistency."],"cuisine_tags":["Korean"],"ingredient_tags":["kimchi","rice"],"item_tags":["ginger","scallions","sesame oil"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Breakfast","Brunch","Dinner","Ginger","Kimchi","Korean","Lunch","Main Course","Porridge","Scallion","Sesame Oil","Weeknight"],"issues":null,"front":"nyt_1019558.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019558-kimchi-rice-porridge","rating":{"value":4,"count":319},"date":"2018-09-10"},{"pair":1019816,"title":"Vegetarian ‘Carbonara’ With Spinach","subtitle":null,"author":"Kay Chun","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"719","fat":"25 g","carbohydrates":"96 g","protein":"28 g"},"description":"This spinach-laden carbonara deviates from the standard by nixing two of its leading ingredients: custardy egg yolks, which create its silky texture, and cured meat, which delivers its salty punch. This egg-free version uses a combination of butter and starchy pasta cooking water to give the sauce body. A sprinkle of grated smoked Provolone or Gouda adds a bit of the earthy flavor that traditionally comes from guanciale or pancetta. The final coup? Adding greens: One entire pound of baby spinach may look like a gargantuan amount, but it wilts right into the pasta. Most importantly, don’t be shy with the black pepper: It adds a necessary dose of spice and heat.","from_your_kitchen":null,"ingredients":["3 tablespoons extra-virgin olive oil","1 cup finely chopped onion","5 cloves garlic, thinly sliced","1 pound spaghetti","Salt and pepper","2 tablespoons unsalted butter","1 pound fresh baby spinach","Red-pepper flakes, to taste (optional)","¾ cup grated Parmesan (2 ½ ounces)","1 tablespoon fresh lemon juice","½ cup grated smoked Provolone or Gouda (1 ½ ounces)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil in a large nonstick skillet over medium heat. Add the onion and garlic and cook, stirring occasionally, until light golden, about 5 minutes."},{"n":2,"title":null,"text":"Meanwhile, cook the pasta in a pot of salted boiling water until al dente. Reserve 2 cups cooking water and drain the pasta. Return the pasta and reserved cooking water to the pot and heat over low. Add the butter and onion-garlic mixture and cook, stirring constantly, until most of the liquid is absorbed and sauce is slightly thickened, 3 to 5 minutes. Add the spinach, season with salt, plenty of pepper and red-pepper flakes, if using, and stir until spinach is wilted. Stir in the Parmesan and lemon juice; season with salt and pepper."},{"n":3,"title":null,"text":"Divide the pasta among 4 bowls and top each with 2 tablespoons smoked cheese. Finish with more black pepper, if desired."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["pasta","spinach"],"item_tags":["lemon","parmesan","red chile flakes"],"course_tags":["Dinner"],"keywords":["American","Boil","Dinner","Easy","Italian","Kid-Friendly","Main Course","Parmesan","Pastas","Provolone","Quick","Saute","Simmer","Spaghetti","Spinach"],"issues":null,"front":"nyt_1019816.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019816-vegetarian-carbonara-with-spinach","rating":{"value":4,"count":1906},"date":"2018-12-05"},{"pair":1021319,"title":"Chile-Oil Noodles With Cilantro","subtitle":null,"author":"Judy Kim","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"468","fat":"11 g","carbohydrates":"78 g","protein":"14 g"},"description":"In this 20-minute recipe, a mixture of savory condiments coats bowlfuls of wide noodles chilled slightly by a quick rinse in cool water. While you cook the udon, take the time to prepare the sauce, abundant with contrasting flavors, and the fresh herbs. The sauce can be made in advance, but make sure it’s at room temperature before tossing it with the noodles and the cilantro at the last minute. Substitutions are welcome: Swap in chile crisp in place of the chile oil with crunchy garlic, or scallions in place of garlic chives. Sichuan chile oil brings a citrusy flavor that is hard to replicate, so don’t skip it. It can vary in spice level: For a milder sauce, use only the liquid oil, or add Sichuan peppercorns from the bottom of the oil for extra tingle. Fried shallots are here for texture, but omit them if you use chile crisp.","from_your_kitchen":null,"ingredients":["14 ounces dried udon noodles","¼ cup chile oil with crunchy garlic","2 tablespoons pure sesame oil","2 teaspoons Sichuan chile oil, or to taste","2 teaspoons soy sauce","½ cup finely sliced garlic chives or scallions, plus more for garnish","2 tablespoons store-bought fried shallots, crumbled by hand (optional)","½ cup finely chopped cilantro (see Note), plus a few sprigs for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of water to boil and cook noodles according to package instructions, stirring from time to time to prevent them from sticking. Drain well in a colander, then run noodles under cold water until cooled."},{"n":2,"title":null,"text":"Meanwhile, in a large bowl, combine all three oils with the soy sauce and ½ cup garlic chives."},{"n":3,"title":null,"text":"Toss cooled noodles into the chile oil mixture. Gently fold in the crumbled fried shallots and chopped cilantro. Divide among four bowls, and top with more garlic chives and cilantro sprigs."}],"tips":["For crisp cilantro, place leaves and stems in an ice water bath until the leaves are firm. Drain and spin in a salad spinner. Store cilantro in the spinner and refrigerate until ready to use."],"cuisine_tags":["Chinese"],"ingredient_tags":["udon"],"item_tags":["chili crisp","cilantro","scallions","sesame oil"],"course_tags":["Dinner","Lunch"],"keywords":["Boil","Chile Crisp","Chile Oil","Cilantro","Dinner","Easy","Lunch","Main Course","Noodles","Quick","Sesame Oil","Udon Noodle","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021319.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021319-chile-oil-noodles-with-cilantro","rating":{"value":4,"count":3407},"date":"2022-09-25"},{"pair":1019453,"title":"Silky Eggplant With Almond Salsa and Yogurt","subtitle":null,"author":"Sarah Jampel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"About 50 minutes","nutrition":{"calories":"667","fat":"48 g","carbohydrates":"45 g","protein":"22 g"},"description":"Eggplant that’s silky-soft and bubbly-brown all over (rather than tough, oily or fossil-like) is a revelation — and, with just a little maneuvering, it’s not that hard. You’ll want to sear the eggplant slices in hot oil, cover them for a minute or two, until they’re soft, and then add a touch more oil until they’re beautifully golden. You could, of course, eat these rounds on their own (and you might!), but spicy almond salsa, cubes of salty, crispy halloumi, and a bed of garlicky yogurt make them a full meal (especially if have warmed pita for swiping everything up). While salting the eggplant slices before you cook isn’t completely necessary, it will help draw out some of the vegetable’s moisture, making it less prone to bitterness and oil saturation.","from_your_kitchen":null,"ingredients":["3 small or 2 medium Italian eggplant (about 24 ounces total)","Kosher salt","½ cup plain, full-fat Greek yogurt","Juice of ½ lemon, plus more for serving","2 garlic cloves, 1 smashed and 1 minced","1 teaspoon plus ¼ to ½ cup olive oil","2 heaping tablespoons torn or roughly chopped mint","Black pepper","⅔ cup roughly chopped almonds","3 tablespoons red-wine vinegar","1 Fresno or Serrano pepper, minced","8 ounces halloumi cheese, cut into 1-inch cubes","Pita bread, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Line a colander with paper towels or a clean dishcloth. Slice the eggplant into ¾- to 1-inch rounds, place in the colander and sprinkle with salt. Set aside for 20 to 30 minutes, until water beads on top of the eggplant."},{"n":2,"title":null,"text":"Meanwhile, make the yogurt sauce: In a medium bowl, mix the yogurt with the lemon juice, smashed garlic clove, 1 teaspoon olive oil and 1 tablespoon of the torn mint. Season with salt and pepper to taste and set aside."},{"n":3,"title":null,"text":"In a heavy pan with high sides over medium heat, toast the chopped almonds until golden brown and fragrant, 4 to 6 minutes, stirring occasionally to avoid burning. Remove pan from the heat and transfer nuts to a medium bowl, then add the red-wine vinegar, 1 tablespoon olive oil, minced garlic clove and Fresno pepper. Mix and season with salt to taste."},{"n":4,"title":null,"text":"Set up a plate or cutting board lined with paper towels next to the stove. Wipe out the pan you were working with and heat 2 tablespoons of olive oil over medium-high heat until hot. Blot the moisture from the eggplant, and when the oil is hot, add the slices in a single layer (you’ll probably have to work in batches). Cook until brown, then flip, about 3 to 4 minutes per side. While browning, as the eggplant is getting dry, add 1 to 2 teaspoons of olive oil and cover the pan for 1 to 2 minutes. The eggplant will be fork-tender and golden brown on both sides when finished. Transfer to the paper towel-lined surface and sprinkle with salt."},{"n":5,"title":null,"text":"When you’ve finished cooking the eggplant, add the cubed cheese to the hot pan, leaving any residual oil (add a teaspoon of olive oil if there’s not enough left in the pan). Sauté, stirring frequently, until brown and crisp all over. Remove pan from the heat."},{"n":6,"title":null,"text":"Spread the yogurt on a platter. Arrange the eggplant and halloumi on top, then scatter with almond salsa. Garnish with remaining torn mint, then sprinkle with any leftover lemon juice and season with salt and pepper. Serve with pita."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["almonds","eggplant","halloumi"],"item_tags":["lemon","mint","yogurt"],"course_tags":["Dinner","Lunch"],"keywords":["Almond","Dinner","Eggplant","Fry","Halloumi","Lunch","Main Course","Summer","Vegetables","Vegetarian","Yogurt"],"issues":null,"front":"nyt_1019453.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019453-silky-eggplant-with-almond-salsa-and-yogurt","rating":{"value":4,"count":340},"date":"2018-08-03"},{"pair":1020107,"title":"French Onion Grilled Cheese","subtitle":null,"author":"Ali Slagle","servings":"2","yield_text":"2 servings","yield_count":2,"cook_time":"45 minutes","nutrition":{"calories":"680","fat":"44 g","carbohydrates":"46 g","protein":"25 g"},"description":"Grilled cheese is a near-perfect food on its own, but adding bacon, kimchi or, in this case, heaps of caramelized onions really makes it special. Caramelizing onions takes a good half-hour, so save this recipe for when you have a little extra time and company (this recipe serves two). If time permits, you could even prep them ahead in a slow cooker. Rather than layer the grated Gruyère and the warm caramelized onions in the sandwich, you should stir them together before assembling, which guarantees that the cheese will melt evenly throughout and that each bite will contain the perfect ratio of fragrant cheese to jammy onions. A splash of sherry, red-wine or white-wine vinegar added to the onions balances out the buttery flavors, but a side salad dressed with a tangy mustard vinaigrette would do the trick, too. (Watch the video of Ali Slagle making French onion grilled cheese here.)","from_your_kitchen":null,"ingredients":["4 tablespoons unsalted butter","1 pound yellow or Vidalia onions, peeled, halved and thinly sliced","Kosher salt and black pepper","2 teaspoons sherry, red-wine or white-wine vinegar (optional)","4 ounces Gruyère cheese, grated","4 slices bread, cut no wider than ½-inch thick"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large skillet over medium-high heat, melt 2 tablespoons butter. Add the onions and season with salt and pepper. Cover and cook, stirring once or twice, until the onions are softened, 3 to 5 minutes. Uncover, reduce the heat to medium-low, and cook, stirring occasionally, until deep golden brown, 20 to 25 minutes. If the onions look dry or like they might burn, add a few tablespoons of water at a time, scraping up any browned bits that are stuck to the bottom of the skillet. If desired, once the onions are done, deglaze the skillet with vinegar and cook until the liquid has evaporated, about 1 minute. Transfer the onions to a medium bowl and season to taste with salt and pepper. Wipe out the skillet, or wash it, if necessary."},{"n":2,"title":null,"text":"Add the cheese to the onions and stir to combine. Put down two slices of bread, and scoop half of the cheese-onion mixture onto each one. Top with the remaining slices of bread, and press down gently."},{"n":3,"title":null,"text":"In the skillet, melt 1 tablespoon butter over medium heat. Add the sandwiches and cook until the bottoms turn golden brown, 3 to 4 minutes, reducing the heat to prevent toast from darkening too quickly, if needed. Add the remaining 1 tablespoon butter, flip the sandwiches, press down and cook until the cheese has fully melted and the bottoms turn golden brown, 3 to 4 minutes. Serve immediately."}],"tips":[],"cuisine_tags":["American","French"],"ingredient_tags":["onion"],"item_tags":["gruyere","red wine vinegar"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["American","Brunch","Butter","Dinner","Gruyère","Lunch","Onion","Sandwiches"],"issues":null,"front":"nyt_1020107.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020107-french-onion-grilled-cheese","rating":{"value":5,"count":5183},"date":"2019-03-21"},{"pair":1014102,"title":"Lavash Pizza With Tomatoes, Mozzarella and Goat Cheese","subtitle":null,"author":"Martha Rose Shulman","servings":"2","yield_text":"Serves two","yield_count":2,"cook_time":"20 minutes","nutrition":{"calories":"277","fat":"19 g","carbohydrates":"13 g","protein":"14 g"},"description":"This pizza, made with the Iranian flatbread called lavash, is utterly simple to throw together, and I love the way the flavor of the tomatoes intensifies during their short time in the oven. Assemble the pizza just before baking.","from_your_kitchen":null,"ingredients":["1 9-by-12-inch piece of lavash","½ cup, tightly packed, grated or shredded fresh mozzarella (2 ounces)","2 plum tomatoes, sliced","¼ red onion, sliced (optional)","½ cup crumbled goat cheese (2 ounces)","1 to 2 teaspoons fresh thyme","Salt","Freshly ground black pepper","1 tablespoon extra-virgin olive oil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 375 degrees, preferably with a pizza stone in it."},{"n":2,"title":null,"text":"Place the lavash on a baking sheet. Sprinkle the mozzarella over the lavash, and top with the tomato slices and onion. Arrange the goat cheese over and between the tomato slices. Sprinkle with thyme, salt and pepper. Drizzle on the olive oil."},{"n":3,"title":null,"text":"Bake 15 to 20 minutes, until the lavash is crisp and dark brown on the edges. Remove from the heat and serve; or allow to cool slightly, then serve. Cut with a pizza wheel or scissors."}],"tips":[],"cuisine_tags":["Fusion","Mediterranean"],"ingredient_tags":["flatbread","tomato"],"item_tags":["goat cheese","mozzarella","thyme"],"course_tags":["Dinner"],"keywords":["Bake","Dinner","Easy","Healthy","Lavash","Main Course","Mozzarella","Quick","Tomato","Vegetarian"],"issues":null,"front":"nyt_1014102.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014102-lavash-pizza-with-tomatoes-mozzarella-and-goat-cheese","rating":{"value":5,"count":326},"date":"2010-10-25"},{"pair":12344,"title":"Polenta and Broccoli Rabe Lasagna","subtitle":null,"author":"Melissa Clark","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"1 hour 45 minutes","nutrition":{"calories":"610","fat":"36 g","carbohydrates":"48 g","protein":"24 g"},"description":"This lasagna layers noodles, polenta, mozzarella, sauce and broccoli rabe for a wonderfully savory and multi-textured one-dish meal. A note about the lasagna noodles: You don’t have to boil them, nor do you have to buy special no-boil noodles. You can soak the noodles in a bowl of water while you prepare the other ingredients, then slap them in the casserole dish. They will start to soften in their cold bath and finish cooking as the lasagna bakes.","from_your_kitchen":null,"ingredients":["18 dry lasagna noodles (from 1 package)","3 tablespoons extra-virgin olive oil, plus more as needed","4 garlic cloves, finely chopped","⅛ teaspoon red chile flakes, plus more for serving (optional)","1 28-ounce can or box chopped tomatoes","2 tablespoons plus ½ teaspoon kosher salt","¼ cup finely chopped fresh basil","1 large bunch broccoli rabe (about 1 ½ pounds)","1 ¼ cups quick-cooking polenta","18-ounce container mascarpone or fresh ricotta","4 ounces parmesan, finely grated (about 1 cup)","2 tablespoons unsalted butter","12 ounces fresh mozzarella, torn into bite-size pieces","½ teaspoon black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Place the lasagna noodles in a large bowl of cold water to soak (if you are using no-boil noodles, you can skip this step). Lightly oil a 9- by 13-inch baking pan."},{"n":2,"title":null,"text":"Heat 3 tablespoons oil in a large skillet over medium-high heat. Add the garlic and chili flakes; cook until fragrant, about 30 seconds. Stir in the tomatoes and simmer over medium-low heat for 10 minutes. Stir in ½ teaspoon salt and the basil. Remove from heat."},{"n":3,"title":null,"text":"Remove the tough lower stem ends of the broccoli rabe. Cut the remaining stems, leaves and florets into 1-inch pieces. Fill a pot with 8 cups water and 2 tablespoons salt. Bring water to a boil and add the broccoli rabe. Cook 30 seconds, then use a slotted spoon to transfer broccoli rabe to a bowl."},{"n":4,"title":null,"text":"Slowly whisk the polenta into the water. Simmer until polenta is thick and creamy, 5 to 10 minutes. Add the mascarpone or ricotta, ½ cup parmesan and the butter, and stir until combined. Stir in the broccoli rabe."},{"n":5,"title":null,"text":"Heat the oven to 400 degrees. Arrange a single layer of lasagna noodles in the bottom of the pan. Tear or break any pieces as needed to fit them in one layer, with no overlapping. Top with a third of the polenta mixture, half the tomato sauce and a third of the mozzarella. Arrange a second layer of lasagna noodles over the mozzarella. Repeat layering of polenta, sauce and mozzarella. Arrange a final layer of noodles over the cheese and finish with the remaining polenta and mozzarella. Scatter ½ cup parmesan and the black pepper over the top."},{"n":6,"title":null,"text":"Transfer casserole to the oven. Bake until cheese is golden and bubbling, 30 to 40 minutes. Let stand 20 minutes before serving. Serve with more chili flakes scattered on top, if you like."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["broccoli rabe","pasta","polenta"],"item_tags":["basil","mascarpone","parmesan","red chile flakes"],"course_tags":["Dinner"],"keywords":["Bake","Boil","Broccoli Rabe","Casseroles","Dinner","Great Leftovers","Italian","Lasagna","Lasagna Noodle","Main Course","Polenta","Saute"],"issues":null,"front":"nyt_12344.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12344-polenta-and-broccoli-rabe-lasagna","rating":{"value":4,"count":115},"date":"2012-03-23"},{"pair":1016073,"title":"Spaghetti With Cauliflower, Almonds, Tomatoes and Chickpeas","subtitle":null,"author":"Martha Rose Shulman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"About 30 minutes","nutrition":{"calories":"518","fat":"15 g","carbohydrates":"85 g","protein":"20 g"},"description":"Pasta with cauliflower comes in many variations throughout Italy. This one is all about texture -- crunchy almonds, tender (but not mushy) cauliflower and plush chickpeas. The original version of this recipe called for quinoa spaghetti (and if you're into that, go for it!), but we've found it's just as tasty with the traditional sort as well.","from_your_kitchen":null,"ingredients":["24 raw almonds (about 3 tablespoons), blanched, skinned* and chopped","1 small or ½ large head cauliflower, broken into florets","2 tablespoons extra virgin olive oil","2 garlic cloves, minced","1-14 ½-ounce can chopped tomatoes in juice","¼ teaspoon sugar","Pinch of cinnamon","Salt to taste","½ to 1 teaspoon dried oregano (to taste)","Freshly ground pepper to taste","½ cup cooked chickpeas (canned or freshly cooked)","¾ pound spaghetti","Crumbled feta or freshly grated Parmesan for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Fill a large pasta pot with water and bring to a boil. Add salt to taste and cauliflower. Boil 5 minutes, then using a Chinese skimmer, a strainer or a slotted spoon, transfer cauliflower to a bowl of cold water (do not drain the pot; you’ll use the water for the pasta). Drain the cauliflower and chop medium-fine. Set aside."},{"n":2,"title":null,"text":"(You can do this step while you are waiting for the water to come to a boil for the cauliflower). Heat 1 tablespoon of the olive oil over medium heat in a large, heavy skillet or a wide saucepan and add garlic. Cook, stirring, until fragrant, about 30 seconds, and stir in tomatoes with liquid, sugar, cinnamon, salt and oregano. Turn up heat to medium-high and stir often as tomatoes come to a brisk boil. Turn heat down to medium and cook, stirring often, until tomatoes have cooked down and taste very fragrant, about 10 minutes. Add pepper to taste."},{"n":3,"title":null,"text":"Add cauliflower and almonds to the tomato sauce, along with ¼ cup cooking water from the cauliflower, and stir together. Stir in chickpeas."},{"n":4,"title":null,"text":"Bring water in the pot back to a boil and add spaghetti. Cook al dente, following timing instructions on the package but checking for doneness a minute before indicated time on the package. Set aside ½ cup of the cooking water from the pasta, in case you want to moisten the sauce more, drain pasta and toss with the tomato and cauliflower sauce and the remaining tablespoon of olive oil. Add water from pasta only if you think the mixture seems dry. Serve, passing crumbled feta or grated Parmesan at the table for sprinkling."}],"tips":["To blanch and skin almonds, bring a small pot of water to a boil and drop in almonds. Boil 30 seconds and transfer to a bowl of cold water. Drain and slip off skins, then chop.","Advance preparation: The cauliflower and tomato sauce can be prepared through Step 3 up to 3 days ahead."],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["almonds","cauliflower","chickpeas","pasta","tomato"],"item_tags":["cinnamon","feta","oregano"],"course_tags":["Dinner"],"keywords":["Dinner","Fall","Gluten-Free","Healthy","High Fiber","Italian","Low-Sodium","Main Course","Mediterranean","Quick","Vegetarian","Winter"],"issues":null,"front":"nyt_1016073.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016073-spaghetti-with-cauliflower-almonds-tomatoes-and-chickpeas","rating":{"value":4,"count":670},"date":"2014-02-24"},{"pair":1016146,"title":"Broccoli Salad With Garlic and Sesame","subtitle":null,"author":"Melissa Clark","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"10 minutes, plus marinating","nutrition":{"calories":"232","fat":"22 g","carbohydrates":"8 g","protein":"3 g"},"description":"This salad is made from uncooked broccoli tossed with an assertive garlic, sesame, chile and cumin-seed vinaigrette slicked with good extra-virgin olive oil and red wine vinegar. The acid “cooks” the florets a little as ceviche does fish. After an hour, the broccoli softens as if blanched, turning bright emerald, and soaking up all the intense flavors of the dressing. You’ll be making this one again.","from_your_kitchen":null,"ingredients":["1 ½ teaspoons red wine vinegar","1 teaspoon kosher salt, more to taste","2 heads broccoli, 1 pound each, cut into bite-size florets","¾ cup extra virgin olive oil","4 fat garlic cloves, minced","2 teaspoons cumin seeds","2 teaspoons roasted (Asian) sesame oil","Large pinch crushed red pepper flakes."],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, stir together the vinegar and salt. Add broccoli and toss to combine."},{"n":2,"title":null,"text":"In a large skillet, heat olive oil until hot, but not smoking. Add garlic and cumin and cook until fragrant, about 1 minute. Stir in sesame oil and pepper flakes. Pour mixture over broccoli and toss well. Let sit for at least 1 hour at room temperature, and up to 48 (chill it if you want to keep it for more than 2 hours). Adjust seasonings (it may need more salt) and serve."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["broccoli"],"item_tags":["cumin seeds","red wine vinegar","sesame oil"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Broccoli","Christmas","Dairy-Free","Dinner","Easter","Easy","Gluten-Free","Great Leftovers","Kid-Friendly","Low-Fat","Make-Ahead","New Year’s Day","Party","Red Wine Vinegar","Salad","Sesame Oil","Side Dish","Stovetop","Thanksgiving","Vegan","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1016146.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016146-broccoli-salad-with-garlic-and-sesame","rating":{"value":5,"count":5882},"date":"2008-02-20"},{"pair":1017804,"title":"Stuffed Delicata Squash With Lentils and Cashew Raita","subtitle":null,"author":"Tara Parker-Pope","servings":"4","yield_text":"4 main-dish servings","yield_count":4,"cook_time":"5 hours 20 minutes","nutrition":{"calories":"622","fat":"32 g","carbohydrates":"78 g","protein":"23 g"},"description":"Delicata is a light yellow squash with green stripes and a creamy, rich texture. One of the best things about delicata is that it’s much easier to clean, cut and cook than butternut or other winter squash varieties. Hannah Kaminsky of Fairfield, Conn., creator of the My Sweet Vegan blog, was inspired by the tubelike shape of the delicata. “Each perfect yellow and green-striped edible tube becomes an ideal vessel for every sort of filling imaginable, no matter how you cut or cook it,” said Ms. Kaminsky. Tara Parker-Pope","from_your_kitchen":null,"ingredients":["1 cup raw cashew pieces","2 tablespoons fresh mint leaves, roughly chopped","3 tablespoons lemon juice","¼ cup water","½ teaspoon salt","2 – 3 Persian cucumbers, finely diced","2 medium delicata squash (About 1 pound each)","2 tablespoons olive oil","3 shallots, finely diced","1 Jalapeno, seeded and finely diced","1 ½ teaspoons whole cumin seeds","1 ½ teaspoons whole mustard seeds","1 cup dry beluga lentils","2 cups vegetable broth","⅔ cup full-fat coconut milk","1 tablespoon balsamic vinegar","¾ – 1 teaspoon salt","¼ teaspoon freshly ground black pepper"],"ingredient_groups":[{"at":0,"title":"CASHEW RAITA"},{"at":7,"title":"LENTIL STUFFING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Place the cashew pieces in a bowl and cover with cool water. Cover and place in the fridge to soak for four hours."},{"n":2,"title":null,"text":"Thoroughly drain the soaked cashews and combine with the chopped mint, lemon juice, water and salt in a blender. Purée, pausing to scrape down the sides of the canister with a spatula as needed, until completely silky-smooth. This process may take longer if you use a lower-powered blender, but stick with it; that creamy texture is important. Stir in the cucumber pieces by hand. Store in an air-tight container and keep refrigerated prior to serving."},{"n":3,"title":null,"text":"For the filling, heat olive oil in a medium pot over medium heat before adding the shallots and jalapeno. Cook until translucent, then add the cumin and mustard seeds. Cook until the entire mixture is highly aromatic, about a minute. Add the lentils and broth and bring to a boil. Once boiling, reduce heat to a simmer and cover. Cook for about 30 minutes, until the liquid has absorbed and lentils are tender. Add the coconut milk and vinegar and season with salt and pepper. Keep the pot partially covered and simmer for an additional 5 to 10 minutes, until the liquid has been absorbed. Cover and keep warm."},{"n":4,"title":null,"text":"As the lentils cook, preheat oven to 375 degrees. Cut both squash in half lengthwise and scoop out (but reserve) seeds. Place each half with the cut sides down on a lightly greased baking sheet and bake for about 30 minutes, or until a fork easily pierces the flesh. Remove from oven and let cool for at least 5 minutes before handling."},{"n":5,"title":null,"text":"Reduce oven to 250 degrees and toss the reserved seeds with 1 tablespoon of olive oil and a pinch of salt and roast for 10 to 20 minutes, stirring frequently to prevent them from burning. Once golden and crisp, remove from oven and allow to cool."},{"n":6,"title":null,"text":"Flip the roasted delicata squashes up to turn them into boats and spoon the warm lentils inside. Serve the cashew raita alongside for guests to top their squashes as desired and finish with a sprinkle of roasted seeds."}],"tips":[],"cuisine_tags":["Fusion","Indian"],"ingredient_tags":["cashews","delicata squash","lentils"],"item_tags":["brown mustard seeds","coconut milk","cumin seeds","mint"],"course_tags":["Dinner"],"keywords":["Fall","Main Course","Thanksgiving","Vegan","Vegan Thanksgiving","Vegetarian"],"issues":null,"front":"nyt_1017804.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017804-stuffed-delicata-squash-with-lentils-and-cashew-raita","rating":{"value":5,"count":558},"date":"2015-11-06"},{"pair":1013345,"title":"Butternut Squash, Pecans and Currants","subtitle":null,"author":"Sam Sifton","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"30 minutes","nutrition":{"calories":"351","fat":"23 g","carbohydrates":"45 g","protein":"4 g"},"description":"This recipe, from the restaurant Balaboosta in New York, came to The Times in 2010 as part of a roundup of restaurant Thanksgiving dinners, but it can be served any time, even as a weeknight main alongside a hearty salad or starch. The currants and candied pecans play off the butternut squash’s sweetness, while a vinaigrette stops it all from being too cloying. It’s a delightful vegetarian main for when you want the essence of the restaurant meal, without too much work. Sam Sifton","from_your_kitchen":null,"ingredients":["2 small butternut squash (about 2 pounds each)","7 tablespoons extra-virgin olive oil","5 thyme sprigs","Salt","Pepper","3 garlic cloves, finely chopped","½ cup coarsely chopped pecans","1 tablespoon sugar","¼ cup Champagne vinegar or white wine vinegar","¼ cup currants","½ teaspoon chili flakes"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 450 degrees. Cut the squash in two at the base of the neck, discarding the hollow bulb end or reserving for another use. Peel the rest and slice into ½-inch disks. Toss the squash in a large roasting pan with 2 tablespoons of the olive oil, thyme and salt and pepper to taste, and arrange in a single layer. Roast the squash, turning once halfway through, until tender and beginning to brown, about 30 minutes."},{"n":2,"title":null,"text":"Meanwhile, in a large skillet over medium heat, combine garlic and one tablespoon of the remaining olive oil. Sauté until fragrant and tender, about one minute. Add pecans and sugar, and toss until the sugar has melted and the pecans are lightly browned, about 2 minutes. Whisk the vinegar into the remaining olive oil. Add the pecan mixture, currants and chili flakes. Mix well, and season with salt and pepper to taste."},{"n":3,"title":null,"text":"Arrange the squash on a warm platter and top with some or all of the dressing."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["butternut squash","pecans"],"item_tags":["champagne vinegar","currants","red chile flakes","thyme"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Butternut Squash","Christmas","Fall","Main Course","Pecan","Quick","Roast","Side Dish","Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_1013345.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013345-butternut-squash-pecans-and-currants","rating":{"value":5,"count":421},"date":"2010-11-10"},{"pair":1014187,"title":"Tomato Sauce With Capers and Vinegar","subtitle":null,"author":"Martha Rose Shulman","servings":"1","yield_text":"About 1 1/4 cups, serving four to six","yield_count":1,"cook_time":"About 30 minutes","nutrition":{"calories":"60","fat":"5 g","carbohydrates":"4 g","protein":"1 g"},"description":"There are so many ways to enjoy this sauce. You can serve it with pasta or grains, over vegetables (try it with cauliflower) or on a bruschetta. I recently tried it with Israeli couscous, sautéed in olive oil then simmered in stock and topped with this sauce.","from_your_kitchen":null,"ingredients":["2 tablespoons extra virgin olive oil","½ medium onion, finely chopped","1 large garlic clove, minced","1 pound fresh tomatoes, grated, or 1 can chopped tomatoes","1 basil sprig","1 tablespoon capers, rinsed and finely chopped","Salt","freshly ground pepper to taste","1 tablespoon red wine vinegar or sherry vinegar (more to taste)","1 to 2 tablespoons minced parsley or slivered basil (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE PUNGENT TOMATO SAUCE WITH CAPERS AND VINEGAR"}],"tools":null,"steps":[{"n":1,"title":"FOR THE PUNGENT TOMATO SAUCE WITH CAPERS AND VINEGAR","text":"Heat 1 tablespoon of the olive oil in a medium heavy saucepan. Add the onion. Cook, stirring often, until tender, about five minutes. Stir in the garlic. Cook, stirring, until fragrant, about 30 seconds. Stir in the tomatoes, basil sprig, capers, salt and pepper. Bring to a simmer over medium-high heat, stir and reduce the heat. Simmer 10 to 15 minutes until cooked down and very fragrant. Remove the basil sprig. Stir in the vinegar, the remaining tablespoon of olive oil and the optional parsley or basil. Taste and adjust seasonings. Serve hot or cold."}],"tips":["Advance preparation: You can keep this sauce for about a week in the refrigerator. It freezes well."],"cuisine_tags":["Italian","Mediterranean"],"ingredient_tags":["tomato"],"item_tags":["basil","capers","parsley","red wine vinegar"],"course_tags":["Dinner"],"keywords":["Caper","Condiments","Easy","Healthy","Quick","Sauces and Gravies","Sherry Vinegar","Tomato","Vegan","Vegetarian"],"issues":null,"front":"nyt_1014187.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014187-tomato-sauce-with-capers-and-vinegar","rating":{"value":5,"count":215},"date":"2011-07-04"},{"pair":1019471,"title":"Sweet and Spicy Tofu With Soba Noodles","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"601","fat":"28 g","carbohydrates":"63 g","protein":"37 g"},"description":"If you don’t cook tofu often (or even if you do), this unfussy tofu dish is for you: There’s no flour-dredging or shallow-frying, and no marinating at all. As long as you pat the tofu dry (a bit fussy, but not by much), the vegetable oil’s high smoke point will yield crisp edges, while the sesame oil imparts flavor, putting you well on your way to making tofu taste great. What’s more, a ginger-and-garlic-laced soy sauce coats noodles and tofu alike, giving you chopstick after chopstick of toothsome pleasure. Serve these warm or cold, and be generous with the cool, crispy vegetables on top, especially for summer picnics where you can stretch this to serve 6 or even 8 as a side.","from_your_kitchen":null,"ingredients":["1 ½ (14-ounce) packages firm tofu, drained","2 tablespoons canola oil","2 tablespoons sesame oil","1 (8-ounce) package all-buckwheat soba noodles","4 garlic cloves, smashed","1 (1-inch) piece ginger, peeled and thinly sliced","1 small bunch green onions, white and green parts separated, cut into 2-inch matchsticks","⅓ cup soy sauce or tamari","3 tablespoons dark brown sugar","1 teaspoon black pepper","Pinch of red-pepper flakes","4 mini or 1 large, thin-skinned cucumber, thinly sliced","4 radishes, thinly sliced","Handful of cilantro leaves, for serving","1 lime, cut in wedges, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Drain the tofu in a colander, or dry on paper-towel lined plate while you prep the remaining ingredients, about 10 minutes. Meanwhile, bring a small pot of water to a boil for the soba noodles."},{"n":2,"title":null,"text":"Cut tofu into 1-inch cubes. Heat a cast-iron skillet over medium-high heat. Add the vegetable oil and 1 tablespoon of the sesame oil. When the oil shimmers, add the tofu in a single layer, in batches if needed and cook until golden on all sides, turning as needed when the tofu releases easily from the pan, about 8 to 10 minutes total. Lift the tofu out of the pan with a spatula and transfer to a new paper-towel-lined plate."},{"n":3,"title":null,"text":"Meanwhile, cook the soba in boiling water for 5 to 8 minutes (or according to package directions), until just al dente, stirring frequently. Drain and rinse in cold water until the noodles no longer feel sticky."},{"n":4,"title":null,"text":"Add garlic, ginger and whites of the onions to the skillet, along with the remaining tablespoon sesame oil, reduce the heat to medium, and cook until the oil is fragrant, stirring constantly, about 1 minute."},{"n":5,"title":null,"text":"Add cooked and drained soba noodles to the pan, along with soy sauce, sugar, black pepper, red pepper and reserved green onions; toss together until the noodles are coated. Gently toss in the tofu until all the pieces are covered in the sauce."},{"n":6,"title":null,"text":"Remove from the heat, and sprinkle cucumber, radish and cilantro on top. Serve warm or at room temperature, with lime."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["soba noodles","tofu"],"item_tags":["brown sugar","cilantro","ginger","lime","sesame oil","tamari"],"course_tags":["Dinner"],"keywords":["Boil","Dinner","Firm Tofu","Fry","Japanese","Main Course","Noodles","Soba Noodle","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019471.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019471-sweet-and-spicy-tofu-with-soba-noodles","rating":{"value":5,"count":6587},"date":"2018-08-08"},{"pair":1015769,"title":"Sweet Potato-Pecan Salad","subtitle":null,"author":"John Willoughby","servings":"6","yield_text":"6 side-dish servings","yield_count":6,"cook_time":"25 minutes","nutrition":{"calories":"400","fat":"31 g","carbohydrates":"38 g","protein":"4 g"},"description":"Southern-style sweet potato salad with pecans makes an excellent companion for fried chicken.","from_your_kitchen":null,"ingredients":["4 medium sweet potatoes (about 2 pounds), peeled and cut into uniform 2-inch chunks","2 tablespoons salt","½ red bell pepper, seeded and diced small","½ green bell pepper, seeded and diced small","½ large red onion, diced small","¼ cup finely chopped parsley","3 tablespoons Dijon mustard","3 tablespoons ketchup","1 teaspoon minced garlic","¾ cup olive oil","¼ cup cider vinegar","1 tablespoon Worcestershire sauce","2 tablespoons fresh lime juice","Salt and pepper to taste","⅓ cup pecan halves, lightly toasted"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Fill sink or a large bowl with water and ice cubes. Put sweet potatoes in a large saucepan, add the salt and water to cover, and bring to a boil over high heat. Reduce heat to medium and simmer until potatoes can be easily pierced with a fork but still offer some resistance and don’t break apart, 10 to 12 minutes."},{"n":2,"title":null,"text":"Drain potatoes and immediately put them into the ice-water bath. After 1 minute, remove potatoes, drain again, and put into a large bowl along with diced peppers, onion and parsley."},{"n":3,"title":null,"text":"Make the dressing: In a large bowl, combine mustard, ketchup and garlic. Add olive oil in a slow, steady stream, whisking constantly. Whisk in vinegar, Worcestershire and lime juice, then season to taste with salt and pepper."},{"n":4,"title":null,"text":"Pour dressing over sweet potatoes, add pecans and toss gently."}],"tips":[],"cuisine_tags":["American","Southern"],"ingredient_tags":["bell pepper","pecans","sweet potato"],"item_tags":["dijon mustard","lime","worcestershire sauce"],"course_tags":["Sides & Appetizers"],"keywords":["Pecan","Potato Salad","Quick","Side Dish","Sweet Potato"],"issues":null,"front":"nyt_1015769.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015769-sweet-potato-pecan-salad","rating":{"value":4,"count":307},"date":"2013-12-04"},{"pair":12475,"title":"Lasagna With Roasted Broccoli","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 45 minutes","nutrition":{"calories":"369","fat":"15 g","carbohydrates":"41 g","protein":"19 g"},"description":"The broccoli part of this recipe is adapted from Molly Stevens’ Blasted Broccoli in her wonderful book “All About Roasting.”","from_your_kitchen":null,"ingredients":["1 ¼ pounds broccoli, crowns only","2 tablespoons extra virgin olive oil","Salt and freshly ground pepper","8 ounces ricotta cheese","1 egg","2 tablespoons water","Pinch of cinnamon","2 anchovy fillets, rinsed (optional)","3 cups marinara sauce, preferably homemade from fresh or canned tomatoes","7 to 8 ounces no-boil lasagna","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 450 degrees. Line a baking sheet with parchment paper. Slice the broccoli crowns ⅓ inch thick, letting the florets on the edges fall off. Peel any large pieces of stem by gently pulling away the thick skin, then toss the slices and the unattached florets with the olive oil, salt and pepper. Place on the baking sheet in an even layer. Roast, stirring and flipping the large slices over (tongs are a good tool for this) after 8 minutes, until the broccoli is tender when pierced with a knife and the tops are nicely browned, about 15 minutes total. Remove from the oven and set aside. Turn the oven down to 350 degrees."},{"n":2,"title":null,"text":"Blend the ricotta cheese with the egg, water, cinnamon, salt and pepper."},{"n":3,"title":null,"text":"Chop the anchovies and stir into the tomato sauce. Oil a rectangular baking dish and spread a spoonful of tomato sauce over the bottom. Top with a layer of lasagna noodles. Spoon a thin layer of the ricotta mixture over the noodles. Top with a layer of broccoli, then a layer of tomato sauce and a layer of Parmesan. Repeat the layers until the ingredients are used up, ending with a layer of lasagna noodles topped with tomato sauce and Parmesan."},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 10 minutes, until the top begins to brown. Remove from the heat and allow to sit for 5 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Italian"],"ingredient_tags":["broccoli","pasta"],"item_tags":["cinnamon","parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["Bake","Broccoli","Casseroles","Dinner","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Roast","Vegetarian"],"issues":null,"front":"nyt_12475.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12475-lasagna-with-roasted-broccoli","rating":{"value":5,"count":246},"date":"2012-05-29"},{"pair":1021018,"title":"Oven-Fried Patatas Bravas (Crispy Potatoes With Two Sauces)","subtitle":null,"author":"David Tanis","servings":"4","yield_text":"4 appetizer servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"698","fat":"51 g","carbohydrates":"55 g","protein":"10 g"},"description":"Served with spicy salsa brava and garlicky allioli, crispy hot patatas bravas are traditionally served in tapas bars throughout Spain. The salsa brava is made with pimentón, the smoked Spanish paprika sold as picante (hot) and dulce (sweet). Some cooks include a lot of chopped tomato, but my friends in Madrid tell me they prefer this version, which looks a bit like rusty gravy. As for the allioli, you can mount it by hand with a whisk, or use a stick blender as most Spaniards do. Though patatas bravas are typically pan-fried on the stovetop, I came up with this easier, oven-fried method. The potatoes emerge beautifully browned and crisped, and their flavor is sensational cooked in extra-virgin olive oil. This is not fancy fare. Grab a fork and dip the hot potatoes in both sauces for the optimal experience.","from_your_kitchen":null,"ingredients":["2 pounds yellow-fleshed or russet potatoes, peeled and cut in 1 ½-inch chunks","Kosher salt","½ cup extra-virgin olive oil","1 head garlic, separated into cloves but not peeled","2 tablespoons extra-virgin olive oil","2 garlic cloves, minced","2 tablespoons all-purpose flour","1 tablespoon tomato paste","1 tablespoon pimentón dulce, or use sweet paprika","1 teaspoon pimentón picante, ½ teaspoon chipotle chile powder or ¼ teaspoon cayenne","1 cup chicken broth or water","1 tablespoon sherry vinegar","Kosher salt","2 egg yolks","4 garlic cloves, pounded, finely minced or grated","1 ½ cups extra-virgin olive oil","Kosher salt and black pepper"],"ingredient_groups":[{"at":0,"title":"FOR THE POTATOES"},{"at":4,"title":"FOR THE SALSA BRAVA"},{"at":13,"title":"FOR THE ALLIOLI"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 450 degrees. Put potato chunks in a large bowl, season generously with salt and toss to coat. Leave for a few minutes to let potatoes absorb salt. Add olive oil and unpeeled garlic cloves and toss to coat well. (Don’t skimp on the oil; it can be strained and saved after cooking for future use.)"},{"n":2,"title":null,"text":"Transfer potatoes (and garlic cloves) and oil to a large cast-iron skillet or heavy roasting pan. Make sure to have potatoes in a single layer without crowding. (If necessary, use two pans.) There should be a good ½-inch oil in the bottom of the pan. Add more if required."},{"n":3,"title":null,"text":"Place pan in oven and roast for 15 to 20 minutes, until potato chunks are well browned on the bottom. With a metal spatula, carefully turn chunks over. Reduce heat to 400 degrees, and continue roasting until potatoes are well browned and crisp, about another 15 to 20 minutes."},{"n":4,"title":null,"text":"While potatoes are roasting, make the two sauces: For the salsa brava, put 2 tablespoons olive oil in a small saucepan over medium heat. Add garlic and let sizzle without browning, then stir in flour and let mixture sizzle. Stir in tomato paste, pimentón dulce and pimentón picante, then add chicken broth gradually, stirring well as the sauce thickens. Bring to a gentle simmer, add vinegar and cook for 5 minutes until the sauce has a gravylike consistency, but isn't too thick. Thin with a little more broth or water, if necessary. Season with salt to taste."},{"n":5,"title":null,"text":"For the allioli, put egg yolks and garlic in a mortar or small bowl and whisk together. (Alternatively, use a mini food processor or stick blender, see note.) Add oil a few drops at a time, whisking vigorously with each addition. As the sauce thickens, add olive oil a teaspoon at a time. If the aioli gets too thick, whisk in 1 tablespoon water, then continue to whisk in remaining oil. The finished sauce should have the consistency of softly whipped cream. Season to taste with salt and pepper."},{"n":6,"title":null,"text":"When potatoes are ready, use spatula to transfer to a pan lined with paper towels to blot, then to a warm serving dish. Sprinkle lightly with salt. Serve warm with the two sauces."}],"tips":["To make in a blender or food processor, use 1 whole egg and 1 egg yolk instead of only yolks. Drizzle oil in a thin stream with motor running until the sauce thickens, which takes only a minute or so. Transfer to a small bowl, then thin with a little water and season with salt and pepper."],"cuisine_tags":["Spanish"],"ingredient_tags":["potato"],"item_tags":["sherry vinegar","smoked paprika","tomato paste"],"course_tags":["Sides & Appetizers"],"keywords":["Appetizer","Egg Yolk","Fry","Garlic","Potato","Side Dish","Small Plate","Snack","Spanish","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1021018.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021018-oven-fried-patatas-bravas-crispy-potatoes-with-two-sauces","rating":{"value":4,"count":1454},"date":"2020-05-13"},{"pair":1019940,"title":"Turkish Eggs With Olives, Feta and Tomatoes (Menemen)","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"516","fat":"30 g","carbohydrates":"40 g","protein":"26 g"},"description":"Scrambled eggs lend themselves to customization because they're a blank, breakfast- or brunch-friendly canvas. Almost any stir-in works: Add cheese or butter for richness, vegetables for heft and herbs and spices for flavor. If you like a little bit of everything in yours, then menemen –– the traditional Turkish egg dish loaded with peppers and tomatoes –– is for you. This version uses plump olives, crumbled feta and a pile of fresh herbs -- and comes together in less than 30 minutes.","from_your_kitchen":null,"ingredients":["3 tablespoons extra-virgin olive oil","5 scallions, white and green parts, finely chopped (see Tip)","2 large red bell peppers, seeded and finely chopped","2 large ripe tomatoes or 3 plum tomatoes (about 1 pound), finely chopped","1 teaspoon red-pepper flakes","Fine sea salt and freshly ground black pepper","4 whole-wheat pitas or flatbread","8 large eggs, beaten","6 ounces feta, crumbled","⅓ packed cup parsley or cilantro leaves, or a mix, chopped","Meaty green olives (such as Cerignola or Castelvetrano)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat 2 tablespoons oil in a large nonstick skillet over medium. Add half the scallions and cook until beginning to soften, about 2 minutes. Increase the heat to medium-high, add the bell peppers and cook until slightly softened, about 4 minutes. Add the tomatoes, red-pepper flakes and 1 teaspoon each salt and pepper and cook until some of the liquid from the tomatoes evaporates, about 10 minutes."},{"n":2,"title":null,"text":"Meanwhile, toast the pita or flatbread on an open flame on the stovetop over low heat, turning with long metal tongs, until toasted and warmed on all sides. Wrap well in a kitchen towel to keep warm."},{"n":3,"title":null,"text":"When most of the liquid has evaporated from the tomatoes, reduce the heat to medium-low and add the remaining 1 tablespoon oil to the skillet. Add the eggs and let them cook, stirring occasionally, 2 to 3 minutes. Continue to cook, stirring frequently, until large curds form and the eggs are mostly cooked through but still slightly runny, about 3 minutes. Stir in the feta and cook until scrambled eggs are just cooked and feta is slightly melted, about 1 minute. Season with salt and pepper to taste. Remove from the heat and sprinkle with the parsley, cilantro and remaining scallions. Serve warm, with olives and pita on the side."}],"tips":["For a subtler flavor, cook all the scallions in Step 1 instead of reserving some as a raw garnish."],"cuisine_tags":["Mediterranean","Turkish"],"ingredient_tags":["bell pepper","eggs","tomato"],"item_tags":["castelvetrano olives","feta","parsley","red chile flakes","scallions"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Breakfast","Brunch","Dinner","Easy","Egg","Feta","For One","For Two","Green Olive","Lunch","Main Course","Quick","Red Bell Pepper","Scallion","Turkish","Weeknight"],"issues":null,"front":"nyt_1019940.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019940-turkish-eggs-with-olives-feta-and-tomatoes-menemen","rating":{"value":4,"count":384},"date":"2019-01-17"},{"pair":12474,"title":"Lasagna With Spinach and Roasted Zucchini","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 30 minutes","nutrition":{"calories":"363","fat":"15 g","carbohydrates":"40 g","protein":"19 g"},"description":"You may think of lasagna as a rich, heavy dish, but it needn’t be. There’s no need to compensate for the absence of a traditional Bolognese sauce by packing these casseroles with pounds of ricotta and grated cheese. Some of each of those elements is welcome, but I cut the usual amounts by half in this recipe, and it was plenty satisfying. You can get ahead on lasagna by making up big batches of marinara sauce and freezing it, or in a pinch use a good commercial brand. The noodles are no-boil, which really makes these lasagnas easy to assemble. They can be made ahead and reheated, or frozen.","from_your_kitchen":null,"ingredients":["2 tablespoons extra virgin olive oil","2 medium zucchini, cut in half crosswise, then cut lengthwise into ¼-inch-thick slices","Salt and freshly ground black pepper to taste","1 pound bunch spinach, washed and stemmed, or ½ pound bagged baby spinach","3 cups marinara sauce, preferably homemade from fresh or canned tomatoes","8 ounces ricotta cheese","1 egg","2 tablespoons water","Pinch of cinnamon","7 to 8 ounces no-boil lasagna","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 450 degrees. Toss the zucchini with the olive oil and season to taste with salt and pepper. Line a baking sheet with parchment paper and top with the slices of zucchini. Place in the oven and roast 8 minutes. Remove from the oven, close the oven door and, using tongs, flip the zucchini slices over. Return to the oven for 5 minutes, or until the zucchini is tender when pierced with a knife and browned in spots. Remove from the oven and reduce the heat to 350 degrees."},{"n":2,"title":null,"text":"Steam the spinach for 2 to 3 minutes above an inch of boiling water, just until it wilts. Rinse briefly with cold water, squeeze out excess water and chop coarsely."},{"n":3,"title":null,"text":"Blend the ricotta cheese with the egg, water, cinnamon, salt and pepper. Set aside."},{"n":4,"title":null,"text":"Lightly oil a rectangular baking pan. Spread a small spoonful of tomato sauce to cover the bottom of the pan. Top with a layer of lasagna noodles. Top the noodles with a thin layer of ricotta, then a layer of zucchini and spinach, a layer of tomato sauce and a layer of Parmesan. Repeat the layers, ending with a layer of lasagna noodles topped with tomato sauce and Parmesan."},{"n":5,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 10 minutes, until the top begins to brown. Remove from the heat and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Italian"],"ingredient_tags":["pasta","spinach","zucchini"],"item_tags":["cinnamon","parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["Bake","Casseroles","Dinner","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Spinach","Steam","Vegetarian"],"issues":null,"front":"nyt_12474.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12474-lasagna-with-spinach-and-roasted-zucchini","rating":{"value":5,"count":4326},"date":"2012-05-28"},{"pair":1014191,"title":"Pappardelle With Fresh Ricotta, Squash Blossoms and Basil Oil","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"512","fat":"23 g","carbohydrates":"62 g","protein":"15 g"},"description":"Ricotta is one of the great undersung cheeses and can be used in dozens of ways. Bake it in a hot oven in an earthenware dish with a little olive oil and rosemary, then spread it on toast for an antipasto or snack. Mix it with chopped cooked spinach or chard for filling ravioli or layering into baked pasta. Or, as is done here, fold the cheese into pappardelle noodles with barely cooked zucchini and squash blossoms and serve with basil oil and grated pecorino for a sensational summer pasta.","from_your_kitchen":null,"ingredients":["About 12 basil leaves, roughly chopped","1 garlic clove, minced","½ teaspoon grated lemon zest","⅓ cup extra virgin olive oil","Salt","pepper","1 pound pappardelle or other pasta","2 tablespoons extra virgin olive oil","½ pound small zucchini, thinly sliced","Salt","pepper","About 12 squash blossoms, stems removed","½ pound fresh ricotta about 1 cup, at room temperature","Pecorino cheese, for grating"],"ingredient_groups":[{"at":0,"title":"FOR THE BASIL OIL"},{"at":6,"title":"FOR THE PASTA"}],"tools":null,"steps":[{"n":1,"title":"FOR THE BASIL OIL","text":"To make the basil oil, in a small dish stir together the basil, garlic, lemon zest and olive oil. Add a little salt and pepper. Set aside for at least 15 minutes. Meanwhile, bring a large pot of salted water to a boil, add the pasta, and cook until al dente."},{"n":2,"title":null,"text":"In a large skillet, heat 2 tablespoons olive oil over medium heat. Add the zucchini, season with salt and pepper, and cook until barely done, 1 or 2 minutes. Turn off the heat. Tear the squash blossoms into strips."},{"n":3,"title":null,"text":"Drain the pasta, reserving 1 cup pasta water. Add pappardelle to the skillet with the zucchini. Add squash blossoms, ricotta and a little salt and pepper. Quickly stir together with 2 wooden spoons, leaving the ricotta a little chunky. Add pasta water if necessary and transfer to a warm serving bowl."},{"n":4,"title":null,"text":"At the table, top each serving with 2 teaspoons basil oil and a sprinkling of grated pecorino."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["pasta","ricotta","squash blossoms","zucchini"],"item_tags":["basil","lemon","pecorino"],"course_tags":["Dinner"],"keywords":["Boil","Dinner","Italian","Main Course","Pastas","Quick","Ricotta","Saute","Summer","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1014191.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014191-pappardelle-with-fresh-ricotta-squash-blossoms-and-basil-oil","rating":{"value":5,"count":191},"date":"2011-08-10"},{"pair":1013946,"title":"Home/Made Mushroom Lasagna","subtitle":null,"author":"Sam Sifton","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"2 hours","nutrition":{"calories":"863","fat":"47 g","carbohydrates":"73 g","protein":"35 g"},"description":"Monica Byrne, with her partner, Leisah Swenson, runs a tiny restaurant in Red Hook, Brooklyn, called Home/Made. A plurality of words that appear on the Home/Made menu: “cheese,” “smoked,” “bacon,” “caramelized.” Three of those four appear in Byrne’s lasagna, leaving out only bacon, which would be a fine addition. She layers smoked mozzarella over a painting of rich, garlicky béchamel and sheets of pasta, then radicchio roasted into sweetness and tossed in sauce. Sautéed mushrooms add heft and loamy funkiness, and a mixture of Fontina and Gruyère add zing. Sam Sifton","from_your_kitchen":null,"ingredients":["½ cup extra-virgin olive oil or herb oil","6 large shallots, peeled and minced","1 ½ pounds mushrooms, wild or best available oyster, shiitake, cremini, trimmed and sliced","1 cup dry white wine","1 softball-size head of radicchio, halved, cored and cut into ½-inch slices","Kosher salt","freshly ground black pepper","4 tablespoons unsalted butter, or herb oil","3 large cloves garlic, peeled and minced","4 tablespoons flour, ideally instant or all-purpose","3 cups whole milk","½ teaspoon grated nutmeg","1 cup Gruyère cheese, grated","1 cup Fontina cheese, grated","2 tablespoons best-quality truffle oil (optional)","2 9-ounce boxes of no-boil lasagna sheets","1 baseball-size ball of smoked mozzarella, sliced","1 cup fresh Parmesan, grated"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat oven to 350. Place a large sauté pan over medium-high heat and add ¼ cup of the olive oil or herb oil. When it begins to shimmer, add half of the shallots and cook, stirring occasionally, until translucent. Add mushrooms and toss to coat, then cook until they begin to color but are still plump, approximately 12 to 15 minutes. Add white wine to deglaze pan and allow to cook down into a syrup, approximately 5 to 7 minutes. Put the mushrooms into a large bowl and reserve."},{"n":2,"title":null,"text":"Meanwhile, in another bowl, toss the radicchio with ¼ cup olive oil or herb oil and season with salt and pepper. Spread the strips out onto a baking pan and place in the oven until the strips are lightly browned around the edges, approximately 15 minutes. Combine with mushrooms and reserve."},{"n":3,"title":null,"text":"Make the béchamel. Place a saucepan over medium heat and melt the butter. When it foams, add the rest of the shallots and cook until they begin to turn translucent. Add the garlic and stir to combine, then cook until the garlic has started to soften. Sprinkle flour over the top and stir to combine, then cook gently until the mixture has turned light brown and gives off a nutty scent, approximately 10 minutes. Add milk to the mixture, whisking all the while, until the sauce is thick and creamy. Add the nutmeg and ¼ cup of grated Gruyère and ¼ cup of grated Fontina, then stir to combine. Season to taste with salt and pepper."},{"n":4,"title":null,"text":"Reserve a cup of béchamel. Pour the rest over the mixture of mushrooms and radicchio, and stir to combine. Add truffle oil, if using."},{"n":5,"title":null,"text":"Assemble lasagna. Spread plain béchamel across the bottom of a 9- by-13-inch baking pan. Place a layer of lasagna sheets across the sauce, being careful not to overlap. Spread a generous layer of mushroom mixture on top of the pasta, and follow with some grated Fontina and Gruyère. Put another layer of pasta above the cheese, and top with smoked mozzarella. Repeat until the pasta is gone and the pan is full. Top with remaining cheeses and a generous amount of grated Parmesan. Cover with a buttered sheet of aluminum foil and place in the oven for 45 minutes. Remove foil and cook until top is golden and bubbling."}],"tips":[],"cuisine_tags":["Fusion","Italian"],"ingredient_tags":["mushrooms","pasta"],"item_tags":["fontina","gruyere","nutmeg","truffle oil"],"course_tags":["Dinner"],"keywords":["Bake","Dinner","Fall","Great Leftovers","Italian","Lasagna","Main Course","Saute"],"issues":null,"front":"nyt_1013946.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013946-home-made-mushroom-lasagna","rating":{"value":4,"count":2138},"date":"2011-11-27"},{"pair":1013845,"title":"Tabbouleh With Apples, Walnuts and Pomegranates","subtitle":null,"author":"Joan Nathan","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"15 minutes","nutrition":{"calories":"273","fat":"24 g","carbohydrates":"16 g","protein":"3 g"},"description":"This grain-free tabbouleh, a perfect side for a Passover meal, comes from chef Michael Solomonov of Zahav. Joan Nathan","from_your_kitchen":null,"ingredients":["2 cups flat-leaf parsley, finely chopped","½ cup fresh pomegranate seeds","1 cup diced, cored, unpeeled apples, preferably Pink Lady","½ cup diced red onion","1 ½ to 2 teaspoons ground urfa biber peppers, smoked paprika or chipotle chile pepper","3 to 4 tablespoons honey","¼ cup lemon juice","½ cup extra virgin olive oil","Coarse kosher salt","1 cup walnuts"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Mix the parsley, pomegranate seeds, apples and red onion in a medium bowl. Stir in the pepper or paprika, honey, lemon juice and olive oil. Season to taste with salt and mix thoroughly. If desired, at this point the mixture may be covered and refrigerated for up to two days."},{"n":2,"title":null,"text":"In a dry skillet over medium heat, stir the walnuts until toasted, about 3 minutes. Sprinkle the walnuts with a pinch salt and crush them with the side of a knife or in a mortar and pestle until they are in coarse pieces."},{"n":3,"title":null,"text":"Stir in the crushed walnuts. (If the tabbouleh has been refrigerated, set it out at room temperature for an hour before adding the walnuts.)"}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["apple","walnuts"],"item_tags":["lemon","pomegranate seeds","smoked paprika"],"course_tags":["Lunch","Sides & Appetizers"],"keywords":["Apple","Easy","Fall","Middle Eastern","Passover","Pomegranate Seed","Quick","Rosh Hashana","Salad","Walnut"],"issues":null,"front":"nyt_1013845.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013845-tabbouleh-with-apples-walnuts-and-pomegranates","rating":{"value":5,"count":468},"date":"2011-09-21"},{"pair":12176,"title":"Loaded Miso Soup","subtitle":null,"author":"Mark Bittman","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"20 minutes","nutrition":{"calories":"140","fat":"5 g","carbohydrates":"16 g","protein":"11 g"},"description":"Many vegan dishes (like fruit salad and peanut butter and jelly) are already beloved, but the problem faced by many of us is in imagining less-traditional dishes that are interesting and not challenging. Miso soup is a more adventurous, though no more complicated, option to try.","from_your_kitchen":null,"ingredients":["1 strip kombu (dried kelp)","1 handful sliced shiitake mushrooms","½ cup miso","Carrots","Turnips","Ginger","1 handful cooked edamame","½ pound silken tofu, cubed","Scallions"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring 6 cups of water to a bare simmer and add one strip kombu; let it soak 10 minutes, then remove it and chop; set aside."},{"n":2,"title":null,"text":"Meanwhile, saute a handful of sliced shiitakes in oil until crisp."},{"n":3,"title":null,"text":"Whisk a cup of the water with ½ cup miso in a bowl until smooth."},{"n":4,"title":null,"text":"Pour the miso mix into the water and add ½ pound silken tofu along with some shredded carrots, turnip and ginger, the chopped kombu and about a handful of cooked, shelled edamame."},{"n":5,"title":null,"text":"Let stand long enough to heat the tofu through, about a minute. Add some chopped scallions and the crisp shiitakes and serve."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["edamame","mushrooms","tofu"],"item_tags":["ginger","miso","scallions"],"course_tags":["Sides & Appetizers"],"keywords":["Appetizer","Easy","Japanese","Miso","One Pot","Quick","Soup","Tofu","Vegan","Vegetarian"],"issues":null,"front":"nyt_12176.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12176-loaded-miso-soup","rating":{"value":4,"count":1167},"date":"2011-12-29"},{"pair":1021485,"title":"One-Pan Orzo With Spinach and Feta","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"277","fat":"12 g","carbohydrates":"31 g","protein":"12 g"},"description":"Similar to spanakorizo, a Greek spinach and rice dish, this easy, meatless meal features orzo, spinach, peas and scallions. It is deeply satisfying but still on the lighter side of pasta recipes, thanks to all those vegetables. A little feta gives it creaminess and tang, while some lemon zest brightens everything up. It makes a complete meal on its own, or, if you’re looking for something more substantial, serve this as a hearty side dish to roasted meats or fish.","from_your_kitchen":null,"ingredients":["2 tablespoons unsalted butter","4 large scallions, trimmed and thinly sliced","2 large garlic cloves, minced","8 ounces baby spinach leaves (8 cups), coarsely chopped","1 teaspoon kosher salt","1 ¾ cups low-sodium chicken or vegetable stock","1 cup orzo","1 teaspoon finely grated lemon zest (from 1 lemon)","¾ cup crumbled feta (3 ounces), plus more for garnish","½ cup frozen peas, thawed (optional)","1 cup chopped fresh dill, or use parsley or cilantro"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat a 10-inch skillet over medium, then melt butter, 30 seconds to 1 minute. Stir in about three-quarters of the scallions (saving some of the green parts for garnish) and garlic, and cook until softened, stirring frequently, about 3 minutes."},{"n":2,"title":null,"text":"Stir in spinach, adding in batches if it doesn’t all fit in the pan at once, and ½ teaspoon salt. Continue to cook, stirring occasionally, until spinach is wilted, about 5 minutes."},{"n":3,"title":null,"text":"Stir in stock and bring to a simmer. Stir in orzo, lemon zest and remaining ½ teaspoon salt. Cover and simmer over medium-low heat until orzo is nearly cooked through and most of the liquid is absorbed, 10 to 14 minutes, stirring once or twice."},{"n":4,"title":null,"text":"Stir in cheese, peas (if you like) and dill, cover the pan, and cook for another 1 minute, to finish cooking and warm the peas. To serve, sprinkle with more cheese and the reserved scallions."}],"tips":[],"cuisine_tags":["Greek","Mediterranean"],"ingredient_tags":["orzo","peas","spinach"],"item_tags":["dill","feta","lemon"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Boil","Dinner","Easy","Feta","Main Course","One Pot","Orzo","Pastas","Side Dish","Skillet","Spinach","Summer","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021485.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021485-one-pan-orzo-with-spinach-and-feta","rating":{"value":5,"count":22785},"date":"2020-09-30"},{"pair":12899,"title":"Lasagna With Roasted Kabocha Squash and Béchamel","subtitle":null,"author":"Martha Rose Shulman","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"2 hours","nutrition":{"calories":"341","fat":"12 g","carbohydrates":"46 g","protein":"16 g"},"description":"This rich-tasting lasagna is inspired by my favorite northern Italian pumpkin-filled ravioli. It would make a terrific vegetarian item on a Thanksgiving buffet. Making the lasagna is not time-consuming if you use no-boil lasagna noodles. Be sure to season the squash well as you assemble this","from_your_kitchen":null,"ingredients":["3 pounds kabocha squash","3 tablespoons extra virgin olive oil","3 tablespoons minced shallot or onion","3 tablespoons sifted all-purpose flour","3 cups low-fat milk (1 percent)","Salt and freshly ground pepper","Pinch of freshly grated nutmeg","2 tablespoons chopped fresh sage","½ pound no-boil lasagna noodles (or a little more, depending on the size of your lasagna pan)","4 ounces Parmesan cheese, grated (1 cup)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 425 degrees. Line a baking sheet with foil. Cut the squash into big chunks, brush the exposed flesh with 1 tablespoon of the olive oil and place on the baking sheet. Bake 45 minutes or until squash is tender enough to be pierced through to the skin with a paring knife. Remove from the heat and allow to cool until you can handle it, then cut away the skin and cut in thin slices. Turn the oven down to 350 degrees"},{"n":2,"title":null,"text":"While the squash is in the oven, make the béchamel. Heat the remaining oil over medium heat in a heavy medium saucepan. Add the shallot or onion and cook, stirring, until it has softened, about 3 minutes. Stir in the flour and cook, stirring, for about 3 minutes, until the mixture is smooth and bubbling, but not browned. It should have the texture of wet sand. Whisk in the milk all at once and bring to a simmer, whisking all the while, until the mixture begins to thicken. Turn the heat to very low and simmer, stirring often with a whisk and scraping the bottom and edges of the pan with a rubber spatula, for 10 to 15 minutes, until the sauce is thick and has lost its raw flour taste. Season with salt, pepper and nutmeg. Strain while hot into a large measuring cup or a medium bowl and stir in ¼ cup of the Parmesan and 1 tablespoon of the sage"},{"n":3,"title":null,"text":"Preheat the oven to 350 degrees. Oil a rectangular baking dish. Spread a spoonful of béchamel over the bottom. Top with a layer of lasagna noodles. Spread a thin layer of the béchamel over the noodles. Top with half the squash. Season the squash with salt and pepper and sprinkle with Parmesan. Repeat the layers, ending with a layer of lasagna noodles topped with béchamel and Parmesan. Sprinkle the remaining sage over the top. Make sure the noodles are well coated with béchamel so they will soften during baking"},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 5 to 10 minutes until the top begins to brown. Remove from the heat and allow to sit for 5 minutes before serving"}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["pasta","squash"],"item_tags":["nutmeg","parmesan","sage"],"course_tags":["Dinner"],"keywords":["American","Bake","Casseroles","Dinner","Fall","Great Leftovers","Healthy","High Fiber","Kabocha","Lasagna","Main Course","Parmesan","Roast","Saute","Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_12899.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12899-lasagna-with-roasted-kabocha-squash-and-bechamel","rating":{"value":4,"count":398},"date":"2012-10-30"},{"pair":1017968,"title":"Winter Citrus Salad With Belgian Endive","subtitle":null,"author":"David Tanis","servings":"2","yield_text":"2 servings","yield_count":2,"cook_time":"15 minutes","nutrition":{"calories":"250","fat":"14 g","carbohydrates":"33 g","protein":"3 g"},"description":"Late winter really is the time for the best citrus. Produce markets have piles of blood oranges, as well as navel and cara cara oranges and grapefruit, the flesh of each in different vivid brilliant colors. For this salad, use as many kinds of citrus as possible. If you can find pomelos, they add their own kind of sweet tanginess. The combined flavor of sweet and sour citrus, fruity olive oil and coarse salt is seductive.","from_your_kitchen":null,"ingredients":["1 blood orange","1 cara cara or navel orange","1 grapefruit","1 small shallot, finely diced","1 tablespoon red wine vinegar","2 tablespoons extra virgin olive oil","Salt and pepper","2 Belgian endives, trimmed","Coarse sea salt for garnishing, such as fleur de sel"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Peel the citrus: With a serrated knife, cut off top and bottom of the fruit, so it sits solidly on the cutting board. Cut top to bottom following fruit’s curve to remove peel and white pith. Slice the oranges and grapefruit horizontally into ⅛-inch rounds and place them in a bowl. Save the accumulated juice in the bowl for the vinaigrette."},{"n":2,"title":null,"text":"Make the vinaigrette: Combine the shallots with red wine vinegar in a small bowl. Let stand for 10 minutes, then whisk in the olive oil and 2 tablespoons of the reserved citrus juice. Season with salt and pepper to taste."},{"n":3,"title":null,"text":"Slice the endives crosswise into 1-inch thick ribbons (but slice the dense core thinner) and place in the center of a salad plate."},{"n":4,"title":null,"text":"Surround the endive with citrus slices. Drizzle the vinaigrette over the salad and sprinkle lightly with coarse sea salt."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["endive","grapefruit","oranges"],"item_tags":["red wine vinegar","shallot"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["American","Appetizer","Dinner","Easy","For One","For Two","Grapefruit","Lunch","Main Course","Orange","Quick","Salad","Side Dish","Valentine’s Day","Weeknight"],"issues":null,"front":"nyt_1017968.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017968-winter-citrus-salad-with-belgian-endive","rating":{"value":5,"count":170},"date":"2016-02-10"},{"pair":1019385,"title":"Creamy White Beans With Herb Oil","subtitle":null,"author":"Colu Henry","servings":"2 to 4","yield_text":"2 to 4 servings","yield_count":2,"cook_time":"15 minutes","nutrition":{"calories":"563","fat":"36 g","carbohydrates":"48 g","protein":"16 g"},"description":"Canned beans are transformed into a hearty, elegant main swirled with an herb oil that comes together in no time with the aid of a food processor. This particular oil includes chives, cilantro and basil, but feel free to use what you have on hand. Parsley and mint would also work well. Serve with a chilled glass of red wine, a big green salad and a loaf of crusty bread.","from_your_kitchen":null,"ingredients":["½ cup roughly chopped chives","½ cup roughly chopped cilantro leaves and tender stems","½ cup tightly packed basil leaves","½ cup olive oil","Squeeze of lemon","Kosher salt, to taste","2 tablespoons olive oil","2 garlic cloves, thinly sliced","2 (15-ounce) cans white beans, like butter beans or cannellini, rinsed and drained","Kosher salt and black pepper","½ cup chicken stock, vegetable stock or water","Flaky salt, for serving (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE HERB OIL"},{"at":6,"title":"FOR THE BEANS"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the oil: In a food processor, combine chives, cilantro and basil, and pulse until finely chopped. Add olive oil, and pulse again until mixture is silky and emulsified. Transfer to a small bowl, stir in lemon juice and salt to taste. Set aside."},{"n":2,"title":null,"text":"Prepare the beans: In a 10-inch skillet, heat olive oil over medium-low heat. Add garlic and cook until translucent, about 1 minute. Add beans to the skillet and season with salt and pepper. Cook, stirring occasionally, until the flavors have melded, about 2 to 3 minutes. With the back of a spoon or spatula, smash about ⅓ to ½ cup of the beans and stir until they are incorporated into the rest of the bean mixture. A good portion of the remaining beans should maintain their structure."},{"n":3,"title":null,"text":"Add stock or water and bring to a gentle simmer. Cook until sauce becomes creamy and is reduced by about about half, about 1 to 2 minutes more. Smash additional beans and add a few more tablespoons of water, if needed, to reach desired consistency and stir again to combined."},{"n":4,"title":null,"text":"Transfer beans to a bowl and swirl with herb oil on top. Season with flaky salt, if desired."}],"tips":[],"cuisine_tags":["Mediterranean"],"ingredient_tags":["white beans"],"item_tags":["basil","chives","cilantro","lemon"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Basil","Beans","Chive","Cilantro","Dinner","Easy","Food Processor","For Two","Kid-Friendly","Lunch","Main Course","Olive Oil","Quick","Side Dish","Vegan","Vegetarian","Weeknight","White Bean"],"issues":null,"front":"nyt_1019385.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019385-creamy-white-beans-with-herb-oil","rating":{"value":5,"count":9241},"date":"2018-09-26"},{"pair":1017704,"title":"Vegetarian Skillet Chili","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"300","fat":"1 g","carbohydrates":"58 g","protein":"18 g"},"description":"If you keep canned beans, tomatoes, onion and garlic in your pantry, you can make this dish on any weeknight without having to shop. The pickled onions aren’t strictly necessary, but they are simple to make and add a welcome tangy contrast to the beans. Pickled peppers are a fine substitute. If you have a bell pepper or jalapeño or two, chop them up and sauté them with the onions. And if you want to be fancy, grate the zest off the lime before juicing for the pickles, and stir it into the sour cream.","from_your_kitchen":null,"ingredients":["1 lime","1 red onion or shallot, thinly sliced","Large pinch of kosher salt","Small pinch of granulated sugar","Olive or grapeseed oil","1 large onion, chopped","3 garlic cloves, or to taste, minced","1 teaspoon chile powder, plus more to taste","1 teaspoon dried oregano, plus more to taste","2 (15-ounce) cans beans, drained","1 (15-ounce) can diced tomatoes with their juices","Kosher salt","Fresh cilantro, diced avocado and sour cream, for garnish (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE PICKLED ONIONS"},{"at":4,"title":"FOR THE CHILI"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the pickled onions: Squeeze lime juice into a bowl, and add onion, salt and sugar. Let rest while you make the chili."},{"n":2,"title":null,"text":"Prepare the chili: Heat a large skillet over medium-high. Add the oil. When hot, add onion and sauté until softened, 5 to 7 minutes. Add garlic, chile powder and oregano and sauté until fragrant, 1 to 2 minutes longer. Add beans and tomatoes and a few large pinches of salt and let simmer until the tomatoes break down, about 20 minutes."},{"n":3,"title":null,"text":"Taste and add more salt, chile powder and/or oregano to taste. Serve with the pickled onions and any of the garnishes you like."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["beans","tomato"],"item_tags":["chile powder","lime","oregano"],"course_tags":["Dinner"],"keywords":["Bean","Canned Tomato","Chili","Dinner","Easy","Great Leftovers","Kid-Friendly","Main Course","Quick","Skillet","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1017704.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017704-vegetarian-skillet-chili","rating":{"value":5,"count":11803},"date":"2015-09-23"},{"pair":1015146,"title":"Lasagna With Tomato Sauce and Roasted Eggplant","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"Serves 6","yield_count":6,"cook_time":"About 2 hours","nutrition":{"calories":"452","fat":"20 g","carbohydrates":"46 g","protein":"22 g"},"description":"This is a great do-ahead dish. I made two of them for a dinner party during a very busy week; I roasted the eggplant one day, made the sauce another, assembled the lasagnas quickly on the morning of my dinner party and refrigerated them until I got home about an hour before my guests were due to arrive.","from_your_kitchen":null,"ingredients":["1 ¼ pounds eggplant, sliced and roasted","2 tablespoons extra virgin olive oil, plus additional for drizzling","Salt and freshly ground pepper","8 ounces ricotta cheese","1 egg","2 tablespoons water","Pinch (tiny!) of cinnamon","Salt and freshly ground pepper","2 cups marinara sauce","½ pound no-boil lasagna noodles","Chopped fresh basil","4 ounces fresh mozzarella, shredded (optional)","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 450 degrees. Line a baking sheet with foil and brush the foil lightly with olive oil. Slice the eggplant ⅓ inch thick, sprinkle with salt and toss with 2 tablespoons of olive oil. Place on the baking sheet and roast 15 to 20 minutes, until the slices are lightly colored on the bottom and soft to the tip of a knife. Remove from the oven, and carefully fold the foil over and crimp the edges together (be careful not to burn yourself!). Let the eggplant cool and steam in the foil packet for 20 minutes. Set aside and turn the oven down to 350 degrees."},{"n":2,"title":null,"text":"Lightly oil a rectangular baking dish. Blend the ricotta cheese with the egg, water, cinnamon, and salt and pepper to taste. Set aside ½ cup of tomato sauce and 3 tablespoons of Parmesan to make sure you have enough for the top layer of the lasagna."},{"n":3,"title":null,"text":"Spread a small spoonful of tomato sauce in a thin layer over the bottom of the baking dish. Top with a layer of lasagna noodles. Top the noodles with a thin layer of ricotta. Spoon on a few dollops then spread it with an offset or a rubber spatula. Top the ricotta with half the eggplant, and sprinkle basil and half the mozzarella over the eggplant. Top with a layer of tomato sauce and a layer of Parmesan. Repeat the layers, then add a final layer of lasagna noodles topped with ricotta if any remains, and most importantly with the tomato sauce and Parmesan you set aside. Drizzle a little bit of olive oil over the top."},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Remove from the heat and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["eggplant","pasta"],"item_tags":["basil","mozzarella","parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["Bake","Casseroles","Dinner","Eggplant","Fall","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Roast","Summer","Vegetarian"],"issues":null,"front":"nyt_1015146.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015146-lasagna-with-tomato-sauce-and-roasted-eggplant","rating":{"value":4,"count":863},"date":"2013-09-25"},{"pair":1020979,"title":"Five-Ingredient Creamy Miso Pasta","subtitle":null,"author":"Alexa Weibel","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"744","fat":"29 g","carbohydrates":"89 g","protein":"30 g"},"description":"This one-pot pasta comes together in minutes, and requires zero prep and minimal cleanup. It builds on the classic combination of pasta, butter and cheese with a spoonful of miso paste for complexity. But you could experiment with using any other condiments or spices you have on hand, such as red pesto, curry paste or ground turmeric in place of the miso. To achieve a silky smooth pasta, you’ll need to put your cacio e pepe skills to work: Vigorously toss the pasta, grated cheese and pasta water together to achieve a properly emulsified sauce. Top with shrimp, edamame, frozen peas or any steamed vegetable. The optional nori or furikake imparts an unexpected flavor of the sea, and it’s worth using if you have it on hand.","from_your_kitchen":null,"ingredients":["Kosher salt","16 ounces spaghetti, linguine or bucatini","6 tablespoons unsalted butter","3 tablespoons white (or red) miso","4 ounces Parmesan, finely grated (1 packed cup)","Kizami nori, furikake or thinly sliced seaweed snacks, for garnish (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of salted water to a boil. Add the pasta and cook, stirring occasionally, until al dente. Reserve 1 ½ cups pasta water, then drain the pasta."},{"n":2,"title":null,"text":"Add the butter, miso and 1 ¼ cups pasta water to the pot and whisk over medium heat until miso breaks down and liquid is uniform, 1 to 2 minutes. Add the pasta and Parmesan and cook, stirring vigorously with tongs until cheese is melted and sauce emulsifies. (The key word here is “vigorously.” To achieve a silky smooth pasta instead of a gloppy one, put your cacio e pepe skills to work.)"},{"n":3,"title":null,"text":"Divide among shallow bowls and sprinkle with nori or furikake, if using."}],"tips":[],"cuisine_tags":["Fusion","Japanese"],"ingredient_tags":["pasta"],"item_tags":["miso","parmesan"],"course_tags":["Dinner"],"keywords":["Butter","Dinner","Easy","Five Ingredient","Linguine","Main Course","Miso","One Pot","Parmesan","Pastas","Quick","Spaghetti","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020979.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020979-five-ingredient-creamy-miso-pasta","rating":{"value":5,"count":13577},"date":"2020-04-22"},{"pair":1015843,"title":"Charlie Bird’s Farro Salad","subtitle":null,"author":"Melissa Clark","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"45 minutes","nutrition":{"calories":"399","fat":"27 g","carbohydrates":"32 g","protein":"12 g"},"description":"There are two essential steps to a stellar farro salad. The first is cooking the farro with enough salt and aromatics so that it delicious before you combine it with the rest of the ingredients. The second is to use very good olive oil in the dressing. This farro salad, from the restaurant Charlie Bird in SoHo, hits both these marks. The chef Ryan Hardy cooks the farro in apple cider seasoned with bay leaves and plenty of salt, which renders it good enough to eat on its own. But it’s even better after he adds loads of olive oil, plus pistachio nuts and Parmesan cheese to make it even richer. Then, before serving, he folds in fresh vegetables to brighten it up: juicy tomatoes, radishes, arugula and plenty of herbs. There are many farro salads of this ilk out there. This is one of the best.","from_your_kitchen":null,"ingredients":["1 cup farro","1 cup apple cider","2 teaspoons kosher salt, more as needed","2 bay leaves","8 tablespoons extra-virgin olive oil","2 tablespoons fresh lemon juice","70 grams Parmesan cheese, shaved with a vegetable peeler (½ cup)","70 grams chopped pistachio nuts (½ cup)","2 cups arugula leaves","1 cup parsley or basil leaves, torn","1 cup mint leaves","¾ cup halved cherry or grape tomatoes","⅓ cup thinly sliced radish","Maldon or other flaky sea salt, for finishing"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a medium saucepan, bring farro, apple cider, salt, bay leaves and 2 cups water to a simmer. Simmer until farro is tender and liquid evaporates, about 30 minutes. If all the liquid evaporates before the farro is done, add a little more water. Let farro cool, then discard bay leaves."},{"n":2,"title":null,"text":"In a salad bowl, whisk together olive oil, lemon juice and a pinch of salt. Add farro, cheese and pistachio nuts and mix well. This salad base will keep for up to 4 hours at room temperature or overnight in the refrigerator (bring to room temperature before serving). Just before serving, fold in arugula, herbs, tomatoes, radish and flaky salt to taste."}],"tips":[],"cuisine_tags":["American","Mediterranean"],"ingredient_tags":["arugula","farro"],"item_tags":["lemon","mint","parmesan","pistachios"],"course_tags":["Dinner","Lunch"],"keywords":["Apple Cider","Arugula","Dinner","Easy","Farro","Grain Bowl","Lunch","Main Course","Pistachio","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1015843.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015843-charlie-birds-farro-salad","rating":{"value":5,"count":11989},"date":"2013-12-17"},{"pair":1019468,"title":"Green Shakshuka With Avocado and Lime","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"472","fat":"36 g","carbohydrates":"18 g","protein":"21 g"},"description":"This easy twist on classic North African shakshuka (traditionally eggs baked in tomato-pepper sauce, with cumin, paprika and cayenne) starts with an onion-garlic-chard sautéed until gently wilted: a nest of sorts for steam-poaching eggs. Once the eggs go in, be sure to keep the flame low and keep the pan covered while cooking, so the eggs stay soft and almost oozy at their yolk, and the Cotija melts a bit. The chard and the half-and-half create a sort of light broth at the bottom of the shakshuka, which holds so much flavor and is one of the dish’s charms. Lastly, be daring with smoked hot sauce at the end: It’ll push the creamy avocado, cheese and eggs to their peak.","from_your_kitchen":null,"ingredients":["3 tablespoons olive oil","1 yellow onion, peeled and thinly sliced","2 garlic cloves, thinly sliced","1 large bunch/1 ½ pounds Swiss chard, stems and leaves separated and chopped (about 9 cups)","½ teaspoon salt, plus more as needed","⅓ cup half-and-half or heavy cream","8 large eggs","¼ teaspoon black pepper, plus more as needed","3 ounces Cotija cheese or queso fresco, crumbled (about ¾ cup)","1 avocado, sliced, for serving","1 small jalapeño, thinly sliced, for serving","Chopped cilantro, for serving","Smoked hot sauce, for serving","Corn tortillas, toasted, for serving","1 lime, cut into wedges, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oil in a large cast-iron skillet over medium-low heat. Add onion and cook until softening, 5 minutes. Add the garlic and cook until fragrant, 5 minutes more."},{"n":2,"title":null,"text":"Raise the heat to medium-high, add the chard stems, and cook to release some liquid, 5 minutes. Add the chard leaves, in batches, adding more as they wilt, and continue cooking, stirring occasionally, until completely wilted, 3 to 5 minutes more. Season with ½ teaspoon salt, pour in the half-and-half and stir loosely together."},{"n":3,"title":null,"text":"Make eight small hollows in the cooked chard with the back of a spoon. Gently crack an egg into each hollow. Cover with a lid or foil and cook on medium-low until the eggs are just set, but still soft, about 7 to 9 minutes. Remove the lid, sprinkle with salt, pepper, Cotija, avocado, jalapeño and cilantro. Serve with smoked hot sauce, toasted tortillas and lime wedges."}],"tips":["Some cast-iron skillets come with a matching lid, which is useful for making the skillet operate a bit like a mini stove-top oven, cooking evenly and basting the food with flavor and steam. If you don’t have one, use a lid from another pan, or two layers of thick foil, folded at the center and large enough to cover your pan."],"cuisine_tags":["Fusion","Middle Eastern"],"ingredient_tags":["avocado","eggs","swiss chard"],"item_tags":["cilantro","cotija","jalapeño","lime"],"course_tags":["Breakfast","Dinner"],"keywords":["Breakfast","Brunch","Cast Iron","Cotija","Dinner","Easy","Egg","Egg Dish","Half and Half","Heavy Cream","Main Course","Queso Fresco","Skillet","Steam","Swiss Chard","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019468.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019468-green-shakshuka-with-avocado-and-lime","rating":{"value":4,"count":6051},"date":"2018-08-08"},{"pair":12477,"title":"Lasagna With Spicy Roasted Cauliflower","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 30 minutes","nutrition":{"calories":"352","fat":"14 g","carbohydrates":"40 g","protein":"18 g"},"description":"Now that I’ve discovered how delicious roasted cauliflower is and how easy it is to do it, that’s the only way I want to cook it. It might be difficult to abstain from eating the cauliflower before you’ve gotten it into your lasagna.","from_your_kitchen":null,"ingredients":["1 ½ pounds cauliflower (¾ of a medium head)","2 tablespoons extra virgin olive oil","Salt and freshly ground pepper","¼ to ½ teaspoon red pepper flakes","3 cups marinara sauce, preferably homemade from fresh or canned tomatoes","7 to 8 ounces no-boil lasagna","8 ounces ricotta cheese","2 tablespoons water, vegetable stock or chicken stock","Pinch of cinnamon","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 450 degrees. Line a baking sheet with parchment paper. Cut away the bottom of the cauliflower stem and trim off the leaves. Cut the cauliflower into slices ⅓ inch thick, letting the florets on the edges fall off. Toss all of it, including the bits that have fallen away, with the olive oil, salt and pepper. Place on the baking sheet in an even layer. Roast for about 15 minutes, stirring and flipping over the big slices after 8 minutes, until the slices are tender when pierced with a paring knife and the small florets are nicely browned. Remove from the oven, toss with the red pepper flakes and set aside. Turn the oven down to 350 degrees."},{"n":2,"title":null,"text":"Blend the ricotta cheese, water or stock, cinnamon, salt and pepper. Set aside."},{"n":3,"title":null,"text":"Oil a rectangular baking dish and spread a spoonful of tomato sauce over the bottom. Top with a layer of lasagna noodles. Spoon a thin layer of the ricotta mixture over the noodles. Top with a layer of cauliflower, then a layer of tomato sauce and a layer of Parmesan. Repeat the layers, ending with a layer of lasagna noodles topped with tomato sauce and Parmesan."},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 10 minutes, until the top begins to brown. Remove from the heat and allow to sit for 5 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["cauliflower","pasta"],"item_tags":["parmesan","red chile flakes","ricotta"],"course_tags":["Dinner"],"keywords":["Bake","Casseroles","Cauliflower","Dinner","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Roast","Vegetarian","Winter"],"issues":null,"front":"nyt_12477.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12477-lasagna-with-spicy-roasted-cauliflower","rating":{"value":5,"count":664},"date":"2012-05-31"},{"pair":12389,"title":"Seaweed Salad","subtitle":null,"author":"David Tanis","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"About 20 minutes","nutrition":{"calories":"168","fat":"12 g","carbohydrates":"14 g","protein":"4 g"},"description":"Seaweed comes in many forms, and is used extensively in Japanese cuisine. Most of us are familiar with the pressed sheets of nori that are wrapped around sushi, and kombu, the dark green algae that is simmered to make classic dashi broth. Japanese groceries have a dizzying array of salt-packed specialty varieties, but many supermarkets and health-food stores sell packages of dried seaweed, which may be the most user-friendly. Two types that are commonly available are reddish-purple dulse and bright green wakame. Both simply need bathing in cold water for a few minutes to soften and ready them for use. Once soaked and drained, the seaweed is tossed with a simple traditional dressing of sesame oil with ginger and soy. My version makes a fine vegetarian meal, with thin slices of carrot, radish, cucumber and daikon, along with avocado, green onion, pumpkin seeds and sesame seeds.","from_your_kitchen":null,"ingredients":["1 ounce dried red dulse seaweed","1 ounce dried green wakame seaweed","2 tablespoons rice-wine vinegar","2 teaspoons sugar","2 teaspoons grated ginger","½ teaspoon wasabi powder","2 teaspoons soy sauce","1 tablespoon roasted sesame oil","Juice of 1 lime","Sea salt, to taste","1 small carrot, peeled and sliced paper-thin","4 red radishes, thinly sliced","2 ounces daikon radish, peeled and thinly sliced","1 small cucumber, peeled and thinly sliced","1 firm-ripe avocado, sliced","1 teaspoon toasted white sesame seeds","1 teaspoon toasted black sesame seeds","2 teaspoons toasted pumpkin seeds","4 green onions, slivered"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put the dulse and wakame in a large bowl and cover with cold water. Let soak 5 to 10 minutes, until softened. Drain in a colander, pat dry and place in a serving bowl."},{"n":2,"title":null,"text":"To make the dressing, whisk together the rice vinegar, sugar, ginger, wasabi powder, soy sauce and sesame oil in a small bowl."},{"n":3,"title":null,"text":"Spoon half the dressing over the seaweed, add the lime juice and toss gently. Taste and add a small amount of salt if necessary. Surround the salad with the carrot, radish, daikon, cucumber and avocado. Season them lightly with salt and drizzle with the remaining dressing."},{"n":4,"title":null,"text":"Sprinkle the salad with the white and black sesame seeds, pumpkin seeds and green onions."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["avocado","cucumber","radish","seaweed"],"item_tags":["ginger","lime","sesame oil","sesame seeds"],"course_tags":["Sides & Appetizers"],"keywords":["Cucumber","Dairy-Free","Japanese","Quick","Radish","Salad","Seaweed","Vegetarian"],"issues":null,"front":"nyt_12389.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12389-seaweed-salad","rating":{"value":4,"count":215},"date":"2012-04-18"},{"pair":1020047,"title":"Somen Noodle Soup With Mushrooms","subtitle":null,"author":"Sue Li","servings":"2","yield_text":"2 servings","yield_count":2,"cook_time":"20 minutes","nutrition":{"calories":"400","fat":"24 g","carbohydrates":"34 g","protein":"13 g"},"description":"The perfect salve for cold winter days, this vegetarian noodle soup can be cobbled together in an instant from the contents of a well-stocked kitchen. It takes its flavor from a quick bouillon using just four ingredients: soy sauce, sesame oil, scallions and shiitakes, which deliver a hefty, flavorful dose of glutamate. Poached eggs add richness to the clean and comforting broth. Fresh eggs have stronger, firmer albumen (egg whites) and will thus hold their shape better than older eggs, which have a tendency to unfurl. The main key to achieving that teardrop shape during poaching is allowing the eggs to simmer without disturbance until cooked.","from_your_kitchen":null,"ingredients":["2 tablespoons vegetable oil","3 scallions, trimmed, whites and greens separated and thinly sliced","8 ounces fresh shiitake mushrooms, stems discarded and caps thinly sliced (about 3 cups)","Kosher salt","1 medium bok choy (about 4 ounces), cut into bite-size pieces","3 tablespoons soy sauce","2 teaspoons toasted sesame oil, plus more for serving","2 bundles (about 7 ounces total) somen noodles, or any thin wheat or rice noodles","2 large eggs"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large saucepan of water to a simmer."},{"n":2,"title":null,"text":"Heat vegetable oil in a pot over medium. Add scallion whites and sliced mushrooms, season with salt and cook until browned, stirring occasionally, 5 to 6 minutes."},{"n":3,"title":null,"text":"Add 3 cups water to the pot and bring to a simmer over medium-high. Add bok choy and cook until crisp-tender, about 1 minute. Stir in soy sauce and 2 teaspoons sesame oil and season to taste with salt. Turn off heat and cover to keep warm."},{"n":4,"title":null,"text":"Meanwhile, cook somen according to package instructions in the simmering water in the saucepan. Using a slotted spoon or spider, divide the noodles among bowls, leaving the simmering water in the saucepan. Crack each egg into its own small bowl, discarding the shells. Swirl the simmering water in the saucepan, creating a vortex by stirring with a wooden spoon. Add the eggs, one right after another, and cook over medium-low until the whites are set, about 3 minutes. Transfer eggs to noodle bowls using a slotted spoon."},{"n":5,"title":null,"text":"Ladle the reserved shiitake broth into the bowls. Top with sliced scallion greens, drizzle with sesame oil and serve."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["bok choy","mushrooms","noodles"],"item_tags":["scallions","sesame oil","soy sauce"],"course_tags":["Dinner"],"keywords":["Asian","Bok Choy","Dinner","Easy","Fall","For Two","Main Course","Noodle","Quick","Scallion","Sesame Oil","Shiitake","Soup","Soy Sauce","Spring","Vegetarian","Weeknight","Winter"],"issues":null,"front":"nyt_1020047.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020047-somen-noodle-soup-with-mushrooms","rating":{"value":5,"count":1986},"date":"2019-02-20"},{"pair":1021535,"title":"Spicy Butternut Squash Pasta With Spinach","subtitle":null,"author":"Yasmin Fahr","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"907","fat":"32 g","carbohydrates":"122 g","protein":"41 g"},"description":"Here’s a vegetable-filled pasta bake that comes together in under an hour. The most time-consuming part of this recipe is prepping the squash. You can buy precut squash, or cut it yourself: Trim the ends so that it can stand up flat. Use a sturdy vegetable peeler to remove the skin. Cut off the bulbous part from the neck. Scoop the seeds out of the bulbous part. Half the squash lengthwise, then cube it. If you’re sensitive to heat, leave out the jalapeños, or remove the seeds before slicing into rounds and placing on top.","from_your_kitchen":null,"ingredients":["Kosher salt","3 tablespoons olive oil, plus more for serving","1 medium butternut squash (about 2 ½ pounds), peeled, seeds removed and cut into ½-inch cubes (about 6 cups)","1 tablespoon ground cumin (see Tip)","½ teaspoon red-pepper flakes, plus more as needed","1 pound penne or other tubular pasta","1 cup low-sodium vegetable broth (or water)","¾ cup grated Parmesan","3 packed cups baby spinach","1 (8-ounce) ball fresh mozzarella, torn into bite-size chunks","1 jalapeño, sliced into rounds","⅓ cup flat-leaf parsley and tender stems, roughly chopped"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large covered pot of heavily salted water to a boil."},{"n":2,"title":null,"text":"Meanwhile, in a 12-inch ovenproof skillet with high sides and a tight-fitting lid (or a Dutch oven), heat the oil over medium-high until shimmering. Add the squash and season with salt, cumin and red-pepper flakes. Cook, stirring every minute, until squash becomes browned in spots and feels just tender, 6 to 8 minutes."},{"n":3,"title":null,"text":"Meanwhile, heat the oven to 400 degrees. Add the pasta to the boiling water and cook, uncovered, until not quite al dente, 3 to 4 minutes less than the package instructions. (It should be a little too firm to the bite.) Reserve 1 cup of the pasta water and drain. If the pasta is done before the squash, then stir in a drizzle of olive oil so that it doesn’t stick together."},{"n":4,"title":null,"text":"When the squash is just tender, add the broth. Bring to an active simmer, cover and cook, stirring occasionally, until the squash is soft and easily mashable, 10 to 12 minutes. Turn off the heat, then use a potato masher or the back of a wooden spoon to crush about half of the butternut squash and leave the rest chunky. Season the squash to taste, keeping in mind that salty Parmesan will be added soon."},{"n":5,"title":null,"text":"Add the cooked pasta to the skillet along with 1 cup reserved pasta water and ½ cup grated Parmesan, stirring vigorously to combine. Stir in the spinach one handful at a time until it shrinks down a little."},{"n":6,"title":null,"text":"Sprinkle the top with the remaining ¼ cup Parmesan, the mozzarella and jalapeño, then place in the oven, on a sheet pan if you are worried about dripping. Cook until the top is melted and browned in spots, 12 to 15 minutes. Drizzle with olive oil, top with parsley and serve."}],"tips":["If you have a preferred curry powder, then you can use 1 to 3 teaspoons of that (according to taste) in place of the cumin and red-pepper flakes."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["butternut squash","pasta","spinach"],"item_tags":["cumin","jalapeño","mozzarella","parmesan"],"course_tags":["Dinner"],"keywords":["Butternut Squash","Dinner","Fall","Jalapeño","Main Course","Mozzarella","Parmesan","Pastas","Penne","Spinach","Vegetarian","Weeknight","Winter"],"issues":null,"front":"nyt_1021535.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021535-spicy-butternut-squash-pasta-with-spinach","rating":{"value":4,"count":8365},"date":"2020-10-08"},{"pair":1012786,"title":"Soba Salad","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"15 minutes","nutrition":{"calories":"207","fat":"4 g","carbohydrates":"33 g","protein":"15 g"},"description":"For most people, even experienced cooks, weeknight dinners are not so much a result of careful planning but of what’s on hand — and what can be accomplished fairly quickly. Noodles of all kinds are easy and beloved. But soba noodles, a Japanese staple, are special: they usually take no more than 3 to 4 minutes to cook and, because they’re made from buckwheat, have a slightly firm texture and a nutty flavor. Traditionally, soba are served hot and cold, making them a flexible partner for almost any fresh ingredients you have in the kitchen. In this case, they are paired with shelled frozen edamame, carrots and spinach and a light dressing.","from_your_kitchen":null,"ingredients":["Salt","freshly ground pepper","3 to 4 ounces soba noodles","1 carrot, peeled and finely chopped","2 cups edamame (frozen are fine)","2 to 3 tablespoons soy sauce","Juice of one lime","2 tablespoons white or light miso","1 tablespoon mirin or 1 teaspoon sugar, or to taste","1 10-ounce package fresh spinach, washed and trimmed","¼ cup chopped scallion","1 tablespoon freshly grated ginger"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of water to a boil and salt it. Drop in the noodles and carrot and cook until tender, 2 to 4 minutes; add the edamame for about 15 to 30 seconds just to warm, then drain everything in a colander. Set aside."},{"n":2,"title":null,"text":"In a large salad bowl, whisk together the soy sauce, lime juice, miso and mirin or sugar. Add spinach, noodles, carrot, edamame, scallion, and toss; then taste and season with salt and pepper as needed. Garnish with grated ginger at the table."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["edamame","soba noodles","spinach"],"item_tags":["ginger","miso","scallions","soy sauce"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Asian","Boil","Main Course","Quick","Salad","Side Dish","Vegan","Vegetarian"],"issues":null,"front":"nyt_1012786.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1012786-soba-salad","rating":{"value":4,"count":2504},"date":"2009-09-23"},{"pair":12864,"title":"Sake-Steamed Kabocha Squash With White Miso","subtitle":null,"author":"David Tanis","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"About 30 minutes","nutrition":{"calories":"144","fat":"8 g","carbohydrates":"12 g","protein":"2 g"},"description":"This steamed kabocha squash is astonishingly delicious straight from the pan or cold the next day. David Tanis","from_your_kitchen":null,"ingredients":["1 pound kabocha squash (about half a medium squash), seeds removed","3 tablespoons white miso","6 tablespoons sake","3 tablespoons canola oil or mild vegetable oil","6 small dried red chile peppers","Kosher salt","1 teaspoon sesame oil, optional"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Using a vegetable peeler, peel squash very lightly, still keeping it green at the edge. Cut squash lengthwise into 1-inch-wide wedges, then cut the wedges crosswise into ¼-inch slices."},{"n":2,"title":null,"text":"In a small bowl, combine miso and 3 tablespoons sake, stir and set aside."},{"n":3,"title":null,"text":"Heat oil in a wide skillet over medium. Add chile peppers and let them sizzle, then add squash and stir to coat. Sprinkle lightly with salt. Spread out squash slices in one layer and cook gently without browning for about 3 minutes. Add remaining 3 tablespoons of sake and cover with lid. Allow squash to steam for about 2 minutes more, until it is just cooked through."},{"n":4,"title":null,"text":"Add miso-sake mixture and sesame oil, if using, carefully combining to coat squash slices without smashing or breaking them. Serve hot, at room temperature or cold."}],"tips":[],"cuisine_tags":["Japanese"],"ingredient_tags":["chile peppers","squash"],"item_tags":["miso","sake","sesame oil"],"course_tags":["Sides & Appetizers"],"keywords":["Easy","Japanese","Kabocha","Quick","Sake","Side Dish","Stir-Fry","Summer","Vegan","Vegetarian"],"issues":null,"front":"nyt_12864.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12864-sake-steamed-kabocha-squash-with-white-miso","rating":{"value":4,"count":276},"date":"2012-10-17"},{"pair":1015522,"title":"Cabbage and Mushroom “Lasagna”","subtitle":null,"author":"Elaine Louie","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"2 hours","nutrition":{"calories":"488","fat":"28 g","carbohydrates":"39 g","protein":"20 g"},"description":"Elaine Louie","from_your_kitchen":null,"ingredients":["9 tablespoons unsalted butter","3 tablespoons plus 1 teaspoon unbleached all-purpose flour","2 ⅔ cups whole milk","¼ teaspoon freshly ground nutmeg","Salt and ground black pepper","1 medium onion, chopped","1 garlic clove, minced","1 pound assorted fresh mushrooms (shiitake, oyster, porcini, chanterelles, cremini), thinly sliced","1 tablespoon finely chopped fresh sage","2 pounds Napa cabbage, 12 large leaves removed from the head, and reserved, the remainder chopped into rough dice","½ cup dry white wine","1 ½ pounds (about 4) Yukon Gold potatoes, sliced ⅛ inch thick","1 cup grated Västerbotten or Parmesan cheese."],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat oven to 350 degrees. In a large saucepan over medium heat, melt 6 tablespoons of the butter. Add flour, stir for 3 minutes (do not allow to brown), then gradually whisk in milk, stirring until thickened, 5 to 8 minutes. Stir in nutmeg and season with salt and pepper to taste. Remove from heat, allow to cool, and reserve."},{"n":2,"title":null,"text":"In a 14 inch sauté pan over medium heat, melt 2 tablespoons of the remaining butter. Add onion and garlic, and sauté until onions are translucent. Add mushrooms, sage and chopped cabbage, and sauté until fragrant and the cabbage is tender, 10 to 12 minutes. Add wine and sauté until it has evaporated. Add reserved sauce and simmer for 10 minutes. The mixture should be very thick but slightly fluid; if necessary, add a little milk or water. Season with salt and pepper to taste."},{"n":3,"title":null,"text":"While the mushroom and cabbage mixture is simmering, pour 6 cups of water into a stock pot, and bring to a boil. Add whole cabbage leaves, and blanch for 2 minutes. Drain under cold water, and pat dry."},{"n":4,"title":null,"text":"With remaining 1 tablespoon butter, grease a 9-by-9-inch glass baking dish. To assemble the lasagna, line the bottom of the dish with half the cabbage leaves, and top with half the potatoes, half the creamed mushrooms. Repeat the layering of cabbage, potatoes and mushrooms, and top with grated cheese. Cover snugly with foil, and bake for 30 minutes. Uncover, and bake until the top is golden brown, about 20 minutes. Allow to cool for 10 minutes, and serve."}],"tips":[],"cuisine_tags":["American","Comfort Food"],"ingredient_tags":["cabbage","mushrooms","potato"],"item_tags":["nutmeg","parmesan"],"course_tags":["Dinner","Lunch"],"keywords":["Cabbage","Dinner","Great Leftovers","Lasagna","Lunch","Mushroom","Vegetables"],"issues":null,"front":"nyt_1015522.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015522-cabbage-and-mushroom-lasagna","rating":{"value":4,"count":253},"date":"2010-11-22"},{"pair":1019702,"title":"Indian-Spiced Eggs With Spinach and Turmeric Yogurt","subtitle":null,"author":"Colu Henry","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"430","fat":"21 g","carbohydrates":"44 g","protein":"21 g"},"description":"In this quick meal, sautéed spinach flecked with ginger, chile and garam masala are paired with eggs and used to top toasted pitas spread with turmeric yogurt. The pitas were chosen for their uniform size, but naan or flatbread would work equally well; you want something sturdy to stand up to the moisture of the yogurt and spinach. An olive oil-fried egg tops this dish, but if you prefer poached have at it — that runny yolk is a key element.","from_your_kitchen":null,"ingredients":["1 cup full-fat Greek yogurt","1 teaspoon ground turmeric","Kosher salt","4 (6- to 8-inch) round pitas","3 tablespoons olive oil","1 tablespoon finely chopped ginger","2 garlic cloves, thinly sliced","1 medium fresh chile, such as cayenne or Serrano, thinly sliced (or ½ teaspoon red-pepper flakes)","1 ½ teaspoons garam masala","1 pound baby spinach","4 large eggs","Black pepper","1 tablespoon roughly chopped cilantro (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 350 degrees. Mix the yogurt and turmeric in a small bowl, season with salt and set aside. Toast the pitas on a sheet pan in the oven until they’re warmed through and beginning to crisp, about 10 to 12 minutes."},{"n":2,"title":null,"text":"Meanwhile, heat 1 tablespoon of olive oil in a 12-inch skillet over medium heat. Add the ginger, garlic and chile and cook until softened, about 1 to 2 minutes. Stir in the garam masala and cook until fragrant, about 30 seconds more. Begin adding in the spinach by the handful, tossing it frequently to encourage wilting. Gradually add more as it cooks down, about 6 to 8 minutes total. Season with salt."},{"n":3,"title":null,"text":"While the spinach cooks, heat the remaining 2 tablespoons oil in a nonstick skillet over medium heat. Crack the eggs into the skillet and season with salt and pepper. Cook until the undersides are crispy and the yolk is still runny, about 3 to 4 minutes."},{"n":4,"title":null,"text":"Spread the turmeric yogurt on the toasted pitas and top each with spinach and then a fried egg. Scatter cilantro over the top, if using, and serve."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["eggs","pita","spinach"],"item_tags":["garam masala","ginger","turmeric","yogurt"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Brunch","Dinner","Egg","Garam Masala","Greek Yogurt","Lunch","Main Course","Pita","Quick","Spinach","Turmeric","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019702.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019702-indian-spiced-eggs-with-spinach-and-turmeric-yogurt","rating":{"value":5,"count":474},"date":"2018-11-01"},{"pair":1014449,"title":"Julienne Carrot Salad","subtitle":null,"author":"David Tanis","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"About 20 minutes","nutrition":{"calories":"135","fat":"10 g","carbohydrates":"11 g","protein":"1 g"},"description":"Sometimes a classic, masterfully executed salad is just what you want, and the easier the better. Enter this simple French salad, also known as called carottes râpées. It is grated carrots dressed with a simple vinaigrette; a lemony one works well. I prefer to cut the carrots into a fine julienne rather than use a box grater, which makes them a bit raggedy. The julienne carrots have a more appealing texture, and they look gorgeous piled on a platter, scattered with chives. It’s not necessary to stay absolutely traditional with this salad. I often veer North African with it, adding pinches of cumin, cinnamon and hot pepper. Nor would it be out of place to introduce Vietnamese seasonings like cilantro, mint, fish sauce and lime.","from_your_kitchen":null,"ingredients":["¾ pound medium carrots","1 small shallot, finely diced","2 tablespoons lemon juice","½ teaspoon finely grated garlic","3 tablespoons extra virgin olive oil","Salt and pepper","2 tablespoons thinly sliced chives"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Peel carrots and cut into fine julienne. Place in a medium bowl."},{"n":2,"title":null,"text":"Put shallot, lemon juice and garlic in a small bowl. Stir in olive oil and season with salt and pepper."},{"n":3,"title":null,"text":"Lightly salt carrots, add vinaigrette and toss well. Let marinate for 5 to 10 minutes. Taste and adjust seasonings. Pile the carrots onto a serving platter and sprinkle with chives."}],"tips":[],"cuisine_tags":["French"],"ingredient_tags":["carrot"],"item_tags":["lemon","shallot"],"course_tags":["Sides & Appetizers"],"keywords":["Carrot","Extra Virgin Olive Oil","French","Kid-Friendly","Lemon Juice","Marinate","Quick","Salad","Vegan","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1014449.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014449-julienne-carrot-salad","rating":{"value":5,"count":372},"date":"2013-01-02"},{"pair":12861,"title":"Orecchiette With Cherry Tomatoes and Arugula","subtitle":null,"author":"Florence Fabricant","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"532","fat":"20 g","carbohydrates":"71 g","protein":"18 g"},"description":"Orecchiette are formed by kneading the dough, letting it rest, then breaking off portions to roll by hand into long skinny ropes. These are cut into pieces, formed into rounds and given the classic cup shape between the index finger and thumb, then flipped inside-out to expose the slightly more textured surface that will “grab” the sauce. Florence Fabricant","from_your_kitchen":null,"ingredients":["Salt","¼ cup extra-virgin olive oil","3 cloves garlic, smashed","1¼ pounds large cherry tomatoes, halved","12 ounces dry orecchiette","2 cups, packed, arugula","Ground black pepper","½ cup freshly grated pecorino"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Start bringing a large pot of salted water to a boil. Meanwhile, heat 3 tablespoons oil on medium-low in a large sauté pan. Add garlic and allow to cook 10 minutes, until oil is fragrant but garlic has not browned. Remove garlic (save for another use). When water boils, stir in pasta."},{"n":2,"title":null,"text":"Add tomatoes to oil in sauté pan, increase heat to medium-high and, when tomatoes start to shrivel and collapse, reduce heat to low and cook until softened but not shapeless, about 5 minutes. Stir a couple of times. Reserve ½ cup of pasta water."},{"n":3,"title":null,"text":"Drain pasta and add to tomatoes, folding both together. Add some pasta water if needed for moistening. Fold in arugula and remaining oil. When arugula has just wilted, season dish with salt and pepper. Serve with a dusting of cheese."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["arugula","pasta","tomato"],"item_tags":["pecorino"],"course_tags":["Dinner"],"keywords":["Arugula","Boil","Dinner","Easy","Five Ingredient","Main Course","Pasta","Pastas","Quick","Saute","Summer","Tomato","Vegetarian"],"issues":null,"front":"nyt_12861.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12861-orecchiette-with-cherry-tomatoes-and-arugula","rating":{"value":5,"count":2455},"date":"2012-10-17"},{"pair":1021031,"title":"The Big Lasagna","subtitle":null,"author":"Samin Nosrat","servings":null,"yield_text":"One 9-by-13-inch lasagna (8 to 12 servings)","yield_count":1,"cook_time":"About 2 1/2 hours","nutrition":{"calories":"538","fat":"34 g","carbohydrates":"36 g","protein":"22 g"},"description":"Delicate sheets of handmade pasta are layered with rich béchamel, savory tomato sauce and creamy ricotta filling, and studded with spinach and herbs, in this deeply comforting lasagna. But if you don’t have the time to make each component or can’t find all of the ingredients, use fresh or dried store-bought noodles and avail yourself of the many suggested substitutions. For a vegan version, use cashew milk and vegan butter to make béchamel, vegan cheese and cashew ricotta for the filling, and make sure to buy dried pasta that does not contain eggs. No matter how you make this dish, you’ll find that it’s grand, comforting and perfect for sharing with whoever is around. (Watch Samin make #TheBigLasagna on YouTube.)","from_your_kitchen":null,"ingredients":["4 tablespoons extra-virgin olive oil (if using fresh spinach)","1 pound fresh mature spinach, washed and ends trimmed, 1 pound baby spinach, or 1 ½ cups frozen spinach, thawed","Fine sea salt","2 pounds whole-milk or part-skim ricotta (about 4 cups)","6 ounces grated whole-milk or part-skim mozzarella, provolone or even string cheese (2 cups)","3 ounces freshly grated Parmesan, Asiago or Grana Padano (1 heaping cup)","20 large fresh basil leaves (from 1 bunch), finely chopped (about ¾ cup), 2 tablespoons finely chopped fresh Italian parsley or chives, 1 teaspoon finely chopped fresh thyme or marjoram or 1 teaspoon dried Italian seasoning","½ cup unsalted butter (1 stick)","½ cup all-purpose flour","4 cups whole milk","Fine sea salt","Freshly ground black pepper","Ground nutmeg (optional)","4 ½ cups Simple Tomato Sauce or 32 ounces store-bought marinara sauce (preferably without added sugar)","Fine sea salt","1 recipe Homemade Lasagna Sheets, 16 fresh store-bought lasagna sheets, 2 (9-ounce) packages dried lasagna noodles (preferably without curly edges) or no-boil noodles (boiled until al dente)","1 ½ ounces grated Parmesan, Asiago or Grana Padano (½ cup)","3 ounces grated whole-milk or part-skim mozzarella, provolone or even string cheese (1 cup)"],"ingredient_groups":[{"at":0,"title":"FOR THE RICOTTA FILLING"},{"at":7,"title":"FOR THE BÉCHAMEL"},{"at":13,"title":"FOR THE ASSEMBLED LASAGNA"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the ricotta filling: If using fresh spinach, set a large skillet over high heat. (If using thawed frozen spinach, skip to Step 2.) When hot, add 2 tablespoons oil and half the fresh spinach. Season with a pinch of salt and sauté to wilt. Cook until stems are tender, about 3 minutes. Transfer to a baking sheet and allow to cool in a single layer. Repeat with remaining spinach."},{"n":2,"title":null,"text":"While spinach cools, combine ricotta, mozzarella, Parmesan, basil and a generous pinch of salt in a large bowl."},{"n":3,"title":null,"text":"Taking handfuls of the cooled or thawed spinach, squeeze out as much water as possible, then chop finely and add to cheese mixture. Mix thoroughly, then taste and adjust seasoning for salt. (Filling makes about 6 cups.) Cover and set aside until ready to assemble lasagna. (Ricotta filling can be made 1 day in advance and refrigerated. Bring to room temperature before assembling lasagna.)"},{"n":4,"title":null,"text":"Prepare the béchamel: Set a large, heavy-bottomed pot or Dutch oven over medium heat and add butter. Once butter has melted, whisk in flour, reduce heat to very low and cook for about 15 minutes, stirring regularly to prevent browning. After the mixture foams a bit, it will visibly transform — the butter will separate, the bubbles will reduce in size, and the mixture will look like freshly wet fine sand. Whisking vigorously, slowly pour in milk. Increase heat to medium and whisk until the mixture thickens, about 2 minutes. Add salt, pepper and nutmeg (if using) to taste."},{"n":5,"title":null,"text":"Return heat to low. Continue cooking, whisking regularly, for 10 to 15 minutes until the sauce is thick and smooth, with no raw flour flavor. Taste and adjust seasoning with salt. If béchamel is lumpy, strain through a fine sieve or purée with an immersion blender. (You’ll have about 3 ½ cups.) Press a piece of parchment or plastic against the surface of the sauce to prevent a skin from forming and set aside until ready to assemble lasagna. (Béchamel can be made up to 1 day in advance, covered directly and refrigerated. Return to room temperature before using.)"},{"n":6,"title":null,"text":"Prepare the lasagna: Position the highest rack in the oven so that it sits about 6 inches below the top. Heat oven to 400 degrees."},{"n":7,"title":null,"text":"If tomato sauce, béchamel and ricotta filling are cold, bring to room temperature or warm them as needed."},{"n":8,"title":null,"text":"Set a large pot of water over high heat. Cover and bring to a boil. Set a large colander in a baking dish and place near stove."},{"n":9,"title":null,"text":"Season the boiling water generously with salt until it tastes like sea water. Carefully lay one sheet of pasta on the water’s surface. Let it be completely immersed in the boiling water, using a slotted spoon to gently it push down if needed, before adding the next sheet. Add two more pasta sheets in this way and cook for about 2 minutes, or until light in color, floppy in texture and completely cooked through. If pasta bubbles above the water's surface, use a slotted spoon to encourage it back in. Use a sieve to gently remove pasta from the water and into the prepared colander. Rinse under cold water until cool enough to handle, then begin assembly. Continue cooking, draining and rinsing pasta two or three sheets at a time as you assemble lasagna."},{"n":10,"title":null,"text":"Spoon about ¾ cup béchamel into a 9-by-13-inch metal, glass or ceramic baking pan, and use a rubber spatula or your hands to generously coat bottom and sides of pan with sauce."},{"n":11,"title":null,"text":"Gently squeezing any remaining water from the pasta, use two or three sheets to entirely cover the bottom of the pan with minimal overlap, and leave ends hanging over sides. (They’ll be helpful for sealing the top.) All four sides need not have overhang; two is plenty."},{"n":12,"title":null,"text":"Crumble about ⅓ of the ricotta mixture evenly over pasta to create foundation, then layer with sheets of pasta from edge to edge of pan. Use kitchen shears to help trim pasta to appropriate size and avoid overlap."},{"n":13,"title":null,"text":"Spread about ⅓ of the tomato sauce over next layer and cover with pasta."},{"n":14,"title":null,"text":"Spread about 1 cup béchamel evenly over next layer, sprinkle with ¼ cup grated Parmesan, and cover with pasta."},{"n":15,"title":null,"text":"Repeat with remaining layers: ricotta, tomato sauce, béchamel and Parmesan, ricotta, tomato sauce, béchamel and Parmesan, following each with a layer of pasta. (If using thicker noodles, you might not be able to fit 8 layers of noodles in the pan. If using store-bought or dried pasta, you can skip the noodle layer between the ricotta and tomato sauce as needed to prevent the lasagna from stretching higher than the top of the pan.)"},{"n":16,"title":null,"text":"For the top, fold overhanging pasta over a whole sheet to create a sealed pasta layer, then spread with remaining béchamel. Gently cover lasagna with a piece of parchment and wrap tightly with foil. Place onto a baking sheet to catch any overflow and bake on prepared rack."},{"n":17,"title":null,"text":"After 40 minutes, pull lasagna from oven and carefully remove foil and parchment. Sprinkle with grated mozzarella and return to oven until golden brown and bubbling on surface, about 20 minutes."},{"n":18,"title":null,"text":"Allow to cool for at least 15 minutes before slicing and serving. Leftover lasagna can be wrapped and refrigerated for up to 4 days. To freeze, bake 30 minutes but do not brown, then cool, and freeze for up to 4 weeks. Defrost, then sprinkle with mozzarella and bake uncovered at 400 degrees for 25 to 30 minutes until golden brown and bubbling on surface."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["pasta","spinach"],"item_tags":["basil","mozzarella","parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["American","Dinner","Great Leftovers","Lasagna","Lasagna Noodle","Main Course","Milk","Mozzarella","Parmesan","Project","Ricotta","Spinach","Thanksgiving","Tomato Sauce","Vegetarian"],"issues":null,"front":"nyt_1021031.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021031-the-big-lasagna","rating":{"value":5,"count":5634},"date":"2020-04-29"},{"pair":1014916,"title":"Cucumber and Tomato Salad With Cilantro and Mint","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"72","fat":"4 g","carbohydrates":"10 g","protein":"2 g"},"description":"Greater Los Angeles is a collection smaller cities, including Glendale, a center of the Armenian diaspora and home to one of the world’s largest Armenian populations outside Armenia. Fleeing religious violence in the late 19th century, genocide in the early 20th or the Soviet Union after that, Armenian Californians became integral in the development of the fig, raisin and bulgur businesses. They also opened restaurants. This salad comes from one of them, Adana. The chef and owner, Edward Khechemyan, gave me the recipe in 2013. Mark Bittman","from_your_kitchen":null,"ingredients":["4 ripe tomatoes, chopped","4 Persian cucumbers, chopped","½ small white onion, chopped","2 tablespoons chopped purple or green basil","1 tablespoon chopped cilantro","½ teaspoon dried mint","½ teaspoon crushed red chili powder (or ancho chile powder)","½ teaspoon salt","2 tablespoons lemon juice","1 tablespoon olive oil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Combine all of the ingredients in a bowl; toss, and serve."}],"tips":[],"cuisine_tags":["Middle Eastern"],"ingredient_tags":["cucumber","tomato"],"item_tags":["basil","cilantro","lemon","mint"],"course_tags":["Sides & Appetizers"],"keywords":["Cucumber","Middle Eastern","No Cook","Quick","Salad","Tomato","Vegan","Vegetarian"],"issues":null,"front":"nyt_1014916.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014916-cucumber-and-tomato-salad-with-cilantro-and-mint","rating":{"value":5,"count":1013},"date":"2013-07-24"},{"pair":1013646,"title":"Lasagna With Asparagus and Chives","subtitle":null,"author":"Martha Rose Shulman","servings":"4","yield_text":"Serves four","yield_count":4,"cook_time":"About 20 minutes","nutrition":{"calories":"308","fat":"6 g","carbohydrates":"50 g","protein":"15 g"},"description":"Lasagna doesn’t always have to be assembled and baked; it can be thrown together quickly, like a regular pasta dish. Use no-boil lasagna noodles for this deconstructed lasagna. Despite the name, they do require boiling here, but they will be lighter than regular lasagna noodles.","from_your_kitchen":null,"ingredients":["1 pound asparagus, trimmed","½ cup ricotta","1 garlic clove, finely minced or preferably pureed","2 tablespoons chopped chives or a combination of chives and slivered basil","½ pound no-boil lasagna noodles","¼ cup (1 ounce) freshly grated Parmesan or pecorino romano (or a combination)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of water to a rolling boil, salt generously and add the asparagus. Meanwhile, fill a bowl with cold water. Boil thin stalks for three minutes, thicker stalks for four to six minutes until tender. Using tongs, remove the asparagus from the pot and transfer to the bowl of cold water. Drain and cut on the diagonal into ¾-inch lengths."},{"n":2,"title":null,"text":"Add the lasagna noodles to the boiling water, and boil until cooked al dente -- firm to the bite. Meanwhile, place the ricotta in a large pasta bowl, and stir in the garlic. When the noodles are done, remove ½ cup of the pasta water, and add to the bowl with the ricotta. Mix together well, and add the asparagus, fresh herbs and Parmesan or pecorino to the bowl. Drain the lasagna, and toss with the ricotta mixture. Serve at once."}],"tips":["Advance preparation: You can make this through Step 1 several hours ahead of serving, then cook the pasta just beforehand."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["asparagus","pasta"],"item_tags":["parmesan","pecorino","ricotta"],"course_tags":["Dinner"],"keywords":["Asparagus","Boil","Dinner","Easy","Great Leftovers","Healthy","Lasagna","Main Course","Quick","Spring","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1013646.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013646-lasagna-with-asparagus-and-chives","rating":{"value":4,"count":187},"date":"2011-06-22"},{"pair":1016949,"title":"Melted Butter Chocolate Chip Cookies","subtitle":null,"author":"Jeff Gordinier","servings":null,"yield_text":"3 dozen cookies","yield_count":36,"cook_time":"30 minutes, not including time to chill","nutrition":{"calories":"89","fat":"4 g","carbohydrates":"12 g","protein":"1 g"},"description":"At WD-50 on Manhattan’s Lower East Side, the pastry chef Malcolm Livingston II specializes in building delicious and visually arresting desserts out of ingredients that seem to have been thrown together like strangers at a cocktail party. (A recent example: “verbena mousse, plum, buckwheat, camelina oil.”) But when it comes to the family meal, when members of the kitchen team meet up for a mass nosh, Mr. Livingston is known for baking something more traditional: chocolate chip cookies. “I think they stand out because of the texture,” he said, citing his blend of all-purpose flour, bread flour and melted butter. Pay attention to the process, though. “When making them at home, set aside enough time for your dough to be chilled,” he advised. “The cookies bake better when they are going straight from freezer or fridge directly into the oven.” Jeff Gordinier","from_your_kitchen":null,"ingredients":["11 tablespoons/150 grams unsalted butter, melted","½ cup/100 grams packed dark brown sugar","½ cup/88 grams granulated sugar","1 egg plus 1 yolk","1 cup/150 grams bread flour","⅓ cup/50 grams all-purpose flour","1 teaspoon/4 grams salt","¼ teaspoon baking soda","¼ teaspoon baking powder","¾ cup/125 grams chocolate chips"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In the bowl of a standing mixer fitted with the whisk attachment, whip the butter, brown sugar and granulated sugar for 3 minutes. Add the egg and yolk and whip for another 6 minutes or until light in color and fluffy."},{"n":2,"title":null,"text":"Sift together the flours, salt, baking soda and baking powder. Switch to the paddle attachment on the mixer and add the dry ingredients and chocolate chips. Mix on low speed until all ingredients are incorporated and mixture looks homogeneous. Dough will be slightly wet."},{"n":3,"title":null,"text":"Chill the dough until set enough to scoop with an ice cream scoop. Or transfer the dough to a sheet of parchment paper and roll into a log. Wrap it in the paper and twist the ends tightly to secure, and chill until firm enough to cut into 1-inch slices, at least 1 hour."},{"n":4,"title":null,"text":"When ready to bake, heat oven to 375 degrees. Line a baking sheet with parchment paper, scoop the dough or slice, and space cookies at least 2 inches apart on the baking sheet. Cook for 12 to 15 minutes or until golden brown on the edges but still soft in the middle."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips"],"item_tags":["brown sugar"],"course_tags":["Dessert"],"keywords":["American","Bake","Chocolate Chip","Chocolate Chip Cookie","Dessert","Easy","Snack"],"issues":null,"front":"nyt_1016949.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016949-melted-butter-chocolate-chip-cookies","rating":{"value":4,"count":684},"date":"2014-11-04"},{"pair":1017228,"title":"Moroccan Chickpeas With Chard","subtitle":null,"author":"Melissa Clark","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"2 1/2 hours, plus overnight soaking","nutrition":{"calories":"346","fat":"11 g","carbohydrates":"52 g","protein":"15 g"},"description":"An array of aromatic spices, along with chopped dried apricots and preserved lemons give this chickpea stew a complex, deep flavor, while chard stems and leaves lighten and freshen it up. Served with couscous or flatbread, it’s a satisfying meatless meal on its own. Or serve it with roasted chicken, beef or lamb as a hearty side dish. If you can find rainbow chard, you’ll get the best color here, but any chard variety (red, Swiss, yellow) will work well.","from_your_kitchen":null,"ingredients":["4 tablespoons olive oil","2 Spanish onions, chopped","1 large jalapeño pepper, seeded if desired, chopped","4 garlic cloves, minced","1 teaspoon grated fresh ginger root","2 ½ teaspoons kosher salt, more to taste","1 teaspoon ground turmeric","1 teaspoon sweet paprika","¾ teaspoon ground cinnamon","½ teaspoon ground cumin","½ teaspoon ground black pepper","Pinch of cayenne","2 tablespoons tomato paste","1 fennel bulb, diced (save fronds for garnish)","1 very large bunch chard, stems sliced ½-inch thick, leaves torn into bite-size pieces","2 carrots, peeled and diced","1 large turnip, peeled and diced","1 pound dried chickpeas, soaked overnight in water to cover or quick-soaked (see Tip)","⅓ cup diced dried apricots","2 tablespoons chopped preserved lemon, more to taste","½ cup chopped cilantro, more for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oil in a large pot over high heat. Add onion and jalapeño and sauté until limp, 3 minutes. Add garlic, ginger, salt, turmeric, paprika, cinnamon, cumin, black pepper and cayenne and sauté until they release their fragrance, about 2 minutes. Add tomato paste and sauté for another minute, until darkened but not burned. (If tomato paste looks too dark too quickly, lower heat.)"},{"n":2,"title":null,"text":"Add fennel, chard stems, carrot and turnip and continue to sauté until vegetables start to soften, about 10 minutes. Add chickpeas and water to barely cover."},{"n":3,"title":null,"text":"Return heat to high if you lowered it and bring to a simmer. Partly cover pot, lower heat to medium low, and simmer for about 1 ½ to 2 hours, until chickpeas are softened. Add more water if needed (this should be like a stew)."},{"n":4,"title":null,"text":"Add chard leaves, apricots and preserved lemon to pot and continue simmering until chard is tender, about 5 minutes longer. Season with more salt if desired, and serve garnished with cilantro and reserved fennel fronds."}],"tips":["To quick-soak chickpeas, bring them to a boil in water to cover by 1 inch. Turn off the heat and let soak for 1 hour. Drain."],"cuisine_tags":["Moroccan"],"ingredient_tags":["chickpeas","fennel","swiss chard"],"item_tags":["cilantro","cinnamon","cumin","dried apricots","turmeric"],"course_tags":["Dinner","Lunch"],"keywords":["Boil","Chickpea","Dinner","Fennel","Great Leftovers","Lunch","Main Course","Moroccan","Saute","Simmer","Stew","Swiss Chard","Turnip","Winter"],"issues":null,"front":"nyt_1017228.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017228-moroccan-chickpeas-with-chard","rating":{"value":5,"count":2138},"date":"2015-02-18"},{"pair":12476,"title":"Lasagna With Roasted Eggplant, Mushrooms and Carrots","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"Yield: 6 servings","yield_count":6,"cook_time":"2 hours 15 minutes","nutrition":{"calories":"356","fat":"16 g","carbohydrates":"39 g","protein":"18 g"},"description":"This is like a combination of eggplant Parmesan and lasagna, with the added texture and flavor provided by savory mushrooms and sweet roasted carrots.","from_your_kitchen":null,"ingredients":["1 medium eggplant, about 1 ¼ pounds, cut in lengthwise slices about ⅓ inch thick","Salt to taste","3 tablespoons extra virgin olive oil","½ pound mushrooms, cut in thick slices","1 large carrot, cut in ½-inch dice","1 teaspoon fresh thyme leaves","2 ½ cups marinara sauce, preferably homemade from fresh or canned tomatoes","7 to 8 ounces no-boil lasagna","3 ounces fresh mozzarella, shredded or thinly sliced","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 450 degrees. Line a baking sheet with parchment. Place the eggplant slices on a sheet pan or a cooling rack and sprinkle with salt. Let sit 15 minutes while you prepare the other ingredients. Pat dry with paper towels and toss in a large bowl with 2 tablespoons of the olive oil. Place on the baking sheet in a single layer (you may have to do this in two batches) and roast in the oven for 10 minutes. Remove from the oven, close the oven door and, using tongs, flip the eggplant slices over. Return to the oven for another 5 to 10 minutes, or until the eggplant is tender when pierced with a knife and browned in spots."},{"n":2,"title":null,"text":"Toss the mushrooms, carrots and thyme with the remaining tablespoon of olive oil and season to taste with salt and pepper. Place on the parchment-lined baking sheet and roast for 15 to 20 minutes, stirring halfway through, until the carrots are lightly caramelized and the mushrooms tender. Remove from the oven and reduce the heat to 350 degrees."},{"n":3,"title":null,"text":"Lightly oil a rectangular baking pan. Stir the mushrooms and carrots into the marinara sauce. Spread a small spoonful of the sauce over the bottom of a baking pan. Top with a layer of lasagna noodles. Top the noodles with a spoonful of sauce, then a layer of eggplant slices. Top the eggplant with half of the mozzarella and a sprinkling of Parmesan. Repeat the layers, ending with a layer of lasagna noodles topped with a layer of tomato sauce and a layer of Parmesan."},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 10 minutes, until the top begins to brown. Remove from the heat and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["carrot","eggplant","mushrooms","pasta"],"item_tags":["mozzarella","parmesan"],"course_tags":["Dinner"],"keywords":["Bake","Casseroles","Dinner","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Roast","Vegetarian"],"issues":null,"front":"nyt_12476.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12476-lasagna-with-roasted-eggplant-mushrooms-and-carrots","rating":{"value":5,"count":840},"date":"2012-05-30"},{"pair":1020094,"title":"Tofu Makhani (Indian Butter Tofu)","subtitle":null,"author":"Sarah Copeland","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"40 minutes","nutrition":{"calories":"588","fat":"49 g","carbohydrates":"18 g","protein":"27 g"},"description":"This recipe is a vegetarian riff on butter chicken, or murgh makhani, a classic Indian dish in which chicken simmers in a rich, dairy-laden tomato sauce that’s seasoned with heady spices like turmeric, cumin, garam masala and cardamom. This weeknight-friendly version has a toned-down ingredient list, and the tofu doesn’t require hours of marinating, which means you can get everything on the table in under an hour if you start the rice as the tomatoes are cooking down. Heavy cream gives this dish a rich finish, but full-fat coconut milk makes a fine substitute. Whatever you do, don’t substitute anything for the butter or ghee (sorry, vegans) — it’s the signature ingredient.","from_your_kitchen":null,"ingredients":["2 tablespoons fresh lemon juice","1 tablespoon ground cumin","1 heaping tablespoon plus 1 teaspoon ground turmeric","2 (14-ounce) packages firm tofu","8 tablespoons ghee or unsalted butter (1 stick)","2 yellow onions, peeled and diced","1 teaspoon ground chile powder, such as cayenne","3 tablespoons peeled and minced fresh ginger","4 garlic cloves, minced","1 (28-ounce) can whole peeled tomatoes","1 cinnamon stick","1 teaspoon paprika","1 ½ teaspoons fine sea salt","1 ½ cups heavy cream or full-fat coconut milk","3 scallions, thinly sliced on the bias","¼ cup cilantro leaves and tender stems","Naan, basmati rice, yogurt and quartered cucumbers, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a large bowl, whisk the lemon juice, cumin and 1 heaping tablespoon turmeric with 1 tablespoon water to make a thin paste. Drain and pat the tofu dry then cut it into 1-inch cubes. Add it to the turmeric marinade, gently stirring to coat. Set aside at room temperature while you prepare the remaining ingredients, or cover and refrigerate for up to 1 day."},{"n":2,"title":null,"text":"In a large pot over medium heat, melt the butter. Add the onions and chile powder, and cook, stirring frequently, until onions are translucent, about 5 minutes. Lower the heat, add the ginger and garlic and cook, stirring occasionally, until the onions are starting to brown, about 5 minutes."},{"n":3,"title":null,"text":"Add the tomatoes and their juices, gently crushing the tomatoes with your hands as you go. Add the cinnamon stick, paprika and sea salt along with the remaining 1 teaspoon turmeric. Cook until the tomatoes and onions break down and the sauce is the consistency of a thick ragù, about 10 minutes. Blend with an immersion blender, or transfer to a blender and purée until smooth. Return to the pot."},{"n":4,"title":null,"text":"Gently stir in the cream and the tofu and its marinade. Simmer over low heat, uncovered, until the tofu has taken on the color of the sauce and is flavored all the way through, about 5 minutes. Stir occasionally but gently, so the tofu doesn’t fall apart. Transfer the tofu and sauce to a deep platter or large shallow serving bowl and sprinkle with scallions and cilantro. Serve with warm naan, rice, yogurt and cucumbers."}],"tips":[],"cuisine_tags":["Indian"],"ingredient_tags":["tofu"],"item_tags":["cinnamon","coconut milk","cumin","ginger","turmeric"],"course_tags":["Dinner","Lunch"],"keywords":["Coconut Milk","Curry","Dinner","Firm Tofu","Fresh Ginger","Ghee","Great Leftovers","Ground Cumin","Ground Ginger","Ground Turmeric","Heavy Cream","Indian","Lunch","Main Course","Unsalted Butter","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020094.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020094-tofu-makhani-indian-butter-tofu","rating":{"value":5,"count":6770},"date":"2019-03-15"},{"pair":1020766,"title":"Red Curry Lentils With Sweet Potatoes and Spinach","subtitle":null,"author":"Lidey Heuck","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"467","fat":"25 g","carbohydrates":"49 g","protein":"12 g"},"description":"In this vegetarian main inspired by Indian dal, lentils are cooked with an aromatic blend of Thai spices — fresh ginger, turmeric, red curry paste and chile — then simmered in coconut milk until fall-apart tender. Browning the sweet potatoes before cooking them with the lentils brings out their sweetness, balancing the heat from the chile and curry paste, while baby spinach tossed in just before serving adds fresh flavor. Serve over steamed white or brown rice, or with toasted flatbread on the side.","from_your_kitchen":null,"ingredients":["3 tablespoons olive oil","1 pound sweet potatoes (about 2 medium sweet potatoes), peeled and cut into ¾-inch cubes","1 medium yellow onion, chopped","3 tablespoons Thai red curry paste","3 garlic cloves, minced (about 1 tablespoon)","1 (1-inch) piece fresh ginger, peeled and grated (about 1 tablespoon)","1 red chile, such as Fresno or serrano, halved, seeds and ribs removed, then minced","1 teaspoon ground turmeric","1 cup red lentils, rinsed","4 cups low-sodium vegetable stock","2 teaspoons kosher salt, plus more to taste","1 (13-ounce) can full-fat coconut milk","1 (4- to 5-ounce) bag baby spinach","½ lime, juiced","Fresh cilantro leaves, for serving","Toasted unsweetened coconut flakes, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a Dutch oven or pot, heat 2 tablespoons olive oil over medium-high. Add the sweet potatoes and cook, stirring occasionally, until browned all over, 5 to 7 minutes. Transfer the browned sweet potatoes to a plate and set aside."},{"n":2,"title":null,"text":"Add the remaining 1 tablespoon olive oil to the pot and set the heat to medium-low. Add the onion and cook, stirring occasionally, until translucent, 4 to 6 minutes. Add the curry paste, garlic, ginger, chile and turmeric, and cook until fragrant, about 1 minute."},{"n":3,"title":null,"text":"Add the lentils, stock, salt and browned sweet potatoes to the pot and bring to a boil over high. Lower the heat and simmer, uncovered, stirring occasionally, until the lentils are just tender, 20 to 25 minutes."},{"n":4,"title":null,"text":"Add the coconut milk and simmer, stirring occasionally, until the liquid has reduced and the lentils are creamy and falling apart, 15 to 20 minutes."},{"n":5,"title":null,"text":"Add the spinach and stir until just wilted, 2 to 3 minutes. Off the heat, stir in the lime juice and season with salt to taste."},{"n":6,"title":null,"text":"Divide among shallow bowls and top with cilantro and coconut flakes, if using."}],"tips":[],"cuisine_tags":["Fusion","Thai"],"ingredient_tags":["red lentils","spinach","sweet potato"],"item_tags":["cilantro","coconut milk","ginger","red curry paste","turmeric"],"course_tags":["Dinner"],"keywords":["Beans","Coconut Milk","Dinner","Dutch Oven","Easy","Fresh Ginger","Main Course","One Pot","Red Curry Paste","Red Lentil","Spinach","Sweet Potato","Turmeric","Vegan","Vegan Thanksgiving","Vegetarian"],"issues":null,"front":"nyt_1020766.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020766-red-curry-lentils-with-sweet-potatoes-and-spinach","rating":{"value":5,"count":19802},"date":"2020-01-07"},{"pair":7472,"title":"Salty Peanut Chocolate Chip Cookies","subtitle":null,"author":"Nigella Lawson","servings":null,"yield_text":"About 20 cookies","yield_count":20,"cook_time":"50 minutes","nutrition":{"calories":"266","fat":"14 g","carbohydrates":"34 g","protein":"4 g"},"description":"These cookies offer a terrific blend of salty and sweet, with the crunch of the peanuts lending a bit of texture to a chewy treat. They are also very easy to make and require only about an hour. But watch the timer — if they are overcooked, they will lose their chewiness.","from_your_kitchen":null,"ingredients":["6 ounces (1 ½ sticks) unsalted butter","1 packed cup light brown sugar","½ cup granulated sugar","2 teaspoons vanilla extract","2 large eggs","2 ¼ cups all-purpose flour","1 teaspoon baking powder","½ teaspoon baking soda","1 cup semisweet chocolate morsels","1 cup salted peanuts"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Using a microwave oven or in a small saucepan, melt butter. Allow it to cool for about 5 minutes. In a medium bowl, using an electric mixer or by hand, beat together the butter, brown sugar, and granulated sugar. Beat in vanilla, eggs, flour, baking powder and baking soda. Fold in chocolate morsels and peanuts."},{"n":2,"title":null,"text":"Refrigerate bowl of cookie dough for 20 minutes. Meanwhile, heat oven to 350 degrees. Line a large baking sheet (or two) with a nonstick liner or parchment paper."},{"n":3,"title":null,"text":"Shape chilled dough into fat disks about 2 ½ inches in diameter and ½-inch thick (slightly less than 3 tablespoons of dough for each cookie). Place cookies on baking sheet 1 ½ inches apart. Bake until golden brown around edges and cracked and chewy in middle, about 15 minutes. If using two sheets, switch position of sheets halfway through baking. Remove cookies from oven while they are still soft in center or they will lose their chewiness as they cool."},{"n":4,"title":null,"text":"Allow cookies to rest on baking sheets for about 3 minutes before transferring them to wire racks to cool. When completely cool, store in an airtight container."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips","peanuts"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Chocolate Chip Cookie","Dessert","Peanut","Semisweet Chocolate Chip","Snack"],"issues":null,"front":"nyt_7472.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/7472-salty-peanut-chocolate-chip-cookies","rating":{"value":4,"count":751},"date":"2004-02-18"},{"pair":1017392,"title":"Pasta Primavera With Asparagus and Peas","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"578","fat":"19 g","carbohydrates":"77 g","protein":"25 g"},"description":"This simple pasta primavera uses a combination of the earliest vegetables available in spring — asparagus, peas and spring onions — making it a true celebration of the season. The sauce works best with springy egg pasta, preferably homemade or a good purchased brand. Make sure not to overcook it; you need the chewy bite to stand up to the gently cooked vegetables. If you can’t find good fresh English peas, you can substitute frozen peas, but don’t add them until the last minute of cooking.","from_your_kitchen":null,"ingredients":["¼ pound sugar snap peas, stems trimmed","½ pound asparagus, ends snapped","2 tablespoons unsalted butter","¾ cup fresh English peas","¼ cup thinly sliced spring onion, white part only (or use shallot)","2 garlic cloves, finely chopped","½ teaspoon fine sea salt, more as needed","Black pepper, more as needed","12 ounces fettuccine or tagliatelle, preferably fresh (see recipe)","⅔ cup grated Parmigiano-Reggiano, at room temperature","½ cup crème fraîche or whole milk Greek yogurt, at room temperature","3 tablespoons finely chopped parsley","1 tablespoon finely chopped tarragon"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of heavily salted water to a boil over medium-high heat."},{"n":2,"title":null,"text":"While the water is coming to a boil, slice snap peas and asparagus stems into ¼-inch-thick pieces; leave asparagus tips whole."},{"n":3,"title":null,"text":"Melt butter in a large skillet over medium-high heat. Add snap peas, asparagus, English peas and onion. Cook until vegetables are barely tender (but not too soft or mushy), 3 to 4 minutes. Stir in garlic and cook 1 minute more. Season with salt and pepper; set aside."},{"n":4,"title":null,"text":"Drop pasta into boiling water and cook until al dente (1 to 3 minutes for fresh pasta, more for dried pasta). Drain well and transfer pasta to a large bowl. Immediately toss pasta with vegetables, Parmigiano-Reggiano, crème fraîche and herbs. Season generously with salt and pepper, if needed."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["asparagus","pasta","peas","sugar snap peas"],"item_tags":["crème fraîche","parmesan","parsley","tarragon"],"course_tags":["Dinner","Lunch"],"keywords":["Asparagus","Boil","Crème Fraîche","Dinner","Fettuccine","Greek Yogurt","Lunch","Main Course","Pastas","Pea","Quick","Spring","Sugar Snap Pea"],"issues":null,"front":"nyt_1017392.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017392-pasta-primavera-with-asparagus-and-peas","rating":{"value":5,"count":9860},"date":"2023-04-29"},{"pair":1017629,"title":"Chinese Smashed Cucumbers With Sesame Oil and Garlic","subtitle":null,"author":"Julia Moskin","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"40 minutes","nutrition":null,"description":"In China, cucumbers are considered the ideal foil for hot weather and hot food. Versions of this salad, pai huang gua, are served all over the country, sometimes spiked with dried chiles and Sichuan peppercorns for more dimensions of flavor. In Beijing, people buy whole chilled cucumbers from street vendors and munch them on the go, much as Americans become attached to their cups of iced coffee in summer. The smashing process, a classic Chinese technique, cracks the skin, helps release the seeds and splits the flesh into appealing craggy pieces. Salting and chilling the cracked cucumbers give them the perfect cool, crunchy, watery mouth feel.","from_your_kitchen":null,"ingredients":["About 2 pounds thin-skinned cucumbers like English or Persian (8 to 10 mini cucumbers, 4 medium-size or 2 large greenhouse)","1 teaspoon kosher salt, plus more for cucumbers","2 teaspoons granulated sugar, plus more for cucumbers","1 ½ tablespoons rice vinegar","2 teaspoons sesame oil","2 teaspoons soy sauce","1 tablespoon grapeseed or extra-virgin olive oil","2 large garlic cloves, minced or put through a press","Red pepper flakes, to taste","Small handful whole cilantro leaves, for garnish","2 teaspoons toasted white sesame seeds, for garnish (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Rinse cucumbers and pat dry. Cut crosswise into pieces about 4 inches long. Cut each piece in half lengthwise."},{"n":2,"title":null,"text":"On a work surface, place a piece of cucumber (or several) cut side down. Lay the blade of a large knife flat on top the cucumber and smash down lightly with your other hand. The skin will begin to crack, the flesh will break down and the seeds will separate. Repeat until the whole piece is smashed. Break or slice diagonally into bite-size pieces, leaving the seeds behind."},{"n":3,"title":null,"text":"Place the cucumber pieces in a strainer and toss with a big pinch of salt and a big pinch of sugar. Place a plastic bag filled with ice on top of the cucumbers to serve as a weight and place the strainer over a bowl. Let drain 15 to 30 minutes on the counter, or in the refrigerator until ready to serve, up to 4 hours."},{"n":4,"title":null,"text":"Make the dressing: In a small bowl, combine salt, sugar and rice vinegar. Stir until salt and sugar are dissolved. Stir in sesame oil and soy sauce."},{"n":5,"title":null,"text":"When ready to serve, shake cucumbers well to drain off any remaining liquid and transfer to a serving bowl. Drizzle with grapeseed or olive oil and toss. Add half the dressing, half the garlic and the red pepper flakes to taste, and toss. Keep adding dressing until cucumbers are well coated but not drowned. Taste and add more pepper flakes and garlic if needed. Serve immediately, garnished with cilantro and sesame seeds."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["cucumber"],"item_tags":["cilantro","red chile flakes","rice vinegar","sesame oil","sesame seeds","soy sauce"],"course_tags":["Sides & Appetizers"],"keywords":["Chinese","Cucumber","Garlic","No Cook","Salad","Sesame Oil","Side Dish","Summer"],"issues":null,"front":"nyt_1017629.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017629-chinese-smashed-cucumbers-with-sesame-oil-and-garlic","rating":{"value":5,"count":5464},"date":"2015-08-19"},{"pair":1021193,"title":"Cheesy Pan Pizza","subtitle":null,"author":"Tejal Rao","servings":null,"yield_text":"1 (9-to-10-inch) pan pizza","yield_count":1,"cook_time":"45 minutes, plus resting","nutrition":{"calories":"2425","fat":"70 g","carbohydrates":"361 g","protein":"81 g"},"description":"This recipe for a crisp, cheesy pan pizza was developed by Charlotte Rutledge, along with her team of test cooks at King Arthur Flour’s rigorous test kitchen in Vermont. It uses a number of simple techniques to achieve maximum texture and flavor. The dough is folded a few times before it goes in the fridge for a long rest, which develops its flavor and airiness. Cooking the pizza in cast iron gets the edges brown and crackling, and layering the cheese and sauce creates an extra cheesy top with no soggy layer. Make it once in its simplest form, then use the model to play around with the fermentation time and toppings. Tejal Rao","from_your_kitchen":null,"ingredients":["1 ¾ cups plus 2 tablespoons/240 grams all-purpose flour","¾ cup/180 milliliters lukewarm water","1 tablespoon olive oil","¾ teaspoon kosher salt","½ teaspoon instant or active dry yeast","1 ½ tablespoons olive oil","6 ounces mozzarella, grated (about 1 ¼ loosely packed cups)","½ cup/120 grams tomato sauce or pizza sauce","Freshly grated hard cheese, such as Parmesan or pecorino, for garnish (optional)","Fresh herbs, such as basil, marjoram or oregano, for garnish (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE DOUGH"},{"at":5,"title":"FOR THE ASSEMBLY"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Prepare the dough: Measure the flour, water, olive oil, salt and yeast into a large mixing bowl. Mix together with your hand or a dough scraper until it forms a shaggy, sticky ball with no dry patches. Cover the bowl using a damp towel or plastic wrap, and let the dough rest for 5 minutes."},{"n":2,"title":null,"text":"Wet your hand, and reach down between the side of the bowl and the dough, as though you were going to lift the dough out, but instead of lifting, stretch the bottom of the dough up, and fold it over the top. Repeat three more times, turning the bowl 90 degrees each time. Cover the bowl again for 5 minutes, then repeat the folding-and-resting process three more times. After the fourth time, cover the bowl, and let the dough rest, undisturbed, for 40 minutes, then transfer the bowl to the fridge for at least 12 hours or up to 72 hours."},{"n":3,"title":null,"text":"About 3 hours before you want to eat the pizza, get ready for assembly: Pour the olive oil into a well-seasoned 9- or 10-inch cast-iron skillet, and use your fingers to coat the inside of the pan, including the sides. Transfer the dough to the pan, and turn it once to coat both sides with the oil. After coating the dough in oil, press the dough to the edges of the pan, dimpling it with your fingertips. If the dough shrinks back, cover it and let it rest for about 15 minutes, then repeat the pressing and dimpling. At this point, you should be able to smush the dough out and into the edges of the pan, but if not, give it one more 15-minute rest before trying again. Cover the dough, and let it rise for 2 hours at room temperature. It will look soft and jiggle when you gently shake the pan."},{"n":4,"title":null,"text":"Place one rack at the bottom of the oven and one toward the top (about 4 to 5 inches from the top heating element), then heat the oven to 450 degrees. When you’re ready to bake the pizza, sprinkle a scant 1 cup mozzarella evenly over the crust. Cover the entire dough so none is showing, then dollop small spoonfuls of the sauce over the cheese. Sprinkle the remaining mozzarella on top, and bake on the bottom rack of the oven for 18 to 20 minutes, until the cheese is bubbling and the bottom and edges of the crust are a rich golden brown. (Use a spatula to check the bottom.) If the bottom is brown but the top still seems pale, transfer the pizza to the top rack, and bake for 2 to 4 minutes longer. On the other hand, if the top seems fine but the bottom’s not browned to your liking, leave the pizza on the bottom rack for another 2 to 4 minutes."},{"n":5,"title":null,"text":"Remove the pizza from the oven, and place the pan on a heatproof surface. Carefully run a table knife or spatula between the edge of the pizza and side of the pan to prevent the cheese from sticking as it cools. Let the pizza cool very briefly; as soon as you feel comfortable doing so, carefully transfer it from the pan to a cooling rack or cutting surface. If garnishing with hard cheese and herbs, add those now. Serve the pizza anywhere from medium-hot to warm, and use kitchen shears or a large pair of scissors to cut it into wedges."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["mozzarella"],"item_tags":["basil","parmesan","tomato sauce"],"course_tags":["Dinner","Lunch"],"keywords":["Active Dry Yeast","All-Purpose Flour","Bake","Basil","Dinner","Instant Yeast","Lunch","Main Course","Mozzarella","Parmesan","Pizza and Calzones","Tomato Sauce","Vegetarian","Yeast"],"issues":null,"front":"nyt_1021193.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021193-cheesy-pan-pizza","rating":{"value":4,"count":3106},"date":"2020-06-23"},{"pair":12478,"title":"Lasagna With Roasted Beets and Herb Béchamel","subtitle":null,"author":"Martha Rose Shulman","servings":"8","yield_text":"8 servings","yield_count":8,"cook_time":"2 hours 30 minutes","nutrition":{"calories":"291","fat":"10 g","carbohydrates":"36 g","protein":"14 g"},"description":"I also call this “pink lasagna,” as the beets will bleed into the béchamel and onto the pasta when it bakes. Roast the beets ahead so that they will be cool enough to handle easily when you’re ready to assemble the lasagna.","from_your_kitchen":null,"ingredients":["6 medium-size red beets","3 tablespoons extra virgin olive oil","3 tablespoons minced shallot or onion","3 tablespoons sifted all-purpose flour","3 cups low-fat (1 percent) milk","Salt and freshly ground pepper","Pinch of freshly grated nutmeg","¼ cup finely chopped fresh herbs, like parsley, tarragon and chives","½ pound no-boil lasagna noodles","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 425 degrees. Cut the greens away from the beets, leaving about ¼ inch of stems. Scrub the beets and place in a baking dish or lidded ovenproof casserole. Add ¼ inch water to the dish. Cover tightly. Place in the oven and roast 40 to 45 minutes, until the beets are easily penetrated with the tip of a knife. Remove from the oven and allow to cool in the dish. Cut away the ends and slip off the skins. Slice crosswise into ¼-inch-thick rounds and set aside."},{"n":2,"title":null,"text":"Meanwhile, make the béchamel. Heat the oil over medium heat in a heavy medium saucepan. Add the shallot or onion and cook, stirring, until softened, about 3 minutes. Stir in the flour and cook, stirring, for about 3 minutes, until the mixture is smooth and bubbling, but not browned. It should have the texture of wet sand. Whisk in the milk all at once and bring to a simmer, whisking all the while, until the mixture begins to thicken. Turn the heat to very low and simmer, stirring often with a whisk and scraping the bottom and edges of the pan with a rubber spatula, for 10 to 15 minutes, until the sauce is thick and has lost its raw flour taste. Season with salt, pepper and nutmeg. Strain while hot into a large measuring cup or a medium bowl and stir in the chopped herbs and ¼ cup of the Parmesan."},{"n":3,"title":null,"text":"Preheat the oven to 350 degrees. Oil a rectangular baking dish. Spread a spoonful of béchamel over the bottom. Top with a layer of lasagna noodles. Spoon a thin layer of the béchamel over the noodles. Top with a layer of beets and sprinkle with Parmesan. Repeat the layers, ending with a layer of lasagna noodles topped with béchamel and Parmesan. Make sure the noodles are well coated with béchamel so they will be sure to soften during baking."},{"n":4,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Uncover and, if you wish, bake another 5 to 10 minutes, until the top begins to brown. Remove from the heat and allow to sit for 5 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["beets","pasta"],"item_tags":["nutmeg","parmesan","parsley"],"course_tags":["Dinner"],"keywords":["Bake","Beet","Casseroles","Dinner","Great Leftovers","Healthy","Italian","Lasagna","Main Course","Roast","Saute","Spring","Vegetarian"],"issues":null,"front":"nyt_12478.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12478-lasagna-with-roasted-beets-and-herb-bechamel","rating":{"value":4,"count":87},"date":"2012-06-01"},{"pair":1019901,"title":"Linguine With Crisp Chickpeas and Rosemary","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"921","fat":"44 g","carbohydrates":"109 g","protein":"25 g"},"description":"Pasta with chickpeas is a substantial, quickly assembled meal, but what’s alluring about this version is the undercurrent of rosemary. Whole sprigs lightly fried in olive oil provide flavor in two ways: the leaves are crumbled into the pasta for a fragrant punch, and the infused oil slicks the noodles. You could add spinach, arugula or kale when you toss the pasta in the sauce, or simply brighten it with parsley, Parmesan and lemon.","from_your_kitchen":null,"ingredients":["½ cup extra-virgin olive oil, plus more for serving","8 fresh rosemary sprigs","Kosher salt and black pepper","1 pound linguine or other long noodle","3 tablespoons unsalted butter","3 garlic cloves, peeled and smashed","1 (14-ounce) can chickpeas, rinsed, drained and patted very dry","½ cup coarsely chopped parsley","1 lemon, cut into wedges","Freshly grated Parmesan or pecorino, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of heavily salted water (2 heaping tablespoons kosher salt to about 7 quarts water) to a boil. Meanwhile, make the rosemary oil: Pat the rosemary dry with a kitchen towel. In a large Dutch oven or skillet big enough to hold all the pasta, warm the oil over medium heat. Once shimmering, add the rosemary sprigs and fry, flipping once, until sizzling subsides and leaves are crisp, 3 or 4 minutes."},{"n":2,"title":null,"text":"Transfer the sprigs to a paper towel-lined plate, and sprinkle with salt and pepper. Keep the pot with the oil on the stove."},{"n":3,"title":null,"text":"Add pasta to the boiling water, and cook to al dente according to package directions. Reserve ½ cup of the pasta cooking water, and drain the pasta."},{"n":4,"title":null,"text":"While the pasta cooks, with the rosemary oil over medium-high heat, add the butter. Once melted, add the garlic and chickpeas and fry, stirring occasionally, until the chickpeas are golden brown and crisp, 8 to 10 minutes. If some of the chickpeas explode like popcorn, that’s a good sign."},{"n":5,"title":null,"text":"As the chickpeas cook, remove the rosemary leaves from the sprigs (pinch the top of the sprig and swipe downwards). If any do not come off easily, they aren’t fully fried: Throw them back into the oil with the chickpeas and remove them after a quick fry. Crumble the leaves by rubbing them between your fingers, and set aside."},{"n":6,"title":null,"text":"Once the chickpeas are crisp, season with salt and pepper, reduce heat to low and stir in the pasta, adding pasta water as needed to form a glossy sauce. Stir in the parsley and crumbled rosemary leaves. Season to taste with salt and pepper. Serve with a lemon wedge for squeezing. Top with grated cheese and a drizzle of olive oil if desired."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["chickpeas","pasta"],"item_tags":["lemon","parmesan","rosemary"],"course_tags":["Dinner","Lunch"],"keywords":["Boil","Chickpea","Dinner","Italian","Kid-Friendly","Linguine","Lunch","Main Course","Pastas","Rosemary","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1019901.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019901-linguine-with-crisp-chickpeas-and-rosemary","rating":{"value":4,"count":1986},"date":"2019-01-07"},{"pair":1014929,"title":"Grated Squash, Corn and Tomatillo Tacos","subtitle":null,"author":"Martha Rose Shulman","servings":null,"yield_text":"10 to 12 tacos","yield_count":10,"cook_time":"About 30 minutes","nutrition":{"calories":"104","fat":"4 g","carbohydrates":"15 g","protein":"4 g"},"description":"Once you’ve made the tomatillo salsa, this light filling is very quick to put together.","from_your_kitchen":null,"ingredients":["1 tablespoon extra virgin olive oil or sunflower oil","1 small red onion, chopped","1 to 2 garlic cloves, minced","1 to 3 serrano or jalapeño chiles, minced (to taste)","1 pound summer squash, grated","Kernels from 2 ears of corn","¼ cup cilantro (more to taste)","10 to 12 corn tortillas","About 1 cup cooked tomatillo salsa","3 ounces crumbled queso fresco or feta","Shredded cabbage for topping (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil over medium heat in a large, heavy skillet and add the onion. Cook, stirring, until tender, about 5 minutes, and add the garlic and chiles. Cook, stirring, until the garlic is fragrant, 30 seconds to a minute, and add the grated squash, the corn kernels, and salt and pepper to taste. Cook, stirring, until the squash has wilted in the pan and the corn is tender, about 5 minutes. Stir in the cilantro, taste and adjust seasonings. Remove from the heat."},{"n":2,"title":null,"text":"Warm corn tortillas: Wrap them in a dish towel and place in a steamer above 1 inch of water. Bring the water to a boil, cover tightly and steam for 1 minute. Turn off the heat and allow to sit for 10 to 12 minutes."},{"n":3,"title":null,"text":"Spoon the warm corn and squash mixture onto the hot tortillas. Top with a generous spoonful of salsa, a sprinkling of cheese, and if desired, a handful of shredded cabbage. Fold up the tortilla and serve."}],"tips":["Advanced preparation: You can prepare the corn and squash filling several hours ahead. The color will fade out somewhat. The salsa will keep for 3 days in the refrigerator."],"cuisine_tags":["Mexican"],"ingredient_tags":["corn","summer squash","tortilla"],"item_tags":["cilantro","jalapeño","queso fresco"],"course_tags":["Dinner","Lunch"],"keywords":["Corn","Dinner","Easy","Gluten-Free","Healthy","Low-Sodium","Lunch","Main Course","Quick","Salsa","Saute","Squash","Steam","Summer","Vegetarian"],"issues":null,"front":"nyt_1014929.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014929-grated-squash-corn-and-tomatillo-tacos","rating":{"value":5,"count":288},"date":"2013-07-31"},{"pair":1018760,"title":"Chocolate-Chip Cookie Pizza","subtitle":null,"author":"Margaux Laskey","servings":null,"yield_text":"2 10-inch cookies or 1 sheet-pan pizza cookie","yield_count":2,"cook_time":"1 hour","nutrition":{"calories":"362","fat":"19 g","carbohydrates":"51 g","protein":"2 g"},"description":"You like chocolate chip cookies. You like pizza. What could be better than a giant chocolate chip pizza cookie? If your answer is, “pretty much nothing,” we’d say you’re 100% right. This Instagram-worthy treat starts with a batch of our famous chocolate chip cookie dough (with a smidge of cornstarch to keep the cookie soft and gooey in the center), but from there, it’s all yours. When we took it out of the oven, we spread on cherry jam “pizza sauce,” drizzled on melted white chocolate “mozzarella,” and added rounds of raspberry fruit leather “pepperoni.” But warmed Nutella and blobs of marshmallow fluff are a pretty awesome combination, too. We developed this recipe for a special print-only edition of The New York Times for Kids, but our sources tell us grown-up sweet tooths can't resist this oversized treat either. For a more sophisticated dinner party-worthy variation, leave off the toppings and serve generous wedges with scoops of vanilla ice cream and salted caramel sauce.","from_your_kitchen":null,"ingredients":["3 ⅔ cups minus 2 tablespoons all-purpose flour","3 ½ teaspoons cornstarch","1 ¼ teaspoons baking soda","1 ½ teaspoons coarse salt","2 ½ sticks (1 ¼ cups) unsalted butter, softened","1 ¼ cups (10 ounces) light brown sugar","1 cup plus 2 tablespoons (8 ounces) granulated sugar","2 large eggs","2 teaspoons natural vanilla extract","1 pound bittersweet or semisweet chocolate chips"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 350 degrees. Sift flour, cornstarch, baking soda and salt into a large bowl. Set aside."},{"n":2,"title":null,"text":"Using a mixer fitted with paddle attachment, cream butter and sugars together until very light, about 5 minutes, on medium-high. Add eggs, one at a time, mixing well after each addition. Stir in the vanilla. Reduce speed to low, add dry ingredients and mix until the white streaks of flour just disappear, 5 to 10 seconds. Stir in chocolate chips."},{"n":3,"title":null,"text":"For one large rectangular pizza, transfer the dough to a sheet pan lined with parchment paper and flatten out with your fingers or a rubber spatula. For two cookies, divide the dough into two equal pieces on two separate sheet pans lined with parchment paper and flatten into the shape of a circle. Be sure to leave a border of at least 1 ½ inches as cookie will spread."},{"n":4,"title":null,"text":"Bake until golden brown but still soft, 18 to 25 minutes. Transfer sheet to a wire rack for 10 minutes. Top as desired (see note). Cut in wedges and serve."}],"tips":["Toppings: warmed fruit jam, marshmallows or marshmallow fluff, fruit leather cut into circles for “pepperoni”, dried cherries, Nutella, peanut butter, shredded coconut, sprinkles, Swedish fish “anchovies,” “herbs” made from green Nerds candies. Use your imagination."],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Bittersweet Chocolate","Chocolate Chip Cookie","Cornstarch","Dessert","Kid-Friendly","Party","Semisweet Chocolate Chip"],"issues":null,"front":"nyt_1018760.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1018760-chocolate-chip-cookie-pizza","rating":{"value":4,"count":389},"date":"2017-05-11"},{"pair":11245,"title":"Thick-and-Gooey Chocolate-Chip Cookies","subtitle":null,"author":"Amanda Hesser","servings":null,"yield_text":"Makes 30 cookies","yield_count":30,"cook_time":"30 minutes","nutrition":{"calories":"282","fat":"17 g","carbohydrates":"33 g","protein":"4 g"},"description":"These hefty and extremely satisfying treats should be devoured with a cool glass of milk on hand. In the search for the perfect iteration of chocolate-chip cookies, three subsets of cookie rose to the top (check out the crisp and chewy versions to compare). Each recipe was tested more than a half-dozen times, so please grant us some generosity. Note that this version uses baking powder and the balls of dough are considerably larger.","from_your_kitchen":null,"ingredients":["2 ½ cups all-purpose flour","1 teaspoon baking powder","1 teaspoon baking soda","2 teaspoons kosher salt","8 ounces butter, softened","1 ½ cups packed light brown sugar","¼ cup sugar","3 eggs","1 tablespoon vanilla extract","3 cups chopped bittersweet chocolate (chunks and shavings)","2 cups chopped walnuts (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 350 degrees. Line two baking sheets with parchment paper or Silpat. Sift together the flour, baking powder, baking soda and salt."},{"n":2,"title":null,"text":"In a mixer fitted with a paddle, cream the butter and sugars until fluffy, 3 minutes. Add the eggs, one at a time, then the vanilla. Add the flour mixture all at once and blend until a dough forms. Fold in the chocolate and walnuts. Chill the dough for at least an hour."},{"n":3,"title":null,"text":"Roll ¼ -cup lumps of dough into balls, then place on the baking sheet and flatten to ½ -inch-thick disks spaced 2 inches apart. Chill the dough between batches. Bake until the edges turn golden, 14 to 17 minutes. Let cool slightly on the baking sheet, then transfer to a baking rack."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips","walnuts"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["All-Purpose Flour","Bake","Chocolate","Chocolate Chip Cookie","Dessert","Walnut"],"issues":null,"front":"nyt_11245.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/11245-thick-and-gooey-chocolate-chip-cookies","rating":{"value":4,"count":970},"date":"2006-01-22"},{"pair":1019703,"title":"Pasta With Mushrooms, Fried Eggs and Herbs","subtitle":null,"author":"Colu Henry","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"35 minutes","nutrition":{"calories":"517","fat":"21 g","carbohydrates":"68 g","protein":"18 g"},"description":"This fall-inspired, earthy pasta uses a combination of mushrooms for depth of flavor and is topped with a runny egg, which silkens up the sauce. Supermarkets these days generally have a good selection of different varieties such as cremini and shiitake, but if your standard white-button mushroom is all that’s available, this dish will still be a winner. If you’re not feeling pasta, the mushrooms are equally good served on top of creamy polenta or on their own. Red wine not optional.","from_your_kitchen":null,"ingredients":["Kosher salt","1 pound rigatoni or mezzi rigatoni","3 tablespoons olive oil, plus more for serving","4 large eggs","Black pepper","4 tablespoons unsalted butter","1 ½ pounds mixed mushrooms such as cremini, white button and shiitake, trimmed and roughly torn or chopped","1 large shallot, finely chopped","2 garlic cloves, finely chopped","2 teaspoons thyme, finely chopped","½ teaspoon red-pepper flakes","¼ cup grated pecorino or Parmesan, plus more for serving","¼ cup roughly chopped Italian parsley, leaves and tender stems","2 tablespoons torn mint, for garnish (optional, but recommended)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of well-salted water to a boil and cook pasta until it's al dente, 1 to 2 minutes less than package directions. Drain, reserving 1 ½ cups pasta water."},{"n":2,"title":null,"text":"Meanwhile, heat 1 tablespoon olive oil in a nonstick skillet over medium heat. Crack the eggs into the skillet and season with salt and pepper. Fry until the undersides are golden and crispy and the yolk is still runny, 2 to 4 minutes. Using a spatula, transfer eggs to a paper towel-lined plate."},{"n":3,"title":null,"text":"Heat 2 tablespoons of butter and the remaining olive oil in a 12-inch skillet over medium heat. Once the butter melts, add the mushrooms and sauté until deeply browned, about 12 to 15 minutes. Add the shallots, garlic, thyme and red-pepper flakes, and cook for 1 minute. Season well with salt."},{"n":4,"title":null,"text":"Add the pasta to the skillet along with the remaining butter, grated cheese and 1 cup of the pasta water, tossing everything together until the butter melts and the sauce is glossy, 1 to 2 minutes. Add the parsley and toss again to combine, adding more of the pasta water as needed to loosen up the sauce."},{"n":5,"title":null,"text":"Serve in bowls with a fried egg on top of each portion and scatter with the mint, if using. Pass additional grated cheese at the table and drizzle with a bit more of the olive oil if desired."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["eggs","mushrooms","pasta"],"item_tags":["mint","parmesan","red chile flakes","thyme"],"course_tags":["Dinner","Lunch"],"keywords":["Boil","Dinner","Fall","Lunch","Main Course","Mushroom","Parmesan","Pastas","Rigatoni","Vegetarian","Weeknight","Winter"],"issues":null,"front":"nyt_1019703.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019703-pasta-with-mushrooms-fried-eggs-and-herbs","rating":{"value":5,"count":731},"date":"2018-11-01"},{"pair":1014291,"title":"Mushroom Lasagna","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"90 minutes","nutrition":{"calories":"403","fat":"15 g","carbohydrates":"48 g","protein":"18 g"},"description":"This lasagna tastes very rich, even though it really isn’t. It combines an olive oil béchamel with a simple mushroom ragout and Parmesan cheese. I prefer no-boil lasagna noodles because they’re lighter than regular lasagna noodles. But I still boil them because I think the results are better if they’re cooked until they’re flexible (a couple of minutes) first.","from_your_kitchen":null,"ingredients":["1 ounce about 1 cup dried porcini or shiitake mushrooms","1 tablespoon extra virgin olive oil","2 shallots or 1 small onion, finely chopped","2 to 3 garlic cloves, minced","1 pound cremini mushrooms, sliced","Salt","½ cup fruity red wine, such as a Côtes du Rhône or Syrah","1 teaspoon fresh thyme leaves","Freshly ground pepper","2 tablespoons extra virgin olive oil","2 tablespoons minced shallot or onion","2 tablespoons sifted all-purpose flour","2 cups milk (may use low-fat milk)","Salt","freshly ground pepper","½ pound no-boil lasagna noodles","4 ounces Parmesan cheese, grated 1 cup","A few leaves of fresh sage (optional)"],"ingredient_groups":[{"at":0,"title":"FOR THE MUSHROOMS"},{"at":9,"title":"FOR THE BÉCHAMEL"},{"at":15,"title":"FOR THE LASAGNA"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Place the dried mushrooms in a glass measuring cup and pour 2 cups boiling water over them. Let soak 30 minutes, while you prepare the other ingredients. Place a strainer over a bowl, line it with cheesecloth or paper towels, and drain the mushrooms. Squeeze the mushrooms over the strainer to extract all the flavorful juices. If using shiitakes, cut away and discard the stems. Then rinse the mushrooms, away from the bowl with the soaking liquid, until they are free of sand. Squeeze dry and set aside. Chop coarsely. Measure out 1 ½ cups of the soaking liquid and set aside."},{"n":2,"title":null,"text":"Heat 1 tablespoon olive oil in a large, heavy skillet over medium heat and add the shallots or onion. Cook, stirring often, until tender, 3 to 5 minutes. Add the garlic, stir together for about 30 seconds, then add the fresh and reconstituted mushrooms and salt to taste. Cook, stirring often, until the mushrooms begin to soften and to sweat, about 5 minutes. Add the wine and turn the heat to high. Cook, stirring, until the liquid boils down and glazes the mushrooms, 5 to 10 minutes. Add thyme and stir in the mushroom soaking liquid. Bring to a simmer, add salt, and cook over medium-high heat, stirring often, until the mushrooms are thoroughly tender and fragrant and the surrounding broth has reduced by a little more than half, about 10 to 15 minutes. Remove from the heat, stir in some freshly ground pepper, taste and adjust salt."},{"n":3,"title":null,"text":"Meanwhile, make the béchamel. Heat the oil over medium heat in a heavy saucepan. Add the shallot or onion and cook, stirring, until softened, about 3 minutes. Stir in the flour and cook, stirring, for about 3 minutes, until smooth and bubbling, but not browned. It should have the texture of wet sand. Whisk in the milk all at once and bring to a simmer, whisking all the while, until the mixture begins to thicken. Turn the heat to very low and simmer, stirring often with a whisk and scraping the bottom and edges of the pan with a rubber spatula, for 10 to 15 minutes, until the sauce is thick and has lost its raw-flour taste. Season with salt and pepper. Strain while hot into the pan with the mushrooms."},{"n":4,"title":null,"text":"Assemble the lasagna. Heat the oven to 350 degrees Fahrenheit. Oil or butter a 2-quart rectangular baking dish. Bring a large pot of water to a boil, salt generously and add 3 or 4 lasagna noodles, just the number you need for one layer. Cook only until flexible, and using tongs or a skimmer, remove from the pan and set on a kitchen towel to drain. Spoon a thin layer of béchamel and mushrooms over the bottom of the dish. Top with a layer of noodles. Spread a ladleful of the mushroom/béchamel mixture over the noodles and top with a layer of Parmesan. Cook the next layer of noodles and continue to repeat the layers (I get three layers in my pan), ending with a layer of the mushroom/béchamel mixture topped with Parmesan. Cover with foil and place in the oven. Bake 30 minutes. Remove the foil, and if you want the edges of the noodles crispy and the top lightly browned, continue to bake uncovered for another 5 to 10 minutes. Serve hot or warm."}],"tips":["Advance preparation: The mushrooms can be cooked up to 4 days before the lasagna is assembled and baked. The bÃ©chamel can be made a day ahead. Whisk well and reheat gently before straining into the mushrooms and assembling the lasagna. The assembled lasagna can be tightly covered and refrigerated for a day before baking. Leftovers will keep for 3 or 4 days. Reheat in a low oven or in a microwave."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["mushrooms","pasta"],"item_tags":["parmesan","red wine","thyme"],"course_tags":["Dinner"],"keywords":["Bake","Dinner","Great Leftovers","Healthy","Lasagna","Main Course","Milk","Mushroom","Sauces and Gravies","Saute","Vegetarian"],"issues":null,"front":"nyt_1014291.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014291-mushroom-lasagna","rating":{"value":5,"count":2350},"date":"2011-10-12"},{"pair":9558,"title":"Takeout-Style Sesame Noodles","subtitle":null,"author":"Sam Sifton","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"10 minutes","nutrition":{"calories":"646","fat":"23 g","carbohydrates":"90 g","protein":"22 g"},"description":"Noodles dressed with sesame are popular in many parts of China, but this particular style, made with peanut butter and served cold, became a Chinese-American staple in the United States in the 1970s. The family of Shorty Tang — an ambitious restaurateur who emigrated from Sichuan to Taipei to New York — firmly believes that he invented the dish and still serve it at Hwa Yuan, the restaurant he opened in 1967 in Manhattan’s Chinatown. They have never divulged the exact recipe; this is our own lush but refreshing version. Sam Sifton","from_your_kitchen":null,"ingredients":["1 pound noodles, frozen or (preferably) fresh","2 tablespoons sesame oil, plus a splash","3 ½ tablespoons soy sauce","2 tablespoons rice vinegar","2 tablespoons sesame paste (preferably Chinese)","1 tablespoon smooth peanut butter","1 tablespoon granulated sugar","1 tablespoon finely grated ginger","2 teaspoons minced garlic","2 teaspoons chile-garlic paste, chile crisp or chile oil, or to taste","Half a cucumber, peeled, seeded and cut into ⅛-inch by ⅛-inch by 2-inch sticks","¼ cup chopped roasted peanuts"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of water to a boil. Add noodles and cook until barely tender, about 5 minutes. They should retain a hint of chewiness."},{"n":2,"title":null,"text":"Drain noodles, rinse with cold water, drain again and toss with a splash of sesame oil."},{"n":3,"title":null,"text":"In a medium bowl, whisk together the remaining 2 tablespoons sesame oil, the soy sauce, rice vinegar, sesame paste, peanut butter, sugar, ginger, garlic and chile-garlic paste."},{"n":4,"title":null,"text":"Pour the sauce over the noodles and toss."},{"n":5,"title":null,"text":"Transfer to a serving bowl, and garnish with cucumber and peanuts."}],"tips":["The Chinese sesame paste called for here is made of toasted sesame seeds; it is not the same as tahini, the Middle Eastern paste made of plain, untoasted sesame. But you could use tahini in a pinch. You need only add a little toasted sesame oil to compensate for flavor, and perhaps some peanut butter to keep the sauce emulsified."],"cuisine_tags":["Chinese","Fusion"],"ingredient_tags":["noodles","peanuts"],"item_tags":["ginger","peanut butter","rice vinegar","scallions","sesame oil"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Appetizer","Boil","Chinese American","Dinner","Easy","Kid-Friendly","Main Course","Noodle","Noodles","Peanut Butter","Quick","Sesame Paste","Side Dish","Summer","Vegetarian"],"issues":null,"front":"nyt_9558.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/9558-takeout-style-sesame-noodles","rating":{"value":5,"count":12626},"date":"2019-05-01"},{"pair":1021252,"title":"Heirloom Tomato Tart","subtitle":null,"author":"Vallery Lomas","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"1 1/2 hours","nutrition":{"calories":"282","fat":"15 g","carbohydrates":"25 g","protein":"12 g"},"description":"Heirloom tomatoes may seem flawed, but it’s actually their uniformly red counterparts who are the genetic deviants of the tomato family. Decades ago, many businesses decided to prioritize cookie-cutter-like hybrid tomatoes, which grow year-round and can survive a long, bumpy journey. It left heirloom tomatoes on the wrong side of the deal. The varieties that remain have a shorter shelf life and are relegated to just a few months of summer, but they’re sweeter with a more robust flavor. This tart celebrates juicy, vibrant tomatoes in a cheesy, herby, custard-filled, flaky crust, with each bite punctuated with pesto.","from_your_kitchen":null,"ingredients":["Dough for a 9-inch single crust pie, or use store-bought, rolled into an 11-inch round (see Note)","1 ½ pounds ripe heirloom tomatoes (about 4 medium)","¼ cup store-bought pesto","¾ cup shredded mozzarella (about 3 ounces)","1 tablespoon finely chopped fresh basil","1 tablespoon finely chopped fresh oregano","3 large eggs","⅓ cup heavy cream","½ teaspoon kosher salt","½ teaspoon freshly ground black pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 350 degrees. Fit the rolled-out dough into a 9-inch tart pan, allowing the edges to rise about ¼ inch above the rim of the pan. Prick the dough all over with a fork."},{"n":2,"title":null,"text":"Line the dough with aluminum foil and fill with pie weights or dried beans. Bake for 15 minutes until beginning to brown at the edges. Remove from the oven and carefully remove the foil and weights. Increase the oven temperature to 375 degrees."},{"n":3,"title":null,"text":"Meanwhile, cut the tomatoes into ½-inch slices. Place in a colander to drain excess tomato liquid for 20 minutes."},{"n":4,"title":null,"text":"Spread ¼ cup pesto in an even layer over the parbaked tart crust. Sprinkle the shredded mozzarella over the pesto. Sprinkle the fresh basil and oregano over the cheese."},{"n":5,"title":null,"text":"In a medium bowl, prepare the custard: Whisk together the eggs, cream, salt and pepper until combined."},{"n":6,"title":null,"text":"Place the sliced tomatoes evenly over the cheese and herbs in overlapping concentric circles."},{"n":7,"title":null,"text":"Pour the custard evenly over the tomato slices. Swirl the pan to evenly distribute the liquid. Bake until the filling is set and won’t jiggle when shaken, about 35 minutes."},{"n":8,"title":null,"text":"Remove from the oven and let cool slightly before serving warm. This tart can also be served at room temperature."}],"tips":["Packaged pie dough is an excellent shortcut for weeknight meals, and the tart crust can be parbaked a day in advance."],"cuisine_tags":["American","Italian"],"ingredient_tags":["eggs","tomato"],"item_tags":["basil","basil pesto","mozzarella","oregano"],"course_tags":["Breakfast","Dinner"],"keywords":["Basil","Brunch","Dinner","Heirloom Tomato","Main Course","Mozzarella","Pesto","Summer","Tart","Vegetarian"],"issues":null,"front":"nyt_1021252.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021252-heirloom-tomato-tart","rating":{"value":4,"count":4210},"date":"2020-07-22"},{"pair":1015023,"title":"Cucumber Salad With Soy, Ginger and Garlic","subtitle":null,"author":"Martha Rose Shulman","servings":"4","yield_text":"Serves 4","yield_count":4,"cook_time":"20 minutes","nutrition":{"calories":"196","fat":"17 g","carbohydrates":"10 g","protein":"2 g"},"description":"The trick to any sliced cucumber salad is to slice the cucumbers as thin as you can and to purge them by salting them before making the salad so the dressing doesn’t get watered down by the cucumber juice.","from_your_kitchen":null,"ingredients":["2 large thin-skinned cucumbers (about 1 ½ pounds), thinly sliced","Salt, to taste","3 tablespoons seasoned rice vinegar","1 tablespoon soy sauce","1 teaspoon sugar","1 small garlic clove, minced, or granulated garlic or garlic flakes to taste","1 teaspoon minced fresh ginger","⅛ teaspoon ground cayenne, plus more to taste","Freshly ground pepper","2 tablespoons dark sesame oil","3 tablespoons sunflower oil or grapeseed oil","1 bunch scallions, white and light green parts, very thinly sliced","2 tablespoons chopped cilantro"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Sprinkle the cucumbers with a generous amount of salt and let sit in a colander in the sink for 15 minutes. Rinse and dry on a kitchen towel. Transfer to a salad bowl."},{"n":2,"title":null,"text":"Whisk together the vinegar, soy sauce, sugar, garlic, ginger, cayenne, and pepper. Whisk in the sesame oil and the sunflower or grapeseed oil. Toss with the cucumbers, scallions, and cilantro. Chill until ready to serve."}],"tips":["Advance preparation: This will keep for a day or two in the refrigerator but the dressing will become more watery."],"cuisine_tags":["Chinese"],"ingredient_tags":["cucumber"],"item_tags":["cilantro","ginger","rice vinegar","scallions","sesame oil","soy sauce"],"course_tags":["Sides & Appetizers"],"keywords":["Asian","Cucumber","Dairy-Free","Easy","Healthy","No Cook","Quick","Rice Vinegar","Salad","Sesame Oil","Side Dish","Soy Sauce","Summer","Vegan","Vegetarian"],"issues":null,"front":"nyt_1015023.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015023-cucumber-salad-with-soy-ginger-and-garlic","rating":{"value":5,"count":6016},"date":"2013-09-05"},{"pair":1017358,"title":"Vegan Mapo Tofu","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"157","fat":"11 g","carbohydrates":"10 g","protein":"7 g"},"description":"Mapo tofu is a justly popular menu item in many Chinese restaurants. It is a quickly cooked dish of braised tofu with minced pork (sometimes beef) in a bracing spicy sauce made with fermented black beans and fermented broad bean paste, along with hot red pepper and Sichuan pepper. This meatless version with fresh shiitake mushrooms is completely satisfying, and surprisingly easy to make. For the best texture, use soft tofu rather than firm, taking care to cook it gently to keep it from crumbling.","from_your_kitchen":null,"ingredients":["8 ounces shiitake mushrooms","2 cups water","15 ounce block of soft tofu (do not use silken)","Salt","3 tablespoons vegetable oil","3 small dried hot red peppers","1 tablespoon fermented black beans, rinsed","1 tablespoon fermented spicy broad bean paste (doubanjiang)","2 teaspoons minced garlic","1 tablespoon grated ginger","2 teaspoons soy sauce","1 teaspoon toasted sesame oil","1 teaspoon finely ground Sichuan pepper","1 tablespoon corn- or potato starch, dissolved in 3 tablespoons cold water","½ cup slivered scallions, both white and green parts","Cilantro sprigs, for garnish"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Remove stems from mushrooms. Make a light mushroom broth by simmering stems in 2 cups water for 15 minutes, then strain and reserve broth (discard stems). Dice mushroom caps and set aside."},{"n":2,"title":null,"text":"Cut tofu into 1-inch cubes. Cover with boiling salted water, let steep for 15 minutes, then drain."},{"n":3,"title":null,"text":"Put oil in a wok or wide skillet over medium heat. Add red peppers, black beans and bean paste and cook, stirring until fragrant, about 1 minute. Add garlic and ginger and let sizzle, then add mushrooms, soy sauce, sesame oil and Sichuan pepper. Add 1 ½ cups mushroom broth and cook mixture gently for 2 minutes."},{"n":4,"title":null,"text":"Carefully add tofu cubes. Shake pan to distribute sauce, using a wooden spoon to help. Try to avoid smashing tofu. Drizzle in cornstarch mixture, gently swirling pan to incorporate (sauce will thicken) and simmer tofu in sauce for 2 minutes more. Thin with a little mushroom broth if necessary. Transfer to a low bowl or platter. Sprinkle with scallions and cilantro sprigs."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["mushrooms","tofu"],"item_tags":["doubanjiang","fermented black beans","ginger","scallions","sichuan pepper","soy sauce"],"course_tags":["Dinner","Lunch"],"keywords":["Beans","Chinese","Dinner","Doubanjiang","Fermented Black Bean","Lunch","Main Course","Quick","Shiitake","Sichuan Pepper","Simmer","Soft Tofu","Stir-Fry","Vegan","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1017358.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017358-vegan-mapo-tofu","rating":{"value":5,"count":3666},"date":"2015-04-22"},{"pair":1016467,"title":"Lasagna with Chard, Tomato Sauce and Ricotta","subtitle":null,"author":"Martha Rose Shulman","servings":"4 to 6","yield_text":"Serves 4 to 6","yield_count":4,"cook_time":"About 1 hour 30 minutes","nutrition":{"calories":"340","fat":"11 g","carbohydrates":"48 g","protein":"15 g"},"description":"This savory vegetarian lasagna is easy to put together. You can assemble it up to a day ahead of time, then bake it shortly before dinner.","from_your_kitchen":null,"ingredients":["1 generous bunch Swiss chard (about 1 ½ pounds)","Salt","½ pound regular or no-boil lasagna noodles","2 tablespoons plus 1 teaspoon extra virgin olive oil","2 large garlic cloves, minced or pressed","2 pounds fresh tomatoes, peeled, seeded and diced, or 1 (28-ounce) can chopped tomatoes, with juice","Pinch of sugar","1 large basil sprig","Freshly ground pepper","½ cup fresh ricotta cheese","⅓ to ½ cup freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of generously salted water to a boil while you prepare the chard. Fill a bowl with ice water. Tear the leaves from the stems and wash thoroughly in two changes of water. Discard the stems or set aside for another purpose."},{"n":2,"title":null,"text":"When the water comes to a boil, add the Swiss chard leaves. Boil 1 minute (from the time the water comes back to a boil), until tender but still bright green, then remove from the water with a slotted spoon or skimmer and transfer to the ice water. Drain and squeeze out excess water. Chop coarsely and set aside. Cook the lasagna noodles in the same pot of water if not using no-boil lasagna. Remove from the pot and toss with 1 teaspoon olive oil in a bowl."},{"n":3,"title":null,"text":"In a wide, nonstick frying pan, heat 1 tablespoon of the olive oil over medium heat and add the garlic. Cook, stirring, just until fragrant, about 1 minute. Add the tomatoes, sugar, basil sprig, and salt (begin with ½ teaspoon and add more later), and bring to a simmer. Simmer, stirring often, until thick, 15 to 25 minutes, depending on the amount of juice in the pan. Taste and adjust seasonings. Remove the basil sprig. Stir in the Swiss chard and remove from the heat."},{"n":4,"title":null,"text":"Preheat the oven to 375ºF. Oil a square or rectangular baking dish (no bigger than 2-quart) and line the bottom with a layer of lasagna noodles. Spread half the ricotta over the noodles and half the tomato-chard sauce over the ricotta. Sprinkle 2 tablespoons Parmesan over the tomato-chard sauce. Add another layer of noodles and top with the remaining ricotta and tomato-chard sauce, and 2 tablespoons Parmesan. Finish with a layer of noodles and the remaining Parmesan. Drizzle the remaining tablespoon of olive oil over the top. Cover the dish tightly with foil. Bake 30 minutes, or until bubbling and the pasta is tender. Uncover, allow to sit for 5 minutes, and serve."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["pasta","ricotta","swiss chard"],"item_tags":["basil","parmesan","tomato sauce"],"course_tags":["Dinner"],"keywords":["Great Leftovers","Lasagna","Vegetarian"],"issues":null,"front":"nyt_1016467.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016467-lasagna-with-chard-tomato-sauce-and-ricotta","rating":{"value":5,"count":307},"date":"2008-10-09"},{"pair":1017518,"title":"Panzanella","subtitle":null,"author":"Melissa Clark","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"45 minutes","nutrition":{"calories":"289","fat":"21 g","carbohydrates":"18 g","protein":"10 g"},"description":"At the height of tomato season, for every perfectly ripe, taut and juicy specimen there’s an overripe, oozing counterpart not far away. The Tuscan bread salad called panzanella is the perfect place to use those sad, soft tomatoes that are still rich in flavor. Traditional panzanella is made with stale, dried bread that’s rehydrated with a dressing of sweet tomato juices, vinegar and plenty of olive oil. This version includes mozzarella for richness and cucumber for crunch. It’s an ideal do-ahead dish; the longer the mixture sits (up to 6 or so hours), the better it tastes. Just be sure to dry your bread out thoroughly in the oven so it won’t turn to mush. For a make-ahead summer party, serve alongside crunchy fried chicken and round out the meal with a luscious coconut cake accented with peaches.","from_your_kitchen":null,"ingredients":["4 ounces ciabatta or baguette, preferably stale, cut into 1-inch cubes (about 3 cups)","6 tablespoons extra-virgin olive oil, more to taste","¾ teaspoon kosher sea salt, more to taste","2 pounds very ripe tomatoes, preferably a mix of varieties and colors","6 ounces fresh mozzarella, torn or cut into bite-size pieces","½ cup thinly sliced red onion, about half a small onion","2 garlic cloves, grated to a paste","2 tablespoons red wine vinegar, more to taste","1 tablespoon chopped fresh oregano or thyme (or a combination)","Large pinch red-pepper flakes (optional)","½ teaspoon Dijon mustard","Black pepper, to taste","½ cup thinly sliced Persian or Kirby cucumber, about 1 small cucumber","½ cup torn basil leaves","¼ cup flat-leaf parsley leaves, roughly chopped","1 tablespoon capers, drained"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Spread the bread cubes on a rimmed baking sheet and toss with 2 tablespoons oil and a pinch of salt. Bake until they are dried out and pale golden brown at the edges, about 7 to 15 minutes. Let cool on a wire rack."},{"n":2,"title":null,"text":"Cut tomatoes into bite-size pieces and transfer to a large bowl. Add mozzarella, onions, garlic paste, 1 tablespoon vinegar, oregano or thyme, ¼ teaspoon salt and the red-pepper flakes if using. Toss to coat and set aside."},{"n":3,"title":null,"text":"In a medium bowl, combine remaining 1 tablespoon vinegar, the mustard, ¼ teaspoon salt and some black pepper to taste. While whisking constantly, slowly drizzle in the remaining 4 tablespoons olive oil until the mixture is thickened. Stir in cucumbers, basil and parsley."},{"n":4,"title":null,"text":"Add bread cubes, cucumber mixture and capers to the tomatoes and toss well. Let sit for at least 30 minutes and up to 4 hours before serving. Toss with a little more olive oil, vinegar and salt if needed just before serving."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["ciabatta","tomato"],"item_tags":["basil","capers","mozzarella","red wine vinegar"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Dinner","Italian","Lunch","Mozzarella","Salad","Side Dish","Tomato"],"issues":null,"front":"nyt_1017518.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017518-panzanella","rating":{"value":5,"count":3452},"date":"2015-07-08"},{"pair":1020860,"title":"Pasta e Ceci (Italian Pasta and Chickpea Stew)","subtitle":null,"author":"Colu Henry","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"396","fat":"16 g","carbohydrates":"51 g","protein":"15 g"},"description":"There is an incredible number of recipes for this classic Roman dish, and everyone has an opinion on how it should be prepared. This version is more stew than soup, but it can be loosened up with a bit more water if you prefer. It begins with sautéing onion, tomatoes, garlic and rosemary in olive oil, then tossing in the chickpeas, and smashing a few to give the stew a creamy texture. Water is added, then uncooked pasta, which cooks as the stew simmers (and results in one less dish for you wash). Escarole is folded in right before serving. This flexible stew can go in a number of directions, so tweak it as you see fit, but don’t forget to finish each bowl with grated pecorino and a drizzle of olive oil. Ciao.","from_your_kitchen":null,"ingredients":["3 tablespoons olive oil, plus more for drizzling","1 medium yellow onion, finely chopped","3 garlic cloves, finely chopped","2 teaspoons chopped fresh rosemary","½ teaspoon red-pepper flakes","Kosher salt and black pepper","1 packed cup canned whole tomatoes, drained","1 (15-ounce) can chickpeas, rinsed","1 cup ditalini","4 cups roughly chopped escarole, Tuscan kale or radicchio","Grated pecorino, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oil in a large stock pot or Dutch oven over medium. Add the onion and cook, stirring occasionally, until softened but not taking on any color, 4 to 5 minutes. Add the garlic, rosemary and red-pepper flakes, and cook 1 minute more. Season well with salt and pepper."},{"n":2,"title":null,"text":"Stir in the tomatoes and the chickpeas, breaking up the tomatoes with the back of a spoon or spatula and smashing about ½ cup of the beans."},{"n":3,"title":null,"text":"Add 3 cups water and bring to a boil over high. Add the pasta and simmer, stirring often to make sure nothing sticks to the bottom of the pan, until the pasta is al dente, about 10 minutes. The water will mostly be absorbed by the pasta, but if you prefer it brothier, you can add ½ to 1 cup water and simmer until warmed through, 1 minute more. Season to taste with salt and pepper."},{"n":4,"title":null,"text":"Add the escarole and stir until wilted. Taste and adjust seasonings accordingly. Ladle into bowls and top with grated cheese and a drizzle of olive oil."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["chickpeas","kale","pasta"],"item_tags":["pecorino","red chile flakes","rosemary"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Appetizer","Budget","Canned Tomato","Chickpea","Dinner","Dutch Oven","Easy","Escarole","Great Leftovers","Italian","Main Course","Pasta","Quick","Radicchio","Stew","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020860.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020860-pasta-e-ceci-italian-pasta-and-chickpea-stew","rating":{"value":5,"count":10719},"date":"2020-02-06"},{"pair":1015236,"title":"Penne all’Arrabbiata","subtitle":null,"author":"The New York Times","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"30 minutes","nutrition":{"calories":"469","fat":"20 g","carbohydrates":"62 g","protein":"11 g"},"description":"This, Mario Batali wrote in 2013 in The Times, is one of his late-night favorites. Its uncomplicated nature lends itself to an after-midnight feast. It’s basically pasta with tomato sauce and cheese, but red pepper flakes give the sauce a delicious kick.","from_your_kitchen":null,"ingredients":["3 tablespoons kosher salt","4 tablespoons extra-virgin olive oil, plus 4 more tablespoons","½ cup tomato paste","1 tablespoon hot red-pepper flakes","1 ½ cups chopped tomatoes, like Pomì","1 pound penne","Maldon or other flaky sea salt","Freshly grated Parmigiano-Reggiano for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring 6 quarts of water to a boil in a large pot, and add 3 tablespoons kosher salt."},{"n":2,"title":null,"text":"Meanwhile, put 4 tablespoons olive oil in a large sauté pan over medium heat, and then add the tomato paste and pepper flakes; reduce the heat to low and stir just until fragrant, about 4 minutes. Stir in the tomatoes, and remove from the heat."},{"n":3,"title":null,"text":"Drop the pasta into the boiling water, and cook until al dente. Drain the pasta, reserving ¼ cup of the pasta water."},{"n":4,"title":null,"text":"Add the pasta and the reserved pasta water to the tomato sauce, stir and toss over medium heat until the pasta is well coated. Season with salt if necessary, then add the remaining oil, tossing well. Serve immediately, with grated Parmigiano-Reggiano on the side."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["pasta"],"item_tags":["parmesan","red chile flakes","tomato paste"],"course_tags":["Dinner","Lunch"],"keywords":["Boil","Dinner","Easy","Lunch","Main Course","Quick","Saute","Vegetarian"],"issues":null,"front":"nyt_1015236.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015236-penne-allarrabbiata","rating":{"value":5,"count":2013},"date":"2013-10-20"},{"pair":11244,"title":"Flat-and-Chewy Chocolate-Chip Cookies","subtitle":null,"author":"Amanda Hesser","servings":null,"yield_text":"Makes 30 to 35 cookies","yield_count":30,"cook_time":"30 minutes","nutrition":{"calories":"226","fat":"14 g","carbohydrates":"25 g","protein":"3 g"},"description":"It is with great trepidation that I offer three classic recipes, hoping to suit the three schools of chocolate-chip cookiedom. (Try the crisp and gooey versions to compare.) This version is perfect for dunking in milk, and miles ahead of anything found in a plastic sleeve. Note that this recipe uses two eggs, directly between the crisp version's omission and the gooey version's use of three.","from_your_kitchen":null,"ingredients":["2 cups all-purpose flour","1 ¼ teaspoons baking soda","1 tablespoon kosher salt","8 ounces butter, softened","1 ½ cups packed light brown sugar","¼ cup sugar","2 eggs","1 tablespoon vanilla extract","2 cups chopped bittersweet chocolate (chunks and shavings)","2 cups chopped toasted walnuts (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Line two baking sheets with parchment paper or Silpat. Sift together the flour, baking soda and salt."},{"n":2,"title":null,"text":"In a mixer fitted with a paddle, cream the butter and sugars until fluffy, 3 minutes. Add the eggs, one at a time, then the vanilla. Add the flour mixture all at once and blend until a dough forms. Fold in the chocolate and walnuts. Chill the dough for at least an hour."},{"n":3,"title":null,"text":"Preheat oven to 325. Roll 2 ½ -tablespoon lumps of dough into balls, then place on the baking sheet and flatten to ½ -inch-thick disks spaced 2 inches apart. Chill the dough between batches. Bake until the edges are golden brown, 14 to 16 minutes. Let cool slightly on the baking sheet, then transfer to a baking rack."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips","walnuts"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["All-Purpose Flour","Bake","Chocolate","Chocolate Chip Cookie","Dessert","Walnut"],"issues":null,"front":"nyt_11244.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/11244-flat-and-chewy-chocolate-chip-cookies","rating":{"value":4,"count":2330},"date":"2006-01-22"},{"pair":1020055,"title":"Huevos Rotos (Broken Eggs)","subtitle":null,"author":"Ali Slagle","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"417","fat":"22 g","carbohydrates":"45 g","protein":"11 g"},"description":"Variations of this hearty fried egg-and-potato dish can be found throughout Spain, including the Canary Islands, where it’s said to have originated. There’s always a runny egg, but whether it sits atop fried potato rounds, French fries or crunchy chips varies by region and personal preference. The potatoes are often served with chorizo sausage or Serrano ham, but in this vegetarian version, smoked paprika and red-pepper flakes mimic chorizo’s flavor and heat. Pierce the eggs just before serving so the golden yolks coat the potatoes with a glossy sauce. Serve with sautéed greens or a crisp salad dressed with a lemon vinaigrette. This one-pan meal is good with a cup of coffee or a beer — it’s breakfast, lunch or dinner material.","from_your_kitchen":null,"ingredients":["⅓ cup extra-virgin olive oil, plus more as needed","2 teaspoons smoked paprika","½ teaspoon red-pepper flakes or ¼ teaspoon ground cayenne","Kosher salt and black pepper","2 pounds new potatoes, cut into 1-inch pieces if necessary","1 medium onion, finely chopped","4 garlic cloves, finely chopped","4 eggs","Lemon wedges, for serving","Flaky sea salt, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In a measuring cup, combine the olive oil, paprika, red-pepper flakes, 1 ½ teaspoons salt, a generous grind of pepper and 1 cup water. Put the potatoes in a large skillet and pour the olive oil mixture over them. Bring to a boil, then cover and cook on high until the potatoes are fork-tender, 6 to 9 minutes."},{"n":2,"title":null,"text":"Uncover and turn the heat to low. If the potatoes are sticking or dry, add more olive oil. Arrange the potatoes in an even layer, cut side down if halved, then add the onion and garlic surrounding the potatoes. Cover and cook until the potatoes are golden-brown and the onions are softened, 4 to 6 minutes."},{"n":3,"title":null,"text":"Stir the potatoes (if they’re sticking, add more oil). Make 4 nests in the potatoes and crack an egg into each. Season with salt and pepper. Cover and cook until the whites are set and the yolks are still runny, 4 to 6 minutes."},{"n":4,"title":null,"text":"To serve, break the yolks gently with a serving spoon, then scoop some potatoes and an egg onto plates or into shallow bowls. Serve with a squeeze of lemon and flaky salt."}],"tips":[],"cuisine_tags":["Spanish"],"ingredient_tags":["eggs","potato"],"item_tags":["red chile flakes","smoked paprika"],"course_tags":["Breakfast","Dinner","Lunch"],"keywords":["Breakfast","Brunch","Dinner","Easy","Egg","Egg Dish","Kid-Friendly","Lunch","Main Course","New Potato","Quick","Skillet","Smoked Paprika","Spanish","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020055.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020055-huevos-rotos-broken-eggs","rating":{"value":5,"count":5083},"date":"2019-02-24"},{"pair":1015832,"title":"Quesadilla With Mushroom Ragoût and Chipotles","subtitle":null,"author":"Martha Rose Shulman","servings":null,"yield_text":"2 quesadillas","yield_count":2,"cook_time":"10 minutes","nutrition":{"calories":"190","fat":"8 g","carbohydrates":"22 g","protein":"8 g"},"description":"Mushroom ragoût accepts chipotles willingly. I made a delicious and substantial quesadilla dinner with the ragoût, two tortillas and a bit of cheese in under three minutes.","from_your_kitchen":null,"ingredients":["6 tablespoons mushroom ragoût","1 teaspoon chopped canned chipotle in adobo (more to taste)","4 corn tortillas","1 ½ ounces grated Monterey Jack or Gruyère (about ⅓ cup)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Stir the chopped chipotles into the mushroom ragoût. Taste and add more if you want more spice."},{"n":2,"title":null,"text":"Using a microwave: Place a corn tortilla on a plate. Top with a heaped tablespoon of the grated cheese. Add half the mushrooms and spread in an even layer. Sprinkle another heaped tablespoon of the cheese over the mushrooms and top with another tortilla. Press down gently. Repeat with the remaining ingredients. Microwave for 1 to 1 ½ minutes, until the cheese has melted. Remove from the microwave, cut into quarters, and serve. Using a pan: Place a corn tortilla in a pan. Top with a heaped tablespoon of the cheese and half the mushrooms and spread in an even layer. Sprinkle on another heaped tablespoon the cheese. Turn the heat on medium-high and heat until the cheese begins to melt. Place the remaining tortilla on top of the cheese and press down lightly. Flip the quesadilla over in the pan and heat for about 30 seconds, or until the cheese has melted. Flip back over and remove to a plate. Cut into quarters or sixths, and serve. Repeat with the remaining ingredients."}],"tips":["Advance preparation: The mushroom ragoût will keep for 3 or 4 days in the refrigerator."],"cuisine_tags":["Mexican"],"ingredient_tags":["mushrooms","tortilla"],"item_tags":["chipotle","gruyere","monterey jack"],"course_tags":["Breakfast","Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Brunch","Dinner","Fall","Five Ingredient","Gruyère","Healthy","Low Sugar","Lunch","Main Course","Mexican","Microwave","Monterey Jack Cheese","Mushroom","Quesadilla","Quick","Vegetarian","Winter"],"issues":null,"front":"nyt_1015832.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015832-quesadilla-with-mushroom-ragout-and-chipotles","rating":{"value":4,"count":119},"date":"2013-12-20"},{"pair":1017811,"title":"Shaved Butternut Squash With Dates","subtitle":null,"author":"Melissa Clark","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"20 minutes","nutrition":{"calories":"169","fat":"7 g","carbohydrates":"28 g","protein":"2 g"},"description":"Shaved slivers of raw butternut squash make for a surprisingly refreshing and crisp salad. Here, it is served with a dressing of tangy buttermilk, sweet dates and crunchy pumpkinseeds. Look for a small, fresh butternut squash, preferably one with a long neck, which makes it easy to shave. Melissa Clark","from_your_kitchen":null,"ingredients":["1 ½ pounds young butternut squash, peeled, halved lengthwise and seeded","½ teaspoon finely grated lemon zest (from ½ lemon)","1 tablespoon lemon juice (from ½ lemon), more as needed","3 tablespoons extra-virgin olive oil","Pinch of granulated sugar","Fine sea salt","Freshly cracked black pepper","½ cup dates, pitted and roughly chopped","¼ cup buttermilk","2 tablespoons toasted pumpkinseeds"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Cut the squash into 2-inch chunks. Using a mandoline or vegetable peeler, shave the chunks into thin slivers."},{"n":2,"title":null,"text":"Place squash shavings in large bowl and add lemon zest and juice, olive oil and sugar. Season with a few pinches of salt and pepper and toss to coat. Macerate for 10 minutes, or until shavings tenderize (this could take up to 30 minutes, and once tender you can hold them for up to 6 hours). Toss with dates and season to taste with more salt and lemon juice."},{"n":3,"title":null,"text":"Pour buttermilk into a small bowl and season with salt and pepper. Smear the buttermilk on a serving platter and top with shaved mixture. Sprinkle with pumpkinseeds."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["butternut squash"],"item_tags":["dates","lemon","pumpkin seeds"],"course_tags":["Sides & Appetizers"],"keywords":["American","Butternut Squash","Fall","Gluten-Free","Pumpkin Seed","Salad","Side Dish","Thanksgiving","Vegetables","Vegetarian","Winter"],"issues":null,"front":"nyt_1017811.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017811-shaved-butternut-squash-with-dates","rating":{"value":4,"count":163},"date":"2015-11-18"},{"pair":1014343,"title":"Butternut Squash, Caramelized Onion and Spinach Lasagna","subtitle":null,"author":"Tara Parker-Pope","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"3 hours 15 minutes","nutrition":{"calories":"446","fat":"26 g","carbohydrates":"35 g","protein":"20 g"},"description":"This rich fall lasagna from Kim Quay, the owner of Comfort Food, a catering and prepared food business in Morrisville, Pa., makes an excellent main course for vegetarians and meat-lovers alike. Tara Parker-Pope","from_your_kitchen":null,"ingredients":["1 large butternut squash","6 tablespoons olive oil, divided","3 red onions, medium, julienned","1 pound part-skim ricotta cheese","2 tablespoons rosemary, chopped","2 eggs","1 ½ cups grated Parmesan cheese, divided","3 tablespoons unsalted butter","Scant ½ cup all-purpose flour","3 ½ cups whole milk","Pinch nutmeg","1 bag chopped frozen spinach (1-pound), defrosted and drained","6 sheets fresh pasta, or no-boil lasagna noodles","Salt","Pepper"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Roast the butternut squash. Preheat oven to 375 degrees. Cut squash in half lengthwise; remove seeds. Place in roasting pan and drizzle with 3 tablespoons of olive oil. Place in oven and cook until soft all the way through, about 1 hour. Set aside until cool. When cooled, remove skin and place in food processor. Purée until smooth, season with salt and pepper to taste, and set aside."},{"n":2,"title":null,"text":"To caramelize the onions: Place 3 tablespoons of olive oil in sauté pan. Heat until hot but not smoking; add onions. Toss to coat with oil. Turn heat down to medium and cook until onions are soft and browned, about 25 minutes. Season with salt and pepper to taste. Set aside."},{"n":3,"title":null,"text":"Prepare a ricotta cheese mixture. Mix ricotta cheese, chopped rosemary, eggs, half the grated Parmesan and salt and pepper to taste. Set aside."},{"n":4,"title":null,"text":"Make a spinach Mornay sauce. Melt butter in a saucepan, add flour and stir. Cook 2 minutes. Add milk and stir until it comes to a boil. Add the rest of the grated Parmesan, the nutmeg and the defrosted spinach. Season with salt and pepper. Set aside."},{"n":5,"title":null,"text":"Assemble the dish. Spray a 9” x 13” pan with cooking spray. Spread 1 cup of the spinach sauce on the bottom of the pan. Cover with a layer of fresh pasta sheets. Spread half of the roasted butternut squash on top of the pasta sheets. Top with another layer of pasta sheets. Spread ricotta cheese mixture on top of pasta sheets, and spread caramelized onion on top of ricotta mixture. Cover with an additional layer of pasta sheets. Top with the other half of the butternut purée and then another layer of pasta. Finish by using the rest of the spinach Mornay sauce for the top layer. Cover with aluminum foil and bake at 350 degrees for 1 hour. Uncover and cook for 15 minutes more."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["butternut squash","pasta","ricotta","spinach"],"item_tags":["nutmeg","parmesan","rosemary"],"course_tags":["Dinner"],"keywords":["Bake","Butternut Squash","Caramelize","Dinner","Fall","Great Leftovers","Lasagna","Main Course","Roast","Sauces and Gravies","Spinach","Thanksgiving","Vegetarian"],"issues":null,"front":"nyt_1014343.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014343-butternut-squash-caramelized-onion-and-spinach-lasagna","rating":{"value":5,"count":909},"date":"2012-11-16"},{"pair":1020738,"title":"Mushroom Bourguignon","subtitle":null,"author":"Melissa Clark","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"325","fat":"15 g","carbohydrates":"34 g","protein":"7 g"},"description":"Meaty mushrooms simmered with pearl onions, wine and carrots make for a rich, wintry Bourguignon-style stew. The quality of the stock here makes a big difference, so if you’re not using homemade, buy a good brand. If you’re a meat eater, beef broth adds a familiar brawny character to this dish, but mushroom or vegetable broth works just as well, especially because the whole dish is rounded out with a tamari for depth. For the best flavor, use as many kinds of mushrooms as you can get, and let them really brown when searing; that caramelization adds a lot of depth to the sauce. Maitake mushrooms give this a brisket-like texture, in a very good way.","from_your_kitchen":null,"ingredients":["6 tablespoons butter or extra-virgin olive oil, plus more as needed","2 pounds mixed mushrooms, such as portobello, cremini, white button, shiitake or oyster, cut into 1-inch chunks (about 10 cups)","8 ounces peeled pearl onions (2 cups), larger ones cut in half","Kosher salt and freshly ground black pepper","1 large leek or 2 small leeks, white and light green parts, diced (1 ½ cups)","2 carrots, thinly sliced","3 garlic cloves (2 minced, 1 grated to a paste)","1 tablespoon tomato paste","2 ½ tablespoons all-purpose flour","1 ½ cups dry red wine","1 ½ cups beef, mushroom or vegetable broth","1 tablespoon tamari or soy sauce, plus more to taste","3 large fresh thyme branches or ½ teaspoon dried thyme","1 bay leaf","3 to 4 ounces chanterelle or oyster mushrooms, thinly sliced (about 1 cup)","Smoked paprika, for serving","Polenta, egg noodles or mashed potatoes, for serving","Chopped flat-leaf parsley, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Add 2 tablespoons butter or oil to a large Dutch oven or pot and set it over medium heat. When the fat is hot, stir in half the mushrooms and half the pearl onions. (If it doesn’t all fit in the pot in one layer, you might have to do this in three batches, rather than two.) Without moving them around too much, cook the mushrooms until they are brown on one side, about 3 minutes. Stir and let them brown on the other side, 2 to 3 minutes more. Use a slotted spoon to transfer mushrooms and onions to a large bowl or plate and sprinkle with salt and pepper. Repeat with another 2 tablespoons butter and the remaining mushrooms and pearl onions, seasoning them as you go."},{"n":2,"title":null,"text":"Reduce heat to medium-low. Add another 1 tablespoon butter or oil to pan. Add leeks and carrot and sauté until the leeks turn lightly golden and start to soften, 5 minutes. Add the 2 minced garlic cloves and sauté for 1 minute longer. Stir in tomato paste and cook for 1 minute. Stir in flour and cook, stirring, for 1 minute, then add wine, broth, 1 tablespoon tamari, thyme and bay leaf, scraping up the brown bits at bottom of pot."},{"n":3,"title":null,"text":"Add reserved cooked mushrooms and pearl onions back to the pot and bring to a simmer. Partly cover the pot and simmer on low heat until carrots and onions are tender and sauce is thick, 30 to 40 minutes. Taste and add more salt and tamari if needed. Stir in the grated garlic clove."},{"n":4,"title":null,"text":"Just before serving, heat a small skillet over high heat and add ½ tablespoon butter or oil. Add half of the sliced chanterelles or oyster mushrooms and let cook without moving until they are crisp and brown on one side, 1 to 2 minutes. Flip and cook on the other side. Transfer to a plate and sprinkle with salt and smoked paprika. Repeat with remaining butter and mushrooms. Serve mushroom Bourguignon over polenta, noodles or mashed potatoes, topped with fried mushrooms and parsley."}],"tips":[],"cuisine_tags":["French"],"ingredient_tags":["carrot","mushrooms"],"item_tags":["red wine","tamari","thyme","tomato paste"],"course_tags":["Dinner"],"keywords":["Dinner","Dry Red Wine","Dutch Oven","Fall","French","Great Leftovers","Main Course","Mushroom","Pearl Onion","Stew","Vegan","Vegan Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_1020738.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020738-mushroom-bourguignon","rating":{"value":4,"count":13282},"date":"2020-01-01"},{"pair":1013416,"title":"Roasted Cauliflower Salad With Watercress, Walnuts and Gruyère","subtitle":null,"author":"Melissa Clark","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"1 hour","nutrition":{"calories":"487","fat":"44 g","carbohydrates":"10 g","protein":"17 g"},"description":"You can make this kind of salad with almost any vegetable that won’t wilt or burn when subjected to a copious slick of oil and a blast of high heat. Broccoli, brussels sprouts, beets, parsnips, sweet potatoes, winter squash and rutabagas all work well. One of the best vegetables for this salad, though, is cauliflower. The florets turn juicy and tender in the center while crisping and browning around the edges, and cauliflower’s mild flavor is amenable enough to pair nicely with almost anything else you toss in the bowl.","from_your_kitchen":null,"ingredients":["1 head cauliflower, cut into bite-size florets","6 tablespoons extra virgin olive oil","1 ½ teaspoons kosher salt","¾ teaspoon pepper","1 tablespoon sherry vinegar","2 bunches watercress, large stems removed","¼ pound Gruyère, diced or grated (about 1 cup)","⅔ cup toasted walnuts"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 400 degrees. In a bowl, toss together the cauliflower, 2 tablespoons olive oil, 1 teaspoon salt and ¼ teaspoon pepper. Spread the cauliflower on a baking sheet in a single layer. Roast, tossing occasionally, until tender and dark golden, 30 to 35 minutes. Let cool for 10 minutes."},{"n":2,"title":null,"text":"In a small bowl, whisk together the vinegar with the remaining salt and pepper, and then whisk in the remaining oil."},{"n":3,"title":null,"text":"In a salad bowl, toss the watercress, cheese, nuts and warm cauliflower. Pour the vinaigrette over the salad and toss until well combined."}],"tips":[],"cuisine_tags":["French"],"ingredient_tags":["cauliflower","walnuts"],"item_tags":["gruyere","sherry vinegar"],"course_tags":["Lunch","Sides & Appetizers"],"keywords":["Cauliflower","Easy","Gluten-Free","Roast","Salad","Vegetables","Vegetarian","Watercress","Weeknight"],"issues":null,"front":"nyt_1013416.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1013416-roasted-cauliflower-salad-with-watercress-walnuts-and-gruyere","rating":{"value":5,"count":830},"date":"2011-01-05"},{"pair":1019704,"title":"Baked Eggs With Beans and Greens","subtitle":null,"author":"Colu Henry","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"358","fat":"21 g","carbohydrates":"25 g","protein":"20 g"},"description":"Consider this a heartier version of the classic Italian dish “eggs in purgatory,” which works well for breakfast, lunch or dinner. It’s also very forgiving. If you’d rather keep this a vegetarian meal, skip the sausage. No chickpeas? No problem. Any white bean will work well in its place. Same with the greens. Use what you have (anything that wilts works). Sprinkling the dish with grated cheese before serving is not required, but it sure does taste good. Serve with thick slices of toasted sesame bread slathered with plenty of softened butter.","from_your_kitchen":null,"ingredients":["2 tablespoons olive oil","½ pound sweet or spicy Italian sausage, casings removed (optional)","1 medium yellow onion, thinly sliced","1 (15-ounce) can chickpeas or white beans, drained and rinsed","2 garlic cloves, finely chopped","Kosher salt","1 (28-ounce) can whole tomatoes, gently crushed by hand","4 cups stemmed and packed roughly chopped greens such as spinach, kale or Swiss chard","6 large eggs","Black pepper","2 tablespoons mixed herbs, such as Italian parsley and basil, for garnish","Grated cheese, such as pecorino or Parmesan, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 375 degrees. Heat the olive oil in a 12-inch ovenproof skillet over medium heat. If using the sausage, add to the pan and cook, breaking it into ½-inch pieces, by pressing with the back of spatula or wooden spoon until crisp and cooked through, about 8 minutes. Remove with a slotted spoon and set aside."},{"n":2,"title":null,"text":"Add the onion to the skillet and cook until softened, about 3 to 5 minutes. Add the chickpeas and the garlic and cook until the garlic is fragrant, about 1 minute. Season with salt. Add the sausage back to the pan along with the tomatoes and stir to combine. Bring to a simmer and gradually add in the chopped greens by the handful, tossing together until wilted. Season with salt."},{"n":3,"title":null,"text":"Using a spoon, create hollows in the sauce and gently crack the eggs into each, and season the eggs with salt and pepper. Transfer to the oven and cook until the eggs are set, about 7 to 9 minutes. Scatter the herbs on top along with a tablespoon or two of grated cheese, if using."}],"tips":[],"cuisine_tags":["Italian"],"ingredient_tags":["chickpeas","eggs","tomato"],"item_tags":["basil","parmesan"],"course_tags":["Breakfast","Dinner"],"keywords":["Bake","Brunch","Chickpea","Dinner","Egg","Father’s Day","Greens","Italian Sausage","Main Course","Mother’s Day","Sausages","Saute","Tomato","Weeknight"],"issues":null,"front":"nyt_1019704.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019704-baked-eggs-with-beans-and-greens","rating":{"value":5,"count":1597},"date":"2018-11-01"},{"pair":11243,"title":"Thin-and-Crisp Chocolate-Chip Cookies","subtitle":null,"author":"Amanda Hesser","servings":null,"yield_text":"Makes 24 cookies","yield_count":24,"cook_time":"30 minutes","nutrition":{"calories":"249","fat":"16 g","carbohydrates":"25 g","protein":"3 g"},"description":"Chocolate-chip cookies tend to spark the kind of tense debate usually reserved for topics like religion and politics. Opinions on various brands abound, but an excellent recipe is the key to baked good paradise. This recipe, one of three that were extensively tested, is for a golden brown emblem of cookie engineering. Note that in this crisp version the ingredients include milk and light corn syrup, and the balls of dough are quite small. This version also calls for what might seem like a lot of salt, but one tablespoon is correct. Be sure to use Diamond Crystal kosher salt, and if you use Morton's, reduce the amount by about half. (Make the chewy and gooey versions to compare.)","from_your_kitchen":null,"ingredients":["1 ¾ cups all-purpose flour","¾ teaspoon baking soda","1 tablespoon Diamond Crystal kosher salt","14 tablespoons butter, melted","½ cup packed light brown sugar","½ cup sugar","2 tablespoons light corn syrup","1 tablespoon vanilla extract","2 tablespoons milk","1 ½ cups chopped bittersweet chocolate (peasize pieces and shavings)","2 cups chopped toasted walnuts (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat the oven to 325 degrees. Line two baking sheets with foil. Sift together the flour, baking soda and salt."},{"n":2,"title":null,"text":"In a mixer fitted with a paddle, cream the butter, sugars and corn syrup for about 3 minutes. Stir in the vanilla, then the milk. Add the flour mixture all at once and blend just until a dough forms. Fold in the chocolate and walnuts. Chill the dough for at least an hour."},{"n":3,"title":null,"text":"Roll 2-tablespoon lumps of dough into balls, then place on the baking sheet and flatten to ¼ inch-thick disks spaced 2 inches apart. Chill the dough between batches. Bake until the edges are dark golden brown, 14 to 17 minutes. Let cool slightly on the baking sheet, then transfer to a baking rack."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips","walnuts"],"item_tags":["brown sugar","corn syrup","vanilla"],"course_tags":["Dessert"],"keywords":["All-Purpose Flour","Bake","Chocolate","Chocolate Chip Cookie","Dessert","Walnut"],"issues":null,"front":"nyt_11243.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/11243-thin-and-crisp-chocolate-chip-cookies","rating":{"value":4,"count":714},"date":"2006-01-22"},{"pair":1016637,"title":"Scrambled Tofu With Tomatoes, Scallions and Soy Sauce","subtitle":null,"author":"Mark Bittman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"15 minutes","nutrition":{"calories":"242","fat":"17 g","carbohydrates":"7 g","protein":"21 g"},"description":"Eggs are nicely mimicked when you scramble firm tofu with vegetables or grains. The point is not to fool anyone into thinking he is eating eggs, but to create a scramble that is easy and satisfying.","from_your_kitchen":null,"ingredients":["2 tablespoons neutral oil","1 ½ cups chopped tomatoes","Salt and ground black pepper","1 pound firm tofu, drained","⅓ cup sliced scallions","Soy sauce"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Put the oil in a deep skillet over medium heat. When hot, add the tomatoes, sprinkle with salt and pepper and cook, stirring occasionally, until their juices release and they begin to dry out slightly, 5 to 10 minutes."},{"n":2,"title":null,"text":"Crumble the tofu with your fingers and add it to the pan along with the scallions. Cook, stirring occasionally, until the tofu is heated through and dried out a bit, 5 to 10 minutes. Serve, drizzling with soy sauce at the table. Note: To make Scrambled Tofu With Corn, Tomatoes and Basil, use olive oil instead of neutral oil and reduce the amount of tomatoes to 1 cup. Substitute ¾-cup corn kernels for the scallions and stir in some chopped fresh basil before serving. Skip the soy sauce and drizzle with a little more olive oil at the table if you like."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["tofu","tomato"],"item_tags":["scallions","soy sauce"],"course_tags":["Breakfast"],"keywords":["Quick","Saute","Scallion","Soy Sauce","Tofu"],"issues":null,"front":"nyt_1016637.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016637-scrambled-tofu-with-tomatoes-scallions-and-soy-sauce","rating":{"value":4,"count":279},"date":"2014-07-09"},{"pair":1015170,"title":"Lasagna With Pistou and Mushrooms","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"Serves 6","yield_count":6,"cook_time":"1 hour 15 minutes","nutrition":{"calories":"370","fat":"20 g","carbohydrates":"32 g","protein":"16 g"},"description":"There will be a day when the weather suddenly cools and my basil plants and those at your farmers’ market stop thriving, but that day hasn’t come yet. So I’m making lots of pesto and pistou (pesto without the nuts), putting some of it in the freezer (I just blend the basil and olive oil together for the freezer and add the other ingredients when I thaw the mixture) and using the rest in all manner of pastas. This is the first time I’ve used it in a lasagna.","from_your_kitchen":null,"ingredients":["1 cup, tightly packed, basil leaves (1 ounce)","1 large garlic clove, peeled, halved green shoot removed if there is one","Salt to taste","3 tablespoons extra virgin olive oil","1 ounce Parmesan, grated (¼ cup, tightly packed)","1 egg","½ pound fresh ricotta","Salt and freshly ground pepper","2 tablespoons extra virgin olive oil","1 pound mushrooms, sliced","1 garlic clove, minced","2 tablespoons dry white wine (optional)","6 to 8 ounces no-boil lasagna noodles (depending on the size of your baking dish)","2 ounces freshly grated Parmesan (½ cup, tightly packed)"],"ingredient_groups":[{"at":0,"title":"FOR THE PISTOU"},{"at":5,"title":"FOR THE LASAGNA"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Grind the basil leaves and garlic in a food processor fitted with the steel blade, or in a mortar and pestle. Add salt to taste and slowly drizzle in the olive oil. Blend or grind until smooth. Blend in the Parmesan (¼ cup) and set aside."},{"n":2,"title":null,"text":"In a medium size bowl whisk the egg and add the ricotta and the pistou. Whisk to blend well."},{"n":3,"title":null,"text":"Heat 1 tablespoon of the olive oil over medium-high heat in a large, heavy skillet and add the mushrooms. Do not stir for about 1 minute, then shake the pan and cook, stirring occasionally, until the mushrooms are moist and beginning to soften. Add a generous pinch of salt and the garlic and cook, stirring, for another minute or two. Add the wine if using, or a couple of tablespoons of water or stock and cook, stirring, until the mushrooms are tender and fragrant, another couple of minutes. Season to taste with salt and pepper. Remove from the heat."},{"n":4,"title":null,"text":"Preheat the oven to 350 degrees. Lightly oil a rectangular baking dish with olive oil. Spread a small spoonful of the ricotta mixture in a thin layer over the bottom of the baking dish. Top with a layer of lasagna noodles. Top the noodles with a thin layer of ricotta, spooning on a few dollops then spreading it with an offset or a rubber spatula. Top the ricotta with half the mushrooms, and sprinkle Parmesan over the mushrooms. Repeat the layers, then add a final layer of lasagna noodles topped with ricotta and Parmesan. Make sure that the noodles are covered with ricotta and that there are no dry exposed edges. Drizzle a little bit of olive oil over the top."},{"n":5,"title":null,"text":"Cover the baking dish tightly with foil and place in the oven. Bake 35 to 40 minutes, until the noodles are tender and the mixture is bubbling. Remove from the heat and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this through Step 4 hours before baking the lasagna and refrigerate until shortly before baking. You can freeze the lasagna, before or after baking."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["mushrooms","pasta","ricotta"],"item_tags":["basil","parmesan","white wine"],"course_tags":["Dinner","Lunch"],"keywords":["Bake","Basil","Casseroles","Dinner","Fall","Great Leftovers","Healthy","Italian","Lasagna","Lunch","Main Course","Mushroom","Saute","Summer"],"issues":null,"front":"nyt_1015170.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015170-lasagna-with-pistou-and-mushrooms","rating":{"value":4,"count":174},"date":"2013-10-04"},{"pair":1017656,"title":"Citrus Rice Salad With Parmesan","subtitle":null,"author":"Mark Bittman","servings":"4 to 8","yield_text":"4 to 8 servings","yield_count":4,"cook_time":"30 to 60 minutes, depending on the type of rice","nutrition":null,"description":"In all of American cooking there is probably no term less meaningful than “salad.” I’m racking my brain for a way to narrow the definition, but the best I can do is a dictionary-like “mixture of food, usually cold or at room temperature, with some kind of dressing.” That’s not saying much, but it opens a world of opportunities, especially when the base ingredient is rice, which offers a far wider variety of flavors and textures than any other grain.","from_your_kitchen":null,"ingredients":["1 ½ to 2 cups any rice","Salt and freshly ground black pepper","½ cup extra-virgin olive oil","3 tablespoons freshly squeezed citrus juice, or more to taste (lemon, lime, orange, tangerine, grapefruit, or a combination)","2 tablespoons grated citrus zest","1 tablespoon sugar or honey","1 cup chopped citrus flesh (or whole segments, if small)","½ large red or mild white onion, minced","½ cup chopped fresh mint","½ cup or more grated Parmesan","Chopped almonds or pecans, optional"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Cook rice in abundant salted water, as you would pasta, until it’s just done; white rice will take 10 to 15 minutes, brown 30 or a little longer. Drain, rinse in cold water, drain again, then put in a large bowl."},{"n":2,"title":null,"text":"Combine olive oil, citrus juice, zest, sugar or honey, salt and pepper in a blender and turn the machine on; a creamy emulsion will form within 30 seconds. Taste and add more citrus juice a teaspoon or two at a time until the balance tastes right to you."},{"n":3,"title":null,"text":"Drizzle vinaigrette over rice. Use 2 big forks to combine, fluffing rice and tossing gently to separate grains. Stir in citrus flesh, onion and mint; taste, and adjust the seasoning or moisten with a little more dressing. Serve, sprinkled with Parmesan and chopped nuts, at room temperature, or refrigerate for up to a day, bringing salad back to room temperature before serving."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["citrus","rice"],"item_tags":["mint","parmesan"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Citrus","Dinner","Grains and Rice","Lunch","Main Course","Parmesan","Rice","Salad","Side Dish"],"issues":null,"front":"nyt_1017656.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017656-citrus-rice-salad-with-parmesan","rating":{"value":4,"count":300},"date":"2015-08-20"},{"pair":1017077,"title":"Lasagna With Roasted Brussels Sprouts and Carrots","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 20 minutes","nutrition":{"calories":"430","fat":"19 g","carbohydrates":"48 g","protein":"19 g"},"description":"A crowd-pleasing dish with endless varieties. If you are ever in doubt about what sort of casserole to make ahead for a crowd, make lasagna. There are so many versions that will please children and grown-ups, lacto-vegetarians and meat eaters. I like to tuck roasted vegetables into the layers of pasta, marinara sauce, Parmesan and ricotta. In this rendition I used brussels sprouts and carrots; the sprouts are slightly bitter and the carrots sweet. I sliced the brussels sprouts about the same width as the carrots and roasted the two together. Before you begin to assemble your lasagna it helps to be organized about the quantities of each element that you will need for the layers. It is very frustrating to get to the last layer of your casserole and not have enough sauce for the top.","from_your_kitchen":null,"ingredients":["¾ pound brussels sprouts, trimmed at base and sliced (not much thicker than ¼ inch; I get about 3 slices out of a small brussels sprout, 4 out of a larger one)","½ pound carrots, peeled and sliced on the diagonal","Salt and freshly ground pepper","3 tablespoons extra virgin olive oil, plus additional for oiling baking dish","8 ounces ricotta cheese","1 egg","1 tablespoon water","Very small pinch of cinnamon","Salt and freshly ground pepper","2 ⅓ to 2 ½ cups marinara sauce (more to taste)","7 to 8 ounces no-boil lasagna (depends on the size and shape of your dish)","4 ounces (1 cup) freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 425 degrees. Line a sheet pan with parchment. Place brussels sprouts and carrots on the parchment and season with salt and pepper. Toss with 2 tablespoons olive oil until evenly coated. Place in oven and roast 15 to 20 minutes, stirring every 5 to 10 minutes, until tender and lightly colored. Remove from oven and turn heat down to 350 degrees."},{"n":2,"title":null,"text":"Lightly oil a rectangular baking dish."},{"n":3,"title":null,"text":"Blend ricotta cheese with egg, water, cinnamon, and salt and pepper to taste."},{"n":4,"title":null,"text":"Spread a small spoonful of tomato sauce in a thin layer over the bottom of the baking dish. Top with a layer of lasagna noodles. Top the noodles with a thin layer of ricotta. Spoon on a few dollops then spread with an offset or a rubber spatula. Top ricotta with half the brussels sprouts and carrots, and top vegetables with a layer of tomato sauce and a layer of Parmesan. Repeat layers, then add a final layer of lasagna noodles topped with tomato sauce and Parmesan. Drizzle remaining tablespoon of oil over the top."},{"n":5,"title":null,"text":"Cover baking dish tightly with foil and place in the oven. Bake 40 minutes, until the noodles are tender and the mixture is bubbling. Remove from the heat and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to a day ahead and refrigerate, or freeze for a month. The lasagna can be baked several hours ahead and reheated in a medium oven."],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["brussels sprouts","carrot","pasta"],"item_tags":["parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["Brussels Sprout","Christmas","Dinner","Great Leftovers","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Mediterranean","New Year’s Day","Parmesan","Ricotta","Super Bowl","Vegetarian","Winter"],"issues":null,"front":"nyt_1017077.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017077-lasagna-with-roasted-brussels-sprouts-and-carrots","rating":{"value":4,"count":394},"date":"2014-12-22"},{"pair":1016563,"title":"Chickpeas With Mint, Scallions and Cilantro","subtitle":null,"author":"David Tanis","servings":null,"yield_text":"About 6 cups cooked chickpeas","yield_count":6,"cook_time":"About 1 hour, plus overnight soaking","nutrition":{"calories":"330","fat":"9 g","carbohydrates":"49 g","protein":"16 g"},"description":"Chickpeas (garbanzos) always taste better cooked from scratch, but unlike other beans, you do have to soak them overnight. Then it’s a simple matter of simmering for about 45 minutes. Cooked chickpeas will keep up to 5 days stored in their cooking liquid in the refrigerator. The combination of warm beans and cool herbs makes a great side dish.","from_your_kitchen":null,"ingredients":["1 pound chickpeas, soaked overnight in cold water","1 onion, halved, with each half stuck with 2 cloves","2 bay leaves","1 2-inch piece cinnamon stick","Salt","2 tablespoons olive oil","½ teaspoon turmeric, or a small pinch of crumbled saffron","2 tablespoons chopped mint","¼ cup chopped scallions","¼ cup chopped cilantro leaves and tender stems"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Pour soaked chickpeas into a colander to drain and put in a medium-size soup pot. Add water to cover by 1 inch and bring to a boil. Add onion, bay leaves, cinnamon and 2 teaspoons salt. Skim off and discard any rising foam. Lower heat and simmer gently for about 45 minutes, until tender. (May prepare in advance and reheat)."},{"n":2,"title":null,"text":"Drain hot chickpeas (reserve broth for another purpose, such as soup) and discard onion and aromatics. Return chickpeas to pot and add olive oil and turmeric or saffron, stirring to distribute. Taste for salt and adjust."},{"n":3,"title":null,"text":"Transfer to a warm serving bowl. Mix mint, scallions and cilantro together and sprinkle over top. Serve warm."}],"tips":[],"cuisine_tags":["Middle Eastern","Moroccan"],"ingredient_tags":["chickpeas"],"item_tags":["cilantro","cinnamon","mint","scallions","turmeric"],"course_tags":["Sides & Appetizers"],"keywords":["Beans","Boil","Chickpea","Easy","Mint","Moroccan","Scallion","Side Dish","Vegetarian"],"issues":null,"front":"nyt_1016563.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016563-chickpeas-with-mint-scallions-and-cilantro","rating":{"value":4,"count":364},"date":"2014-06-11"},{"pair":1018055,"title":"Salted Tahini Chocolate Chip Cookies","subtitle":null,"author":"Julia Moskin","servings":null,"yield_text":"12 to 18 cookies","yield_count":12,"cook_time":"45 minutes, plus 12 hours' refrigeration","nutrition":{"calories":"306","fat":"15 g","carbohydrates":"40 g","protein":"5 g"},"description":"When the chef Danielle Oron was growing up in the New Jersey suburbs, she knew that her Israeli family’s habits of dousing vanilla ice cream with tahini and spreading halvah on toast would be considered odd. Sesame has long been shunned in American desserts, but its addition to a confection can add a nutty, salty undertone, and sesame desserts are now popping up all over the place. These chocolate chip cookies, developed by Ms. Oron, are a great place to start for the home baker seeking more sesame. Rich, savory and sweet, they are one of the rare variations that are just as good as the original. Julia Moskin","from_your_kitchen":null,"ingredients":["8 tablespoons/113 grams unsalted butter at room temperature","½ cup/120 milliliters tahini, well stirred","1 cup/200 grams granulated sugar","1 large egg","1 egg yolk","1 teaspoon vanilla extract","1 cup plus 2 tablespoons/150 grams all-purpose flour, or matzo cake meal (See tip)","½ teaspoon baking soda","½ teaspoon baking powder","1 teaspoon kosher salt","1 ¾ cups/230 grams chocolate chips or chunks, bittersweet or semisweet","Flaky salt, like fleur de sel or Maldon"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"In the bowl of an electric mixer fitted with the paddle attachment, cream butter, tahini and sugar at medium speed until light and fluffy, about 5 minutes. Add egg, egg yolk and vanilla and continue mixing at medium speed for another 5 minutes."},{"n":2,"title":null,"text":"Sift flour, baking soda, baking powder and kosher salt into a large bowl and mix with a fork. Add flour mixture to butter mixture at low speed until just combined. Use a rubber spatula to fold in chocolate chips. Dough will be soft, not stiff. Refrigerate at least 12 hours; this ensures tender cookies."},{"n":3,"title":null,"text":"When ready to bake, heat oven to 325 degrees and line a baking sheet with parchment paper or nonstick baking mat. Use a large ice cream scoop or spoon to form dough into 12 to 18 balls."},{"n":4,"title":null,"text":"Place the cookies on the baking sheet at least 3 inches apart to allow them to spread. Bake 13 to 16 minutes until just golden brown around the edges but still pale in the middle to make thick, soft cookies. As cookies come out of the oven, sprinkle sparsely with salt. Let cool at least 20 minutes on a rack."}],"tips":["To make this recipe kosher for Passover, substitute matzo cake meal for the all-purpose flour."],"cuisine_tags":["American","Middle Eastern"],"ingredient_tags":["chocolate chips"],"item_tags":["tahini","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Chocolate Chip","Chocolate Chip Cookie","Dessert","Israeli","Plan-Ahead","Snack","Tahini"],"issues":null,"front":"nyt_1018055.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1018055-salted-tahini-chocolate-chip-cookies","rating":{"value":5,"count":6792},"date":"2016-04-13"},{"pair":1020754,"title":"Spicy White Bean Stew With Broccoli Rabe","subtitle":null,"author":"Alison Roman","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"40 minutes","nutrition":null,"description":"Not quite a fridge clean-out situation, this extremely flexible stew can use up much of what you’ve got on hand. It’s vegetarian by nature, but feel free to start the pot with sausage, slab bacon or leftover ham if you’re feeling more omnivorous. If you can’t find harissa, use tomato paste and a pinch of red-pepper flakes for spiciness.","from_your_kitchen":null,"ingredients":["1 large bunch (or 2 small bunches) broccoli rabe or kale, thick stems separated from the leaves","¼ cup olive oil, plus more for drizzling","4 garlic cloves, thinly sliced","1 medium red or yellow onion, thinly sliced","Kosher salt and black pepper","2 to 3 tablespoons harissa or tomato paste","Red-pepper flakes (optional)","3 (15-ounce) cans large white beans, such as cannellini, butter or great Northern, drained and rinsed","4 cups vegetable or chicken broth","1 preserved lemon, thinly sliced, or 1 lemon, halved, for squeezing","2 ounces feta or other salty cheese, such as queso fresco or pecorino, crumbled","1 cup parsley or cilantro, leaves and tender stems","Fried or medium-boiled eggs, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Tear broccoli rabe or kale leaves into bite-size pieces and set aside. Chop the stems into about ¼-inch pieces; set aside."},{"n":2,"title":null,"text":"Heat ¼ cup olive oil in a large pot over medium heat. Add garlic and onion, and season with salt and pepper. Cook, stirring occasionally, until lightly browned and sizzled at the edges, 4 to 6 minutes."},{"n":3,"title":null,"text":"Add harissa (or tomato paste and a pinch of red-pepper flakes), and stir to coat in the oil. Cook until the harissa is a nice brick red color, the sugars start to caramelize and the oil turns a nice vibrant fiery orange color, about 2 minutes."},{"n":4,"title":null,"text":"Add beans, and season with salt and pepper. Using a wooden spoon or spatula, crush a few beans to release their creamy interior."},{"n":5,"title":null,"text":"Add the broth and reserved stems, and season with salt and pepper. Bring to a simmer and cook until you’ve reached your desired consistency (less time for a brothier soup, more time for a thicker stew), 15 to 20 minutes."},{"n":6,"title":null,"text":"Add broccoli rabe or kale leaves and preserved lemon or lemon juice, and stir to wilt the greens. Season with salt, pepper and more red-pepper flakes if you want it spicier."},{"n":7,"title":null,"text":"Serve with feta and parsley, and with eggs, if you like."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["broccoli rabe","white beans"],"item_tags":["feta","harissa","preserved lemon","red chile flakes"],"course_tags":["Dinner"],"keywords":["Broccoli Rabe","Easy","Fall","Feta","Great Leftovers","Harissa","Kale","Main Course","Preserved Lemon","Quick","Stew","Vegetarian","Weeknight","White Bean","Winter"],"issues":null,"front":"nyt_1020754.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020754-spicy-white-bean-stew-with-broccoli-rabe","rating":{"value":5,"count":10102},"date":"2020-01-01"},{"pair":1014826,"title":"Quintessential Chocolate Chip Cookies","subtitle":null,"author":"Martha Rose Shulman","servings":null,"yield_text":"About 4 dozen cookies","yield_count":48,"cook_time":"40 minutes","nutrition":{"calories":"70","fat":"4 g","carbohydrates":"10 g","protein":"1 g"},"description":"Sherry Yard's iconic chocolate-chip cookies are just the right mix of chewy and crisp, with a bittersweet morsel of chocolate in each bite. They are the cookies anyone who asks you to make chocolate chip cookies are asking for -- the kind of chocolate cookie that demands to be dunked into a glass of ice-cold milk. Martha Rose Shulman","from_your_kitchen":null,"ingredients":["185 grams all-purpose flour (1 ½ cups)","2 grams baking soda (½ teaspoon)","115 grams butter (4 ounces/1 stick)","100 grams sugar (½ cup)","80 grams light brown sugar (½ cup packed)","2 grams salt (¼ teaspoon)","1 egg","5 grams vanilla (1 teaspoon)","225 grams bittersweet chocolate (8 ounces), cut in 1-inch pieces (or use coins)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Sift together flour and baking soda and set aside. In the bowl of a standing electric mixer fitted with the paddle attachment, cream butter until lemony yellow, about 2 minutes. Scrape down sides of bowl and paddle. Add sugar, brown sugar and salt. Continue creaming mixture on medium speed until it is smooth and lump free, about 1 minute. Stop mixer and scrape down sides of bowl and paddle."},{"n":2,"title":null,"text":"Add egg and vanilla and beat on low speed for 15 seconds, or until they are fully incorporated. Do not over-beat. Scrape down sides of bowl and paddle."},{"n":3,"title":null,"text":"On low speed, add sifted flour mixture. Beat slowly until all of the flour is incorporated. Scrape down sides of bowl. Add chocolate chunks and mix in."},{"n":4,"title":null,"text":"Heat oven to 350 degrees with the rack positioned in the lower third of the oven. Line 2 baking sheets with parchment. Spoon heaping teaspoons of dough 2 inches apart onto baking sheets. If not baking right away, remove small handfuls or spoonfuls of dough from mixer and plop them down on the middle of a sheet of parchment or wax paper, creating a log about 1 ½ inches wide and 12 inches long. Fold parchment over, creating a sausage. Chill for at least 1 hour, preferably overnight. Using a serrated knife, slice chilled dough into ⅓-inch-thick rounds and place them 2 inches apart, in staggered rows, on parchment-lined sheets and proceed. (Dough will keep nicely, tightly wrapped, in the refrigerator for 1 week, or in the freezer for up to 1 month. Thaw frozen dough at room temperature for 30 minutes before slicing.)"},{"n":5,"title":null,"text":"Bake one sheet at a time for 12 to 15 minutes, until lightly browned, rotating the baking sheet front to back halfway through. Remove from heat and slide parchment off baking sheet and onto a work surface. Allow cookies to cool for at least 5 minutes before serving, or for at least 20 minutes before storing in an airtight container. They will keep for up to 3 days at room temperature."}],"tips":["For even more chocolaty cookies, add another 1 to 2 ounces (30 to 60 grams) of chocolate. If you want flat, crispy cookies, when you go to turn the baking sheets halfway through the baking, tap them down on the back of the oven door before sliding them back in. This will cause the rising cookies to fall."],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["All-Purpose Flour","Bake","Bittersweet Chocolate","Chocolate Chip Cookie","Dessert","Sugar"],"issues":null,"front":"nyt_1014826.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014826-quintessential-chocolate-chip-cookies","rating":{"value":5,"count":6583},"date":"2013-06-19"},{"pair":1016222,"title":"Rainbow Quinoa Salad","subtitle":null,"author":"Martha Rose Shulman","servings":"6 to 8","yield_text":"Serves 6 to 8","yield_count":6,"cook_time":"35 minutes","nutrition":{"calories":"269","fat":"17 g","carbohydrates":"26 g","protein":"6 g"},"description":"Dr. David Eisenberg of the Harvard School of Public Health demonstrated along with his daughter, Naomi, a whole- wheat couscous salad that is the inspiration for this one at the “Healthy Kitchens, Healthy Lives” medical education conference in Napa Valley this year. You can use a variety of dried fruits and nuts, as well as a mix of herbs. Chop the larger dried fruits small so that the pieces are uniform.","from_your_kitchen":null,"ingredients":["4 cups water","⅔ cup chopped dried fruit (such as apricots, raisins, cranberries, figs, currants)","¼ cup chopped cilantro","¼ cup chopped fresh mint","½ cup chopped fresh parsley","Salt to taste","1 cup red quinoa or rainbow quinoa, rinsed","¼ cup lightly toasted pistachios","¼ cup lightly toasted almonds, chopped","¼ cup chopped walnuts","2 teaspoons lemon zest","¼ cup fresh lemon juice","Salt to taste","1 small garlic clove, puréeed (optional)","¼ teaspoon ground cinnamon","1 teaspoon pomegranate molasses","⅓ cup extra- virgin olive oil"],"ingredient_groups":[{"at":0,"title":"FOR THE SALAD"},{"at":11,"title":"FOR THE DRESSING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Bring water to a boil in a 3-quart saucepan and add quinoa and salt to taste. Bring back to a rolling boil, then reduce heat slightly and boil gently for 20 minutes, or until you see a thread emerge from the blond and red quinoa. Drain and shake well in the strainer, then return to pot. Cover pot with a dishtowel and then , then place a lid over the dishtowel and let sit for 10 to 15 minutes undisturbed. Transfer to a large bowl."},{"n":2,"title":null,"text":"Meanwhile, whisk together lemon juice, salt, garlic, cinnamon, and pomegranate molasses. Whisk in olive oil."},{"n":3,"title":null,"text":"Toss together quinoa and dressing. Add remaining ingredients and toss together. Transfer to a platter, a wide bowl or individual plates and serve."}],"tips":[],"cuisine_tags":["Mediterranean","Middle Eastern"],"ingredient_tags":["quinoa"],"item_tags":["cilantro","lemon","mint","parsley","pistachios"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Appetizer","Boil","Dairy-Free","Dinner","Fall","Gluten-Free","Low-Sodium","Lunch","Main Course","Mediterranean","Salad","Spring","Summer","Vegan","Vegetarian","Winter"],"issues":null,"front":"nyt_1016222.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016222-rainbow-quinoa-salad","rating":{"value":5,"count":2188},"date":"2014-04-04"},{"pair":12463,"title":"Lasagna With Collard Greens","subtitle":null,"author":"Martha Rose Shulman","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 20 minutes","nutrition":{"calories":"321","fat":"12 g","carbohydrates":"36 g","protein":"16 g"},"description":"Collard greens are so big and flat that they fill in for a layer of noodles in this easy, satisfying lasagna. When you make lasagna, be careful not to use up your ingredients on the first layers. You should have enough for three layers here.","from_your_kitchen":null,"ingredients":["½ pound collard greens, preferably large leaves, stemmed and washed, leaves left intact","Salt to taste","Extra virgin olive oil for the pan","2 cups marinara sauce, preferably homemade from fresh or canned tomatoes","½ pound no-boil lasagna noodles","½ pound ricotta","4 ounces freshly grated Parmesan"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Steam the collard greens for 5 minutes above an inch of boiling water, or blanch in boiling salted water for 2 minutes. Transfer to a bowl of cold water, drain and pat dry with paper towels."},{"n":2,"title":null,"text":"Preheat the oven to 350 degrees. Oil a 2- or 3-quart rectangular baking dish with olive oil. Spread a small amount of tomato sauce over the bottom and top with a layer of lasagna noodles. Top the noodles with a thin layer of ricotta. Lay collard green leaves over the ricotta in a single layer. Top the leaves with a layer of tomato sauce, followed by a thin layer of Parmesan."},{"n":3,"title":null,"text":"Set aside enough tomato sauce and Parmesan to top the lasagna and repeat the layers until all of the ingredients are used up. Spread the tomato sauce you set aside over the top, and sprinkle on the Parmesan. Make sure the noodles are covered, and cover the baking dish tightly with foil."},{"n":4,"title":null,"text":"Place in the oven and bake 30 minutes. Remove from the oven and uncover. Check to be sure that the noodles are soft and the mixture is bubbly. Return to the oven for another 5 to 10 minutes if desired, to brown the top. Allow to sit for 10 minutes before serving."}],"tips":["Advance preparation: You can assemble this up to two days ahead and refrigerate until ready to bake."],"cuisine_tags":["Comfort Food","Italian","Southern"],"ingredient_tags":["collard greens","pasta"],"item_tags":["parmesan","ricotta"],"course_tags":["Dinner"],"keywords":["Bake","Casseroles","Collard Greens","Dinner","Five Ingredient","Great Leftovers","Healthy","High Fiber","Italian","Lasagna","Main Course","Marinara Sauce","Steam","Vegetarian"],"issues":null,"front":"nyt_12463.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/12463-lasagna-with-collard-greens","rating":{"value":5,"count":429},"date":"2012-05-23"},{"pair":1017765,"title":"Shredded Tofu and Shiitake Stir-Fry","subtitle":null,"author":"Melissa Clark","servings":"3 to 4","yield_text":"3 to 4 servings","yield_count":3,"cook_time":"20 minutes","nutrition":{"calories":"307","fat":"20 g","carbohydrates":"15 g","protein":"23 g"},"description":"Shredding tofu on a box grater before stir-frying gives it a fluffy, light texture, and the smaller pieces readily absorb the complex, earthy mushroom flavor of the sauce. Unlike with many tofu dishes, you’re not looking to sear the tofu here, just to warm it up in the sauce. The caramelized flavor is supplied by the shiitake mushrooms, which should be cooked until they are well browned and crisp-edged. If you can’t find fresh lemongrass, you can leave it out.","from_your_kitchen":null,"ingredients":["1 (15-ounce) package firm tofu, drained","2 tablespoons soy sauce","1 tablespoon Chinese Shaoxing or dry sherry","Juice of ½ lime, plus lime wedges for serving","2 teaspoons toasted sesame oil","2 tablespoons peanut or grapeseed oil","7 ounces shiitake mushrooms, stems removed and caps thinly sliced (4 cups)","¼ cup sliced scallion","1 stalk lemongrass, trimmed, outer leaves removed, inner core finely chopped (optional)","1 (1-inch) knob of ginger root, grated","1 large garlic clove, grated","1 small red chile, seeded and finely chopped","Salt, as needed","½ cup shelled edamame (defrosted if using frozen)","¼ cup chopped soft herbs, such as cilantro, chives or basil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Using the coarse holes of a box grater, shred the tofu. Spread tofu out on a clean kitchen towel to drain while you prepare the sauce and mushrooms."},{"n":2,"title":null,"text":"In a small bowl, whisk together soy sauce, Shaoxing, lime juice and sesame oil."},{"n":3,"title":null,"text":"Heat a large skillet over medium-high heat until it’s very hot, then add the peanut oil; it should thin out on contact. Once the oil is hot, add the mushrooms and cook, tossing occasionally, until most of the mushroom liquid has evaporated and mushrooms are browned and slightly crisp, 8 to 12 minutes. Stir in the scallion, lemongrass, ginger, garlic, chile and a pinch of salt. Cook until softened, about 2 minutes."},{"n":4,"title":null,"text":"Carefully transfer the tofu from the towel into the skillet. Toss in the edamame and the soy sauce mixture. Cook until mixture is heated through. Season with salt as needed. Remove from heat and stir in herbs. Serve with lime wedges."}],"tips":[],"cuisine_tags":["Chinese","Fusion"],"ingredient_tags":["edamame","mushrooms","tofu"],"item_tags":["ginger","lemongrass","scallions","sesame oil"],"course_tags":["Dinner"],"keywords":["Edamame","Firm Tofu","Healthy","Lemongrass","Main Course","Quick","Shaoxing","Shiitake","Stir-Fry","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1017765.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017765-shredded-tofu-and-shiitake-stir-fry","rating":{"value":4,"count":2367},"date":"2015-10-28"},{"pair":1020515,"title":"Southern Macaroni and Cheese","subtitle":null,"author":"Kiera Wright-Ruiz","servings":"8 to 10","yield_text":"8 to 10 servings","yield_count":8,"cook_time":"45 minutes, plus cooling","nutrition":{"calories":"567","fat":"35 g","carbohydrates":"39 g","protein":"25 g"},"description":"There is macaroni and cheese, and then there is special occasion macaroni and cheese like this one. Discover more ideas for the big day at NYT Cooking.","from_your_kitchen":null,"ingredients":["Kosher salt and black pepper","1 pound elbow macaroni","2 cups whole milk","2 large eggs","4 cups shredded extra-sharp Cheddar (about 16 ounces)","½ cup unsalted butter (1 stick), melted","2 cups shredded Colby Jack (about 8 ounces)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 350 degrees. Bring a large pot of generously salted water to a boil. Add macaroni and cook according to package directions until a little under al dente, about 4 minutes. Transfer to a colander and rinse under cold water to stop cooking. Set aside."},{"n":2,"title":null,"text":"In a large bowl, whisk milk and eggs. Add cooked macaroni, 2 cups extra-sharp Cheddar, melted butter, 1 ½ teaspoons salt and ½ teaspoon pepper, and stir until well combined."},{"n":3,"title":null,"text":"Add half the macaroni mixture to a 9-by-13-inch baking dish in an even layer. Sprinkle 1 ½ cups Colby Jack evenly on top. Spread the remaining macaroni mixture on top in an even layer. Cover with aluminum foil, transfer to the middle rack of the oven and bake for 30 minutes."},{"n":4,"title":null,"text":"Remove from oven. Carefully remove and discard the aluminum foil. Top the macaroni mixture with the remaining 2 cups Cheddar and ½ cup Colby Jack. Broil on top rack until cheese is browned in spots, 3 to 5 minutes. (The broiled cheese can go from golden to burnt fairly quickly, so keep a close eye on it.)"},{"n":5,"title":null,"text":"Remove from oven and let cool until the macaroni and cheese is fully set, 10 to 15 minutes. (The mixture may first appear jiggly, but it will firm up as it cools.) Serve warm."}],"tips":[],"cuisine_tags":["Comfort Food","Southern"],"ingredient_tags":["cheddar","pasta"],"item_tags":["colby jack","eggs"],"course_tags":["Dinner","Sides & Appetizers"],"keywords":["Budget","Casseroles","Christmas","Colby Jack","Dinner","Great Leftovers","Kwanzaa","Macaroni","Macaroni and Cheese","Main Course","Sharp Cheddar","Side Dish","Soul Food","Southern","Thanksgiving","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1020515.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020515-southern-macaroni-and-cheese","rating":{"value":4,"count":12416},"date":"2020-05-27"},{"pair":1021277,"title":"Sheet-Pan Baked Feta With Broccolini, Tomatoes and Lemon","subtitle":null,"author":"Yasmin Fahr","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"25 minutes","nutrition":{"calories":"548","fat":"33 g","carbohydrates":"43 g","protein":"24 g"},"description":"When baked, feta gains an almost creamy texture, similar to goat cheese but with feta’s characteristic tang. In this easy vegetarian sheet-pan dinner, broccolini (or broccoli), grape tomatoes and lemon slices roast alongside the feta until the broccolini crisp, the tomatoes burst and the lemon rinds soften. (Remember, broccolini has a tender, delicious stalk so only the bottom ½-inch needs to be trimmed.) Serve this dish over a pile of orzo for a complete meal. If you like, cut the broccolini, feta and lemon into bite-size pieces and toss with the orzo.","from_your_kitchen":null,"ingredients":["1 bunch broccolini, ends trimmed, thick stalks split lengthwise, or broccoli, stalks trimmed and cut into bite-size pieces","1 pint grape tomatoes, halved (about 2 cups)","1 small red onion, peeled, quartered and cut into 2-inch wedges","1 lemon, ½ cut into thin rounds and the remaining ½ left intact, for serving","3 tablespoons olive oil, plus more for serving","1 teaspoon ground cumin","½ teaspoon red-pepper flakes","Kosher salt and black pepper","2 (6- to 8-ounce) blocks feta, cut into 1-inch slices","Cooked orzo or farro, for serving","½ cup fresh basil or cilantro leaves and fine stems, roughly chopped (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 400 degrees with a rack set in the lower third. On a sheet pan, combine the broccolini, tomatoes, onion and lemon slices with the olive oil and toss. Add cumin and red-pepper flakes, season with salt and pepper, and toss again until evenly coated. Nestle the feta slices into the vegetables. (It’s OK if they break apart a little.)"},{"n":2,"title":null,"text":"Roast 15 to 20 minutes, stirring halfway through but leaving the feta in place, until the broccolini is charred at the tips, the stems are easily pierced with a fork and the tomato skins start to blister and break down."},{"n":3,"title":null,"text":"Serve over orzo or farro. Drizzle with olive oil and serve with the remaining lemon half for squeezing. Top with fresh herbs, if using."}],"tips":[],"cuisine_tags":["Greek","Mediterranean"],"ingredient_tags":["broccolini","feta","tomato"],"item_tags":["cumin","lemon","red chile flakes"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Broccoli","Broccolini","Cumin","Dinner","Easy","Fall","Feta","Grape Tomato","Lemon","Lunch","Main Course","Orzo","Quick","Red Onion","Roast","Sheet-Pan","Side Dish","Tomato","Vegetables","Vegetarian","Weeknight"],"issues":null,"front":"nyt_1021277.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1021277-sheet-pan-baked-feta-with-broccolini-tomatoes-and-lemon","rating":{"value":5,"count":21397},"date":"2020-07-24"},{"pair":9465,"title":"The $250 Cookie Recipe","subtitle":null,"author":"Barbara Whitaker","servings":null,"yield_text":"About 55 cookies","yield_count":55,"cook_time":"45 minutes","nutrition":{"calories":"156","fat":"8 g","carbohydrates":"20 g","protein":"2 g"},"description":"Almost everybody has heard the one about the woman lunching at the Neiman Marcus Cafe in Dallas, who enjoyed the chocolate chip cookies so much that she asked for the recipe. For \"only two-fifty,\" the waitress said, it was hers. But when the credit card bill arrived, the woman found the total near $300. Turns out the recipe cost $250, the story goes. In 1997, after years of enduring the myth, Neiman Marcus came up with a recipe – and gave it out for free. It's a delicious variation on chocolate chip cookies, using ground oatmeal, nuts and adding extra chocolate with a grated Hershey bar (you can use any brand you love).","from_your_kitchen":null,"ingredients":["1 cup butter","1 cup dark brown sugar, packed","1 cup granulated sugar","2 eggs","1 teaspoon vanilla","2 ½ cups oatmeal","2 cups flour","½ teaspoon salt","1 teaspoon baking soda","1 teaspoon baking powder","12 ounces chocolate chips","1 4-ounce milk chocolate bar","1 ½ cups chopped nuts"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 375 degrees."},{"n":2,"title":null,"text":"Cream together butter and both sugars. Stir in eggs and vanilla."},{"n":3,"title":null,"text":"Finely grind oatmeal in a blender or food processor. Combine the oatmeal, flour, salt, baking powder and soda in a medium bowl, and slowly add it to the wet ingredients. Beat just until combined. Grate chocolate bar using a microplane grater and add it, along with chocolate chips and nuts to the batter. Mix just to combine."},{"n":4,"title":null,"text":"Drop by heaping tablespoonfuls, 2 inches apart, on a greased cookie sheet. Bake for 10 minutes."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips","oats"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Chocolate Chip","Chocolate Chip Cookie","Dessert","Nut","Oat"],"issues":null,"front":"nyt_9465.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/9465-the-250-cookie-recipe","rating":{"value":4,"count":8105},"date":"1997-07-02"},{"pair":1014983,"title":"Greens and Garlic Frittata to Go","subtitle":null,"author":"Martha Rose Shulman","servings":"2","yield_text":"Serves 2","yield_count":2,"cook_time":"About 30 minutes","nutrition":{"calories":"191","fat":"14 g","carbohydrates":"2 g","protein":"13 g"},"description":"Chop the greens super-fine to achieve the prettiest color. Use whatever looks best in the market (spinach and chard are brightest when it comes to color), or you can use bagged baby spinach. You only need ½ cup of chopped greens, but you could use twice that amount.","from_your_kitchen":null,"ingredients":["4 eggs","1 tablespoon milk","Salt and freshly ground pepper to taste","½ to ¾ cup finely chopped blanched spinach, chard, kale or beet greens (to taste)","1 garlic clove, minced or pureed","1 tablespoon, tightly packed, freshly grated Parmesan","2 teaspoons extra virgin olive oil"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Beat the eggs and milk in a bowl with salt and pepper to taste. Beat in the greens, garlic and the Parmesan."},{"n":2,"title":null,"text":"Heat the olive oil over medium-high heat in a heavy, 8-inch nonstick omelet pan. Drop a bit of egg into the pan and if it sizzles and cooks at once, the pan is ready. Pour in the egg mixture, scraping in every last bit with a heat-proof rubber spatula. Swirl the pan to distribute the eggs and filling evenly over the surface. Shake the pan gently, tilting it slightly with one hand while lifting up the edges of the frittata with the spatula in your other hand, to let the eggs run underneath during the first few minutes of cooking. Once a few layers of egg have cooked during the first couple of minutes of cooking, turn the heat down to low, cover and cook 7 to 10 minutes, until the frittata is puffed and just about set. From time to time remove the lid and loosen the bottom of the omelet with a wooden or heat-proof rubber spatula, tilting the pan, so that the bottom doesn’t burn. It will however turn golden."},{"n":3,"title":null,"text":"If the frittata is still runny on the top, wearing oven mitts, slide the frittata out onto a plate or even better, a saucepan lid that has a handle, reverse the pan over the plate or lid, and holding the two together, flip the plate or lid so that the frittata goes back into the pan on its not-quite-cooked side. Finish for no longer than a minute, then reverse onto a platter. Allow to cool to room temperature, and serve, or chill. Cut into 4 wedges to serve. The wedges pack well and are very portable."}],"tips":["Advance preparation: The blanched greens will keep for 3 or 4 days in the refrigerator and can be frozen. The frittata will keep for about 3 days in the refrigerator."],"cuisine_tags":["Italian"],"ingredient_tags":["eggs","spinach"],"item_tags":["garlic","parmesan"],"course_tags":["Breakfast"],"keywords":["Breakfast","Easy","Egg","Garlic","Gluten-Free","Greens","Healthy","Low Sugar","Low-Carb","Quick","Saute","Summer","Vegetarian"],"issues":null,"front":"nyt_1014983.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1014983-greens-and-garlic-frittata-to-go","rating":{"value":4,"count":692},"date":"2013-08-22"},{"pair":1015968,"title":"Roasted Cauliflower Gratin With Tomatoes and Goat Cheese","subtitle":null,"author":"Martha Rose Shulman","servings":"4 to 6","yield_text":"Serves 4 to 6","yield_count":4,"cook_time":"About 1 hour 10 minutes, plus 10 minutes cooling time","nutrition":{"calories":"179","fat":"13 g","carbohydrates":"11 g","protein":"8 g"},"description":"Roasting is one of my favorite ways to prepare cauliflower, and I have always loved preparations that pair the vegetable with coriander seeds. I use coriander seeds and cinnamon to season the tomato sauce that I toss with the roasted cauliflower and sautéed red onions, then add a couple of eggs beaten with goat cheese.","from_your_kitchen":null,"ingredients":["1 medium-size head of cauliflower","Salt and freshly ground pepper to taste","3 tablespoons extra virgin olive oil","1 small or ½ large red onion, cut in half or quarters (if using a whole onion) lengthwise, then sliced thin across the grain","2 garlic cloves, minced","1 teaspoon fresh thyme leaves","1 (14 8/10-ounce) can chopped tomatoes in juice","⅛ teaspoon cinnamon","½ teaspoon coriander seeds, lightly toasted and coarsely ground","2 eggs","2 ½ ounces soft goat cheese (about ½ cup plus 2 tablespoons)","2 to 3 teaspoon chopped chives"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Preheat oven to 450 degrees. Line a baking sheet with parchment or foil. Cut away the bottom of the cauliflower stem and trim off leaves. Cut cauliflower into ⅓ inch thick slices, letting the florets on the edges fall off. Toss all of it, including the bits that have fallen away, with 2 tablespoons of the olive oil, salt, and pepper. Place on baking sheet in an even layer."},{"n":2,"title":null,"text":"Roast for 15 to 20 minutes, stirring and flipping over the big slices after 8 minutes, until the slices are tender when pierced with a paring knife and the small florets are nicely browned. Remove from oven and cut large slices into smaller pieces. You should have about 2 cups. Transfer to a large bowl. Turn oven down to 375 degrees."},{"n":3,"title":null,"text":"Oil a 1-½ to 2-quart baking dish or gratin. Heat remaining oil over medium heat in a medium-size skillet or a wide saucepan and add onion. Cook, stirring, until tender, about 5 minutes. Add a generous pinch of salt and the garlic and thyme and continue to cook, stirring, until garlic is fragrant, 30 seconds to a minute. Add tomatoes, cinnamon, ground coriander seeds, and salt and pepper to taste and bring to a simmer. Cook, stirring often, over medium-low heat, for 10 to 15 minutes, until the tomatoes have cooked down and the sauce is fragrant. Taste and adjust seasoning. Add to bowl with the cauliflower and stir everything together. Scrape into prepared baking dish."},{"n":4,"title":null,"text":"Set aside 2 tablespoons of the goat cheese. Beat eggs, then add the remaining cheese and beat together until smooth. Pour over cauliflower mixture, making sure to scrape out every last bit with a rubber spatula. Dot top with small pieces of the remaining goat cheese and sprinkle on chives."},{"n":5,"title":null,"text":"Bake 30 minutes, until top is beginning to brown in spots. Remove from oven and allow to sit for 5 to 10 minutes before serving."}],"tips":["Advance preparation: Both the roasted cauliflower and the tomato sauce will keep for a couple of days in the refrigerator. The finished gratin will also keep for a couple of days. Reheat in a medium oven."],"cuisine_tags":["Mediterranean"],"ingredient_tags":["cauliflower","tomato"],"item_tags":["cinnamon","coriander","goat cheese"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Bake","Dinner","Fall","Gluten-Free","Healthy","Lunch","Main Course","Mediterranean","Roast","Side Dish","Thanksgiving","Vegetarian","Winter"],"issues":null,"front":"nyt_1015968.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015968-roasted-cauliflower-gratin-with-tomatoes-and-goat-cheese","rating":{"value":5,"count":5324},"date":"2014-01-24"},{"pair":1017061,"title":"Persimmon Salad with Pomegranate and Walnuts","subtitle":null,"author":"David Tanis","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"183","fat":"13 g","carbohydrates":"16 g","protein":"3 g"},"description":"Persimmons make a colorful cool weather salad, combined with dark red Treviso and radicchio leaves and glistening ruby-like pomegranate seeds. Walnut oil and shallots give the vinaigrette an earthy flavor, accentuated by caramelized walnuts with sea salt. You need the small apple-size Fuyu persimmons, which are delicious eaten raw. (The pointy Hachiya persimmons need to ripen to softness and are usually cooked for cakes or puddings.) Make this throughout the fall and winter. If persimmons are unavailable use pears, Asian pears or crisp tart apples.","from_your_kitchen":null,"ingredients":["2 ounces walnuts, about ½ cup","2 tablespoons sugar","½ teaspoon fleur de sel or other coarse sea salt, crumbled","1 shallot, finely sliced","2 tablespoons sherry vinegar","Salt and pepper","3 tablespoons walnut oil","3 medium Fuyu persimmons, peeled","8 ounces radicchio, Treviso or other chicory leaves","½ cup pomegranate seeds"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 350 degrees. Make the sugared walnuts: Line a baking sheet with parchment. Put walnuts in a small bowl. Pour very hot water over walnuts for 1 minute, then drain. Add sugar and fleur de sel. Mix to coat nuts evenly, then spread them on the parchment. Bake for 7 to 10 minutes, until crisp and caramelized. Cool, then break walnuts apart. (May be prepared up to 5 days ahead; store in the cupboard in an airtight container.)"},{"n":2,"title":null,"text":"Core and cut persimmons into ½-inch-thick wedges and transfer to a low, wide salad bowl. Salt persimmons lightly, then dress with vinaigrette. Add radicchio leaves and gently toss with hands to coat leaves, pulling persimmon pieces to the top. Scatter pomegranate seeds over the top, along with any collected juices. Garnish with sugared walnuts and serve."},{"n":3,"title":"MAKE THE VINAIGRETTE","text":"Put shallots in a small bowl. Add a pinch of salt and the sherry vinegar. Let mixture steep for 10 minutes. Whisk in walnut oil. Season to taste with salt and pepper. Set aside."}],"tips":[],"cuisine_tags":["American"],"ingredient_tags":["persimmon","radicchio","walnuts"],"item_tags":["pomegranate seeds","sherry vinegar"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Bake","Dinner","Easy","Lunch","Persimmon","Quick","Radicchio","Salad","Side Dish","Vegan Thanksgiving","Walnut"],"issues":null,"front":"nyt_1017061.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017061-persimmon-salad-with-pomegranate-and-walnuts","rating":{"value":5,"count":477},"date":"2014-12-17"},{"pair":1016931,"title":"Glazed Shiitakes With Bok Choy","subtitle":null,"author":"David Tanis","servings":"6 to 8","yield_text":"6 to 8 servings","yield_count":6,"cook_time":"30 minutes","nutrition":{"calories":"119","fat":"7 g","carbohydrates":"13 g","protein":"4 g"},"description":"Gorgeous glazed shiitake mushrooms and tender green bok choy sparked with ginger, sesame and hot pepper work beautifully against more staid flavors, so consider serving them next to a traditional roast chicken or turkey. They also are delicious draped over a pile of rice.","from_your_kitchen":null,"ingredients":["2 pounds baby bok choy","3 tablespoons vegetable oil","3 small dry red Chinese hot peppers","1 pound shiitake mushrooms (about 4 dozen), stems removed","Salt and pepper","4 garlic cloves, minced","1 tablespoon grated ginger","1 tablespoons sugar","1 teaspoon sesame oil","3 tablespoons tamari or soy sauce","6 scallions, sliced diagonally, for garnish","1 tablespoon roasted sesame seeds for garnish (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Bring a large pot of well-salted water to a boil. Cut off and discard stem ends of bok choy. Separate leaves, rinse and drain. Drop leaves into boiling water and cook for 1 to 2 minutes, until barely cooked. Immediately remove, rinse with cool water, drain and pat dry. Arrange leaves in one layer on an ovenproof earthenware platter, then set aside."},{"n":2,"title":null,"text":"Put a large wok or cast-iron skillet over high heat. Add oil and heat until nearly smoking, then add hot peppers and shiitake caps, stirring to coat. Season lightly with salt and pepper. Stir-fry for 2 minutes. Reduce heat slightly and add garlic, ginger, sugar, sesame oil and tamari. Stir-fry for 1 minute more."},{"n":3,"title":null,"text":"Spoon shiitake and pan juices over reserved cooked bok choy. Serve at room temperature, or if you prefer, reheat covered with foil for 10 to 15 minutes in a hot oven. Garnish with scallions and sesame seeds, if using."}],"tips":[],"cuisine_tags":["Chinese"],"ingredient_tags":["bok choy","mushrooms"],"item_tags":["ginger","scallions","sesame oil","tamari"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Boil","Bok Choy","Christmas","Dinner","Easy","Hanukkah","Lunch","New Year’s Day","Quick","Shiitake","Side Dish","Stir-Fry","Thanksgiving","Vegan","Vegan Thanksgiving","Vegetables","Vegetarian"],"issues":null,"front":"nyt_1016931.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1016931-glazed-shiitakes-with-bok-choy","rating":{"value":5,"count":2245},"date":"2014-10-29"},{"pair":1017128,"title":"Lentil Salad With Roasted Vegetables","subtitle":null,"author":"Melissa Clark","servings":"10 to 12","yield_text":"10 to 12 servings","yield_count":10,"cook_time":"1 hour 30 minutes","nutrition":{"calories":"289","fat":"15 g","carbohydrates":"29 g","protein":"10 g"},"description":"This lentil salad looks and tastes bright, thanks to a combination of tangerine juice, sherry vinegar and colorful caramelized roasted root vegetables. It works either as a main course, served with good bread and butter, or as side dish with roasted meat or fish. For the maximum visual impact, use both golden and red beets. Vegetarians can feel free to leave out the bacon. Leftovers will keep for at least five days, though try to pack it up without the radicchio, which gets soggy in the fridge.","from_your_kitchen":null,"ingredients":["1 small whole acorn squash, peeled if desired, halved, seeded and diced into ½-inch pieces","2 medium carrots, peeled and diced into ½-inch pieces","1 medium celeriac, peeled and diced into ½-inch pieces","3 small beets, peeled and diced into ½-inch pieces","2 tablespoons extra-virgin olive oil","½ teaspoon salt","2 sprigs thyme","1 sprig rosemary, cut in half","4 slices (4 ounces) bacon, cut into 1-inch pieces (optional)","2 cups brown or green lentils","2 garlic cloves, smashed and peeled","1 bay leaf","1 ½ teaspoons kosher salt, more to taste","½ teaspoon black pepper","¼ cup sherry vinegar, more to taste","2 teaspoons Dijon mustard","½ teaspoon salt","½ cup extra-virgin olive oil, more as needed","2 heads radicchio, sliced","2 scallions, thinly sliced (whites and greens)","Parsley, roughly chopped, for garnish","Flaky sea salt, to taste","Cracked black pepper, to taste","1 tangerine, halved and seeded"],"ingredient_groups":[{"at":0,"title":"FOR THE LENTIL SALAD"},{"at":14,"title":"FOR THE SHERRY VINAIGRETTE"},{"at":18,"title":"FOR SERVING"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Heat oven to 400 degrees. Place vegetables in one layer on one or two large rimmed baking pans, toss with olive oil and salt. Place thyme and rosemary on top of vegetables, cover pans with foil and roast for 25 minutes. Remove foil, stir in bacon and bake for 30 to 40 minutes longer, until vegetables are tender and golden all over."},{"n":2,"title":null,"text":"In a large pot, combine lentils, 6 cups water, garlic, bay leaf, salt and pepper and bring to a boil over high heat. Reduce heat to low and simmer for 20 to 30 minutes, until lentils are tender."},{"n":3,"title":null,"text":"In a small bowl, whisk together vinegar, mustard and salt. Then whisk in olive oil."},{"n":4,"title":null,"text":"Drain lentils and discard bay leaf; keep or discard garlic as you like. Toss lentils with half of the sherry vinaigrette while still warm. Add more salt, olive oil and vinegar as needed."},{"n":5,"title":null,"text":"Toss radicchio with enough of remaining vinaigrette to lightly coat it and arrange it on a platter. Combine lentils and roasted vegetables, adding more of the vinaigrette to taste; spoon mixture on top of radicchio. Garnish with scallions, parsley, sea salt and black pepper. Squeeze tangerine juice over the lentils and drizzle with more olive oil if needed."}],"tips":[],"cuisine_tags":["American","French"],"ingredient_tags":["beets","carrot","lentils","radicchio"],"item_tags":["dijon mustard","scallions","sherry vinegar"],"course_tags":["Dinner","Lunch","Sides & Appetizers"],"keywords":["Acorn Squash","Appetizer","Bake","Beet","Carrot","Dinner","Lentil","Lunch","Radicchio","Roast","Salad","Simmer"],"issues":null,"front":"nyt_1017128.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017128-lentil-salad-with-roasted-vegetables","rating":{"value":5,"count":1956},"date":"2015-01-14"},{"pair":1017294,"title":"Broccoli Rabe Lasagna","subtitle":null,"author":"David Tanis","servings":"6","yield_text":"6 servings","yield_count":6,"cook_time":"1 hour 30 minutes","nutrition":{"calories":"972","fat":"60 g","carbohydrates":"79 g","protein":"32 g"},"description":"Broccoli rabe (sometimes spelled raab, or known as rapini greens) is one of the most delicious members of the mustard green family. The leaves, tender stems and broccoli-like buds have a distinctive pleasant bitterness when cooked. For this vegetarian lasagna, some of the cooked greens are puréed to make a garlicky pesto and the rest is coarsely chopped and added to the layers. Find more lasagna recipes.","from_your_kitchen":null,"ingredients":["4 tablespoons butter","¼ cup all-purpose flour","2 cups half-and-half, heated, plus a little more if necessary","Salt and pepper","Pinch of cayenne","Grated nutmeg, to taste","1 pound dry lasagna noodles","Salt and pepper","2 bunches broccoli rabe, about 2 pounds","4 garlic cloves, minced","½ cup extra-virgin olive oil","1 pound ricotta cheese","½ teaspoon grated lemon zest","4 tablespoons butter","4 ounces grated Parmesan, about 2 cups, or a combination of Parmesan and pecorino"],"ingredient_groups":[{"at":0,"title":"FOR THE BÉCHAMEL SAUCE"},{"at":6,"title":"FOR THE LASAGNA"}],"tools":null,"steps":[{"n":1,"title":null,"text":"Make the béchamel: Melt butter in a small saucepan. Whisk in flour and cook for a minute over medium heat without browning. Gradually whisk in half-and-half, ½ cup at a time, to obtain a smooth, lightly thickened sauce. Turn heat to low. Add ½ teaspoon salt, some ground black pepper, the cayenne and nutmeg. Cook, whisking, for 4 to 5 minutes, then place saucepan in a hot-water bath to keep sauce warm. Thin if necessary with a little more half-and-half."},{"n":2,"title":null,"text":"Bring a large pot of well-salted water to the boil. Add lasagna noodles and cook for 5 minutes. Lift noodles from water with a spider and rinse well in a bowl of cold water. Drain and lay noodles flat on a kitchen towel."},{"n":3,"title":null,"text":"Using the same cooking water, blanch the greens for 1 minute, until just wilted. Rinse greens with cool water, squeeze dry and chop them roughly. Put 1 cup of chopped greens, the minced garlic and ½ cup olive oil in a food processor or blender and purée to make a pesto. Season with salt and pepper to taste and transfer to a small bowl."},{"n":4,"title":null,"text":"Mix the ricotta and lemon zest in a small bowl and season with salt and pepper to taste. Heat oven to 375 degrees. Organize to have all ingredients within easy reach for assembling lasagna. Use 2 tablespoons butter to grease an 8-by-10-inch baking dish."},{"n":5,"title":null,"text":"Assemble the lasagna: Put a layer of cooked noodles on the bottom of the baking dish. Spoon a quarter of the béchamel over noodles, then dot with a third of the ricotta. Complete layer with chopped greens, a drizzle of pesto and some grated cheese. Continue layering, finishing with a layer of pasta. Spread the last of the béchamel on top and sprinkle with Parmesan. (There should be 4 layers of pasta and 3 layers of filling.)"},{"n":6,"title":null,"text":"Dot with remaining butter and bake, covered with foil, for 20 minutes. Uncover and bake for 20 minutes more, until nicely browned and bubbling. Let lasagna rest 10 minutes before serving."}],"tips":[],"cuisine_tags":["Comfort Food","Italian"],"ingredient_tags":["broccoli rabe","pasta","ricotta"],"item_tags":["cayenne","lemon","nutmeg","parmesan"],"course_tags":["Dinner","Lunch"],"keywords":["Bake","Boil","Broccoli Rabe","Dinner","Great Leftovers","Half and Half","Italian","Lasagna","Lasagna Noodle","Lunch","Main Course","Parmesan","Ricotta"],"issues":null,"front":"nyt_1017294.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1017294-broccoli-rabe-lasagna","rating":{"value":4,"count":871},"date":"2015-03-18"},{"pair":1015819,"title":"Chocolate Chip Cookies","subtitle":null,"author":"David Leite","servings":null,"yield_text":"1 1/2 dozen 5-inch cookies","yield_count":18,"cook_time":"45 minutes, plus chilling","nutrition":{"calories":"399","fat":"18 g","carbohydrates":"67 g","protein":"10 g"},"description":"You may have memorized the foolproof gem on the back of the Toll House bag, given to the world by Ruth Graves Wakefield in the 1930s. But this may become your new favorite chocolate chip cookie recipe. It’s a little more complicated, and you’ll have to plan ahead: After assembling the dough, you must chill it for at least 24 hours before baking it, and preferably up to 36. This allows the dry ingredients time to soak up the wet ones, which results in a firmer dough. It leads to a marvelously chewy, chocolate-rich cookie. Don’t skimp on good chocolate, and the sea salt is not an option — it’s the beacon at the top of this gorgeous treat. (You can certainly put this recipe together by hand, but a stand mixer makes it easy work. If you’re in the market for one, our colleagues at The Wirecutter have tested quite a few, and they've put together an excellent guide to the best.) David Leite","from_your_kitchen":null,"ingredients":["2 cups minus 2 tablespoons cake flour (8 ½ ounces)","1 ⅔ cups bread flour (8 ½ ounces)","1 ¼ teaspoons baking soda","1 ½ teaspoons baking powder","1 ½ teaspoons coarse sea salt, plus more for sprinkling","1 ¼ cups unsalted butter (2 ½ sticks)","1 ¼ cups light brown sugar (10 ounces)","1 cup plus 2 tablespoons granulated sugar (8 ounces)","2 large eggs","2 teaspoons natural vanilla extract","1 ¼ pounds bittersweet chocolate disks or fèves, at least 60 percent cacao content (see note)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Sift flours, baking soda, baking powder and salt into a bowl. Set aside."},{"n":2,"title":null,"text":"Using a mixer fitted with paddle attachment, cream butter and sugars together until very light, about 5 minutes. Add eggs, one at a time, mixing well after each addition. Stir in the vanilla. Reduce speed to low, add dry ingredients and mix until just combined, 5 to 10 seconds. Drop chocolate pieces in and incorporate them without breaking them. Press plastic wrap against dough and refrigerate for 24 to 36 hours. Dough may be used in batches, and can be refrigerated for up to 72 hours."},{"n":3,"title":null,"text":"When ready to bake, preheat oven to 350 degrees. Line a baking sheet with parchment paper or a nonstick baking mat. Set aside."},{"n":4,"title":null,"text":"Scoop 6 3 ½-ounce mounds of dough (the size of generous golf balls) onto baking sheet, making sure to turn horizontally any chocolate pieces that are poking up; it will make for a more attractive cookie. Sprinkle lightly with salt and bake until golden brown but still soft, 18 to 20 minutes. Transfer sheet to a wire rack for 10 minutes, then slip cookies onto another rack to cool a bit more. Repeat with remaining dough, or reserve dough, refrigerated, for baking remaining batches the next day. Eat warm, with a big napkin."}],"tips":["Disks are sold at Jacques Torres Chocolate; Valrhona fèves, oval-shaped chocolate pieces, are at Whole Foods."],"cuisine_tags":["American"],"ingredient_tags":["chocolate chips"],"item_tags":["brown sugar","vanilla"],"course_tags":["Dessert"],"keywords":["Bake","Bittersweet Chocolate","Bread Flour","Cake Flour","Chocolate Chip Cookie","Dessert","Freezer Friendly","Plan-Ahead","Thanksgiving"],"issues":null,"front":"nyt_1015819.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1015819-chocolate-chip-cookies","rating":{"value":5,"count":20579},"date":"2008-07-09"},{"pair":1019908,"title":"Fried Eggs With Garlicky Green Rice","subtitle":null,"author":"Sarah Copeland","servings":"4","yield_text":"4 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"600","fat":"21 g","carbohydrates":"82 g","protein":"20 g"},"description":"Fried eggs are a simple vegetarian staple. But set them on top of garlicky kale- and herb-flecked rice, and they form a deeply satisfying supper. This recipe is endlessly customizable: Go with what you have — reheated leftover rice works equally well as a fresh pot — or use any whole grain you have. The secret here is locking flavor into the grains by stirring in garlic herbs while the rice is warm. To finish, be generous with the lime — the acid brings all the flavors up a notch — and play around with your tolerance for garlic and heat. Lastly, don't be afraid to raid your fridge: Avocado or leftover beans would be right at home here, too.","from_your_kitchen":null,"ingredients":["2 cups brown or white basmati or long-grain rice, rinsed and drained","½ teaspoon kosher salt, plus more for seasoning","2 tablespoons olive oil","4 large eggs","Black pepper","½ small bunch kale, stems removed and leaves finely chopped (about 1 packed cup)","½ bunch fresh cilantro, stems discarded and leaves finely chopped (about 1 packed cup)","½ bunch fresh parsley, stems discarded and leaves finely chopped (about 1 packed cup)","4 garlic cloves, finely chopped","1 jalapeño, seeded and finely chopped","4 small pink radishes or 1 large watermelon radish, thinly sliced","4 ounces cotija cheese or queso fresco","2 limes, cut in wedges","Hot sauce, for serving (optional)"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Cook rice with ½ teaspoon kosher salt according to package instructions. Set aside, covered, to steam."},{"n":2,"title":null,"text":"Meanwhile, heat the oil over medium in your largest skillet or griddle until glistening. Crack in the eggs and cook until golden-brown around the edges, about 2 minutes. Cover loosely using a lid or aluminum foil and cook until the whites are just set and the yolks are still runny but starting to set. (They’ll break and mingle with the rice in a beautiful way.) Season with salt and pepper."},{"n":3,"title":null,"text":"While the eggs cook, fluff the cooked rice with a fork, then stir in the kale, cilantro and parsley. Add the garlic and jalapeño a little at a time and taste, adding more salt, garlic or jalapeño to your liking."},{"n":4,"title":null,"text":"Spoon rice into shallow bowls and top with the fried eggs, radishes, cheese and lime wedges. Serve with your hot sauce of choice."}],"tips":[],"cuisine_tags":["Mexican"],"ingredient_tags":["eggs","kale","rice"],"item_tags":["cilantro","hot sauce","jalapeño","lime","parsley"],"course_tags":["Dinner"],"keywords":["Cilantro","Dinner","Easy","Egg","Fall","Fry","Hot Sauce","Kale","Main Course","Parsley","Quick","Rice","Spring","Steam","Summer","Weeknight","Winter"],"issues":null,"front":"nyt_1019908.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1019908-fried-eggs-with-garlicky-green-rice","rating":{"value":4,"count":1092},"date":"2019-01-09"},{"pair":1020926,"title":"Roasted Tomato and White Bean Stew","subtitle":null,"author":"Colu Henry","servings":"4 to 6","yield_text":"4 to 6 servings","yield_count":4,"cook_time":"30 minutes","nutrition":{"calories":"506","fat":"17 g","carbohydrates":"71 g","protein":"19 g"},"description":"This hearty, flexible stew comes together with pantry ingredients and delivers layers of flavors. Cherry tomatoes, roasted in a generous glug of olive oil to amplify their sweetness, lend a welcome brightness to this otherwise rich dish. Onion, garlic and red-pepper flakes form the backbone of this dish, to which white beans and broth are added, then simmered until thick. While this stew is lovely on its own, you could also add wilt-able greens such as kale, escarole or Swiss chard at the end, and toasted bread crumbs on top. The dish is vegan as written, but should you choose to top your bowl with a showering of grated pecorino or Parmesan, it would most likely work well in your favor.","from_your_kitchen":null,"ingredients":["½ cup roughly chopped Italian parsley leaves and tender stems","2 teaspoons lemon zest (from 1 large lemon)","2 (10-ounce) containers cherry or grape tomatoes","¼ cup olive oil, plus 2 tablespoons and more for drizzling (optional)","1 tablespoon fresh thyme leaves","Kosher salt and black pepper","1 medium yellow onion, thinly sliced","3 large garlic cloves, thinly sliced","½ teaspoon red-pepper flakes","2 (15-ounce) cans white beans (such as butter or cannellini), rinsed","1 ½ cups vegetable or chicken broth, or water","Flaky salt, for serving (optional)","Toasted bread, for serving"],"ingredient_groups":null,"tools":null,"steps":[{"n":1,"title":null,"text":"Heat the oven to 425 degrees. In a small bowl, gently toss together the parsley and lemon zest with your hands until well combined; set aside."},{"n":2,"title":null,"text":"In a large baking dish or on a sheet pan, toss the tomatoes with ¼ cup oil and thyme; season well with salt and pepper. Roast tomatoes until they have collapsed and begin to turn golden around the edges, 20 to 25 minutes."},{"n":3,"title":null,"text":"When the tomatoes are almost done roasting, heat 2 tablespoons oil in a large (12-inch), deep skillet or Dutch oven over medium. Add the onion, garlic and red-pepper flakes and cook until the onion is softened and the garlic is fragrant, 4 to 5 minutes. Stir in the rinsed beans and broth and bring to a simmer. With the back of a spoon or spatula, gently smash about ½ cup of the beans so they slightly thicken the broth. If you want a thicker stew, crush some more of the beans. Season with salt and pepper."},{"n":4,"title":null,"text":"When the tomatoes are finished roasting, add them directly to the stew along with any juices that have been released. Simmer for 5 to 10 minutes more so the flavors become friendly; season to taste with salt."},{"n":5,"title":null,"text":"Ladle into shallow bowls. Top each serving with some of the lemon-parsley mixture and drizzle with more olive oil, and season with flaky salt, if you like. Serve with toasted bread."}],"tips":[],"cuisine_tags":["American","Mediterranean"],"ingredient_tags":["tomato","white beans"],"item_tags":["parsley","red chile flakes","thyme"],"course_tags":["Dinner","Lunch"],"keywords":["American","Cherry Tomato","Dinner","Fall","Great Leftovers","Lunch","Main Course","Quick","Roast","Simmer","Stew","Vegetarian","Weeknight","White Bean","Winter"],"issues":null,"front":"nyt_1020926.jpg","back":null,"era":"nyt","source":"nyt","hero":null,"url":"https://cooking.nytimes.com/recipes/1020926-roasted-tomato-and-white-bean-stew","rating":{"value":5,"count":14932},"date":"2020-03-05"}];
